              className={`flex-1 px-4 py-2 text-sm rounded-full outline-none transition-all ${
                isDarkMode ? 'bg-slate-800 focus:bg-slate-700 border-slate-700' : 'bg-slate-100 focus:bg-white border-transparent'
              } border`}
            />
            <button className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center shadow-lg shadow-blue-500/30">
              <ChevronRight size={18}/>
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

// --- Subcomponents ---

const NavItem = ({ active, onClick, icon, label, isDarkMode }: any) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all ${
      active 
        ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' 
        : `text-slate-500 ${isDarkMode ? 'hover:bg-slate-800 hover:text-white' : 'hover:bg-slate-100 hover:text-slate-900'}`
    }`}
  >
    <span className={`${active ? 'scale-110 transition-transform' : ''}`}>{icon}</span>
    <span className="text-sm font-bold">{label}</span>
  </button>
);

export default App;

