  phone: string;
  alamat: string;
  sales: string;
}

interface Product {
  id: string;
  nama: string;
  sku: string;
  harga: number;
  stok: number;
}

interface Transaction {
  id: string;
  tanggal: string;
  customerId: string;
  customerName: string;
  produkId: string;
  produkNama: string;
  qty: number;
  nilai: number;
  status: 'Selesai' | 'Proses' | 'Batal';
  sales: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  // --- States ---
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isChatOpen, setIsChatOpen] = useState(false);

  // --- Database States (Local Storage) ---
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [chatMessages, setChatMessages] = useState<{role: 'bot'|'user', text: string}[]>([]);
  const [chatInput, setChatInput] = useState('');

  // --- Form States ---
  const [showModal, setShowModal] = useState<string | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const savedCustomers = localStorage.getItem('mypanca_customers');
    const savedProducts = localStorage.getItem('mypanca_products');
    const savedTransactions = localStorage.getItem('mypanca_transactions');
    const savedTheme = localStorage.getItem('theme');

    if (savedCustomers) setCustomers(JSON.parse(savedCustomers));
    if (savedProducts) setProducts(JSON.parse(savedProducts));
    if (savedTransactions) setTransactions(JSON.parse(savedTransactions));
    if (savedTheme === 'dark') setIsDarkMode(true);

    // Initial bot message
    setChatMessages([{ role: 'bot', text: 'Halo! Saya asisten MyPanca. Apa yang bisa saya bantu hari ini? Anda bisa tanya "stok" atau "transaksi".' }]);
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_customers', JSON.stringify(customers));
    localStorage.setItem('mypanca_products', JSON.stringify(products));
    localStorage.setItem('mypanca_transactions', JSON.stringify(transactions));
    document.documentElement.setAttribute('data-theme', isDarkMode ? 'dark' : 'light');
    localStorage.setItem('theme', isDarkMode ? 'dark' : 'light');
  }, [customers, products, transactions, isDarkMode]);

  // --- Dashboard Calculations ---
  const stats = useMemo(() => {
    const totalRevenue = transactions
      .filter(t => t.status === 'Selesai')
      .reduce((sum, t) => sum + t.nilai, 0);

    return {
      totalCustomers: customers.length,
      revenue: new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(totalRevenue),
      proses: transactions.filter(t => t.status === 'Proses').length,
      batal: transactions.filter(t => t.status === 'Batal').length
    };
  }, [customers, transactions]);

  // --- CRUD Handlers ---
  const addSampleData = () => {
    const sampleCust: Customer = { id: 'c1', nama: 'PT Jaya Selalu', email: 'info@jaya.com', phone: '0812345678', alamat: 'Jakarta', sales: 'Indra' };
    const sampleProd: Product = { id: 'p1', nama: 'Alat Semprot Pro', sku: 'ASP-001', harga: 1500000, stok: 50 };
    setCustomers([sampleCust]);
    setProducts([sampleProd]);
    showToast("Data sampel ditambahkan!");
  };

  const handleAddTransaction = (e: any) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    const prodId = formData.get('produkId') as string;
    const custId = formData.get('customerId') as string;
    const qty = Number(formData.get('qty'));

    const product = products.find(p => p.id === prodId);
    const customer = customers.find(c => c.id === custId);

    if (product && customer) {
      const newTrx: Transaction = {
        id: 'TRX-' + Date.now(),
        tanggal: new Date().toLocaleDateString('id-ID'),
        customerId: custId,
        customerName: customer.nama,
        produkId: prodId,
        produkNama: product.nama,
        qty: qty,
        nilai: product.harga * qty,
        status: 'Proses',
        sales: customer.sales
      };
      setTransactions([newTrx, ...transactions]);
      setShowModal(null);
      showToast("Transaksi Berhasil Dibuat!");
    }
  };

  const showToast = (msg: string) => {
    alert(msg); // Placeholder for a better toast component
  };

  // --- Chatbot Logic ---
  const handleChat = (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim()) return;

    const userMsg = chatInput.toLowerCase();
    setChatMessages(prev => [...prev, { role: 'user', text: chatInput }]);
    setChatInput('');

    setTimeout(() => {
      let botResponse = "Maaf, saya tidak mengerti. Coba tanya 'stok' atau 'transaksi'.";

      if (userMsg.includes('stok') || userMsg.includes('produk')) {
        const stokInfo = products.map(p => `${p.nama}: ${p.stok} unit`).join(', ');
        botResponse = stokInfo ? `Stok saat ini: ${stokInfo}` : "Belum ada data produk.";
      } else if (userMsg.includes('transaksi') || userMsg.includes('order')) {
        botResponse = `Ada ${transactions.length} transaksi tercatat. ${stats.proses} dalam proses, ${transactions.filter(t => t.status === 'Selesai').length} selesai.`;
      } else if (userMsg.includes('halo') || userMsg.includes('hai')) {
        botResponse = "Halo! Senang bertemu Anda. Ada yang bisa saya bantu?";
      }

      setChatMessages(prev => [...prev, { role: 'bot', text: botResponse }]);
    }, 600);
  };

  // --- Components ---
  const NavItem = ({ active, onClick, icon, label }: any) => (
    <button 
      onClick={onClick}
      className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all ${
        active 
          ? 'bg-blue-600 text-white shadow-lg' 
          : `text-slate-500 ${isDarkMode ? 'hover:bg-slate-800' : 'hover:bg-slate-100'}`
      }`}
    >
      {icon}
      <span className="text-sm font-bold">{label}</span>
    </button>
  );

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark text-slate-200 bg-slate-950' : 'bg-slate-50 text-slate-900'}`}>

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:inset-0 ${
        isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
      } ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'} border-r`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <Package size={22} />
            </div>
            <h1 className="font-bold text-lg">MyPanca</h1>
          </div>

          <nav className="flex-1 space-y-1">
            <p className="text-[10px] font-bold text-slate-400 uppercase mb-4">Menu Utama</p>
            <NavItem active={activePanel === 'dashboard'} onClick={() => setActivePanel('dashboard')} icon={<LayoutDashboard size={20}/>} label="Dashboard" />
            <NavItem active={activePanel === 'tracking'} onClick={() => setActivePanel('tracking')} icon={<LineChart size={20}/>} label="Transaksi" />

            <p className="text-[10px] font-bold text-slate-400 uppercase mt-8 mb-4">Master Data</p>
            <NavItem active={activePanel === 'customer'} onClick={() => setActivePanel('customer')} icon={<Users size={20}/>} label="Customer" />
            <NavItem active={activePanel === 'produk'} onClick={() => setActivePanel('produk')} icon={<Package size={20}/>} label="Produk" />
          </nav>

          <button onClick={() => setIsDarkMode(!isDarkMode)} className="mt-auto flex items-center gap-3 text-slate-500 font-bold text-sm p-3 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl">
            {isDarkMode ? <Sun size={20}/> : <Moon size={20}/>}
            {isDarkMode ? 'Mode Terang' : 'Mode Gelap'}
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0">
        <header className={`h-16 flex items-center justify-between px-6 border-b sticky top-0 z-30 ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden"><Menu size={24} /></button>
            <h2 className="text-xl font-bold capitalize">{activePanel}</h2>
          </div>
          <div className="flex gap-4">
             {customers.length === 0 && (
               <button onClick={addSampleData} className="text-xs font-bold text-blue-500 border border-blue-500 px-3 py-1 rounded-full hover:bg-blue-500 hover:text-white transition-all">
                 Load Sample Data
               </button>
             )}
          </div>
        </header>

        <div className="flex-1 p-6 overflow-y-auto">
          {activePanel === 'dashboard' && (
            <div className="space-y-6 animate-in fade-in duration-500">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className={`p-6 rounded-2xl border ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-100 shadow-sm'}`}>
                   <Users className="text-blue-500 mb-2" />
                   <p className="text-xs text-slate-500 font-bold">Total Customer</p>
                   <p className="text-2xl font-black">{stats.totalCustomers}</p>
                </div>
                <div className={`p-6 rounded-2xl border ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-100 shadow-sm'}`}>
                   <TrendingUp className="text-emerald-500 mb-2" />
                   <p className="text-xs text-slate-500 font-bold">Revenue (Selesai)</p>
                   <p className="text-2xl font-black">{stats.revenue}</p>
                </div>
                <div className={`p-6 rounded-2xl border ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-100 shadow-sm'}`}>
                   <Clock className="text-amber-500 mb-2" />
                   <p className="text-xs text-slate-500 font-bold">Transaksi Proses</p>
                   <p className="text-2xl font-black">{stats.proses}</p>
                </div>
                <div className={`p-6 rounded-2xl border ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-100 shadow-sm'}`}>
                   <AlertCircle className="text-rose-500 mb-2" />
                   <p className="text-xs text-slate-500 font-bold">Transaksi Batal</p>
                   <p className="text-2xl font-black">{stats.batal}</p>
                </div>
              </div>

              <div className={`p-6 rounded-2xl border ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-100'}`}>
                <h3 className="font-bold mb-4 flex items-center gap-2 text-blue-500"><Clock size={18}/> Transaksi Terbaru</h3>
                <div className="space-y-4">
                  {transactions.length === 0 ? (
                    <p className="text-sm text-slate-500 italic">Belum ada transaksi.</p>
                  ) : transactions.slice(0, 5).map(trx => (
                    <div key={trx.id} className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800">
                      <div>
                        <p className="font-bold text-sm">{trx.customerName}</p>
                        <p className="text-[10px] text-slate-500">{trx.produkNama} (x{trx.qty})</p>
                      </div>
                      <div className="text-right">
                        <p className="font-black text-sm">{new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(trx.nilai)}</p>
                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                          trx.status === 'Selesai' ? 'bg-emerald-100 text-emerald-600' : 
                          trx.status === 'Batal' ? 'bg-rose-100 text-rose-600' : 'bg-amber-100 text-amber-600'
                        }`}>{trx.status}</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activePanel === 'tracking' && (
            <div className="space-y-6">
              <div className="flex justify-between items-center">
                <h3 className="font-bold">Daftar Transaksi</h3>
                <button onClick={() => setShowModal('addTrx')} className="bg-blue-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2">
                  <Plus size={18}/> Transaksi Baru
                </button>
              </div>
              <div className={`overflow-x-auto rounded-2xl border ${isDarkMode ? 'border-slate-800 bg-slate-900' : 'border-slate-200 bg-white'}`}>
                <table className="w-full text-left text-sm">
                  <thead>
                    <tr className="border-b dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50">
                      <th className="p-4 font-bold">ID</th>
                      <th className="p-4 font-bold">Customer</th>
                      <th className="p-4 font-bold">Produk</th>
                      <th className="p-4 font-bold">Nilai</th>
                      <th className="p-4 font-bold">Status</th>
                      <th className="p-4 font-bold">Aksi</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y dark:divide-slate-800">
                    {transactions.map(t => (
                      <tr key={t.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30">
                        <td className="p-4 font-mono text-[10px]">{t.id}</td>
                        <td className="p-4 font-bold">{t.customerName}</td>
                        <td className="p-4">{t.produkNama}</td>
                        <td className="p-4 font-bold text-blue-500">{new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(t.nilai)}</td>
                        <td className="p-4">
                          <span className={`px-2 py-1 rounded-lg text-[10px] font-black uppercase ${
                             t.status === 'Selesai' ? 'bg-emerald-100 text-emerald-600' : 
                             t.status === 'Batal' ? 'bg-rose-100 text-rose-600' : 'bg-amber-100 text-amber-600'
                          }`}>{t.status}</span>
                        </td>
                        <td className="p-4">
                          <button onClick={() => setTransactions(transactions.filter(item => item.id !== t.id))} className="text-rose-500 hover:bg-rose-50 p-2 rounded-lg"><Trash2 size={16}/></button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {activePanel === 'customer' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {customers.map(c => (
                <div key={c.id} className={`p-6 rounded-3xl border ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-200 shadow-sm'}`}>
                  <div className="w-12 h-12 bg-blue-100 text-blue-600 rounded-2xl flex items-center justify-center font-bold text-xl mb-4">{c.nama.charAt(0)}</div>
                  <h4 className="font-bold text-lg">{c.nama}</h4>
                  <p className="text-xs text-slate-500 mb-4">{c.email}</p>
                  <div className="space-y-2 mb-6">
                    <div className="flex items-center gap-2 text-xs text-slate-600 dark:text-slate-400"><Phone size={14}/> {c.phone}</div>
                    <div className="flex items-center gap-2 text-xs text-slate-600 dark:text-slate-400"><Mail size={14}/> {c.email}</div>
                  </div>
                  <button className="w-full py-2 bg-slate-100 dark:bg-slate-700 text-sm font-bold rounded-xl">Detail Profil</button>
                </div>
              ))}
            </div>
          )}

          {activePanel === 'produk' && (
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
               {products.map(p => (
                 <div key={p.id} className={`p-6 rounded-3xl border ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-200 shadow-sm'}`}>
                    <div className="flex justify-between items-start mb-4">
                      <div className="p-3 bg-emerald-100 text-emerald-600 rounded-xl"><Package /></div>
                      <span className="text-[10px] font-bold bg-slate-100 dark:bg-slate-700 px-2 py-0.5 rounded-full">{p.sku}</span>
                    </div>
                    <h4 className="font-bold">{p.nama}</h4>
                    <p className="text-xl font-black text-blue-600 mt-1">{new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(p.harga)}</p>
                    <div className="mt-4 flex items-center justify-between text-xs font-bold text-slate-500">
                      <span>Stok Tersedia</span>
                      <span className={p.stok < 10 ? 'text-rose-500' : 'text-emerald-500'}>{p.stok} Unit</span>
                    </div>
                 </div>
               ))}
             </div>
          )}
        </div>
      </main>

      {/* Floating Chatbot */}
      <div className={`fixed bottom-6 right-6 flex flex-col items-end z-50 ${isChatOpen ? 'w-80 h-[450px]' : 'w-14 h-14'}`}>
         {isChatOpen && (
           <div className={`w-full flex-1 mb-4 flex flex-col rounded-3xl shadow-2xl overflow-hidden border ${isDarkMode ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-200'} animate-in zoom-in duration-200`}>
              <div className="p-4 bg-blue-600 text-white flex items-center justify-between">
                <span className="font-bold text-sm">Panca Assistant</span>
                <button onClick={() => setIsChatOpen(false)}><X size={18}/></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50 dark:bg-slate-950/50">
                {chatMessages.map((m, i) => (
                  <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[85%] p-3 text-xs leading-relaxed ${
                      m.role === 'user' 
                      ? 'bg-blue-600 text-white rounded-2xl rounded-tr-none shadow-md' 
                      : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-200 rounded-2xl rounded-tl-none border border-slate-100 dark:border-slate-700 shadow-sm'
                    }`}>
                      {m.text}
                    </div>
                  </div>
                ))}
              </div>
              <form onSubmit={handleChat} className="p-3 border-t dark:border-slate-800 bg-white dark:bg-slate-900 flex gap-2">
                <input 
                  value={chatInput} 
                  onChange={(e) => setChatInput(e.target.value)}
                  placeholder="Ketik pesan..." 
                  className="flex-1 text-xs bg-slate-100 dark:bg-slate-800 px-4 py-2 rounded-full outline-none focus:ring-1 focus:ring-blue-500"
                />
                <button type="submit" className="bg-blue-600 text-white p-2 rounded-full shadow-lg"><Send size={14}/></button>
              </form>
           </div>
         )}
         {!isChatOpen && (
            <button onClick={() => setIsChatOpen(true)} className="w-14 h-14 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all">
              <MessageSquare size={24}/>
            </button>
         )}
      </div>

      {/* Modal Transaksi Baru */}
      {showModal === 'addTrx' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className={`w-full max-w-md rounded-3xl p-8 shadow-2xl ${isDarkMode ? 'bg-slate-900 border border-slate-800' : 'bg-white border-slate-100'}`}>
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black">Transaksi Baru</h3>
              <button onClick={() => setShowModal(null)} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full"><X size={20}/></button>
            </div>
            <form onSubmit={handleAddTransaction} className="space-y-4">
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase">Customer</label>
                <select name="customerId" required className="w-full mt-1 bg-slate-100 dark:bg-slate-800 p-3 rounded-xl outline-none text-sm font-bold">
                  {customers.map(c => <option key={c.id} value={c.id}>{c.nama}</option>)}
                </select>
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase">Produk</label>
                <select name="produkId" required className="w-full mt-1 bg-slate-100 dark:bg-slate-800 p-3 rounded-xl outline-none text-sm font-bold">
                  {products.map(p => <option key={p.id} value={p.id}>{p.nama} ({new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(p.harga)})</option>)}
                </select>
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase">Kuantitas</label>
                <input name="qty" type="number" defaultValue="1" min="1" required className="w-full mt-1 bg-slate-100 dark:bg-slate-800 p-3 rounded-xl outline-none text-sm font-bold" />
              </div>
              <button type="submit" className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black shadow-xl shadow-blue-500/20 hover:bg-blue-700 transition-all mt-4">Simpan Transaksi</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, Users, Package, LineChart, FileEdit, ShieldCheck, 
  LogOut, Menu, X, Sun, Moon, Search, Plus, Phone, MessageSquare, 
  Send, Trash2, Edit3, ChevronDown, Check, AlertCircle, TrendingUp, Clock
} from 'lucide-react';

// --- Interfaces ---
interface User {
  id: string;
  username: string;
  role: 'superadmin' | 'admin' | 'sales' | 'stockist';
  lastLogin: string;
}

interface Customer {
  id: string;
  nama: string;
  perusahaan: string;
  email: string;
  phone: string;
  sales: string;
}

interface Product {
  id: string;
  nama: string;
  sku: string;
  harga: number;
  stok: number;
}

interface Transaction {
  id: string;
  noTransaksi: string;
  tanggal: string;
  customerName: string;
  produkNama: string;
  nilai: number;
  status: 'Selesai' | 'Proses' | 'Batal';
  sales: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk' | 'users' | 'access';

const App: React.FC = () => {
  // --- States ---
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedMonth, setSelectedMonth] = useState('Semua Bulan');

  // --- Database States ---
  const [users, setUsers] = useState<User[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Current User Mock (Identik dengan gambar: superadmin)
  const [currentUser] = useState<User>({ id: '1', username: 'superadmin', role: 'superadmin', lastLogin: 'Now' });

  // --- Initialization ---
  useEffect(() => {
    const savedData = (key: string) => {
      const data = localStorage.getItem(key);
      return data ? JSON.parse(data) : null;
    };

    setUsers(savedData('mypanca_users') || [
      { id: '1', username: 'superadmin', role: 'superadmin', lastLogin: '2023-10-27' },
      { id: '2', username: 'maria', role: 'sales', lastLogin: '2023-10-26' }
    ]);

    setCustomers(savedData('mypanca_customers') || []);
