  Send, Trash2, Edit3, ChevronDown, Check, AlertCircle, TrendingUp, Clock,
  Printer, History, Briefcase
} from 'lucide-react';

// --- Interfaces ---
interface Customer {
  id: string;
  nama: string;
  sales: string;
}

interface Product {
  id: string;
  nama: string;
  sku: string;
  harga: number;
  stok: number;
}

interface Transaction {
  id: string;
  noTrx: string;
  tanggal: string;
  customerName: string;
  produkNama: string;
  qty: string;
  sku: string;
  nilai: number;
  status: 'Selesai' | 'Progress' | 'Batal';
  sales: string;
  keterangan: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk' | 'users' | 'access';

const App: React.FC = () => {
  // --- UI States ---
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
