  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // --- Filter States ---
  const [filterCustomer, setFilterCustomer] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [filterProduct, setFilterProduct] = useState('');
  const [filterSKU, setFilterSKU] = useState('');

  // --- Initial Data Load (Identik dengan Gambar) ---
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_v2_transactions');
    if (savedTrx) {
      setTransactions(JSON.parse(savedTrx));
      const savedCust = localStorage.getItem('mypanca_v2_customers');
      const savedProd = localStorage.getItem('mypanca_v2_products');
      if (savedCust) setCustomers(JSON.parse(savedCust));
      if (savedProd) setProducts(JSON.parse(savedProd));
    } else {
      // Data Default jika kosong
      const sampleCust = [
        { id: 'c1', nama: 'Ervani PT Sari Bumbu Indonesia', sales: 'maria' },
        { id: 'c2', nama: 'Agus Susanto', sales: 'maria' },
        { id: 'c3', nama: 'Jemmy', sales: 'maria' },
        { id: 'c4', nama: 'Indratama PT Hitachi', sales: 'maria' },
