      const sampleProd = [
        { id: 'p1', nama: 'Fumilikuid 7 Kg', sku: 'FL 7 Kg 9PT. Panca Prima', harga: 2646400, stok: 100 },
        { id: 'p2', nama: 'Fumiphos Dus', sku: 'F DUS4PT. Panca Prima Wij', harga: 7100000, stok: 108 },
