        { id: '1', noTrx: 'TRX-5', tanggal: '06/01/2026', customerName: 'Ervani PT Sari Bumbu Indonesia', produkNama: 'Fumilikuid 7 Kg', qty: '1|1', sku: 'FL 7 Kg 9PT. Panca Prima', nilai: 2646400, status: 'Progress', sales: 'maria', keterangan: 'Pesan sud...' },
        { id: '2', noTrx: 'TRX-10', tanggal: '05/01/2026', customerName: 'Agus Susanto', produkNama: 'Fumiphos Dus', qty: '1|1', sku: 'F DUS4PT. Panca Prima Wij', nilai: 6244000, status: 'Selesai', sales: 'maria', keterangan: 'Transaksi ...' },
        { id: '3', noTrx: 'TRX-20', tanggal: '30/12/2025', customerName: 'Jemmy', produkNama: 'Plastik Sungkup 2...', qty: '2|1', sku: 'PS 20 X 2019PT. Panca Pri', nilai: 12900000, status: 'Selesai', sales: 'maria', keterangan: 'Transaksi ...' },
        { id: '4', noTrx: 'TRX-25', tanggal: '29/12/2025', customerName: 'Indratama PT Hitachi', produkNama: 'kontak seminar 19 ...', qty: '1', sku: 'Seminar 19-0843PT. Panca', nilai: 100, status: 'Batal', sales: 'maria', keterangan: 'dapat kont...' },
      ];
      setCustomers(sampleCust);
      setProducts(sampleProd);
      setTransactions(sampleTrx);
    }
