  // Sync to Local Storage
  useEffect(() => {
    if (transactions.length > 0) {
      localStorage.setItem('mypanca_v2_customers', JSON.stringify(customers));
      localStorage.setItem('mypanca_v2_products', JSON.stringify(products));
      localStorage.setItem('mypanca_v2_transactions', JSON.stringify(transactions));
    }
  }, [customers, products, transactions]);

  // --- Filter Logic ---
  const filteredTrx = useMemo(() => {
    return transactions.filter(t => {
      const matchCust = filterCustomer === '' || t.customerName === filterCustomer;
      const matchStat = filterStatus === '' || t.status === filterStatus;
      return matchCust && matchStat;
    });
  }, [transactions, filterCustomer, filterStatus]);

