    return products.filter(p => {
      const matchName = filterProduct === '' || p.nama === filterProduct;
      const matchSKU = filterSKU === '' || p.sku === filterSKU;
      return matchName && matchSKU;
    });
  }, [products, filterProduct, filterSKU]);

