import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, Users, Package, LineChart, FileEdit, ShieldCheck, 
  LogOut, Menu, X, Sun, Moon, Search, Plus, Phone, MessageSquare, 
  Send, Trash2, Edit3, ChevronDown, Check, AlertCircle, TrendingUp, Clock,
  Printer, History, Briefcase, ExternalLink, Calculator, Save, PlusCircle
} from 'lucide-react';

// --- Interfaces & Types ---
type Role = 'superadmin' | 'admin' | 'sales' | 'purchasing' | 'pajak' | 'finance' | 'stockist' | 'audit' | 'engineer';

interface User {
  username: string;
  role: Role;
}

interface ProductLot {
  lot: 1 | 2 | 3;
  sku: string;
  stock: number;
  hpp: number;
  hargaJual: number;
}

interface Product {
  id: string;
  nama: string;
  kode: string;
  lots: ProductLot[];
}

interface Customer {
  id: string;
  kode: string;
  nama: string;
  jenis: string;
  phone: string;
  email: string;
  alamat: string;
  sales: string;
  status: 'Aktif' | 'Nonaktif';
}

interface TransactionItem {
  produkId: string;
  nama: string;
  sku: string;
  harga: number;
  qty: number;
  diskon: number;
}

interface Transaction {
  id: string;
  noTrx: string;
  tanggal: string;
  customerName: string;
  items: TransactionItem[];
  nilaiProyek: number;
  ppn: number;
  ongkir: number;
  jasaKirim: string;
  status: 'Selesai' | 'Progress' | 'Batal';
  sales: string;
  keterangan: string;
  skuHistory: string; // SKU+Qty | SKU+Qty
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk' | 'users' | 'access';

const App: React.FC = () => {
  // --- UI States ---
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [currentUser, setCurrentUser] = useState<User>({ username: 'superadmin', role: 'superadmin' });

  // --- Data States ---
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // --- Filter States ---
  const [filterCustomer, setFilterCustomer] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [filterProduct, setFilterProduct] = useState('');
  const [filterSKU, setFilterSKU] = useState('');

  // --- Initial Data Load ---
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_v3_transactions');
    const savedCust = localStorage.getItem('mypanca_v3_customers');
    const savedProd = localStorage.getItem('mypanca_v3_products');

    if (savedTrx && savedCust && savedProd) {
      setTransactions(JSON.parse(savedTrx));
      setCustomers(JSON.parse(savedCust));
      setProducts(JSON.parse(savedProd));
    } else {
      // Default Mock Data based on your GS code
      const sampleCust: Customer[] = [
        { id: 'c1', kode: 'TN001', nama: 'Ervani PT Sari Bumbu Indonesia', jenis: 'Perusahaan', phone: '0812345678', email: 'ervani@sari.com', alamat: 'Jl. Bumbu No 1', sales: 'maria', status: 'Aktif' },
        { id: 'c2', kode: 'TN002', nama: 'Agus Susanto', jenis: 'Perorangan', phone: '0812223334', email: 'agus@gmail.com', alamat: 'Perum Indah Blok A', sales: 'maria', status: 'Aktif' },
      ];
      const sampleProd: Product[] = [
        { 
          id: 'p1', nama: 'Fumilikuid 7 Kg', kode: 'FL', 
          lots: [
            { lot: 1, sku: 'FL 7 Kg 9PT. Panca Prima', stock: 100, hpp: 2000000, hargaJual: 2646400 },
            { lot: 2, sku: '', stock: 0, hpp: 0, hargaJual: 0 },
            { lot: 3, sku: '', stock: 0, hpp: 0, hargaJual: 0 }
          ]
        },
        { 
          id: 'p2', nama: 'Fumiphos Dus', kode: 'F', 
          lots: [
            { lot: 1, sku: 'F DUS4PT. Panca Prima Wij', stock: 108, hpp: 5000000, hargaJual: 7100000 },
            { lot: 2, sku: '', stock: 0, hpp: 0, hargaJual: 0 },
            { lot: 3, sku: '', stock: 0, hpp: 0, hargaJual: 0 }
          ]
        }
      ];
      const sampleTrx: Transaction[] = [
        { 
          id: '1', noTrx: 'TRX-1', tanggal: '2026-01-06', customerName: 'Ervani PT Sari Bumbu Indonesia', 
          items: [{ produkId: 'p1', nama: 'Fumilikuid 7 Kg', sku: 'FL 7 Kg 9PT. Panca Prima', harga: 2646400, qty: 1, diskon: 0 }],
          nilaiProyek: 2646400, ppn: 0, ongkir: 0, jasaKirim: '', status: 'Progress', sales: 'maria', keterangan: 'Pesan sudah diproses', skuHistory: 'FL 7 Kg 9PT. Panca Prima+1'
        }
      ];
      setCustomers(sampleCust);
      setProducts(sampleProd);
      setTransactions(sampleTrx);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_v3_transactions', JSON.stringify(transactions));
    localStorage.setItem('mypanca_v3_customers', JSON.stringify(customers));
    localStorage.setItem('mypanca_v3_products', JSON.stringify(products));
  }, [transactions, customers, products]);

  // --- Core Logistics Logic (Replicating code.gs) ---

  const deductStock = (skuHistory: string) => {
    const updatedProducts = [...products];
    skuHistory.split(' | ').forEach(entry => {
      const [sku, qtyStr] = entry.split('+');
      const qty = parseFloat(qtyStr);
      updatedProducts.forEach(p => {
        p.lots.forEach(l => {
          if (l.sku === sku) l.stock = Math.max(0, l.stock - qty);
        });
      });
    });
    setProducts(updatedProducts);
  };

  const restoreStock = (skuHistory: string) => {
    const updatedProducts = [...products];
    skuHistory.split(' | ').forEach(entry => {
      const [sku, qtyStr] = entry.split('+');
      const qty = parseFloat(qtyStr);
      updatedProducts.forEach(p => {
        p.lots.forEach(l => {
          if (l.sku === sku) l.stock += qty;
        });
      });
    });
    setProducts(updatedProducts);
  };

  const updateTrxStatus = (id: string, newStatus: Transaction['status']) => {
    const trx = transactions.find(t => t.id === id);
    if (!trx) return;

    const oldStatus = trx.status;
    if (oldStatus !== 'Selesai' && newStatus === 'Selesai') {
      deductStock(trx.skuHistory);
    } else if (oldStatus === 'Selesai' && newStatus !== 'Selesai') {
      restoreStock(trx.skuHistory);
    }

    setTransactions(transactions.map(t => t.id === id ? { ...t, status: newStatus } : t));
  };

  // --- Filtering ---
  const filteredTransactions = transactions.filter(t => {
    const matchCust = !filterCustomer || t.customerName === filterCustomer;
    const matchStat = !filterStatus || t.status === filterStatus;
    return matchCust && matchStat;
  });

  const allProductLots = useMemo(() => {
    const lots: { productName: string, lotData: ProductLot }[] = [];
    products.forEach(p => {
      p.lots.forEach(l => {
        if (l.sku) lots.push({ productName: p.nama, lotData: l });
      });
    });
    return lots;
  }, [products]);

  const filteredLots = allProductLots.filter(item => {
    const matchName = !filterProduct || item.productName === filterProduct;
    const matchSKU = !filterSKU || item.lotData.sku === filterSKU;
    return matchName && matchSKU;
  });

  // --- Sub-components ---
  const SidebarItem = ({ id, icon: Icon, label }: { id: Panel, icon: any, label: string }) => (
    <button 
      onClick={() => { setActivePanel(id); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all mb-1 ${
        activePanel === id 
          ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20 translate-x-1' 
          : 'text-slate-500 hover:bg-slate-100 hover:text-blue-600 dark:hover:bg-slate-800'
      }`}
    >
      <Icon size={18} />
      <span className="text-sm font-bold">{label}</span>
    </button>
  );

  const StatusBadge = ({ status }: { status: Transaction['status'] }) => {
    const colors = {
      Selesai: 'bg-emerald-100 text-emerald-600 border-emerald-200',
      Progress: 'bg-amber-100 text-amber-600 border-amber-200',
      Batal: 'bg-rose-100 text-rose-600 border-rose-200'
