  npwp: string;
}

interface TransactionItem {
  produkId: string;
  nama: string;
  sku: string;
  harga: number;
  qty: number;
  diskon: number;
}

interface Transaction {
  id: string;
  noTrx: string;
  tanggal: string;
  customerName: string;
  items: TransactionItem[];
  nilaiProyek: number;
  ppn: number;
  ongkir: number;
  jasaKirim: string;
  status: 'Selesai' | 'Progress' | 'Batal';
  sales: string;
  keterangan: string;
  skuHistory: string;
}

