  const [currentProd, setCurrentProd] = useState<Partial<Product>>({ lots: [] });

  // --- Data States ---
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentUser] = useState<User>({ username: 'superadmin', role: 'superadmin' });

  // --- Filter States ---
  const [filterCustomer, setFilterCustomer] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [filterProduct, setFilterProduct] = useState('');
  const [filterSKU, setFilterSKU] = useState('');

  // --- Persistence ---
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');

    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
  }, [transactions, customers, products]);

  // --- Business Logic Replicas ---

  const generateNoTrx = () => `TRX-${transactions.length + 1}`;

  const handleAddTrxItem = () => {
    const newItem: TransactionItem = { produkId: '', nama: '', sku: '', harga: 0, qty: 1, diskon: 0 };
    setCurrentTrx(prev => ({ ...prev, items: [...(prev.items || []), newItem] }));
  };

  const handleUpdateStock = (skuHistory: string, type: 'deduct' | 'restore') => {
    setProducts(prev => prev.map(p => ({
      ...p,
      lots: p.lots.map(l => {
        const entries = skuHistory.split(' | ');
        const entry = entries.find(e => e.split('+')[0] === l.sku);
        if (entry) {
          const qty = parseFloat(entry.split('+')[1]);
          return { ...l, stock: type === 'deduct' ? l.stock - qty : l.stock + qty };
        }
        return l;
      })
    })));
  };

  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data transaksi");

    const skuHistory = currentTrx.items.map(i => `${i.sku}+${i.qty}`).join(' | ');
    const newTrx: Transaction = {
      ...(currentTrx as Transaction),
      id: currentTrx.id || Date.now().toString(),
      noTrx: currentTrx.noTrx || generateNoTrx(),
      skuHistory
    };

    if (newTrx.status === 'Selesai') handleUpdateStock(skuHistory, 'deduct');

    if (currentTrx.id) {
      setTransactions(prev => prev.map(t => t.id === newTrx.id ? newTrx : t));
    } else {
      setTransactions(prev => [newTrx, ...prev]);
    }
    setShowModal(null);
    setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0] });
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi");
    const newCust: Customer = {
      ...(currentCust as Customer),
      id: currentCust.id || Date.now().toString(),
      kode: currentCust.kode || `TN${String(customers.length + 1).padStart(3, '0')}`
    };
    if (currentCust.id) {
      setCustomers(prev => prev.map(c => c.id === newCust.id ? newCust : c));
    } else {
      setCustomers(prev => [...prev, newCust]);
    }
    setShowModal(null);
    setCurrentCust({});
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Nama & Kode wajib");
    const newProd: Product = {
      ...(currentProd as Product),
      id: currentProd.id || Date.now().toString(),
      lots: currentProd.lots?.length ? currentProd.lots : [
        { lot: 1, sku: '', stock: 0, hpp: 0, hargaJual: 0 },
        { lot: 2, sku: '', stock: 0, hpp: 0, hargaJual: 0 },
        { lot: 3, sku: '', stock: 0, hpp: 0, hargaJual: 0 }
      ] as ProductLot[]
    };
    if (currentProd.id) {
      setProducts(prev => prev.map(p => p.id === newProd.id ? newProd : p));
    } else {
      setProducts(prev => [...prev, newProd]);
    }
    setShowModal(null);
    setCurrentProd({ lots: [] });
  };

  // --- Calculations ---
  const totals = useMemo(() => {
    const itemsTotal = currentTrx.items?.reduce((acc, i) => acc + (i.harga * i.qty - i.diskon), 0) || 0;
    const ppn = currentTrx.ppn ? itemsTotal * 0.11 : 0;
    const grandTotal = itemsTotal + ppn + (Number(currentTrx.ongkir) || 0);
    return { itemsTotal, ppn, grandTotal };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir]);

  // --- Filters ---
  const filteredTransactions = transactions.filter(t => 
    (!filterCustomer || t.customerName === filterCustomer) && 
    (!filterStatus || t.status === filterStatus)
  );

  const flatLots = useMemo(() => {
    return products.flatMap(p => p.lots.filter(l => l.sku).map(l => ({ ...l, productName: p.nama })));
  }, [products]);

  // --- UI Renderers ---
  const SidebarItem = ({ id, icon: Icon, label }: { id: Panel, icon: any, label: string }) => (
    <button 
      onClick={() => { setActivePanel(id); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all mb-1 ${
        activePanel === id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'
      }`}
    >
      <Icon size={18} />
      <span className="text-sm font-bold">{label}</span>
    </button>
  );

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 transform transition-transform duration-300 lg:translate-x-0 lg:static ${
        isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
      } ${isDarkMode ? 'bg-[#1e293b] border-slate-800' : 'bg-white border-slate-200'} border-r`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-4 mb-10 px-2">
            <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-6"><Package size={24} /></div>
            <div>
              <h1 className="font-black text-xl tracking-tight leading-none">MyPanca</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Business CRM</p>
            </div>
          </div>
          <nav className="flex-1">
            <SidebarItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <SidebarItem id="tracking" icon={LineChart} label="Transaksi" />
            <SidebarItem id="customer" icon={Users} label="Customer" />
            <SidebarItem id="produk" icon={Package} label="Produk & Stock" />
          </nav>
          <div className="mt-auto p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-500 rounded-xl flex items-center justify-center text-white font-bold">S</div>
            <div className="flex-1 min-w-0">
              <p className="text-xs font-bold truncate">superadmin</p>
              <p className="text-[9px] text-slate-500 uppercase font-black">Online</p>
            </div>
            <button className="p-2 text-slate-400 hover:text-rose-500"><LogOut size={16}/></button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 h-screen overflow-hidden">
        <header className="h-20 flex items-center justify-between px-8 border-b bg-white/80 dark:bg-[#0f172a]/80 backdrop-blur-xl sticky top-0 z-40">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 bg-slate-100 rounded-xl"><Menu size={20} /></button>
            <h2 className="text-2xl font-black tracking-tight">{activePanel.toUpperCase()}</h2>
          </div>
          <div className="flex items-center gap-4">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="w-10 h-10 flex items-center justify-center rounded-xl bg-slate-100 dark:bg-slate-800">
              {isDarkMode ? <Sun size={20} className="text-yellow-400" /> : <Moon size={20} />}
            </button>
            <div className="relative hidden md:block">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input type="text" placeholder="Cari..." className="pl-12 pr-6 py-2 bg-slate-100 dark:bg-slate-800 border-none rounded-2xl text-sm w-64 outline-none" />
            </div>
          </div>
        </header>

        <div className="flex-1 p-8 overflow-y-auto">

          {/* Dashboard Summary */}
          {activePanel === 'dashboard' && (
            <div className="space-y-8 animate-in fade-in duration-500">
               <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                  {[
                    { label: 'Revenue', value: `Rp${transactions.filter(t=>t.status==='Selesai').reduce((a,b)=>a+b.nilaiProyek,0).toLocaleString()}`, icon: LineChart, color: 'text-blue-600', bg: 'bg-blue-100' },
                    { label: 'Customer', value: customers.length, icon: Users, color: 'text-emerald-600', bg: 'bg-emerald-100' },
                    { label: 'Progress', value: transactions.filter(t=>t.status==='Progress').length, icon: Clock, color: 'text-amber-600', bg: 'bg-amber-100' },
                    { label: 'Batal', value: transactions.filter(t=>t.status==='Batal').length, icon: AlertCircle, color: 'text-rose-600', bg: 'bg-rose-100' },
                  ].map((stat, i) => (
                    <div key={i} className="bg-white dark:bg-slate-900 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
                      <div className={`w-12 h-12 ${stat.bg} ${stat.color} rounded-2xl flex items-center justify-center mb-4`}><stat.icon size={24}/></div>
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{stat.label}</p>
                      <p className={`text-2xl font-black ${stat.color}`}>{stat.value}</p>
                    </div>
                  ))}
               </div>

               <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-8 shadow-sm">
                  <h3 className="text-xl font-black mb-6">Pending Deals</h3>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {transactions.filter(t => t.status === 'Progress').map(t => (
                      <div key={t.id} className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-3xl border border-slate-100 dark:border-slate-700">
                        <div className="flex items-center gap-4 mb-4">
                          <div className="w-12 h-12 bg-white dark:bg-slate-800 rounded-xl flex items-center justify-center font-bold text-blue-600">{t.customerName[0]}</div>
                          <div className="flex-1 min-w-0">
                            <h4 className="font-black text-sm truncate">{t.customerName}</h4>
                            <p className="text-[10px] font-bold text-slate-400">{t.sales}</p>
                          </div>
                        </div>
                        <div className="flex justify-between items-center text-xs font-bold">
                          <span className="text-slate-400">Total</span>
                          <span className="text-blue-600">Rp{t.nilaiProyek.toLocaleString()}</span>
                        </div>
                      </div>
                    ))}
                  </div>
               </div>
            </div>
          )}

          {/* Transaksi Panel */}
          {activePanel === 'tracking' && (
            <div className="space-y-6 animate-in fade-in duration-500">
              <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-8">
                <div className="flex justify-between items-center mb-8">
                  <h3 className="text-2xl font-black">Transaksi</h3>
                  <button onClick={() => { setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0] }); setShowModal('trx'); }} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-sm flex items-center gap-2 hover:bg-blue-700 transition-all">
                    <Plus size={20} /> Tambah Transaksi
                  </button>
                </div>

                <div className="flex gap-4 mb-8">
                  <select onChange={e => setFilterCustomer(e.target.value)} className="appearance-none bg-slate-100 dark:bg-slate-800 rounded-full px-6 py-3 text-sm font-bold min-w-[200px] outline-none border-2 border-transparent focus:border-blue-500">
                    <option value="">Semua Customer</option>
                    {customers.map(c => <option key={c.id} value={c.nama}>{c.nama}</option>)}
                  </select>
                  <select onChange={e => setFilterStatus(e.target.value)} className="appearance-none bg-slate-100 dark:bg-slate-800 rounded-full px-6 py-3 text-sm font-bold min-w-[150px] outline-none border-2 border-transparent focus:border-blue-500">
                    <option value="">Semua Status</option>
                    <option value="Progress">Progress</option>
                    <option value="Selesai">Selesai</option>
                    <option value="Batal">Batal</option>
                  </select>
                </div>

                <div className="overflow-x-auto rounded-2xl">
                  <table className="w-full text-left text-xs">
                    <thead>
                      <tr className="bg-slate-50 dark:bg-slate-800/50 text-slate-400 font-black uppercase tracking-widest border-b dark:border-slate-800">
                        <th className="px-6 py-4">Tanggal</th>
                        <th className="px-6 py-4">Customer</th>
                        <th className="px-6 py-4">Produk</th>
                        <th className="px-6 py-4">Nilai</th>
                        <th className="px-6 py-4">Status</th>
                        <th className="px-6 py-4">Aksi</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y dark:divide-slate-800">
                      {filteredTransactions.map(t => (
                        <tr key={t.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-all">
                          <td className="px-6 py-5 font-bold">{t.tanggal}</td>
                          <td className="px-6 py-5 font-black text-slate-800 dark:text-slate-100">{t.customerName}</td>
                          <td className="px-6 py-5 font-bold truncate max-w-[150px]">{t.items.map(i=>i.nama).join(', ')}</td>
                          <td className="px-6 py-5 font-black text-blue-600">Rp{t.nilaiProyek.toLocaleString()}</td>
                          <td className="px-6 py-5">
                            <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${
                              t.status === 'Selesai' ? 'bg-emerald-100 text-emerald-600' :
                              t.status === 'Batal' ? 'bg-rose-100 text-rose-600' : 'bg-amber-100 text-amber-600'
                            }`}>{t.status}</span>
                          </td>
                          <td className="px-6 py-5">
                            <div className="flex gap-2">
                              <button onClick={() => { setCurrentTrx(t); setShowModal('trx'); }} className="p-2 bg-amber-100 text-amber-600 rounded-lg hover:bg-amber-600 hover:text-white"><Edit3 size={14}/></button>
                              <button onClick={() => setTransactions(prev => prev.filter(x => x.id !== t.id))} className="p-2 bg-rose-100 text-rose-600 rounded-lg hover:bg-rose-600 hover:text-white"><Trash2 size={14}/></button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {/* Customer Panel */}
          {activePanel === 'customer' && (
            <div className="animate-in fade-in duration-500">
              <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-8">
                <div className="flex justify-between items-center mb-8">
                  <h3 className="text-2xl font-black">Customer</h3>
                  <button onClick={() => { setCurrentCust({}); setShowModal('cust'); }} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-sm flex items-center gap-2 hover:bg-blue-700 transition-all">
                    <Plus size={20} /> Tambah Customer
                  </button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  {customers.map(c => (
                    <div key={c.id} className="bg-slate-50 dark:bg-slate-800/40 p-6 rounded-3xl border border-slate-100 dark:border-slate-700 hover:border-blue-500 transition-all">
                      <div className="w-14 h-14 bg-blue-100 text-blue-600 rounded-2xl flex items-center justify-center font-black text-xl mb-4">{c.nama[0]}</div>
                      <h4 className="font-black text-sm mb-1">{c.nama}</h4>
                      <p className="text-[10px] text-slate-400 font-bold uppercase mb-4">{c.kode}</p>
                      <div className="space-y-2 mb-6">
                        <div className="flex items-center gap-2 text-xs text-slate-500"><Phone size={12}/> {c.phone}</div>
                        <div className="flex items-center gap-2 text-xs text-slate-500 truncate"><Briefcase size={12}/> {c.alamat}</div>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => { setCurrentCust(c); setShowModal('cust'); }} className="flex-1 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-[10px] font-black uppercase hover:bg-blue-600 hover:text-white transition-all">Edit</button>
                        <button onClick={() => setCustomers(prev => prev.filter(x => x.id !== c.id))} className="p-2 text-rose-500 hover:bg-rose-100 rounded-xl transition-all"><Trash2 size={16}/></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* Produk Panel */}
          {activePanel === 'produk' && (
            <div className="space-y-6 animate-in fade-in duration-500">
              <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-8">
                <div className="flex justify-between items-center mb-8">
                  <h3 className="text-2xl font-black">Produk & Stock</h3>
                  <button onClick={() => { setCurrentProd({ lots: [] }); setShowModal('prod'); }} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-sm flex items-center gap-2 hover:bg-blue-700 transition-all">
                    <Plus size={20} /> Tambah Produk
                  </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  {flatLots.map((l, i) => (
                    <div key={i} className="bg-slate-50 dark:bg-slate-800/40 p-6 rounded-3xl border border-slate-100 dark:border-slate-700 group hover:border-blue-500 transition-all">
                      <div className="w-12 h-12 bg-white dark:bg-slate-800 rounded-xl flex items-center justify-center text-blue-600 mb-4 shadow-sm group-hover:rotate-6 transition-all"><Package size={24}/></div>
                      <h4 className="font-black text-sm truncate">{l.productName}</h4>
                      <p className="text-[10px] font-mono text-slate-400 mb-4">{l.sku}</p>
                      <div className="space-y-3">
                        <div className="flex justify-between text-[11px] font-bold">
                          <span className="text-slate-400">STOCK</span>
                          <span className={`${l.stock < 10 ? 'text-rose-500' : 'text-slate-700 dark:text-slate-200'}`}>{l.stock} Unit</span>
                        </div>
                        <div className="flex justify-between text-[11px] font-bold">
                          <span className="text-slate-400">HARGA</span>
                          <span className="text-blue-600">Rp{l.hargaJual.toLocaleString()}</span>
                        </div>
