      </main>

      {/* --- MODALS --- */}

      {/* MODAL TRANSAKSI */}
      {showModal === 'trx' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 overflow-y-auto">
          <div className="bg-white dark:bg-[#1e293b] w-full max-w-4xl rounded-[2.5rem] shadow-2xl p-8 max-h-[90vh] overflow-y-auto custom-scrollbar">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-2xl font-black">Tambah / Edit Transaksi</h3>
              <button onClick={() => setShowModal(null)} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl"><X size={24}/></button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Customer</label>
                <select 
                  value={currentTrx.customerName || ''}
                  onChange={e => setCurrentTrx(prev => ({ ...prev, customerName: e.target.value, sales: customers.find(c=>c.nama===e.target.value)?.sales }))}
                  className="w-full bg-slate-50 dark:bg-slate-900 border-2 border-transparent focus:border-blue-500 rounded-2xl px-6 py-3.5 font-bold outline-none transition-all"
                >
                  <option value="">Pilih Customer</option>
                  {customers.map(c => <option key={c.id} value={c.nama}>{c.nama}</option>)}
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Tanggal</label>
                <input type="date" value={currentTrx.tanggal} onChange={e => setCurrentTrx(prev => ({ ...prev, tanggal: e.target.value }))} className="w-full bg-slate-50 dark:bg-slate-900 border-2 border-transparent focus:border-blue-500 rounded-2xl px-6 py-3.5 font-bold outline-none" />
              </div>
            </div>

            <div className="space-y-4 mb-8">
              <div className="flex justify-between items-center">
                <h4 className="font-black text-sm uppercase tracking-widest text-slate-400">Item Produk</h4>
                <button onClick={handleAddTrxItem} className="text-blue-600 font-black text-xs flex items-center gap-1 hover:underline"><PlusCircle size={14}/> Tambah Item</button>
              </div>
              <div className="space-y-3">
                {currentTrx.items?.map((item, idx) => (
                  <div key={idx} className="grid grid-cols-1 md:grid-cols-6 gap-3 p-4 bg-slate-50 dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800 items-end">
                    <div className="md:col-span-2 space-y-1">
                      <label className="text-[9px] font-black text-slate-400">Produk</label>
                      <select 
                        value={item.nama}
                        onChange={e => {
                          const prod = products.find(p => p.nama === e.target.value);
                          const firstLot = prod?.lots.find(l => l.sku);
                          const newItems = [...(currentTrx.items || [])];
                          newItems[idx] = { ...item, nama: e.target.value, sku: firstLot?.sku || '', harga: firstLot?.hargaJual || 0 };
                          setCurrentTrx(prev => ({ ...prev, items: newItems }));
                        }}
                        className="w-full bg-white dark:bg-slate-800 rounded-xl px-4 py-2 text-xs font-bold border-none outline-none"
                      >
                        <option value="">Pilih</option>
                        {products.map(p => <option key={p.id} value={p.nama}>{p.nama}</option>)}
                      </select>
                    </div>
                    <div className="md:col-span-2 space-y-1">
                      <label className="text-[9px] font-black text-slate-400">SKU</label>
                      <select 
                        value={item.sku}
                        onChange={e => {
                          const lot = products.find(p => p.nama === item.nama)?.lots.find(l => l.sku === e.target.value);
                          const newItems = [...(currentTrx.items || [])];
                          newItems[idx] = { ...item, sku: e.target.value, harga: lot?.hargaJual || 0 };
                          setCurrentTrx(prev => ({ ...prev, items: newItems }));
                        }}
                        className="w-full bg-white dark:bg-slate-800 rounded-xl px-4 py-2 text-xs font-bold border-none outline-none"
                      >
                        <option value="">Pilih</option>
                        {products.find(p => p.nama === item.nama)?.lots.filter(l => l.sku).map(l => <option key={l.sku} value={l.sku}>{l.sku}</option>)}
                      </select>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-slate-400">Qty</label>
                      <input 
                        type="number" 
                        value={item.qty} 
                        onChange={e => {
                          const newItems = [...(currentTrx.items || [])];
                          newItems[idx] = { ...item, qty: parseFloat(e.target.value) || 0 };
                          setCurrentTrx(prev => ({ ...prev, items: newItems }));
                        }} 
                        className="w-full bg-white dark:bg-slate-800 rounded-xl px-4 py-2 text-xs font-bold border-none outline-none" 
                      />
                    </div>
                    <button onClick={() => setCurrentTrx(prev => ({ ...prev, items: prev.items?.filter((_, i) => i !== idx) }))} className="p-2 text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-xl transition-all"><Trash size={14}/></button>
                  </div>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
              <div className="space-y-4">
                <div className="p-6 bg-blue-50 dark:bg-blue-900/20 rounded-3xl space-y-3 border border-blue-100 dark:border-blue-900/30">
                  <div className="flex justify-between items-center text-xs font-bold"><span className="text-slate-400">SUBTOTAL</span><span className="text-slate-600 dark:text-slate-300">Rp{totals.itemsTotal.toLocaleString()}</span></div>
                  <div className="flex justify-between items-center text-xs font-bold"><span className="text-slate-400">PPN (11%)</span><span className="text-slate-600 dark:text-slate-300">Rp{totals.ppn.toLocaleString()}</span></div>
                  <div className="h-px bg-blue-200 dark:bg-blue-800"></div>
                  <div className="flex justify-between items-center text-sm font-black"><span className="text-blue-600">GRAND TOTAL</span><span className="text-blue-600">Rp{totals.grandTotal.toLocaleString()}</span></div>
                </div>
              </div>
              <div className="space-y-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Status</label>
                  <select value={currentTrx.status} onChange={e => setCurrentTrx(p=>({...p, status: e.target.value as any}))} className="w-full bg-slate-50 dark:bg-slate-900 border-none rounded-2xl px-6 py-3.5 font-bold outline-none">
                    <option value="Progress">Progress</option>
                    <option value="Selesai">Selesai</option>
                    <option value="Batal">Batal</option>
