                </div>
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Keterangan</label>
                   <textarea value={currentTrx.keterangan || ''} onChange={e=>setCurrentTrx(p=>({...p, keterangan: e.target.value}))} className="w-full bg-slate-50 dark:bg-slate-900 border-none rounded-2xl px-6 py-3.5 text-xs font-bold h-24 outline-none" placeholder="Catatan transaksi..."></textarea>
                </div>
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t dark:border-slate-800">
              <button onClick={() => setShowModal(null)} className="px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest text-slate-500 hover:bg-slate-100 transition-all">Batal</button>
              <button onClick={saveTransaction} className="px-10 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl shadow-blue-600/30 hover:bg-blue-700 transition-all">Simpan Transaksi</button>
            </div>
          </div>
