      {/* MODAL CUSTOMER */}
      {showModal === 'cust' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-[#1e293b] w-full max-w-xl rounded-[2.5rem] p-8">
