              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Alamat</label>
                <textarea value={currentCust.alamat || ''} onChange={e=>setCurrentCust(p=>({...p, alamat: e.target.value}))} className="w-full bg-slate-50 dark:bg-slate-900 border-none rounded-2xl px-6 py-3.5 text-xs font-bold h-24 outline-none" placeholder="Alamat lengkap..."></textarea>
              </div>
            </div>
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowModal(null)} className="px-6 py-3 rounded-xl font-bold text-slate-500 hover:bg-slate-100">Batal</button>
              <button onClick={saveCustomer} className="px-8 py-3 bg-blue-600 text-white rounded-xl font-black shadow-lg shadow-blue-600/20">Simpan Customer</button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL PRODUCT */}
      {showModal === 'prod' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 overflow-y-auto">
          <div className="bg-white dark:bg-[#1e293b] w-full max-w-2xl rounded-[2.5rem] p-8 max-h-[90vh] overflow-y-auto">
            <h3 className="text-2xl font-black mb-8">Data Produk & Lot</h3>
            <div className="grid grid-cols-2 gap-4 mb-8">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Nama Produk</label>
                <input value={currentProd.nama || ''} onChange={e=>setCurrentProd(p=>({...p, nama: e.target.value}))} className="w-full bg-slate-50 dark:bg-slate-900 border-none rounded-2xl px-6 py-3.5 font-bold outline-none" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Kode (Prefix SKU)</label>
                <input value={currentProd.kode || ''} onChange={e=>setCurrentProd(p=>({...p, kode: e.target.value}))} className="w-full bg-slate-50 dark:bg-slate-900 border-none rounded-2xl px-6 py-3.5 font-bold outline-none" />
              </div>
            </div>

            <div className="space-y-6 mb-10">
              <h4 className="font-black text-xs uppercase tracking-widest text-slate-400">Manajemen 3-Lot</h4>
              {[1, 2, 3].map(lotNum => {
                const lot = currentProd.lots?.find(l => l.lot === lotNum) || { lot: lotNum as any, sku: '', stock: 0, hpp: 0, hargaJual: 0 };
                return (
                  <div key={lotNum} className="p-5 bg-slate-50 dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800">
                    <div className="flex items-center gap-2 mb-4"><div className="w-6 h-6 bg-blue-500 text-white rounded-lg flex items-center justify-center text-[10px] font-black">{lotNum}</div> <span className="font-black text-xs uppercase">Lot {lotNum}</span></div>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                       <input placeholder="SKU" value={lot.sku} onChange={e => {
                         const newLots = [...(currentProd.lots || [])];
                         const idx = newLots.findIndex(l => l.lot === lotNum);
                         const updated = { ...lot, sku: e.target.value };
                         idx === -1 ? newLots.push(updated) : newLots[idx] = updated;
                         setCurrentProd(p=>({...p, lots: newLots}));
                       }} className="bg-white dark:bg-slate-800 rounded-xl px-4 py-2 text-xs font-bold outline-none border-none" />
                       <input type="number" placeholder="Stock" value={lot.stock} onChange={e => {
                         const newLots = [...(currentProd.lots || [])];
                         const idx = newLots.findIndex(l => l.lot === lotNum);
                         const updated = { ...lot, stock: parseFloat(e.target.value) || 0 };
                         idx === -1 ? newLots.push(updated) : newLots[idx] = updated;
                         setCurrentProd(p=>({...p, lots: newLots}));
                       }} className="bg-white dark:bg-slate-800 rounded-xl px-4 py-2 text-xs font-bold outline-none border-none" />
                       <input type="number" placeholder="HPP" value={lot.hpp} onChange={e => {
                         const newLots = [...(currentProd.lots || [])];
                         const idx = newLots.findIndex(l => l.lot === lotNum);
                         const updated = { ...lot, hpp: parseFloat(e.target.value) || 0 };
                         idx === -1 ? newLots.push(updated) : newLots[idx] = updated;
                         setCurrentProd(p=>({...p, lots: newLots}));
                       }} className="bg-white dark:bg-slate-800 rounded-xl px-4 py-2 text-xs font-bold outline-none border-none" />
                       <input type="number" placeholder="Harga Jual" value={lot.hargaJual} onChange={e => {
                         const newLots = [...(currentProd.lots || [])];
                         const idx = newLots.findIndex(l => l.lot === lotNum);
                         const updated = { ...lot, hargaJual: parseFloat(e.target.value) || 0 };
                         idx === -1 ? newLots.push(updated) : newLots[idx] = updated;
                         setCurrentProd(p=>({...p, lots: newLots}));
                       }} className="bg-white dark:bg-slate-800 rounded-xl px-4 py-2 text-xs font-bold outline-none border-none" />
                    </div>
                  </div>
                );
              })}
            </div>

            <div className="flex justify-end gap-3">
              <button onClick={() => setShowModal(null)} className="px-6 py-3 rounded-xl font-bold text-slate-500 hover:bg-slate-100">Batal</button>
              <button onClick={saveProduct} className="px-8 py-3 bg-blue-600 text-white rounded-xl font-black shadow-lg shadow-blue-600/20">Simpan Produk</button>
            </div>
          </div>
        </div>
      )}

      {/* Floating Chat Assistant */}
      <button onClick={() => alert("Assistant is looking at your data. (Contextual lookup based on GS filters enabled)")} className="fixed bottom-10 right-10 w-16 h-16 bg-blue-600 text-white rounded-[2rem] shadow-2xl shadow-blue-600/40 flex items-center justify-center hover:scale-110 active:scale-95 transition-all z-50 group">
        <MessageSquare size={30} className="group-hover:rotate-12 transition-transform" />
        <span className="absolute -top-1 -right-1 w-5 h-5 bg-rose-500 rounded-full border-4 border-white dark:border-[#0f172a] animate-pulse"></span>
      </button>

    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, Users, Package, LineChart, FileEdit, ShieldCheck, 
  LogOut, Menu, X, Sun, Moon, Search, Plus, Phone, MessageSquare, 
  Send, Trash2, Edit3, ChevronDown, Check, AlertCircle, TrendingUp, Clock,
  Printer, History, Briefcase, ExternalLink, Calculator, Save, PlusCircle, Trash
} from 'lucide-react';

// --- Interfaces & Types ---
type Role = 'superadmin' | 'admin' | 'sales' | 'purchasing' | 'pajak' | 'finance' | 'stockist' | 'audit' | 'engineer';

interface User {
  username: string;
  role: Role;
}

interface ProductLot {
  lot: 1 | 2 | 3;
  sku: string;
  stock: number;
  hpp: number;
  hargaJual: number;
}

interface Product {
  id: string;
  nama: string;
  kode: string;
  lots: ProductLot[];
}

interface Customer {
  id: string;
  kode: string;
  nama: string;
  jenis: string;
  phone: string;
  email: string;
  alamat: string;
  sales: string;
  leadType: string;
  source: string;
  npwp: string;
}

interface TransactionItem {
  produkId: string;
  nama: string;
  sku: string;
  harga: number;
  qty: number;
  diskon: number;
}

interface Transaction {
  id: string;
  noTrx: string;
  tanggal: string;
  customerName: string;
  items: TransactionItem[];
  nilaiProyek: number;
  ppn: number;
  ongkir: number;
  jasaKirim: string;
  status: 'Selesai' | 'Progress' | 'Batal';
  sales: string;
  keterangan: string;
  skuHistory: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  // --- UI States ---
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // --- Form States ---
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0] 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({});
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({ lots: [] });

  // --- Data States ---
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentUser] = useState<User>({ username: 'superadmin', role: 'superadmin' });

  // --- Filter States ---
  const [filterCustomer, setFilterCustomer] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [filterProduct, setFilterProduct] = useState('');
  const [filterSKU, setFilterSKU] = useState('');

  // --- Persistence ---
  useEffect(() => {
    try {
      const savedTrx = localStorage.getItem('mypanca_db_trx');
      const savedCust = localStorage.getItem('mypanca_db_cust');
      const savedProd = localStorage.getItem('mypanca_db_prod');

      if (savedTrx) setTransactions(JSON.parse(savedTrx));
      if (savedCust) setCustomers(JSON.parse(savedCust));
      if (savedProd) setProducts(JSON.parse(savedProd));
    } catch (e) {
      console.error("Failed to load data from localStorage", e);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
  }, [transactions, customers, products]);

  // --- Business Logic Replicas ---

  const generateNoTrx = () => `TRX-${transactions.length + 1}`;

  const handleAddTrxItem = () => {
    const newItem: TransactionItem = { produkId: '', nama: '', sku: '', harga: 0, qty: 1, diskon: 0 };
    setCurrentTrx(prev => ({ ...prev, items: [...(prev.items || []), newItem] }));
  };

  const handleUpdateStock = (skuHistory: string, type: 'deduct' | 'restore') => {
    setProducts(prev => prev.map(p => ({
      ...p,
      lots: p.lots.map(l => {
        const entries = skuHistory.split(' | ');
        const entry = entries.find(e => e.split('+')[0] === l.sku);
        if (entry) {
          const qty = parseFloat(entry.split('+')[1]);
          return { ...l, stock: type === 'deduct' ? l.stock - qty : l.stock + qty };
        }
        return l;
      })
    })));
  };

  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data transaksi");

    const skuHistory = currentTrx.items.map(i => `${i.sku}+${i.qty}`).join(' | ');
    const newTrx: Transaction = {
      id: currentTrx.id || Date.now().toString(),
      noTrx: currentTrx.noTrx || generateNoTrx(),
      tanggal: currentTrx.tanggal || new Date().toISOString().split('T')[0],
      customerName: currentTrx.customerName || '',
      items: currentTrx.items || [],
      nilaiProyek: totals.grandTotal,
      ppn: totals.ppn,
      ongkir: Number(currentTrx.ongkir) || 0,
      jasaKirim: currentTrx.jasaKirim || '',
      status: currentTrx.status || 'Progress',
      sales: currentTrx.sales || 'admin',
      keterangan: currentTrx.keterangan || '',
      skuHistory: skuHistory
    };

    if (newTrx.status === 'Selesai' && (!currentTrx.id || transactions.find(t => t.id === currentTrx.id)?.status !== 'Selesai')) {
      handleUpdateStock(skuHistory, 'deduct');
    }

    if (currentTrx.id) {
      setTransactions(prev => prev.map(t => t.id === newTrx.id ? newTrx : t));
    } else {
      setTransactions(prev => [newTrx, ...prev]);
    }
    setShowModal(null);
    setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0] });
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi");
    const newCust: Customer = {
      id: currentCust.id || Date.now().toString(),
      kode: currentCust.kode || `TN${String(customers.length + 1).padStart(3, '0')}`,
      nama: currentCust.nama || '',
      jenis: currentCust.jenis || 'Perusahaan',
      phone: currentCust.phone || '',
      email: currentCust.email || '',
      alamat: currentCust.alamat || '',
      sales: currentCust.sales || 'admin',
      leadType: currentCust.leadType || 'New',
      source: currentCust.source || 'Direct',
      npwp: currentCust.npwp || ''
    };
    if (currentCust.id) {
      setCustomers(prev => prev.map(c => c.id === newCust.id ? newCust : c));
    } else {
      setCustomers(prev => [...prev, newCust]);
    }
    setShowModal(null);
    setCurrentCust({});
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Nama & Kode wajib");
    const newProd: Product = {
      id: currentProd.id || Date.now().toString(),
      nama: currentProd.nama || '',
      kode: currentProd.kode || '',
      lots: currentProd.lots?.length ? currentProd.lots : [
        { lot: 1, sku: '', stock: 0, hpp: 0, hargaJual: 0 },
        { lot: 2, sku: '', stock: 0, hpp: 0, hargaJual: 0 },
        { lot: 3, sku: '', stock: 0, hpp: 0, hargaJual: 0 }
      ] as ProductLot[]
    };
    if (currentProd.id) {
      setProducts(prev => prev.map(p => p.id === newProd.id ? newProd : p));
    } else {
      setProducts(prev => [...prev, newProd]);
    }
    setShowModal(null);
    setCurrentProd({ lots: [] });
  };

  // --- Calculations ---
  const totals = useMemo(() => {
    const itemsTotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppn = currentTrx.ppn ? itemsTotal * 0.11 : 0;
    const grandTotal = itemsTotal + ppn + (Number(currentTrx.ongkir) || 0);
    return { itemsTotal, ppn, grandTotal };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir]);

  // --- Filters ---
  const filteredTransactions = transactions.filter(t => 
    (!filterCustomer || t.customerName === filterCustomer) && 
    (!filterStatus || t.status === filterStatus)
  );

  const flatLots = useMemo(() => {
    return products.flatMap(p => p.lots.filter(l => l.sku).map(l => ({ ...l, productName: p.nama })));
  }, [products]);

  // --- UI Renderers ---
  const SidebarItem = ({ id, icon: Icon, label }: { id: Panel, icon: any, label: string }) => (
    <button 
      onClick={() => { setActivePanel(id); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all mb-1 ${
        activePanel === id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'
      }`}
    >
      <Icon size={18} />
      <span className="text-sm font-bold">{label}</span>
    </button>
  );

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 transform transition-transform duration-300 lg:translate-x-0 lg:static ${
        isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
      } ${isDarkMode ? 'bg-[#1e293b] border-slate-800' : 'bg-white border-slate-200'} border-r`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-4 mb-10 px-2">
            <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-6"><Package size={24} /></div>
            <div>
              <h1 className="font-black text-xl tracking-tight leading-none">MyPanca</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Business CRM</p>
            </div>
          </div>
          <nav className="flex-1">
            <SidebarItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <SidebarItem id="tracking" icon={LineChart} label="Transaksi" />
            <SidebarItem id="customer" icon={Users} label="Customer" />
            <SidebarItem id="produk" icon={Package} label="Produk & Stock" />
          </nav>
          <div className="mt-auto p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-500 rounded-xl flex items-center justify-center text-white font-bold">S</div>
            <div className="flex-1 min-w-0">
              <p className="text-xs font-bold truncate">{currentUser.username}</p>
              <p className="text-[9px] text-slate-500 uppercase font-black">Online</p>
            </div>
            <button className="p-2 text-slate-400 hover:text-rose-500"><LogOut size={16}/></button>
          </div>
        </div>
      </aside>

