      sales: currentCust.sales || 'admin',
      leadType: currentCust.leadType || 'New',
      source: currentCust.source || 'Direct',
      npwp: currentCust.npwp || ''
    };
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
    setCurrentCust({});
