                    <label className="text-[11px] font-bold text-emerald-800 dark:text-emerald-400">Biaya Ongkir (Rp)</label>
                    <input type="number" value={currentTrx.biayaOngkir} onChange={e => setCurrentTrx(p=>({...p, biayaOngkir: parseFloat(e.target.value) || 0}))} className="w-full bg-white border border-slate-200 rounded-lg px-4 py-1.5 font-bold outline-none" />
                  </div>
                </div>
              )}

              {/* Nilai Proyek & Sales */}
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[11px] font-bold text-slate-500">Nilai Proyek (Rp)</label>
                  <input readOnly value={`Rp${trxCalculations.grandTotal.toLocaleString('id-ID')}`} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2 font-bold text-slate-500 outline-none" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[11px] font-bold text-slate-500">Nama Sales</label>
                  <input readOnly value={currentTrx.sales || ''} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2 font-bold text-slate-400 outline-none" />
                </div>
              </div>

              {/* Status */}
              <div className="space-y-1.5">
                <label className="text-[11px] font-bold text-slate-500">Status</label>
                <div className="relative">
                  <select value={currentTrx.status} onChange={e => setCurrentTrx(p=>({...p, status: e.target.value as any}))} className="w-full appearance-none bg-white border-2 border-blue-500 rounded-full px-4 py-2 font-bold outline-none pr-10">
                    <option value="Progress">Progress</option>
                    <option value="Selesai">Selesai</option>
                    <option value="Batal">Batal</option>
                  </select>
                  <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18}/>
                </div>
              </div>

              {/* Keterangan */}
              <div className="space-y-1.5">
                <label className="text-[11px] font-bold text-slate-500">Keterangan</label>
                <textarea value={currentTrx.keterangan || ''} onChange={e=>setCurrentTrx(p=>({...p, keterangan: e.target.value}))} className="w-full bg-white border border-slate-200 rounded-lg px-4 py-2 font-medium outline-none h-24 resize-none" placeholder="Catatan transaksi..." />
              </div>
            </div>

            {/* Modal Footer */}
            <div className="px-6 py-4 border-t flex justify-end gap-3 bg-slate-50/50">
              <button onClick={() => setShowModal(null)} className="px-6 py-2 border border-slate-200 rounded-lg font-bold text-slate-500 hover:bg-white transition-all text-sm flex items-center gap-2">
                <X size={14}/> Batal
              </button>
              <button onClick={saveTransaction} className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold text-sm shadow-lg shadow-blue-600/20 hover:bg-blue-700 active:scale-95 transition-all flex items-center gap-2">
                <Check size={14}/> Simpan Transaksi
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL CUSTOMER & MODAL PRODUCT - (Kept as previously functional) */}
      {showModal === 'cust' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-[#1e293b] w-full max-w-xl rounded-[2.5rem] p-8 animate-in zoom-in-95 duration-200">
            <h3 className="text-2xl font-black mb-8">Data Customer</h3>
            <div className="space-y-4 mb-10">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Nama Customer</label>
                <input value={currentCust.nama || ''} onChange={e=>setCurrentCust(p=>({...p, nama: e.target.value}))} className="w-full bg-slate-50 dark:bg-slate-900 border-none rounded-2xl px-6 py-3.5 font-bold outline-none" placeholder="Contoh: PT. ABC" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">No Telp</label>
                  <input value={currentCust.phone || ''} onChange={e=>setCurrentCust(p=>({...p, phone: e.target.value}))} className="w-full bg-slate-50 dark:bg-slate-900 border-none rounded-2xl px-6 py-3.5 font-bold outline-none" placeholder="081..." />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Sales</label>
                  <select value={currentCust.sales || ''} onChange={e=>setCurrentCust(p=>({...p, sales: e.target.value}))} className="w-full bg-slate-50 dark:bg-slate-900 border-none rounded-2xl px-6 py-3.5 font-bold outline-none">
                    <option value="">Pilih Sales</option>
                    <option value="maria">Maria</option>
                    <option value="indra">Indra</option>
                    <option value="ahmat">Ahmat</option>
                  </select>
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Alamat</label>
                <textarea value={currentCust.alamat || ''} onChange={e=>setCurrentCust(p=>({...p, alamat: e.target.value}))} className="w-full bg-slate-50 dark:bg-slate-900 border-none rounded-2xl px-6 py-3.5 text-xs font-bold h-24 outline-none" placeholder="Alamat lengkap..."></textarea>
              </div>
            </div>
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowModal(null)} className="px-6 py-3 rounded-xl font-bold text-slate-500 hover:bg-slate-100">Batal</button>
              <button onClick={saveCustomer} className="px-8 py-3 bg-blue-600 text-white rounded-xl font-black shadow-lg shadow-blue-600/20">Simpan Customer</button>
            </div>
          </div>
        </div>
      )}

      {/* Floating Chat Assistant */}
      <button onClick={() => alert("Assistant is looking at your data. (Contextual lookup enabled)")} className="fixed bottom-10 right-10 w-16 h-16 bg-blue-600 text-white rounded-[2rem] shadow-2xl shadow-blue-600/40 flex items-center justify-center hover:scale-110 active:scale-95 transition-all z-50 group">
        <MessageSquare size={30} className="group-hover:rotate-12 transition-transform" />
        <span className="absolute -top-1 -right-1 w-5 h-5 bg-rose-500 rounded-full border-4 border-white dark:border-[#0f172a] animate-pulse"></span>
      </button>

    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, Users, Package, LineChart, FileEdit, ShieldCheck, 
  LogOut, Menu, X, Sun, Moon, Search, Plus, Phone, MessageSquare, 
  Send, Trash2, Edit3, ChevronDown, Check, AlertCircle, TrendingUp, Clock,
  Printer, History, Briefcase, ExternalLink, Calculator, Save, PlusCircle, Trash,
  Mail, FileText, Globe, UserCircle
} from 'lucide-react';

// --- Interfaces & Types ---
type Role = 'superadmin' | 'admin' | 'sales' | 'purchasing' | 'pajak' | 'finance' | 'stockist' | 'audit' | 'engineer';

interface User {
  username: string;
  role: Role;
}

interface ProductLot {
  lot: 1 | 2 | 3;
  sku: string;
  stock: number;
  hpp: number;
  hargaJual: number;
}

interface Product {
  id: string;
  nama: string;
  kode: string;
  lots: ProductLot[];
}

interface Customer {
  id: string;
  kode: string;
  nama: string;
  jenis: string;
  phone: string;
  email: string;
  alamat: string;
  sales: string;
  leadType: string;
  source: string;
  npwp: string;
  keterangan: string;
}

interface TransactionItem {
  produkId: string;
  nama: string;
  sku: string;
  harga: number;
  qty: number;
  diskon: number;
}

interface Transaction {
  id: string;
  noTrx: string;
  tanggal: string;
  customerName: string;
  items: TransactionItem[];
  nilaiProyek: number;
  ppn: boolean;
  ongkir: boolean;
  biayaOngkir: number;
  jasaKirim: string;
  status: 'Selesai' | 'Progress' | 'Batal';
  sales: string;
  keterangan: string;
  skuHistory: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  // --- UI States ---
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // --- Form States ---
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan',
    leadType: 'Belum Transaksi',
    source: 'Organic',
    sales: 'Angel'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({ lots: [] });

  // --- Data States ---
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentUser] = useState<User>({ username: 'superadmin', role: 'superadmin' });

  // --- Filter States ---
  const [searchQuery, setSearchQuery] = useState('');
  const [filterStatus, setFilterStatus] = useState('');

  // --- Persistence ---
  useEffect(() => {
    try {
      const savedTrx = localStorage.getItem('mypanca_db_trx');
      const savedCust = localStorage.getItem('mypanca_db_cust');
      const savedProd = localStorage.getItem('mypanca_db_prod');

      if (savedTrx) setTransactions(JSON.parse(savedTrx));
      if (savedCust) setCustomers(JSON.parse(savedCust));
      if (savedProd) setProducts(JSON.parse(savedProd));
    } catch (e) {
      console.error("Failed to load data from localStorage", e);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
  }, [transactions, customers, products]);

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const matchesSearch = searchQuery === '' || 
        t.customerName.toLowerCase().includes(searchQuery.toLowerCase()) ||
        t.noTrx.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesStatus = filterStatus === '' || t.status === filterStatus;
      return matchesSearch && matchesStatus;
    });
  }, [transactions, searchQuery, filterStatus]);

  const handleUpdateStock = (skuHistory: string, type: 'deduct' | 'restore') => {
    setProducts(prev => prev.map(p => ({
      ...p,
      lots: p.lots.map(l => {
        const entries = skuHistory.split(' | ');
        const entry = entries.find(e => e.split('+')[0] === l.sku);
        if (entry) {
          const qty = parseFloat(entry.split('+')[1]);
          return { ...l, stock: type === 'deduct' ? l.stock - qty : l.stock + qty };
        }
        return l;
      })
    })));
  };

  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data transaksi");

    const skuHistory = currentTrx.items.map(i => `${i.sku}+${i.qty}`).join(' | ');
    const newTrx: Transaction = {
      id: currentTrx.id || Date.now().toString(),
      noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`,
      tanggal: currentTrx.tanggal || new Date().toISOString().split('T')[0],
      customerName: currentTrx.customerName || '',
      items: currentTrx.items || [],
      nilaiProyek: trxCalculations.grandTotal,
      ppn: currentTrx.ppn || false,
      ongkir: currentTrx.ongkir || false,
      biayaOngkir: currentTrx.biayaOngkir || 0,
      jasaKirim: currentTrx.jasaKirim || '',
      status: currentTrx.status || 'Progress',
      sales: currentTrx.sales || 'admin',
      keterangan: currentTrx.keterangan || '',
      skuHistory: skuHistory
    };

    if (newTrx.status === 'Selesai') handleUpdateStock(skuHistory, 'deduct');

    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowModal(null);
    setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 });
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi");
    const newCust: Customer = {
      id: currentCust.id || Date.now().toString(),
      kode: currentCust.kode || `TN${String(customers.length + 1).padStart(3, '0')}`,
      nama: currentCust.nama || '',
      jenis: currentCust.jenis || 'Perusahaan',
      phone: currentCust.phone || '',
      email: currentCust.email || '',
      alamat: currentCust.alamat || '',
      sales: currentCust.sales || 'Angel',
      leadType: currentCust.leadType || 'Belum Transaksi',
      source: currentCust.source || 'Organic',
      npwp: currentCust.npwp || '',
      keterangan: currentCust.keterangan || ''
    };
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
    setCurrentCust({
      jenis: 'Perusahaan',
      leadType: 'Belum Transaksi',
      source: 'Organic',
      sales: 'Angel'
    });
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Nama & Kode wajib");
    const newProd: Product = {
      id: currentProd.id || Date.now().toString(),
      nama: currentProd.nama || '',
      kode: currentProd.kode || '',
      lots: currentProd.lots?.length ? currentProd.lots : [
        { lot: 1, sku: '', stock: 0, hpp: 0, hargaJual: 0 },
        { lot: 2, sku: '', stock: 0, hpp: 0, hargaJual: 0 },
        { lot: 3, sku: '', stock: 0, hpp: 0, hargaJual: 0 }
      ] as ProductLot[]
    };
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowModal(null);
    setCurrentProd({ lots: [] });
  };

  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    const grandTotal = itemsSubtotal + ppnAmount + shippingAmount;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => 
    customers.find(c => c.nama === currentTrx.customerName), 
  [currentTrx.customerName, customers]);

  const SidebarItem = ({ id, icon: Icon, label }: { id: Panel, icon: any, label: string }) => (
    <button 
      onClick={() => { setActivePanel(id); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all mb-1 ${
        activePanel === id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'
      }`}
    >
      <Icon size={18} />
      <span className="text-sm font-bold">{label}</span>
    </button>
  );

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>

      {/* Sidebar */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 transform transition-transform duration-300 lg:translate-x-0 lg:static ${
        isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
      } ${isDarkMode ? 'bg-[#1e293b] border-slate-800' : 'bg-white border-slate-200'} border-r`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-4 mb-10 px-2">
            <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-6"><Package size={24} /></div>
            <div>
              <h1 className="font-black text-xl tracking-tight leading-none">MyPanca</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Business CRM</p>
            </div>
          </div>
          <nav className="flex-1">
            <SidebarItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <SidebarItem id="tracking" icon={LineChart} label="Transaksi" />
            <SidebarItem id="customer" icon={Users} label="Customer" />
            <SidebarItem id="produk" icon={Package} label="Produk & Stock" />
          </nav>
          <div className="mt-auto p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-500 rounded-xl flex items-center justify-center text-white font-bold">S</div>
            <div className="flex-1 min-w-0">
              <p className="text-xs font-bold truncate">{currentUser.username}</p>
              <p className="text-[9px] text-slate-500 uppercase font-black">Online</p>
            </div>
            <button className="p-2 text-slate-400 hover:text-rose-500"><LogOut size={16}/></button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 h-screen overflow-hidden">
        <header className="h-20 flex items-center justify-between px-8 border-b bg-white dark:bg-[#0f172a] sticky top-0 z-40">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 bg-slate-100 rounded-xl"><Menu size={20} /></button>
            <h2 className="text-2xl font-black tracking-tight">{activePanel.toUpperCase()}</h2>
          </div>
          <div className="flex items-center gap-4">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="w-10 h-10 flex items-center justify-center rounded-xl bg-slate-100 dark:bg-slate-800">
              {isDarkMode ? <Sun size={20} className="text-yellow-400" /> : <Moon size={20} />}
            </button>
            <div className="relative hidden md:block">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="Cari..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-12 pr-6 py-2 bg-slate-100 dark:bg-slate-800 border-none rounded-2xl text-sm w-64 outline-none" 
              />
            </div>
          </div>
        </header>

        <div className="flex-1 p-8 overflow-y-auto">
          {activePanel === 'dashboard' && (
            <div className="space-y-8 animate-in fade-in duration-500">
               <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                  {[
                    { label: 'Revenue', value: `Rp${transactions.filter(t=>t.status==='Selesai').reduce((a,b)=>a+(b.nilaiProyek || 0),0).toLocaleString('id-ID')}`, icon: LineChart, color: 'text-blue-600', bg: 'bg-blue-100' },
                    { label: 'Customer', value: customers.length.toString(), icon: Users, color: 'text-emerald-600', bg: 'bg-emerald-100' },
                    { label: 'Progress', value: transactions.filter(t=>t.status==='Progress').length.toString(), icon: Clock, color: 'text-amber-600', bg: 'bg-amber-100' },
                    { label: 'Batal', value: transactions.filter(t=>t.status==='Batal').length.toString(), icon: AlertCircle, color: 'text-rose-600', bg: 'bg-rose-100' },
                  ].map((stat, i) => (
                    <div key={i} className="bg-white dark:bg-slate-900 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
                      <div className={`w-12 h-12 ${stat.bg} ${stat.color} rounded-2xl flex items-center justify-center mb-4`}><stat.icon size={24}/></div>
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{stat.label}</p>
                      <p className={`text-2xl font-black ${stat.color}`}>{stat.value}</p>
                    </div>
                  ))}
               </div>
            </div>
          )}

          {activePanel === 'tracking' && (
            <div className="space-y-6 animate-in fade-in duration-500">
              <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-8">
                <div className="flex justify-between items-center mb-8">
                  <h3 className="text-2xl font-black">Transaksi</h3>
                  <button onClick={() => { 
                    setCurrentTrx({ 
                      items: [], 
                      status: 'Progress', 
                      tanggal: new Date().toISOString().split('T')[0],
                      ppn: true,
                      ongkir: true,
                      biayaOngkir: 0
                    }); 
                    setShowModal('trx'); 
                  }} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-sm flex items-center gap-2 hover:bg-blue-700 transition-all shadow-xl shadow-blue-600/20">
                    <Plus size={20} /> Tambah Transaksi
                  </button>
                </div>
                <div className="overflow-x-auto rounded-2xl border border-slate-100 dark:border-slate-800">
                  <table className="w-full text-left text-xs">
                    <thead>
                      <tr className="bg-slate-50 dark:bg-slate-800/50 text-slate-400 font-black uppercase tracking-widest border-b dark:border-slate-800">
                        <th className="px-6 py-4">Tanggal</th>
                        <th className="px-6 py-4">Customer</th>
                        <th className="px-6 py-4">Produk</th>
                        <th className="px-6 py-4">Nilai</th>
                        <th className="px-6 py-4">Status</th>
                        <th className="px-6 py-4">Aksi</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y dark:divide-slate-800">
                      {filteredTransactions.map(t => (
                        <tr key={t.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-all">
                          <td className="px-6 py-5 font-bold">{t.tanggal}</td>
                          <td className="px-6 py-5 font-black text-slate-800 dark:text-slate-100">{t.customerName}</td>
                          <td className="px-6 py-5 font-bold truncate max-w-[150px]">{t.items.map(i=>i.nama).join(', ')}</td>
                          <td className="px-6 py-5 font-black text-blue-600">Rp{(t.nilaiProyek || 0).toLocaleString('id-ID')}</td>
                          <td className="px-6 py-5">
                            <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${
                              t.status === 'Selesai' ? 'bg-emerald-100 text-emerald-600' :
                              t.status === 'Batal' ? 'bg-rose-100 text-rose-600' : 'bg-amber-100 text-amber-600'
                            }`}>{t.status}</span>
                          </td>
                          <td className="px-6 py-5">
                            <div className="flex gap-2">
                              <button onClick={() => { setCurrentTrx(t); setShowModal('trx'); }} className="p-2 bg-amber-100 text-amber-600 rounded-lg hover:bg-amber-600 hover:text-white"><Edit3 size={14}/></button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

