                <div className="space-y-1.5">
                  <label className="text-[11px] font-bold text-slate-500">Sumber Leads</label>
                  <div className="relative">
                    <select value={currentCust.source || 'Organic'} onChange={e => setCurrentCust(p=>({...p, source: e.target.value}))} className="w-full appearance-none bg-white dark:bg-slate-900 border-2 border-blue-500 rounded-full px-4 py-2 font-bold outline-none pr-10">
                      <option value="Organic">Organic</option>
