                  </div>
                </div>
              </div>

              {/* Row 5: Nama Sales & Keterangan */}
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[11px] font-bold text-slate-500">Nama Sales</label>
                  <div className="relative">
                    <select value={currentCust.sales || 'Angel'} onChange={e => setCurrentCust(p=>({...p, sales: e.target.value}))} className="w-full appearance-none bg-white dark:bg-slate-900 border-2 border-blue-500 rounded-full px-4 py-2 font-bold outline-none pr-10">
                      <option value="Angel">Angel</option>
