      {/* Floating Chat Assistant */}
      <button onClick={() => alert("Assistant is looking at your data. (Contextual lookup enabled)")} className="fixed bottom-10 right-10 w-16 h-16 bg-blue-600 text-white rounded-[2rem] shadow-2xl shadow-blue-600/40 flex items-center justify-center hover:scale-110 active:scale-95 transition-all z-50 group">
        <MessageSquare size={30} className="group-hover:rotate-12 transition-transform" />
        <span className="absolute -top-1 -right-1 w-5 h-5 bg-rose-500 rounded-full border-4 border-white dark:border-[#0f172a] animate-pulse"></span>
