              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5"><label className="text-[11px] font-bold text-slate-500">Nama Sales</label><div className="relative"><select value={currentCust.sales || 'Angel'} onChange={e => setCurrentCust(p=>({...p, sales: e.target.value}))} className="w-full appearance-none bg-white border-2 border-blue-500 rounded-full px-4 py-2 font-bold outline-none pr-10"><option value="Angel">Angel</option><option value="Maria">Maria</option><option value="Indra">Indra</option></select><ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/></div></div>
                <div className="space-y-1.5"><label className="text-[11px] font-bold text-slate-500">Keterangan</label><input value={currentCust.keterangan || ''} onChange={e=>setCurrentCust(p=>({...p, keterangan: e.target.value}))} className="w-full bg-white border border-slate-200 rounded-lg px-4 py-2 font-medium outline-none" placeholder="Catatan" /></div>
              </div>
              <div className="space-y-1.5"><label className="text-[11px] font-bold text-slate-500">NPWP</label><input value={currentCust.npwp || ''} onChange={e=>setCurrentCust(p=>({...p, npwp: e.target.value}))} className="w-full bg-white border border-slate-200 rounded-lg px-4 py-2 font-medium outline-none" placeholder="12.345.678.9-012.345" /></div>
            </div>
            <div className="px-6 py-4 border-t flex justify-end gap-3 bg-slate-50/50">
              <button onClick={() => setShowModal(null)} className="px-6 py-2 border border-slate-200 rounded-lg font-bold text-slate-500 text-sm flex items-center gap-2"><X size={14}/> Batal</button>
              <button onClick={saveCustomer} className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold text-sm flex items-center gap-2 shadow-lg shadow-blue-600/20"><Save size={14}/> Simpan Customer</button>
