type Role = 'superadmin' | 'admin' | 'sales' | 'purchasing' | 'pajak' | 'finance' | 'stockist' | 'audit' | 'engineer';

interface User {
  username: string;
  role: Role;
}

interface Supplier {
  id: string;
  nama: string;
  kode: string;
  npwp: string;
}

interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product {
  id: string;
  nama: string;
  kode: string;
  lots: ProductLot[];
}

interface Customer {
  id: string;
  kode: string;
  nama: string;
  jenis: string;
  phone: string;
  email: string;
  alamat: string;
  sales: string;
  leadType: string;
  source: string;
  npwp: string;
  keterangan: string;
}

interface TransactionItem {
  produkId: string;
  nama: string;
  sku: string;
  harga: number;
  qty: number;
  diskon: number;
}

interface Transaction {
  id: string;
  noTrx: string;
  tanggal: string;
  customerName: string;
  items: TransactionItem[];
  nilaiProyek: number;
  ppn: boolean;
  ongkir: boolean;
  biayaOngkir: number;
  jasaKirim: string;
  status: 'Selesai' | 'Progress' | 'Batal';
  sales: string;
  keterangan: string;
  skuHistory: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  // --- UI States ---
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // --- Form States ---
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({ lots: [] });
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [currentStock, setCurrentStock] = useState<Partial<ProductLot>>({ stock: 0, hpp: 0, hargaJual: 0 });

  // --- Data States ---
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentUser] = useState<User>({ username: 'superadmin', role: 'superadmin' });

  // --- Filter States ---
  const [searchQuery, setSearchQuery] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [prodFilter, setProdFilter] = useState('-- Semua Produk --');
  const [skuFilter, setSkuFilter] = useState('-- Semua SKU --');

  // --- Persistence ---
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');

    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // --- Derived Data ---
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const matchesSearch = searchQuery === '' || t.customerName.toLowerCase().includes(searchQuery.toLowerCase()) || t.noTrx.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesStatus = filterStatus === '' || t.status === filterStatus;
      return matchesSearch && matchesStatus;
    });
  }, [transactions, searchQuery, filterStatus]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesProd = prodFilter === '-- Semua Produk --' || p.nama === prodFilter;
      const matchesSku = skuFilter === '-- Semua SKU --' || p.lots.some(l => l.sku === skuFilter);
      return matchesProd && matchesSku;
    });
  }, [products, prodFilter, skuFilter]);

  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  // --- Handlers ---
  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi");
    const newCust: Customer = {
      id: currentCust.id || Date.now().toString(),
      kode: currentCust.kode || `TN${String(customers.length + 1).padStart(3, '0')}`,
      nama: currentCust.nama || '',
      jenis: currentCust.jenis || 'Perusahaan',
      phone: currentCust.phone || '',
      email: currentCust.email || '',
      alamat: currentCust.alamat || '',
      sales: currentCust.sales || 'Angel',
      leadType: currentCust.leadType || 'Belum Transaksi',
      source: currentCust.source || 'Organic',
      npwp: currentCust.npwp || '',
      keterangan: currentCust.keterangan || ''
    };
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
    setCurrentCust({ jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel' });
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Lengkapi data produk");
    const newProd: Product = {
      id: currentProd.id || Date.now().toString(),
      nama: currentProd.nama || '',
      kode: currentProd.kode || '',
      lots: currentProd.lots || []
    };
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowModal(null);
    setCurrentProd({ lots: [] });
  };

  const saveSupplier = () => {
    if (!currentSupp.nama || !currentSupp.kode) return alert("Lengkapi data supplier");
    const newSupp: Supplier = {
      id: Date.now().toString(),
      nama: currentSupp.nama || '',
      kode: currentSupp.kode || '',
      npwp: currentSupp.npwp || ''
    };
    setSuppliers(prev => [...prev, newSupp]);
    setCurrentSupp({});
  };

  const saveStockLot = () => {
    const prodId = (document.getElementById('stock-prod-select') as HTMLSelectElement)?.value;
    const suppId = (document.getElementById('stock-supp-select') as HTMLSelectElement)?.value;
    if (!prodId || !suppId) return alert("Pilih Produk dan Supplier");

    const prod = products.find(p => p.id === prodId);
    if (!prod) return;

    const lotCount = prod.lots.length + 1;
    const newLot: ProductLot = {
      lot: lotCount,
      sku: `${prod.kode}${lotCount}`,
      supplierId: suppId,
      stock: currentStock.stock || 0,
      hpp: currentStock.hpp || 0,
      hargaJual: currentStock.hargaJual || 0,
      tanggal: new Date().toISOString().split('T')[0]
    };

    setProducts(prev => prev.map(p => p.id === prodId ? { ...p, lots: [...p.lots, newLot] } : p));
    setShowModal(null);
    setCurrentStock({ stock: 0, hpp: 0, hargaJual: 0 });
  };

  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data transaksi");
    const newTrx: Transaction = {
      id: currentTrx.id || Date.now().toString(),
      noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`,
      tanggal: currentTrx.tanggal || new Date().toISOString().split('T')[0],
      customerName: currentTrx.customerName || '',
      items: currentTrx.items || [],
      nilaiProyek: trxCalculations.grandTotal,
      ppn: currentTrx.ppn || false,
      ongkir: currentTrx.ongkir || false,
      biayaOngkir: currentTrx.biayaOngkir || 0,
      jasaKirim: currentTrx.jasaKirim || '',
      status: currentTrx.status || 'Progress',
      sales: currentTrx.sales || 'admin',
      keterangan: currentTrx.keterangan || '',
      skuHistory: currentTrx.items.map(i => `${i.sku}+${i.qty}`).join(' | ')
    };
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowModal(null);
    setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 });
  };

  const SidebarItem = ({ id, icon: Icon, label }: { id: Panel, icon: any, label: string }) => (
    <button onClick={() => { setActivePanel(id); setIsSidebarOpen(false); }} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all mb-1 ${activePanel === id ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'}`}>
      <Icon size={18} /><span className="text-sm font-bold">{label}</span>
    </button>
  );

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>
      <aside className={`fixed inset-y-0 left-0 z-50 w-72 transform transition-transform duration-300 lg:translate-x-0 lg:static ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} bg-white dark:bg-[#1e293b] border-r border-slate-200 dark:border-slate-800`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-4 mb-10 px-2">
            <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-6"><Package size={24} /></div>
            <div><h1 className="font-black text-xl tracking-tight leading-none">MyPanca</h1><p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Business CRM</p></div>
          </div>
          <nav className="flex-1">
            <SidebarItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <SidebarItem id="tracking" icon={LineChart} label="Transaksi" />
            <SidebarItem id="customer" icon={Users} label="Customer" />
            <SidebarItem id="produk" icon={Package} label="Produk & Stock" />
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 h-screen overflow-hidden">
        <header className="h-20 flex items-center justify-between px-8 border-b bg-white dark:bg-[#0f172a] sticky top-0 z-40">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 bg-slate-100 rounded-xl"><Menu size={20} /></button>
            <h2 className="text-2xl font-black tracking-tight">{activePanel.toUpperCase()}</h2>
          </div>
          <div className="flex items-center gap-4">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="w-10 h-10 flex items-center justify-center rounded-xl bg-slate-100 dark:bg-slate-800"><Sun size={20} className="text-yellow-400" /></button>
          </div>
        </header>

        <div className="flex-1 p-8 overflow-y-auto">
          {activePanel === 'produk' && (
            <div className="space-y-10 animate-in fade-in duration-500">
              {/* Top Buttons Section */}
              <div className="flex flex-col gap-4">
                <h3 className="text-xl font-bold">Produk & Stock</h3>
                <p className="text-sm text-slate-500 -mt-3">Kelola produk, supplier, dan stock</p>
                <div className="flex gap-3">
                  <button onClick={() => setShowModal('prod')} className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2 hover:bg-blue-700 transition-all"><Plus size={18} /> Tambah Produk</button>
                  <button onClick={() => setShowModal('supp')} className="bg-white border border-slate-200 px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2 hover:bg-slate-50 transition-all"><FileText size={18} /> Kelola Supplier</button>
                  <button onClick={() => setShowModal('stock')} className="bg-emerald-500 text-white px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2 hover:bg-emerald-600 transition-all"><Download size={18} /> Tambah/Edit Stock</button>
                </div>
              </div>

              {/* Filter Section */}
              <div className="space-y-4">
                <h4 className="font-bold">Cek/Edit Stock</h4>
                <p className="text-xs text-slate-500 -mt-3">Filter dan lihat daftar produk</p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[11px] font-bold text-slate-500">Pilih Produk</label>
                    <div className="relative">
                      <select value={prodFilter} onChange={e => setProdFilter(e.target.value)} className="w-full appearance-none bg-white border border-blue-500 rounded-full px-4 py-2 font-bold text-sm outline-none">
                        <option>-- Semua Produk --</option>
                        {products.map(p => <option key={p.id}>{p.nama}</option>)}
                      </select>
                      <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                    </div>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[11px] font-bold text-slate-500">Pilih SKU</label>
                    <div className="relative">
                      <select value={skuFilter} onChange={e => setSkuFilter(e.target.value)} className="w-full appearance-none bg-white border border-blue-500 rounded-full px-4 py-2 font-bold text-sm outline-none">
                        <option>-- Semua SKU --</option>
                        {products.flatMap(p => p.lots).map(l => <option key={l.sku}>{l.sku}</option>)}
                      </select>
                      <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                    </div>
                  </div>
                </div>
              </div>

              {/* Product List Section */}
              <div className="space-y-4">
                <h4 className="font-bold">Daftar Produk</h4>
                <p className="text-xs text-slate-500 -mt-3">Semua produk dengan stock dan riwayat</p>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  {filteredProducts.map(p => {
                    const totalStock = p.lots.reduce((acc, l) => acc + l.stock, 0);
                    const lastPrice = p.lots.length > 0 ? p.lots[p.lots.length - 1].hargaJual : 0;
                    const supplier = suppliers.find(s => s.id === p.lots[0]?.supplierId)?.nama || '-';
                    return (
                      <div key={p.id} className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm hover:border-blue-500 transition-all flex flex-col gap-4">
                        <div className="flex gap-4 items-start">
                          <div className="w-12 h-12 bg-blue-100 rounded-2xl flex items-center justify-center text-blue-600 shadow-sm"><Package size={24}/></div>
                          <div className="flex-1 min-w-0">
                            <h5 className="font-bold text-sm leading-tight mb-1 truncate">{p.nama}</h5>
                            <p className="text-[10px] text-slate-400 font-bold uppercase truncate">{p.kode} • {supplier}</p>
                          </div>
                        </div>
                        <div className="space-y-1">
                          <div className="flex justify-between items-center text-xs">
                            <span className="text-slate-400 font-medium">Harga Jual : <span className="text-blue-600 font-black">Rp{lastPrice.toLocaleString('id-ID')}</span></span>
                            <Edit3 size={14} className="text-amber-500 cursor-pointer"/>
                          </div>
                          <div className="flex justify-between items-center text-xs">
                            <span className="text-slate-400 font-medium">Stock Terakhir : <span className="text-blue-600 font-black">{totalStock}</span></span>
                            <Edit3 size={14} className="text-amber-500 cursor-pointer"/>
                          </div>
                        </div>
                        <button className="w-full bg-blue-50 text-blue-600 py-2 rounded-xl text-xs font-bold flex items-center justify-center gap-2 hover:bg-blue-100 transition-all mt-2">
                          <Clock size={14}/> Lihat Riwayat Barang
                        </button>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          )}
          {/* Dashboard & Customer panels omitted but maintained */}
        </div>
      </main>

      {/* --- MODAL TAMBAH PRODUK (IMAGE 1) --- */}
      {showModal === 'prod' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl animate-in zoom-in-95 duration-200 overflow-hidden">
            <div className="px-6 py-4 border-b flex justify-between items-center">
              <h3 className="text-lg font-bold">Tambah Produk</h3>
              <button onClick={() => setShowModal(null)} className="p-1 hover:bg-slate-100 rounded-lg"><X size={20}/></button>
            </div>
            <div className="p-6 space-y-6">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-600">Nama Produk</label>
                <input value={currentProd.nama || ''} onChange={e=>setCurrentProd(p=>({...p, nama: e.target.value}))} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 font-medium outline-none focus:border-blue-500" placeholder="Nama produk" />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-600">Kode Produk</label>
                <input value={currentProd.kode || ''} onChange={e=>setCurrentProd(p=>({...p, kode: e.target.value}))} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 font-medium outline-none focus:border-blue-500" placeholder="Contoh: PT02" />
              </div>
            </div>
            <div className="px-6 py-4 border-t flex justify-end gap-3 bg-slate-50/50">
              <button onClick={() => setShowModal(null)} className="px-6 py-2 bg-white border border-slate-200 rounded-xl font-bold text-slate-500 flex items-center gap-2 hover:bg-slate-50"><X size={14}/> Batal</button>
              <button onClick={saveProduct} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold text-sm flex items-center gap-2 shadow-lg shadow-blue-600/20"><Save size={14}/> Simpan Produk</button>
            </div>
          </div>
        </div>
      )}

      {/* --- MODAL KELOLA SUPPLIER (IMAGE 2) --- */}
      {showModal === 'supp' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl animate-in zoom-in-95 duration-200 overflow-hidden flex flex-col h-[90vh]">
            <div className="px-6 py-4 border-b flex justify-between items-center">
              <h3 className="text-lg font-bold">Kelola Supplier</h3>
              <button onClick={() => setShowModal(null)} className="p-1 hover:bg-slate-100 rounded-lg"><X size={20}/></button>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5"><label className="text-xs font-bold text-slate-600">Nama Perusahaan</label><input value={currentSupp.nama || ''} onChange={e=>setCurrentSupp(p=>({...p, nama: e.target.value}))} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 font-medium outline-none" placeholder="PT. Maju Jaya" /></div>
                <div className="space-y-1.5"><label className="text-xs font-bold text-slate-600">Kode Perusahaan</label><input value={currentSupp.kode || ''} onChange={e=>setCurrentSupp(p=>({...p, kode: e.target.value}))} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 font-medium outline-none" placeholder="MJ-001" /></div>
              </div>
              <div className="space-y-1.5"><label className="text-xs font-bold text-slate-600">NPWP</label><input value={currentSupp.npwp || ''} onChange={e=>setCurrentSupp(p=>({...p, npwp: e.target.value}))} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 font-medium outline-none" placeholder="12.345.678.9-012.345" /></div>

              <div className="flex justify-end gap-3 border-b pb-6">
                <button onClick={() => setCurrentSupp({})} className="px-6 py-2 bg-white border border-slate-200 rounded-xl font-bold text-slate-500 flex items-center gap-2"><RotateCcw size={14}/> Reset</button>
                <button onClick={saveSupplier} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold flex items-center gap-2"><Plus size={14}/> Tambah Supplier</button>
              </div>

              <div className="space-y-4">
                <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest">Daftar Supplier</h4>
                <div className="border border-slate-100 rounded-xl overflow-hidden">
                  <table className="w-full text-left text-xs">
                    <thead><tr className="bg-slate-50 text-slate-500 font-bold border-b"><th className="px-4 py-3">Nama</th><th className="px-4 py-3">Kode</th></tr></thead>
                    <tbody className="divide-y divide-slate-100">
                      {suppliers.map(s => (
                        <tr key={s.id} className="hover:bg-slate-50"><td className="px-4 py-3 font-medium">{s.nama}</td><td className="px-4 py-3 text-slate-500">{s.kode}</td></tr>
                      ))}
                      {suppliers.length === 0 && <tr><td colSpan={2} className="px-4 py-8 text-center text-slate-400 italic">Belum ada supplier</td></tr>}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
            <div className="px-6 py-4 border-t flex justify-end bg-slate-50/50">
              <button onClick={() => setShowModal(null)} className="px-8 py-2 bg-white border border-slate-200 rounded-xl font-bold text-slate-600 flex items-center gap-2 hover:bg-slate-50"><X size={14}/> Tutup</button>
            </div>
          </div>
        </div>
      )}

      {/* --- MODAL TAMBAH/EDIT STOCK (IMAGE 3) --- */}
      {showModal === 'stock' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl animate-in zoom-in-95 duration-200 overflow-hidden">
            <div className="px-6 py-4 border-b flex justify-between items-center">
              <h3 className="text-lg font-bold">Tambah/Edit Stock</h3>
              <button onClick={() => setShowModal(null)} className="p-1 hover:bg-slate-100 rounded-lg"><X size={20}/></button>
            </div>
            <div className="p-6 space-y-6 text-sm">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-600">Pilih Produk</label>
                  <div className="relative">
                    <select id="stock-prod-select" className="w-full appearance-none bg-white border border-blue-500 rounded-full px-4 py-2 font-bold outline-none">
                      <option value="">Pilih Produk</option>
                      {products.map(p => <option key={p.id} value={p.id}>{p.nama}</option>)}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                  </div>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-600">Pilih Supplier</label>
                  <div className="relative">
                    <select id="stock-supp-select" className="w-full appearance-none bg-white border border-blue-500 rounded-full px-4 py-2 font-bold outline-none">
                      <option value="">Pilih Supplier</option>
                      {suppliers.map(s => <option key={s.id} value={s.id}>{s.nama}</option>)}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5"><label className="text-xs font-bold text-slate-600">Stock Awal</label><input type="number" value={currentStock.stock} onChange={e=>setCurrentStock(p=>({...p, stock: parseInt(e.target.value) || 0}))} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2 font-medium" /></div>
                <div className="space-y-1.5"><label className="text-xs font-bold text-slate-600">Harga Dasar (Rp)</label><input type="number" value={currentStock.hpp} onChange={e=>setCurrentStock(p=>({...p, hpp: parseInt(e.target.value) || 0}))} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2 font-medium" placeholder="100000" /></div>
              </div>
              <div className="space-y-1.5"><label className="text-xs font-bold text-slate-600">Harga Jual (Rp)</label><input type="number" value={currentStock.hargaJual} onChange={e=>setCurrentStock(p=>({...p, hargaJual: parseInt(e.target.value) || 0}))} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2 font-medium" placeholder="1000000" /></div>

              <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                <p className="text-[10px] font-bold text-blue-400 uppercase tracking-widest mb-1">SKU OTOMATIS</p>
                <p className="font-bold text-slate-600">-</p>
              </div>
            </div>
            <div className="px-6 py-4 border-t flex justify-end gap-3 bg-slate-50/50">
              <button onClick={() => setShowModal(null)} className="px-6 py-2 bg-white border border-slate-200 rounded-xl font-bold text-slate-500 flex items-center gap-2 hover:bg-slate-50"><X size={14}/> Batal</button>
              <button onClick={saveStockLot} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold text-sm flex items-center gap-2 shadow-lg shadow-blue-600/20"><Save size={14}/> Simpan Stock Lot</button>
            </div>
          </div>
        </div>
      )}

      {/* Existing Customer & Transaction Modals maintained... */}
      {/* ... previous code logic for customer and trx modals ... */}

      {/* (Floating Assistant button omitted but logic maintained) */}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, Users, Package, LineChart, FileEdit, ShieldCheck, 
  LogOut, Menu, X, Sun, Moon, Search, Plus, Phone, MessageSquare, 
  Send, Trash2, Edit3, ChevronDown, Check, AlertCircle, TrendingUp, Clock,
  Printer, History, Briefcase, ExternalLink, Calculator, Save, PlusCircle, Trash,
  Mail, FileText, Globe, UserCircle, RotateCcw, Download, Info
} from 'lucide-react';

// --- Interfaces ---
type Role = 'superadmin' | 'admin' | 'sales' | 'purchasing' | 'pajak' | 'finance' | 'stockist' | 'audit' | 'engineer';

interface User { username: string; role: Role; }

interface Supplier { id: string; nama: string; kode: string; npwp: string; }

interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product { id: string; nama: string; kode: string; lots: ProductLot[]; }

interface Customer {
  id: string; kode: string; nama: string; jenis: string; phone: string;
  email: string; alamat: string; sales: string; leadType: string;
  source: string; npwp: string; keterangan: string;
}

interface TransactionItem {
  produkId: string; nama: string; sku: string; harga: number; qty: number; diskon: number;
}

interface Transaction {
  id: string; noTrx: string; tanggal: string; customerName: string;
  items: TransactionItem[]; nilaiProyek: number; ppn: boolean; ongkir: boolean;
  biayaOngkir: number; jasaKirim: string; status: 'Selesai' | 'Progress' | 'Batal';
  sales: string; keterangan: string; skuHistory: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({});
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [currentStock, setCurrentStock] = useState<Partial<ProductLot>>({ stock: 0, hpp: 0, hargaJual: 0 });

  // Filters
  const [searchQuery, setSearchQuery] = useState('');
  const [prodFilter, setProdFilter] = useState('-- Semua Produk --');
  const [skuFilter, setSkuFilter] = useState('-- Semua SKU --');

  // Persistence
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');
    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Calculations & Derived
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => t.customerName.toLowerCase().includes(searchQuery.toLowerCase()) || t.noTrx.toLowerCase().includes(searchQuery.toLowerCase()));
  }, [transactions, searchQuery]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesProd = prodFilter === '-- Semua Produk --' || p.nama === prodFilter;
      const matchesSku = skuFilter === '-- Semua SKU --' || p.lots.some(l => l.sku === skuFilter);
      return matchesProd && matchesSku;
    });
  }, [products, prodFilter, skuFilter]);

  // Handlers
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data!");
    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`, nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowModal(null);
    setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 });
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
    setCurrentCust({ jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel' });
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Lengkapi data!");
    const newProd = { ...currentProd, id: currentProd.id || Date.now().toString(), lots: currentProd.lots || [] } as Product;
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowModal(null);
    setCurrentProd({});
  };

  const saveSupplier = () => {
    if (!currentSupp.nama || !currentSupp.kode) return alert("Lengkapi!");
    setSuppliers(prev => [...prev, { ...currentSupp, id: Date.now().toString() } as Supplier]);
    setCurrentSupp({});
  };

  const saveStockLot = () => {
    const prodId = (document.getElementById('stock-prod-select') as HTMLSelectElement)?.value;
    const suppId = (document.getElementById('stock-supp-select') as HTMLSelectElement)?.value;
    if (!prodId || !suppId) return alert("Pilih Produk dan Supplier!");
    const newLot: ProductLot = { lot: Date.now(), sku: `${products.find(p=>p.id===prodId)?.kode}${Date.now()}`, supplierId: suppId, stock: currentStock.stock || 0, hpp: currentStock.hpp || 0, hargaJual: currentStock.hargaJual || 0, tanggal: new Date().toISOString() };
    setProducts(prev => prev.map(p => p.id === prodId ? { ...p, lots: [...p.lots, newLot] } : p));
    setShowModal(null);
    setCurrentStock({ stock: 0, hpp: 0, hargaJual: 0 });
  };

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>
      <aside className="w-72 bg-white dark:bg-[#1e293b] border-r border-slate-200 dark:border-slate-800 p-6 flex flex-col">
        <div className="flex items-center gap-4 mb-10"><div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white"><Package size={20}/></div><h1 className="font-black text-xl">MyPanca</h1></div>
        <nav className="flex-1 space-y-1">
          <button onClick={()=>setActivePanel('dashboard')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activePanel==='dashboard'?'bg-blue-600 text-white':'text-slate-500 hover:bg-slate-100'}`}><LayoutDashboard size={18}/> Dashboard</button>
          <button onClick={()=>setActivePanel('tracking')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activePanel==='tracking'?'bg-blue-600 text-white':'text-slate-500 hover:bg-slate-100'}`}><LineChart size={18}/> Transaksi</button>
          <button onClick={()=>setActivePanel('customer')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activePanel==='customer'?'bg-blue-600 text-white':'text-slate-500 hover:bg-slate-100'}`}><Users size={18}/> Customer</button>
          <button onClick={()=>setActivePanel('produk')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activePanel==='produk'?'bg-blue-600 text-white':'text-slate-500 hover:bg-slate-100'}`}><Package size={18}/> Produk & Stock</button>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto p-8">
        <header className="flex justify-between mb-8">
          <h2 className="text-2xl font-black">{activePanel.toUpperCase()}</h2>
          <button onClick={()=>setIsDarkMode(!isDarkMode)} className="p-2 bg-white rounded-xl shadow-sm"><Sun size={20}/></button>
        </header>

        {activePanel === 'tracking' && (
          <div className="bg-white rounded-3xl p-8 border border-slate-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold">Daftar Transaksi</h3>
              <button onClick={()=>{setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 }); setShowModal('trx');}} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2"><Plus size={20}/> Tambah Transaksi</button>
            </div>
            <table className="w-full text-sm">
              <thead className="text-slate-400 font-bold border-b"><tr className="text-left"><th className="pb-4">No TRX</th><th className="pb-4">Customer</th><th className="pb-4">Nilai</th><th className="pb-4">Status</th></tr></thead>
              <tbody>
                {filteredTransactions.map(t => (
                  <tr key={t.id} className="border-b last:border-0 hover:bg-slate-50 cursor-pointer" onClick={()=>{setCurrentTrx(t); setShowModal('trx');}}>
                    <td className="py-4 font-bold">{t.noTrx}</td><td className="py-4">{t.customerName}</td><td className="py-4 font-black text-blue-600">Rp{t.nilaiProyek.toLocaleString('id-ID')}</td><td className="py-4"><span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase ${t.status==='Selesai'?'bg-emerald-100 text-emerald-600':'bg-amber-100 text-amber-600'}`}>{t.status}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activePanel === 'customer' && (
          <div className="bg-white rounded-3xl p-8 border border-slate-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold">Daftar Customer</h3>
              <button onClick={()=>{setCurrentCust({jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'}); setShowModal('cust');}} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2"><Plus size={20}/> Tambah Customer</button>
            </div>
            <div className="grid grid-cols-4 gap-6">
              {customers.map(c => (
                <div key={c.id} className="bg-slate-50 p-6 rounded-2xl border border-slate-100 hover:border-blue-500 cursor-pointer" onClick={()=>{setCurrentCust(c); setShowModal('cust');}}>
                  <div className="w-10 h-10 bg-blue-100 text-blue-600 rounded-xl flex items-center justify-center font-bold mb-4">{c.nama[0]}</div>
                  <h4 className="font-bold text-sm truncate">{c.nama}</h4>
                  <p className="text-[10px] text-slate-400 font-bold uppercase">{c.kode}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {activePanel === 'produk' && (
          <div className="space-y-10">
            <div className="flex flex-col gap-4">
              <h3 className="text-xl font-bold">Produk & Stock</h3>
              <p className="text-sm text-slate-500 -mt-3">Kelola produk, supplier, dan stock</p>
              <div className="flex gap-3">
                <button onClick={() => setShowModal('prod')} className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2 hover:bg-blue-700 transition-all"><Plus size={18} /> Tambah Produk</button>
                <button onClick={() => setShowModal('supp')} className="bg-white border border-slate-200 px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2 hover:bg-slate-50 transition-all"><FileText size={18} /> Kelola Supplier</button>
                <button onClick={() => setShowModal('stock')} className="bg-emerald-500 text-white px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2 hover:bg-emerald-600 transition-all"><Download size={18} /> Tambah/Edit Stock</button>
              </div>
            </div>

            <div className="space-y-4">
              <h4 className="font-bold">Cek/Edit Stock</h4>
              <div className="grid grid-cols-2 gap-4">
                <select value={prodFilter} onChange={e=>setProdFilter(e.target.value)} className="w-full bg-white border border-blue-500 rounded-full px-4 py-2 font-bold text-sm"><option>-- Semua Produk --</option>{products.map(p=><option key={p.id}>{p.nama}</option>)}</select>
                <select value={skuFilter} onChange={e=>setSkuFilter(e.target.value)} className="w-full bg-white border border-blue-500 rounded-full px-4 py-2 font-bold text-sm"><option>-- Semua SKU --</option>{products.flatMap(p=>p.lots).map(l=><option key={l.sku}>{l.sku}</option>)}</select>
              </div>
            </div>

            <div className="grid grid-cols-4 gap-6">
              {filteredProducts.map(p => (
                <div key={p.id} className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm flex flex-col gap-4 hover:border-blue-500">
                  <div className="flex gap-4 items-center"><div className="w-10 h-10 bg-blue-100 rounded-xl flex items-center justify-center text-blue-600"><Package size={20}/></div><h5 className="font-bold text-sm truncate">{p.nama}</h5></div>
                  <div className="text-xs space-y-1">
                    <p className="text-slate-400">Harga Jual: <span className="font-black text-blue-600">Rp{(p.lots[p.lots.length-1]?.hargaJual||0).toLocaleString('id-ID')}</span></p>
                    <p className="text-slate-400">Stock: <span className="font-black text-blue-600">{p.lots.reduce((a,b)=>a+b.stock,0)}</span></p>
                  </div>
                  <button className="w-full bg-blue-50 text-blue-600 py-2 rounded-xl text-[10px] font-bold uppercase">Lihat Riwayat</button>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {/* --- MODALS --- */}

      {/* 1. MODAL TRANSAKSI (FUNGSI BARIS PRODUK DI-RESTORE) */}
      {showModal === 'trx' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-2xl rounded-2xl shadow-2xl flex flex-col h-[95vh]">
            <div className="px-6 py-4 border-b flex justify-between items-center"><h3 className="font-bold">Tambah/Edit Transaksi</h3><button onClick={()=>setShowModal(null)}><X size={20}/></button></div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6 text-xs">
              <div className="grid grid-cols-2 gap-4">
                <input type="date" value={currentTrx.tanggal} onChange={e=>setCurrentTrx({...currentTrx, tanggal: e.target.value})} className="border p-2 rounded-lg"/>
                <select value={currentTrx.customerName} onChange={e=>{const c=customers.find(x=>x.nama===e.target.value); setCurrentTrx({...currentTrx, customerName: e.target.value, sales: c?.sales || 'admin'});}} className="border p-2 rounded-lg">
                  <option value="">Pilih Customer</option>{customers.map(c=><option key={c.id} value={c.nama}>{c.nama}</option>)}
                </select>
              </div>
              <div className="space-y-4">
                <div className="flex justify-between items-center"><h4 className="font-bold">Items</h4><button onClick={()=>{setCurrentTrx({...currentTrx, items: [...(currentTrx.items||[]), {produkId: '', nama: '', sku: '', harga: 0, qty: 1, diskon: 0}]})}} className="text-blue-600 font-bold flex items-center gap-1"><PlusCircle size={14}/> Tambah Baris</button></div>
                {currentTrx.items?.map((item, idx) => (
                  <div key={idx} className="bg-slate-50 p-4 rounded-xl border grid grid-cols-12 gap-2">
                    <select className="col-span-4 border rounded-lg p-1" value={item.nama} onChange={e=>{const p=products.find(x=>x.nama===e.target.value); const lot=p?.lots[0]; const n=[...currentTrx.items!]; n[idx]={...item, nama: e.target.value, sku: lot?.sku||'', harga: lot?.hargaJual||0}; setCurrentTrx({...currentTrx, items: n})}}><option value="">Pilih Produk</option>{products.map(p=><option key={p.id} value={p.nama}>{p.nama}</option>)}</select>
                    <select className="col-span-2 border rounded-lg p-1" value={item.sku} onChange={e=>{const p=products.find(x=>x.nama===item.nama); const lot=p?.lots.find(l=>l.sku===e.target.value); const n=[...currentTrx.items!]; n[idx]={...item, sku: e.target.value, harga: lot?.hargaJual||0}; setCurrentTrx({...currentTrx, items: n})}}><option value="">SKU</option>{products.find(x=>x.nama===item.nama)?.lots.map(l=><option key={l.sku} value={l.sku}>{l.sku}</option>)}</select>
                    <input type="number" placeholder="Qty" className="col-span-2 border rounded-lg p-1" value={item.qty} onChange={e=>{const n=[...currentTrx.items!]; n[idx]={...item, qty: parseInt(e.target.value)||0}; setCurrentTrx({...currentTrx, items: n})}}/>
                    <input type="number" placeholder="Disc" className="col-span-2 border rounded-lg p-1" value={item.diskon} onChange={e=>{const n=[...currentTrx.items!]; n[idx]={...item, diskon: parseInt(e.target.value)||0}; setCurrentTrx({...currentTrx, items: n})}}/>
                    <p className="col-span-1 flex items-center font-bold">Rp{((item.harga*item.qty)-item.diskon).toLocaleString()}</p>
                    <button onClick={()=>{const n=[...currentTrx.items!]; n.splice(idx,1); setCurrentTrx({...currentTrx, items: n})}} className="col-span-1 text-rose-500"><Trash size={14}/></button>
                  </div>
                ))}
              </div>
              <div className="p-4 bg-emerald-50 rounded-xl space-y-3">
                <div className="flex gap-4"><label className="flex items-center gap-2"><input type="checkbox" checked={currentTrx.ppn} onChange={e=>setCurrentTrx({...currentTrx, ppn: e.target.checked})}/> PPN 11%</label><label className="flex items-center gap-2"><input type="checkbox" checked={currentTrx.ongkir} onChange={e=>setCurrentTrx({...currentTrx, ongkir: e.target.checked})}/> Ongkir</label></div>
                {currentTrx.ongkir && <div className="grid grid-cols-2 gap-4"><select className="border rounded-lg p-2" value={currentTrx.jasaKirim} onChange={e=>setCurrentTrx({...currentTrx, jasaKirim: e.target.value})}><option value="">Pilih Kurir</option><option value="JNE">JNE</option><option value="J&T">J&T</option></select><input type="number" placeholder="Biaya" className="border rounded-lg p-2" value={currentTrx.biayaOngkir} onChange={e=>setCurrentTrx({...currentTrx, biayaOngkir: parseInt(e.target.value)||0})}/></div>}
              </div>
              <div className="text-right border-t pt-4"><p className="text-slate-400">Total Tagihan:</p><h4 className="text-2xl font-black text-blue-600">Rp{trxCalculations.grandTotal.toLocaleString('id-ID')}</h4></div>
            </div>
            <div className="p-6 border-t flex justify-end gap-3"><button onClick={()=>setShowModal(null)} className="px-6 py-2 border rounded-xl">Batal</button><button onClick={saveTransaction} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold">Simpan Transaksi</button></div>
          </div>
        </div>
      )}

      {/* 2. MODAL CUSTOMER (FORM LENGKAP SESUAI SCREENSHOT) */}
      {showModal === 'cust' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl flex flex-col h-[95vh]">
            <div className="px-6 py-4 border-b flex justify-between items-center"><h3 className="font-bold">Tambah Customer Baru</h3><button onClick={()=>setShowModal(null)}><X size={20}/></button></div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6 text-xs">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold">Nama Customer *</label><input value={currentCust.nama||''} onChange={e=>setCurrentCust({...currentCust, nama:e.target.value})} className="w-full border p-2 rounded-lg" placeholder="Nama"/></div>
                <div className="space-y-1"><label className="font-bold">Jenis</label><select value={currentCust.jenis||'Perusahaan'} onChange={e=>setCurrentCust({...currentCust, jenis:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2"><option value="Perusahaan">Perusahaan</option><option value="Perorangan">Perorangan</option></select></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold">Email</label><input value={currentCust.email||''} onChange={e=>setCurrentCust({...currentCust, email:e.target.value})} className="w-full border p-2 rounded-lg" placeholder="Email"/></div>
                <div className="space-y-1"><label className="font-bold">No Telp</label><input value={currentCust.phone||''} onChange={e=>setCurrentCust({...currentCust, phone:e.target.value})} className="w-full border p-2 rounded-lg" placeholder="No Telp"/></div>
              </div>
              <div className="space-y-1"><label className="font-bold">Alamat</label><textarea value={currentCust.alamat||''} onChange={e=>setCurrentCust({...currentCust, alamat:e.target.value})} className="w-full border p-2 rounded-lg h-20 resize-none"/></div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold">Jenis Leads</label><select value={currentCust.leadType||'Belum Transaksi'} onChange={e=>setCurrentCust({...currentCust, leadType:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2"><option value="Belum Transaksi">Belum Transaksi</option><option value="Sudah Transaksi">Sudah Transaksi</option></select></div>
                <div className="space-y-1"><label className="font-bold">Sumber Leads</label><select value={currentCust.source||'Organic'} onChange={e=>setCurrentCust({...currentCust, source:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2"><option value="Organic">Organic</option><option value="Paid Ads">Paid Ads</option></select></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold">Nama Sales</label><select value={currentCust.sales||'Angel'} onChange={e=>setCurrentCust({...currentCust, sales:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2"><option value="Angel">Angel</option><option value="Maria">Maria</option></select></div>
                <div className="space-y-1"><label className="font-bold">Keterangan</label><input value={currentCust.keterangan||''} onChange={e=>setCurrentCust({...currentCust, keterangan:e.target.value})} className="w-full border p-2 rounded-lg"/></div>
              </div>
              <div className="space-y-1"><label className="font-bold">NPWP</label><input value={currentCust.npwp||''} onChange={e=>setCurrentCust({...currentCust, npwp:e.target.value})} className="w-full border p-2 rounded-lg" placeholder="NPWP"/></div>
            </div>
            <div className="p-6 border-t flex justify-end gap-3"><button onClick={()=>setShowModal(null)} className="px-6 py-2 border rounded-xl font-bold">Batal</button><button onClick={saveCustomer} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold flex items-center gap-2"><Save size={14}/> Simpan Customer</button></div>
          </div>
        </div>
      )}

      {/* 3. MODAL TAMBAH PRODUK (IMAGE 1) */}
      {showModal === 'prod' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="px-6 py-4 border-b flex justify-between items-center"><h3 className="font-bold">Tambah Produk</h3><button onClick={()=>setShowModal(null)}><X size={20}/></button></div>
            <div className="p-6 space-y-6">
              <div className="space-y-1"><label className="text-xs font-bold">Nama Produk</label><input value={currentProd.nama||''} onChange={e=>setCurrentProd({...currentProd, nama:e.target.value})} className="w-full border p-2.5 rounded-xl outline-none" placeholder="Nama produk"/></div>
              <div className="space-y-1"><label className="text-xs font-bold">Kode Produk</label><input value={currentProd.kode||''} onChange={e=>setCurrentProd({...currentProd, kode:e.target.value})} className="w-full border p-2.5 rounded-xl outline-none" placeholder="Contoh: PT02"/></div>
            </div>
            <div className="px-6 py-4 border-t flex justify-end gap-3 bg-slate-50/50">
              <button onClick={()=>setShowModal(null)} className="px-6 py-2 border rounded-xl font-bold flex items-center gap-2"><X size={14}/> Batal</button>
              <button onClick={saveProduct} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20"><Save size={14}/> Simpan Produk</button>
            </div>
          </div>
        </div>
      )}

      {/* 4. MODAL SUPPLIER (IMAGE 2) */}
      {showModal === 'supp' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl flex flex-col h-[90vh] overflow-hidden">
            <div className="px-6 py-4 border-b flex justify-between items-center"><h3 className="font-bold">Kelola Supplier</h3><button onClick={()=>setShowModal(null)}><X size={20}/></button></div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6 text-xs">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold">Nama Perusahaan</label><input value={currentSupp.nama||''} onChange={e=>setCurrentSupp({...currentSupp, nama:e.target.value})} className="w-full border p-2.5 rounded-lg" placeholder="PT. Maju Jaya"/></div>
                <div className="space-y-1"><label className="font-bold">Kode Perusahaan</label><input value={currentSupp.kode||''} onChange={e=>setCurrentSupp({...currentSupp, kode:e.target.value})} className="w-full border p-2.5 rounded-lg" placeholder="MJ-001"/></div>
              </div>
              <div className="space-y-1"><label className="font-bold">NPWP</label><input value={currentSupp.npwp||''} onChange={e=>setCurrentSupp({...currentSupp, npwp:e.target.value})} className="w-full border p-2.5 rounded-lg" placeholder="12.345..."/></div>
              <div className="flex justify-end gap-3 border-b pb-6"><button onClick={()=>setCurrentSupp({})} className="px-6 py-2 border rounded-xl flex items-center gap-2 font-bold"><RotateCcw size={14}/> Reset</button><button onClick={saveSupplier} className="px-6 py-2 bg-blue-600 text-white rounded-xl flex items-center gap-2 font-bold"><Plus size={14}/> Tambah Supplier</button></div>
              <div className="space-y-4">
                <h4 className="font-bold text-slate-400 uppercase tracking-widest text-[10px]">Daftar Supplier</h4>
                <div className="border rounded-xl overflow-hidden"><table className="w-full text-left text-xs"><thead className="bg-slate-50 border-b"><tr><th className="px-4 py-3">Nama</th><th className="px-4 py-3">Kode</th></tr></thead><tbody className="divide-y">{suppliers.map(s=>(<tr key={s.id} className="hover:bg-slate-50"><td className="px-4 py-3 font-medium">{s.nama}</td><td className="px-4 py-3 text-slate-500">{s.kode}</td></tr>))}</tbody></table></div>
              </div>
            </div>
            <div className="p-6 border-t flex justify-end bg-slate-50/50"><button onClick={()=>setShowModal(null)} className="px-8 py-2 border rounded-xl font-bold flex items-center gap-2"><X size={14}/> Tutup</button></div>
          </div>
        </div>
      )}

      {/* 5. MODAL STOCK (IMAGE 3) */}
      {showModal === 'stock' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden">
            <div className="px-6 py-4 border-b flex justify-between items-center"><h3 className="font-bold">Tambah/Edit Stock</h3><button onClick={()=>setShowModal(null)}><X size={20}/></button></div>
            <div className="p-6 space-y-6 text-sm">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="text-xs font-bold">Pilih Produk</label><select id="stock-prod-select" className="w-full border-2 border-blue-500 rounded-full p-2 font-bold"><option value="">Pilih</option>{products.map(p=><option key={p.id} value={p.id}>{p.nama}</option>)}</select></div>
                <div className="space-y-1"><label className="text-xs font-bold">Pilih Supplier</label><select id="stock-supp-select" className="w-full border-2 border-blue-500 rounded-full p-2 font-bold"><option value="">Pilih</option>{suppliers.map(s=><option key={s.id} value={s.id}>{s.nama}</option>)}</select></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="text-xs font-bold">Stock Awal</label><input type="number" value={currentStock.stock} onChange={e=>setCurrentStock({...currentStock, stock: parseInt(e.target.value)||0})} className="w-full border p-2 rounded-xl"/></div>
                <div className="space-y-1"><label className="text-xs font-bold">Harga Dasar (Rp)</label><input type="number" value={currentStock.hpp} onChange={e=>setCurrentStock({...currentStock, hpp: parseInt(e.target.value)||0})} className="w-full border p-2 rounded-xl"/></div>
              </div>
              <div className="space-y-1"><label className="text-xs font-bold">Harga Jual (Rp)</label><input type="number" value={currentStock.hargaJual} onChange={e=>setCurrentStock({...currentStock, hargaJual: parseInt(e.target.value)||0})} className="w-full border p-2 rounded-xl"/></div>
              <div className="bg-slate-50 p-4 rounded-xl border"><p className="text-[10px] font-bold text-blue-400 uppercase tracking-widest">SKU OTOMATIS</p><p className="font-bold">-</p></div>
            </div>
            <div className="px-6 py-4 border-t flex justify-end gap-3 bg-slate-50/50"><button onClick={()=>setShowModal(null)} className="px-6 py-2 border rounded-xl font-bold flex items-center gap-2"><X size={14}/> Batal</button><button onClick={saveStockLot} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20"><Save size={14}/> Simpan Stock Lot</button></div>
          </div>
        </div>
      )}

      {/* Assistant */}
      <button className="fixed bottom-10 right-10 w-16 h-16 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center z-50 animate-bounce"><MessageSquare/></button>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, Users, Package, LineChart, FileEdit, ShieldCheck, 
  LogOut, Menu, X, Sun, Moon, Search, Plus, Phone, MessageSquare, 
  Send, Trash2, Edit3, ChevronDown, Check, AlertCircle, TrendingUp, Clock,
  Printer, History, Briefcase, ExternalLink, Calculator, Save, PlusCircle, Trash,
  Mail, FileText, Globe, UserCircle, RotateCcw, Download, Info
} from 'lucide-react';

// --- Interfaces ---
type Role = 'superadmin' | 'admin' | 'sales' | 'purchasing' | 'pajak' | 'finance' | 'stockist' | 'audit' | 'engineer';

interface User { username: string; role: Role; }

interface Supplier { id: string; nama: string; kode: string; npwp: string; }

interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product { id: string; nama: string; kode: string; lots: ProductLot[]; }

interface Customer {
  id: string; kode: string; nama: string; jenis: string; phone: string;
  email: string; alamat: string; sales: string; leadType: string;
  source: string; npwp: string; keterangan: string;
}

interface TransactionItem {
  produkId: string; nama: string; sku: string; harga: number; qty: number; diskon: number;
}

interface Transaction {
  id: string; noTrx: string; tanggal: string; customerName: string;
  items: TransactionItem[]; nilaiProyek: number; ppn: boolean; ongkir: boolean;
  biayaOngkir: number; jasaKirim: string; status: 'Selesai' | 'Progress' | 'Batal';
  sales: string; keterangan: string; skuHistory: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({});
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [currentStock, setCurrentStock] = useState<Partial<ProductLot>>({ stock: 0, hpp: 0, hargaJual: 0 });

  // Filters
  const [searchQuery, setSearchQuery] = useState('');
  const [prodFilter, setProdFilter] = useState('-- Semua Produk --');
  const [skuFilter, setSkuFilter] = useState('-- Semua SKU --');

  // Persistence
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');
    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Calculations & Derived
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => t.customerName.toLowerCase().includes(searchQuery.toLowerCase()) || t.noTrx.toLowerCase().includes(searchQuery.toLowerCase()));
  }, [transactions, searchQuery]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesProd = prodFilter === '-- Semua Produk --' || p.nama === prodFilter;
      const matchesSku = skuFilter === '-- Semua SKU --' || p.lots.some(l => l.sku === skuFilter);
      return matchesProd && matchesSku;
    });
  }, [products, prodFilter, skuFilter]);

  // Handlers
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data!");
    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`, nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowModal(null);
    setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 });
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
    setCurrentCust({ jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel' });
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Lengkapi data!");
    const newProd = { ...currentProd, id: currentProd.id || Date.now().toString(), lots: currentProd.lots || [] } as Product;
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowModal(null);
    setCurrentProd({});
  };

  const saveSupplier = () => {
    if (!currentSupp.nama || !currentSupp.kode) return alert("Lengkapi!");
    setSuppliers(prev => [...prev, { ...currentSupp, id: Date.now().toString() } as Supplier]);
    setCurrentSupp({});
  };

  const saveStockLot = () => {
    const prodId = (document.getElementById('stock-prod-select') as HTMLSelectElement)?.value;
    const suppId = (document.getElementById('stock-supp-select') as HTMLSelectElement)?.value;
    if (!prodId || !suppId) return alert("Pilih Produk dan Supplier!");
    const newLot: ProductLot = { lot: Date.now(), sku: `${products.find(p=>p.id===prodId)?.kode}${Date.now()}`, supplierId: suppId, stock: currentStock.stock || 0, hpp: currentStock.hpp || 0, hargaJual: currentStock.hargaJual || 0, tanggal: new Date().toISOString() };
    setProducts(prev => prev.map(p => p.id === prodId ? { ...p, lots: [...p.lots, newLot] } : p));
    setShowModal(null);
    setCurrentStock({ stock: 0, hpp: 0, hargaJual: 0 });
  };

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>
      <aside className="w-72 bg-white dark:bg-[#1e293b] border-r border-slate-200 dark:border-slate-800 p-6 flex flex-col">
        <div className="flex items-center gap-4 mb-10"><div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white"><Package size={20}/></div><h1 className="font-black text-xl">MyPanca</h1></div>
        <nav className="flex-1 space-y-1">
          <button onClick={()=>setActivePanel('dashboard')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activePanel==='dashboard'?'bg-blue-600 text-white':'text-slate-500 hover:bg-slate-100'}`}><LayoutDashboard size={18}/> Dashboard</button>
          <button onClick={()=>setActivePanel('tracking')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activePanel==='tracking'?'bg-blue-600 text-white':'text-slate-500 hover:bg-slate-100'}`}><LineChart size={18}/> Transaksi</button>
          <button onClick={()=>setActivePanel('customer')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activePanel==='customer'?'bg-blue-600 text-white':'text-slate-500 hover:bg-slate-100'}`}><Users size={18}/> Customer</button>
          <button onClick={()=>setActivePanel('produk')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activePanel==='produk'?'bg-blue-600 text-white':'text-slate-500 hover:bg-slate-100'}`}><Package size={18}/> Produk & Stock</button>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto p-8">
        <header className="flex justify-between mb-8">
          <h2 className="text-2xl font-black">{activePanel.toUpperCase()}</h2>
          <button onClick={()=>setIsDarkMode(!isDarkMode)} className="p-2 bg-white rounded-xl shadow-sm"><Sun size={20}/></button>
        </header>

        {activePanel === 'tracking' && (
          <div className="bg-white rounded-3xl p-8 border border-slate-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold">Daftar Transaksi</h3>
              <button onClick={()=>{setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 }); setShowModal('trx');}} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2"><Plus size={20}/> Tambah Transaksi</button>
            </div>
            <table className="w-full text-sm">
              <thead className="text-slate-400 font-bold border-b"><tr className="text-left"><th className="pb-4">No TRX</th><th className="pb-4">Customer</th><th className="pb-4">Nilai</th><th className="pb-4">Status</th></tr></thead>
              <tbody>
                {filteredTransactions.map(t => (
                  <tr key={t.id} className="border-b last:border-0 hover:bg-slate-50 cursor-pointer" onClick={()=>{setCurrentTrx(t); setShowModal('trx');}}>
                    <td className="py-4 font-bold">{t.noTrx}</td><td className="py-4">{t.customerName}</td><td className="py-4 font-black text-blue-600">Rp{t.nilaiProyek.toLocaleString('id-ID')}</td><td className="py-4"><span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase ${t.status==='Selesai'?'bg-emerald-100 text-emerald-600':'bg-amber-100 text-amber-600'}`}>{t.status}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* --- MODAL TRANSAKSI (FUNGSI PENUH) --- */}
        {showModal === 'trx' && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 overflow-y-auto">
            <div className="bg-white dark:bg-[#1e293b] w-full max-w-2xl rounded-2xl shadow-2xl flex flex-col h-[95vh] animate-in zoom-in-95 duration-200">
              <div className="px-6 py-4 border-b flex justify-between items-center">
                <h3 className="text-lg font-bold text-slate-800 dark:text-white">Tambah Transaksi</h3>
                <button onClick={() => setShowModal(null)} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg"><X size={20}/></button>
              </div>
              <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar text-[13px]">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5"><label className="text-[11px] font-bold text-slate-500">Tanggal</label><input type="date" value={currentTrx.tanggal} onChange={e => setCurrentTrx(p=>({...p, tanggal: e.target.value}))} className="w-full bg-white border border-slate-200 rounded-lg px-4 py-2 font-medium outline-none focus:border-blue-500 transition-all" /></div>
                  <div className="space-y-1.5"><label className="text-[11px] font-bold text-slate-500">Pilih Customer *</label><div className="relative"><select value={currentTrx.customerName || ''} onChange={e => { const cust = customers.find(c=>c.nama===e.target.value); setCurrentTrx(prev => ({ ...prev, customerName: e.target.value, sales: cust?.sales || 'admin' })); }} className="w-full appearance-none bg-white border-2 border-blue-500 rounded-full px-4 py-2 font-bold outline-none pr-10"><option value="">Pilih Customer</option>{customers.map(c => <option key={c.id} value={c.nama}>{c.nama}</option>)}</select><ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/></div></div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5"><label className="text-[11px] font-bold text-slate-500">Jenis Customer</label><input readOnly value={selectedCustomer?.jenis || ''} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2 font-medium text-slate-400 outline-none" /></div>
                  <div className="space-y-1.5"><label className="text-[11px] font-bold text-slate-500">No Telp</label><input readOnly value={selectedCustomer?.phone || ''} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2 font-medium text-slate-400 outline-none" /></div>
                </div>
                <div className="space-y-1.5"><label className="text-[11px] font-bold text-slate-500">Alamat</label><textarea readOnly value={selectedCustomer?.alamat || ''} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2 font-medium text-slate-400 outline-none h-20 resize-none" /></div>

                <div className="space-y-4 pt-2">
                  <div className="flex justify-between items-center"><h4 className="text-[12px] font-bold text-slate-800 dark:text-white">Daftar Produk</h4><button onClick={() => setCurrentTrx(prev => ({ ...prev, items: [...(prev.items || []), { produkId: '', nama: '', sku: '', harga: 0, qty: 1, diskon: 0 }] }))} className="text-blue-600 font-bold flex items-center gap-1 hover:underline"><PlusCircle size={14}/> Tambah Baris</button></div>
                  <div className="space-y-3">
                    {currentTrx.items?.map((item, idx) => (
                      <div key={idx} className="bg-slate-50 p-4 rounded-xl border border-slate-100 relative grid grid-cols-12 gap-2 items-end">
                        <div className="col-span-3 space-y-1"><label className="text-[10px] font-bold text-slate-400">Produk</label><select value={item.nama} onChange={e => { const prod = products.find(p => p.nama === e.target.value); const lot = prod?.lots[0]; const newItems = [...(currentTrx.items || [])]; newItems[idx] = { ...item, nama: e.target.value, produkId: prod?.id || '', sku: lot?.sku || '', harga: lot?.hargaJual || 0 }; setCurrentTrx(prev => ({ ...prev, items: newItems })); }} className="w-full border-2 border-blue-500 rounded-full px-2 py-1.5 font-bold outline-none text-[11px]"><option value="">Pilih</option>{products.map(p => <option key={p.id} value={p.nama}>{p.nama}</option>)}</select></div>
                        <div className="col-span-2 space-y-1"><label className="text-[10px] font-bold text-slate-400">SKU</label><select value={item.sku} onChange={e => { const p = products.find(x => x.nama === item.nama); const lot = p?.lots.find(l => l.sku === e.target.value); const newItems = [...(currentTrx.items || [])]; newItems[idx] = { ...item, sku: e.target.value, harga: lot?.hargaJual || 0 }; setCurrentTrx(prev => ({ ...prev, items: newItems })); }} className="w-full border-2 border-blue-500 rounded-full px-2 py-1.5 font-bold outline-none text-[11px]"><option value="">SKU</option>{products.find(x => x.nama === item.nama)?.lots.map(l => <option key={l.sku} value={l.sku}>{l.sku}</option>)}</select></div>
                        <div className="col-span-1.5 space-y-1"><label className="text-[10px] font-bold text-slate-400">Qty</label><input type="number" value={item.qty} onChange={e => { const newItems = [...(currentTrx.items || [])]; newItems[idx] = { ...item, qty: parseInt(e.target.value) || 0 }; setCurrentTrx(prev => ({ ...prev, items: newItems })); }} className="w-full border rounded-lg p-1.5 font-bold text-center" /></div>
                        <div className="col-span-1.5 space-y-1"><label className="text-[10px] font-bold text-slate-400">Disc</label><input type="number" value={item.diskon} onChange={e => { const newItems = [...(currentTrx.items || [])]; newItems[idx] = { ...item, diskon: parseInt(e.target.value) || 0 }; setCurrentTrx(prev => ({ ...prev, items: newItems })); }} className="w-full border rounded-lg p-1.5 font-bold text-center" /></div>
                        <div className="col-span-3 space-y-1"><label className="text-[10px] font-bold text-slate-400">Subtotal</label><input readOnly value={`Rp${((item.harga * item.qty) - item.diskon).toLocaleString()}`} className="w-full bg-slate-100 border rounded-lg p-1.5 font-bold text-slate-600" /></div>
                        <button onClick={() => setCurrentTrx(prev => ({ ...prev, items: prev.items?.filter((_, i) => i !== idx) }))} className="p-2 text-rose-500 hover:bg-rose-50 rounded-lg"><Trash2 size={16}/></button>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="flex gap-4 p-4 bg-slate-50 rounded-xl">
                  <label className="flex items-center gap-2 cursor-pointer font-bold"><input type="checkbox" checked={currentTrx.ppn} onChange={e => setCurrentTrx(p=>({...p, ppn: e.target.checked}))} /> PPN 11%</label>
                  <label className="flex items-center gap-2 cursor-pointer font-bold"><input type="checkbox" checked={currentTrx.ongkir} onChange={e => setCurrentTrx(p=>({...p, ongkir: e.target.checked}))} /> Termasuk Ongkir</label>
                </div>

                {currentTrx.ongkir && (
                  <div className="p-4 bg-emerald-50 border border-emerald-100 rounded-xl grid grid-cols-2 gap-4">
                    <div className="space-y-1.5"><label className="text-[11px] font-bold text-emerald-800">Jasa Pengiriman</label><select value={currentTrx.jasaKirim || ''} onChange={e => setCurrentTrx(p=>({...p, jasaKirim: e.target.value}))} className="w-full border-2 border-blue-500 rounded-full px-4 py-1.5 font-bold outline-none"><option value="">Pilih</option><option value="JNE">JNE</option><option value="J&T">J&T</option></select></div>
                    <div className="space-y-1.5"><label className="text-[11px] font-bold text-emerald-800">Biaya Ongkir (Rp)</label><input type="number" value={currentTrx.biayaOngkir} onChange={e => setCurrentTrx(p=>({...p, biayaOngkir: parseInt(e.target.value) || 0}))} className="w-full border rounded-lg px-4 py-1.5 font-bold outline-none" /></div>
                  </div>
                )}

                <div className="text-right border-t pt-4">
                  <p className="text-slate-400 font-bold uppercase text-[10px] tracking-widest">Total Tagihan Akhir</p>
                  <h4 className="text-3xl font-black text-blue-600">Rp{trxCalculations.grandTotal.toLocaleString('id-ID')}</h4>
                </div>

                <div className="space-y-1.5"><label className="text-[11px] font-bold text-slate-500">Keterangan</label><textarea value={currentTrx.keterangan || ''} onChange={e=>setCurrentTrx(p=>({...p, keterangan: e.target.value}))} className="w-full bg-white border border-slate-200 rounded-lg px-4 py-2 font-medium outline-none h-24 resize-none" placeholder="Catatan transaksi..." /></div>
              </div>
              <div className="px-6 py-4 border-t flex justify-end gap-3 bg-slate-50/50">
                <button onClick={() => setShowModal(null)} className="px-6 py-2 border border-slate-200 rounded-lg font-bold text-slate-500 text-sm flex items-center gap-2"><X size={14}/> Batal</button>
                <button onClick={saveTransaction} className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold text-sm flex items-center gap-2 shadow-lg shadow-blue-600/20"><Check size={14}/> Simpan Transaksi</button>
              </div>
            </div>
          </div>
        )}

        {/* Panel Lainnya (Customer, Produk) tetap ada tapi kodenya diringkas di sini untuk menghemat ruang */}
        {activePanel === 'customer' && (
          <div className="bg-white rounded-3xl p-8 border border-slate-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold">Daftar Customer</h3>
              <button onClick={()=>{setCurrentCust({jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'}); setShowModal('cust');}} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2"><Plus size={20}/> Tambah Customer</button>
            </div>
            <div className="grid grid-cols-4 gap-6">
              {customers.map(c => (
                <div key={c.id} className="bg-slate-50 p-6 rounded-2xl border border-slate-100 hover:border-blue-500 cursor-pointer" onClick={()=>{setCurrentCust(c); setShowModal('cust');}}>
                  <div className="w-10 h-10 bg-blue-100 text-blue-600 rounded-xl flex items-center justify-center font-bold mb-4">{c.nama[0]}</div>
                  <h4 className="font-bold text-sm truncate">{c.nama}</h4>
                  <p className="text-[10px] text-slate-400 font-bold uppercase">{c.kode}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {activePanel === 'produk' && (
          <div className="space-y-10">
            <div className="flex flex-col gap-4">
              <h3 className="text-xl font-bold">Produk & Stock</h3>
              <div className="flex gap-3">
                <button onClick={() => setShowModal('prod')} className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2 hover:bg-blue-700 transition-all"><Plus size={18} /> Tambah Produk</button>
                <button onClick={() => setShowModal('supp')} className="bg-white border border-slate-200 px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2 hover:bg-slate-50 transition-all"><FileText size={18} /> Kelola Supplier</button>
                <button onClick={() => setShowModal('stock')} className="bg-emerald-500 text-white px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2 hover:bg-emerald-600 transition-all"><Download size={18} /> Tambah/Edit Stock</button>
              </div>
            </div>
            <div className="grid grid-cols-4 gap-6">
              {filteredProducts.map(p => (
                <div key={p.id} className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm flex flex-col gap-4 hover:border-blue-500">
                  <div className="flex gap-4 items-center"><div className="w-10 h-10 bg-blue-100 rounded-xl flex items-center justify-center text-blue-600"><Package size={20}/></div><h5 className="font-bold text-sm truncate">{p.nama}</h5></div>
                  <p className="text-xs text-slate-400 font-bold">Stock: <span className="text-blue-600">{p.lots.reduce((a,b)=>a+b.stock,0)}</span></p>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {/* --- MODALS LAINNYA (CUSTOMER, PROD, SUPP, STOCK) --- */}
      {showModal === 'cust' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl flex flex-col h-[95vh]">
            <div className="px-6 py-4 border-b flex justify-between items-center"><h3 className="font-bold">Tambah Customer Baru</h3><button onClick={()=>setShowModal(null)}><X size={20}/></button></div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6 text-xs">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold">Nama Customer *</label><input value={currentCust.nama||''} onChange={e=>setCurrentCust({...currentCust, nama:e.target.value})} className="w-full border p-2 rounded-lg" placeholder="Nama"/></div>
                <div className="space-y-1"><label className="font-bold">Jenis</label><select value={currentCust.jenis||'Perusahaan'} onChange={e=>setCurrentCust({...currentCust, jenis:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2"><option value="Perusahaan">Perusahaan</option><option value="Perorangan">Perorangan</option></select></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold">Email</label><input value={currentCust.email||''} onChange={e=>setCurrentCust({...currentCust, email:e.target.value})} className="w-full border p-2 rounded-lg" placeholder="Email"/></div>
                <div className="space-y-1"><label className="font-bold">No Telp</label><input value={currentCust.phone||''} onChange={e=>setCurrentCust({...currentCust, phone:e.target.value})} className="w-full border p-2 rounded-lg" placeholder="No Telp"/></div>
              </div>
              <div className="space-y-1"><label className="font-bold">Alamat</label><textarea value={currentCust.alamat||''} onChange={e=>setCurrentCust({...currentCust, alamat:e.target.value})} className="w-full border p-2 rounded-lg h-20 resize-none"/></div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold">Jenis Leads</label><select value={currentCust.leadType||'Belum Transaksi'} onChange={e=>setCurrentCust({...currentCust, leadType:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2"><option value="Belum Transaksi">Belum Transaksi</option><option value="Sudah Transaksi">Sudah Transaksi</option></select></div>
                <div className="space-y-1"><label className="font-bold">Sumber Leads</label><select value={currentCust.source||'Organic'} onChange={e=>setCurrentCust({...currentCust, source:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2"><option value="Organic">Organic</option><option value="Paid Ads">Paid Ads</option></select></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold">Nama Sales</label><select value={currentCust.sales||'Angel'} onChange={e=>setCurrentCust({...currentCust, sales:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2"><option value="Angel">Angel</option><option value="Maria">Maria</option></select></div>
                <div className="space-y-1"><label className="font-bold">Keterangan</label><input value={currentCust.keterangan||''} onChange={e=>setCurrentCust({...currentCust, keterangan:e.target.value})} className="w-full border p-2 rounded-lg"/></div>
              </div>
              <div className="space-y-1"><label className="font-bold">NPWP</label><input value={currentCust.npwp||''} onChange={e=>setCurrentCust({...currentCust, npwp:e.target.value})} className="w-full border p-2 rounded-lg" placeholder="NPWP"/></div>
            </div>
            <div className="p-6 border-t flex justify-end gap-3"><button onClick={()=>setShowModal(null)} className="px-6 py-2 border rounded-xl font-bold">Batal</button><button onClick={saveCustomer} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold flex items-center gap-2"><Save size={14}/> Simpan Customer</button></div>
          </div>
        </div>
      )}

      {showModal === 'prod' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="px-6 py-4 border-b flex justify-between items-center"><h3 className="font-bold">Tambah Produk</h3><button onClick={()=>setShowModal(null)}><X size={20}/></button></div>
            <div className="p-6 space-y-6">
              <div className="space-y-1"><label className="text-xs font-bold">Nama Produk</label><input value={currentProd.nama||''} onChange={e=>setCurrentProd({...currentProd, nama:e.target.value})} className="w-full border p-2.5 rounded-xl outline-none" placeholder="Nama produk"/></div>
              <div className="space-y-1"><label className="text-xs font-bold">Kode Produk</label><input value={currentProd.kode||''} onChange={e=>setCurrentProd({...currentProd, kode:e.target.value})} className="w-full border p-2.5 rounded-xl outline-none" placeholder="Contoh: PT02"/></div>
            </div>
            <div className="px-6 py-4 border-t flex justify-end gap-3 bg-slate-50/50">
              <button onClick={()=>setShowModal(null)} className="px-6 py-2 border rounded-xl font-bold flex items-center gap-2"><X size={14}/> Batal</button>
              <button onClick={saveProduct} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20"><Save size={14}/> Simpan Produk</button>
            </div>
          </div>
        </div>
      )}

      {showModal === 'supp' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl flex flex-col h-[90vh] overflow-hidden">
            <div className="px-6 py-4 border-b flex justify-between items-center"><h3 className="font-bold">Kelola Supplier</h3><button onClick={()=>setShowModal(null)}><X size={20}/></button></div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6 text-xs">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold">Nama Perusahaan</label><input value={currentSupp.nama||''} onChange={e=>setCurrentSupp({...currentSupp, nama:e.target.value})} className="w-full border p-2.5 rounded-lg" placeholder="PT. Maju Jaya"/></div>
                <div className="space-y-1"><label className="font-bold">Kode Perusahaan</label><input value={currentSupp.kode||''} onChange={e=>setCurrentSupp({...currentSupp, kode:e.target.value})} className="w-full border p-2.5 rounded-lg" placeholder="MJ-001"/></div>
              </div>
              <div className="space-y-1"><label className="font-bold">NPWP</label><input value={currentSupp.npwp||''} onChange={e=>setCurrentSupp({...currentSupp, npwp:e.target.value})} className="w-full border p-2.5 rounded-lg" placeholder="12.345..."/></div>
              <div className="flex justify-end gap-3 border-b pb-6"><button onClick={()=>setCurrentSupp({})} className="px-6 py-2 border rounded-xl flex items-center gap-2 font-bold"><RotateCcw size={14}/> Reset</button><button onClick={saveSupplier} className="px-6 py-2 bg-blue-600 text-white rounded-xl flex items-center gap-2 font-bold"><Plus size={14}/> Tambah Supplier</button></div>
              <div className="space-y-4">
                <h4 className="font-bold text-slate-400 uppercase tracking-widest text-[10px]">Daftar Supplier</h4>
                <div className="border rounded-xl overflow-hidden"><table className="w-full text-left text-xs"><thead className="bg-slate-50 border-b"><tr><th className="px-4 py-3">Nama</th><th className="px-4 py-3">Kode</th></tr></thead><tbody className="divide-y">{suppliers.map(s=>(<tr key={s.id} className="hover:bg-slate-50"><td className="px-4 py-3 font-medium">{s.nama}</td><td className="px-4 py-3 text-slate-500">{s.kode}</td></tr>))}</tbody></table></div>
              </div>
            </div>
            <div className="p-6 border-t flex justify-end bg-slate-50/50"><button onClick={()=>setShowModal(null)} className="px-8 py-2 border rounded-xl font-bold flex items-center gap-2"><X size={14}/> Tutup</button></div>
          </div>
        </div>
      )}

      {showModal === 'stock' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden">
            <div className="px-6 py-4 border-b flex justify-between items-center"><h3 className="font-bold">Tambah/Edit Stock</h3><button onClick={()=>setShowModal(null)}><X size={20}/></button></div>
            <div className="p-6 space-y-6 text-sm">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="text-xs font-bold">Pilih Produk</label><select id="stock-prod-select" className="w-full border-2 border-blue-500 rounded-full p-2 font-bold"><option value="">Pilih</option>{products.map(p=><option key={p.id} value={p.id}>{p.nama}</option>)}</select></div>
                <div className="space-y-1"><label className="text-xs font-bold">Pilih Supplier</label><select id="stock-supp-select" className="w-full border-2 border-blue-500 rounded-full p-2 font-bold"><option value="">Pilih</option>{suppliers.map(s=><option key={s.id} value={s.id}>{s.nama}</option>)}</select></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="text-xs font-bold">Stock Awal</label><input type="number" value={currentStock.stock} onChange={e=>setCurrentStock({...currentStock, stock: parseInt(e.target.value)||0})} className="w-full border p-2 rounded-xl"/></div>
                <div className="space-y-1"><label className="text-xs font-bold">Harga Dasar (Rp)</label><input type="number" value={currentStock.hpp} onChange={e=>setCurrentStock({...currentStock, hpp: parseInt(e.target.value)||0})} className="w-full border p-2 rounded-xl"/></div>
              </div>
              <div className="space-y-1"><label className="text-xs font-bold">Harga Jual (Rp)</label><input type="number" value={currentStock.hargaJual} onChange={e=>setCurrentStock({...currentStock, hargaJual: parseInt(e.target.value)||0})} className="w-full border p-2 rounded-xl"/></div>
            </div>
            <div className="px-6 py-4 border-t flex justify-end gap-3 bg-slate-50/50"><button onClick={()=>setShowModal(null)} className="px-6 py-2 border rounded-xl font-bold flex items-center gap-2"><X size={14}/> Batal</button><button onClick={saveStockLot} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20"><Save size={14}/> Simpan Stock Lot</button></div>
          </div>
        </div>
      )}

      <button className="fixed bottom-10 right-10 w-16 h-16 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center z-50 animate-bounce"><MessageSquare/></button>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, Users, Package, LineChart, FileEdit, ShieldCheck, 
  LogOut, Menu, X, Sun, Moon, Search, Plus, Phone, MessageSquare, 
  Send, Trash2, Edit3, ChevronDown, Check, AlertCircle, TrendingUp, Clock,
  Printer, History, Briefcase, ExternalLink, Calculator, Save, PlusCircle, Trash,
  Mail, FileText, Globe, UserCircle, RotateCcw, Download, Info, ArrowUpRight, ArrowDownRight, Activity
} from 'lucide-react';

// --- Interfaces ---
type Role = 'superadmin' | 'admin' | 'sales' | 'purchasing' | 'pajak' | 'finance' | 'stockist' | 'audit' | 'engineer';

interface User { username: string; role: Role; }

interface Supplier { id: string; nama: string; kode: string; npwp: string; }

interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product { id: string; nama: string; kode: string; lots: ProductLot[]; }

interface Customer {
  id: string; kode: string; nama: string; jenis: string; phone: string;
  email: string; alamat: string; sales: string; leadType: string;
  source: string; npwp: string; keterangan: string;
}

interface TransactionItem {
  produkId: string; nama: string; sku: string; harga: number; qty: number; diskon: number;
}

interface Transaction {
  id: string; noTrx: string; tanggal: string; customerName: string;
  items: TransactionItem[]; nilaiProyek: number; ppn: boolean; ongkir: boolean;
  biayaOngkir: number; jasaKirim: string; status: 'Selesai' | 'Progress' | 'Batal';
  sales: string; keterangan: string; skuHistory: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({});
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [currentStock, setCurrentStock] = useState<Partial<ProductLot>>({ stock: 0, hpp: 0, hargaJual: 0 });

  // Filters
  const [searchQuery, setSearchQuery] = useState('');
  const [prodFilter, setProdFilter] = useState('-- Semua Produk --');
  const [skuFilter, setSkuFilter] = useState('-- Semua SKU --');

  // Persistence
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');
    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Calculations & Derived
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => t.customerName.toLowerCase().includes(searchQuery.toLowerCase()) || t.noTrx.toLowerCase().includes(searchQuery.toLowerCase()));
  }, [transactions, searchQuery]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesProd = prodFilter === '-- Semua Produk --' || p.nama === prodFilter;
      const matchesSku = skuFilter === '-- Semua SKU --' || p.lots.some(l => l.sku === skuFilter);
      return matchesProd && matchesSku;
    });
  }, [products, prodFilter, skuFilter]);

  // Handlers
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data!");
    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`, nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowModal(null);
    setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 });
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
    setCurrentCust({ jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel' });
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Lengkapi data!");
    const newProd = { ...currentProd, id: currentProd.id || Date.now().toString(), lots: currentProd.lots || [] } as Product;
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowModal(null);
    setCurrentProd({});
  };

  const saveSupplier = () => {
    if (!currentSupp.nama || !currentSupp.kode) return alert("Lengkapi!");
    setSuppliers(prev => [...prev, { ...currentSupp, id: Date.now().toString() } as Supplier]);
    setCurrentSupp({});
  };

  const saveStockLot = () => {
    const prodId = (document.getElementById('stock-prod-select') as HTMLSelectElement)?.value;
    const suppId = (document.getElementById('stock-supp-select') as HTMLSelectElement)?.value;
    if (!prodId || !suppId) return alert("Pilih Produk dan Supplier!");
    const newLot: ProductLot = { lot: Date.now(), sku: `${products.find(p=>p.id===prodId)?.kode}${Date.now()}`, supplierId: suppId, stock: currentStock.stock || 0, hpp: currentStock.hpp || 0, hargaJual: currentStock.hargaJual || 0, tanggal: new Date().toISOString() };
    setProducts(prev => prev.map(p => p.id === prodId ? { ...p, lots: [...p.lots, newLot] } : p));
    setShowModal(null);
    setCurrentStock({ stock: 0, hpp: 0, hargaJual: 0 });
  };

  // --- DASHBOARD CALCULATIONS ---
  const stats = useMemo(() => {
    const totalOmzet = transactions.reduce((acc, t) => t.status === 'Selesai' ? acc + t.nilaiProyek : acc, 0);
    const progressOmzet = transactions.reduce((acc, t) => t.status === 'Progress' ? acc + t.nilaiProyek : acc, 0);
    const completedTrx = transactions.filter(t => t.status === 'Selesai').length;
    const pendingTrx = transactions.filter(t => t.status === 'Progress').length;

    return {
      totalOmzet,
      progressOmzet,
      completedTrx,
      pendingTrx,
      totalCustomers: customers.length,
      totalProducts: products.length
    };
  }, [transactions, customers, products]);

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>
      <aside className="w-72 bg-white dark:bg-[#1e293b] border-r border-slate-200 dark:border-slate-800 p-6 flex flex-col">
        <div className="flex items-center gap-4 mb-10"><div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white"><Package size={20}/></div><h1 className="font-black text-xl">MyPanca</h1></div>
        <nav className="flex-1 space-y-1">
          <button onClick={()=>setActivePanel('dashboard')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activePanel==='dashboard'?'bg-blue-600 text-white shadow-lg shadow-blue-600/20':'text-slate-500 hover:bg-slate-100'}`}><LayoutDashboard size={18}/> Dashboard</button>
          <button onClick={()=>setActivePanel('tracking')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activePanel==='tracking'?'bg-blue-600 text-white shadow-lg shadow-blue-600/20':'text-slate-500 hover:bg-slate-100'}`}><LineChart size={18}/> Transaksi</button>
          <button onClick={()=>setActivePanel('customer')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activePanel==='customer'?'bg-blue-600 text-white shadow-lg shadow-blue-600/20':'text-slate-500 hover:bg-slate-100'}`}><Users size={18}/> Customer</button>
          <button onClick={()=>setActivePanel('produk')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activePanel==='produk'?'bg-blue-600 text-white shadow-lg shadow-blue-600/20':'text-slate-500 hover:bg-slate-100'}`}><Package size={18}/> Produk & Stock</button>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto p-8">
        <header className="flex justify-between items-center mb-10">
          <div>
            <h2 className="text-3xl font-black tracking-tight">{activePanel.toUpperCase()}</h2>
            <p className="text-slate-400 text-sm font-medium">Selamat datang kembali, Superadmin</p>
          </div>
          <button onClick={()=>setIsDarkMode(!isDarkMode)} className="w-12 h-12 flex items-center justify-center bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 transition-all hover:scale-105">
            {isDarkMode ? <Sun size={22} className="text-yellow-400"/> : <Moon size={22} className="text-blue-600"/>}
          </button>
        </header>

        {activePanel === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            {/* Stat Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm relative overflow-hidden group hover:border-blue-500 transition-all">
                <div className="flex justify-between items-start mb-4">
                  <div className="w-12 h-12 bg-blue-50 dark:bg-blue-900/30 rounded-2xl flex items-center justify-center text-blue-600"><TrendingUp size={24}/></div>
                  <span className="flex items-center gap-1 text-emerald-500 text-[10px] font-black bg-emerald-50 dark:bg-emerald-900/30 px-2 py-1 rounded-full"><ArrowUpRight size={12}/> 12.5%</span>
                </div>
                <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Omzet Selesai</p>
                <h3 className="text-2xl font-black mt-1">Rp{stats.totalOmzet.toLocaleString('id-ID')}</h3>
              </div>
              <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm hover:border-blue-500 transition-all">
                <div className="flex justify-between items-start mb-4">
                  <div className="w-12 h-12 bg-amber-50 dark:bg-amber-900/30 rounded-2xl flex items-center justify-center text-amber-600"><Clock size={24}/></div>
                  <span className="text-slate-400 text-[10px] font-bold">In Progress</span>
                </div>
                <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Potential Revenue</p>
                <h3 className="text-2xl font-black mt-1 text-amber-500">Rp{stats.progressOmzet.toLocaleString('id-ID')}</h3>
              </div>
              <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm hover:border-blue-500 transition-all">
                <div className="flex justify-between items-start mb-4">
                  <div className="w-12 h-12 bg-emerald-50 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center text-emerald-600"><Users size={24}/></div>
                </div>
                <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Total Customer</p>
                <h3 className="text-2xl font-black mt-1">{stats.totalCustomers} <span className="text-slate-300 text-sm">Entitas</span></h3>
              </div>
              <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm hover:border-blue-500 transition-all">
                <div className="flex justify-between items-start mb-4">
                  <div className="w-12 h-12 bg-purple-50 dark:bg-purple-900/30 rounded-2xl flex items-center justify-center text-purple-600"><Package size={24}/></div>
                </div>
                <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Total Produk</p>
                <h3 className="text-2xl font-black mt-1">{stats.totalProducts} <span className="text-slate-300 text-sm">SKU</span></h3>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              {/* Left Content: Progress & Chart Mockup */}
              <div className="lg:col-span-2 space-y-8">
                <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                  <div className="flex justify-between items-end mb-8">
                    <div>
                      <h4 className="text-lg font-bold">Ikhtisar Penjualan</h4>
