              <div className="space-y-1"><label className="font-bold text-slate-500">Alamat</label><textarea value={currentCust.alamat||''} onChange={e=>setCurrentCust({...currentCust, alamat:e.target.value})} className="w-full border p-2 rounded-lg h-20 resize-none dark:bg-slate-700 dark:border-slate-600"/></div>
