              </div>
            </div>
            <div className="p-6 border-t dark:border-slate-700 flex justify-end bg-slate-50/50 dark:bg-slate-900/20"><button onClick={()=>setShowModal(null)} className="px-8 py-2 border rounded-xl font-bold flex items-center gap-2"><X size={14}/> Tutup</button></div>
          </div>
        </div>
      )}

      {showModal === 'stock' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-slate-800 w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden">
            <div className="px-6 py-4 border-b dark:border-slate-700 flex justify-between items-center"><h3 className="font-bold">Tambah/Edit Stock</h3><button onClick={()=>setShowModal(null)}><X size={20}/></button></div>
            <div className="p-6 space-y-6 text-sm">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Pilih Produk</label><select id="stock-prod-select" className="w-full border-2 border-blue-500 rounded-full p-2.5 font-bold dark:bg-slate-700"><option value="">Pilih</option>{products.map(p=><option key={p.id} value={p.id}>{p.nama}</option>)}</select></div>
                <div className="space-y-1"><label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Pilih Supplier</label><select id="stock-supp-select" className="w-full border-2 border-blue-500 rounded-full p-2.5 font-bold dark:bg-slate-700"><option value="">Pilih</option>{suppliers.map(s=><option key={s.id} value={s.id}>{s.nama}</option>)}</select></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Stock Awal</label><input type="number" value={currentStock.stock} onChange={e=>setCurrentStock({...currentStock, stock: parseInt(e.target.value)||0})} className="w-full border p-2.5 rounded-xl dark:bg-slate-700 dark:border-slate-600 font-bold"/></div>
                <div className="space-y-1"><label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Harga Dasar (Rp)</label><input type="number" value={currentStock.hpp} onChange={e=>setCurrentStock({...currentStock, hpp: parseInt(e.target.value)||0})} className="w-full border p-2.5 rounded-xl dark:bg-slate-700 dark:border-slate-600 font-bold"/></div>
              </div>
              <div className="space-y-1"><label className="text-xs font-bold text-slate-500 uppercase tracking-widest">Harga Jual (Rp)</label><input type="number" value={currentStock.hargaJual} onChange={e=>setCurrentStock({...currentStock, hargaJual: parseInt(e.target.value)||0})} className="w-full border p-2.5 rounded-xl dark:bg-slate-700 dark:border-slate-600 font-bold text-blue-600"/></div>
            </div>
            <div className="px-6 py-4 border-t dark:border-slate-700 flex justify-end gap-3 bg-slate-50/50 dark:bg-slate-900/20"><button onClick={()=>setShowModal(null)} className="px-6 py-2 border rounded-xl font-bold flex items-center gap-2"><X size={14}/> Batal</button><button onClick={saveStockLot} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20"><Save size={14}/> Simpan Stock Lot</button></div>
          </div>
        </div>
      )}

      {/* Floating Chat Button */}
      <button className="fixed bottom-10 right-10 w-16 h-16 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center z-50 animate-bounce hover:scale-110 transition-transform active:scale-95 group">
        <MessageSquare size={28}/>
        <span className="absolute right-full mr-4 bg-white text-slate-900 px-4 py-2 rounded-xl shadow-lg font-bold text-sm whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity">Butuh Bantuan?</span>
      </button>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, Users, Package, LineChart, FileEdit, ShieldCheck, 
  LogOut, Menu, X, Sun, Moon, Search, Plus, Phone, MessageSquare, 
  Send, Trash2, Edit3, ChevronDown, Check, AlertCircle, TrendingUp, Clock,
  Printer, History, Briefcase, ExternalLink, Calculator, Save, PlusCircle, Trash,
  Mail, FileText, Globe, UserCircle, RotateCcw, Download, Info, ArrowUpRight, ArrowDownRight, Activity,
  ChevronLeft, ChevronRight
} from 'lucide-react';

// --- Interfaces ---
type Role = 'superadmin' | 'admin' | 'sales' | 'purchasing' | 'pajak' | 'finance' | 'stockist' | 'audit' | 'engineer';

interface User { username: string; role: Role; }

interface Supplier { id: string; nama: string; kode: string; npwp: string; }

interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product { id: string; nama: string; kode: string; lots: ProductLot[]; }

interface Customer {
  id: string; kode: string; nama: string; jenis: string; phone: string;
  email: string; alamat: string; sales: string; leadType: string;
  source: string; npwp: string; keterangan: string;
}

interface TransactionItem {
  produkId: string; nama: string; sku: string; harga: number; qty: number; diskon: number;
}

interface Transaction {
  id: string; noTrx: string; tanggal: string; customerName: string;
  items: TransactionItem[]; nilaiProyek: number; ppn: boolean; ongkir: boolean;
  biayaOngkir: number; jasaKirim: string; status: 'Selesai' | 'Progress' | 'Batal';
  sales: string; keterangan: string; skuHistory: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({});
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [currentStock, setCurrentStock] = useState<Partial<ProductLot>>({ stock: 0, hpp: 0, hargaJual: 0 });

  // Filters
  const [searchQuery, setSearchQuery] = useState('');
  const [prodFilter, setProdFilter] = useState('-- Semua Produk --');
  const [skuFilter, setSkuFilter] = useState('-- Semua SKU --');

  // Persistence
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');
    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Calculations & Derived
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => t.customerName.toLowerCase().includes(searchQuery.toLowerCase()) || t.noTrx.toLowerCase().includes(searchQuery.toLowerCase()));
  }, [transactions, searchQuery]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesProd = prodFilter === '-- Semua Produk --' || p.nama === prodFilter;
      const matchesSku = skuFilter === '-- Semua SKU --' || p.lots.some(l => l.sku === skuFilter);
      return matchesProd && matchesSku;
    });
  }, [products, prodFilter, skuFilter]);

  // Handlers
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data!");
    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`, nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowModal(null);
    setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 });
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
    setCurrentCust({ jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel' });
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Lengkapi data!");
    const newProd = { ...currentProd, id: currentProd.id || Date.now().toString(), lots: currentProd.lots || [] } as Product;
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowModal(null);
    setCurrentProd({});
  };

  const saveSupplier = () => {
    if (!currentSupp.nama || !currentSupp.kode) return alert("Lengkapi!");
    setSuppliers(prev => [...prev, { ...currentSupp, id: Date.now().toString() } as Supplier]);
    setCurrentSupp({});
  };

  const saveStockLot = () => {
    const prodId = (document.getElementById('stock-prod-select') as HTMLSelectElement)?.value;
    const suppId = (document.getElementById('stock-supp-select') as HTMLSelectElement)?.value;
    if (!prodId || !suppId) return alert("Pilih Produk dan Supplier!");
    const newLot: ProductLot = { lot: Date.now(), sku: `${products.find(p=>p.id===prodId)?.kode}${Date.now()}`, supplierId: suppId, stock: currentStock.stock || 0, hpp: currentStock.hpp || 0, hargaJual: currentStock.hargaJual || 0, tanggal: new Date().toISOString() };
    setProducts(prev => prev.map(p => p.id === prodId ? { ...p, lots: [...p.lots, newLot] } : p));
    setShowModal(null);
    setCurrentStock({ stock: 0, hpp: 0, hargaJual: 0 });
  };

  // --- DASHBOARD CALCULATIONS ---
  const stats = useMemo(() => {
    const totalOmzet = transactions.reduce((acc, t) => t.status === 'Selesai' ? acc + t.nilaiProyek : acc, 0);
    const progressOmzet = transactions.reduce((acc, t) => t.status === 'Progress' ? acc + t.nilaiProyek : acc, 0);
    const completedTrx = transactions.filter(t => t.status === 'Selesai').length;
    const pendingTrx = transactions.filter(t => t.status === 'Progress').length;

    return {
      totalOmzet,
      progressOmzet,
      completedTrx,
      pendingTrx,
      totalCustomers: customers.length,
      totalProducts: products.length
    };
  }, [transactions, customers, products]);

  return (
    <div className={`min-h-screen flex transition-all duration-300 ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>

      {/* --- SIDEBAR (COLLAPSIBLE) --- */}
      <aside className={`${isSidebarCollapsed ? 'w-20' : 'w-72'} bg-white dark:bg-[#1e293b] border-r border-slate-200 dark:border-slate-800 p-6 flex flex-col transition-all duration-300 relative`}>
        <div className={`flex items-center ${isSidebarCollapsed ? 'justify-center' : 'gap-4'} mb-10`}>
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shrink-0 shadow-lg shadow-blue-600/20 transition-all group-hover:rotate-12">
            <Package size={20}/>
          </div>
          {!isSidebarCollapsed && <h1 className="font-black text-xl tracking-tight transition-all opacity-100 whitespace-nowrap">MyPanca</h1>}
        </div>

        <nav className="flex-1 space-y-2">
          <button 
            onClick={()=>setActivePanel('dashboard')} 
            title="Dashboard"
            className={`w-full flex items-center ${isSidebarCollapsed ? 'justify-center' : 'gap-3 px-4'} py-3 rounded-xl transition-all duration-200 ${activePanel==='dashboard'?'bg-blue-600 text-white shadow-lg shadow-blue-600/20':'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
          >
            <LayoutDashboard size={20}/>
            {!isSidebarCollapsed && <span className="font-bold text-sm">Dashboard</span>}
          </button>

          <button 
            onClick={()=>setActivePanel('tracking')} 
            title="Transaksi"
            className={`w-full flex items-center ${isSidebarCollapsed ? 'justify-center' : 'gap-3 px-4'} py-3 rounded-xl transition-all duration-200 ${activePanel==='tracking'?'bg-blue-600 text-white shadow-lg shadow-blue-600/20':'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
          >
            <LineChart size={20}/>
            {!isSidebarCollapsed && <span className="font-bold text-sm">Transaksi</span>}
          </button>

          <button 
            onClick={()=>setActivePanel('customer')} 
            title="Customer"
            className={`w-full flex items-center ${isSidebarCollapsed ? 'justify-center' : 'gap-3 px-4'} py-3 rounded-xl transition-all duration-200 ${activePanel==='customer'?'bg-blue-600 text-white shadow-lg shadow-blue-600/20':'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
          >
            <Users size={20}/>
            {!isSidebarCollapsed && <span className="font-bold text-sm">Customer</span>}
          </button>

          <button 
            onClick={()=>setActivePanel('produk')} 
            title="Produk & Stock"
            className={`w-full flex items-center ${isSidebarCollapsed ? 'justify-center' : 'gap-3 px-4'} py-3 rounded-xl transition-all duration-200 ${activePanel==='produk'?'bg-blue-600 text-white shadow-lg shadow-blue-600/20':'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
          >
            <Package size={20}/>
            {!isSidebarCollapsed && <span className="font-bold text-sm">Produk & Stock</span>}
          </button>
        </nav>

        {/* Toggle Collapse Button */}
        <button 
          onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
          className="absolute -right-3 top-20 w-6 h-6 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full flex items-center justify-center text-slate-400 hover:text-blue-600 hover:border-blue-500 shadow-sm transition-all z-20"
        >
          {isSidebarCollapsed ? <ChevronRight size={14}/> : <ChevronLeft size={14}/>}
        </button>

        <div className="pt-6 border-t dark:border-slate-800 mt-auto">
          <button className={`w-full flex items-center ${isSidebarCollapsed ? 'justify-center' : 'gap-3 px-4'} py-3 rounded-xl text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/10 transition-all font-bold text-sm`}>
            <LogOut size={20}/>
            {!isSidebarCollapsed && <span>Logout</span>}
          </button>
        </div>
      </aside>

      {/* --- MAIN CONTENT --- */}
      <main className="flex-1 overflow-y-auto p-8 custom-scrollbar">
        <header className="flex justify-between items-center mb-10">
          <div>
            <h2 className="text-3xl font-black tracking-tight">{activePanel.toUpperCase()}</h2>
            <p className="text-slate-400 text-sm font-medium">Selamat datang kembali, Superadmin</p>
          </div>
          <button onClick={()=>setIsDarkMode(!isDarkMode)} className="w-12 h-12 flex items-center justify-center bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 transition-all hover:scale-105">
            {isDarkMode ? <Sun size={22} className="text-yellow-400"/> : <Moon size={22} className="text-blue-600"/>}
          </button>
        </header>

        {activePanel === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            {/* Stat Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm relative overflow-hidden group hover:border-blue-500 transition-all">
                <div className="flex justify-between items-start mb-4">
                  <div className="w-12 h-12 bg-blue-50 dark:bg-blue-900/30 rounded-2xl flex items-center justify-center text-blue-600"><TrendingUp size={24}/></div>
                  <span className="flex items-center gap-1 text-emerald-500 text-[10px] font-black bg-emerald-50 dark:bg-emerald-900/30 px-2 py-1 rounded-full"><ArrowUpRight size={12}/> 12.5%</span>
                </div>
                <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Omzet Selesai</p>
                <h3 className="text-2xl font-black mt-1">Rp{stats.totalOmzet.toLocaleString('id-ID')}</h3>
              </div>
              <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm hover:border-blue-500 transition-all">
                <div className="flex justify-between items-start mb-4">
                  <div className="w-12 h-12 bg-amber-50 dark:bg-amber-900/30 rounded-2xl flex items-center justify-center text-amber-600"><Clock size={24}/></div>
                  <span className="text-slate-400 text-[10px] font-bold">In Progress</span>
                </div>
                <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Potential Revenue</p>
                <h3 className="text-2xl font-black mt-1 text-amber-500">Rp{stats.progressOmzet.toLocaleString('id-ID')}</h3>
              </div>
              <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm hover:border-blue-500 transition-all">
                <div className="flex justify-between items-start mb-4">
                  <div className="w-12 h-12 bg-emerald-50 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center text-emerald-600"><Users size={24}/></div>
                </div>
                <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Total Customer</p>
                <h3 className="text-2xl font-black mt-1">{stats.totalCustomers} <span className="text-slate-300 text-sm">Entitas</span></h3>
              </div>
              <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm hover:border-blue-500 transition-all">
                <div className="flex justify-between items-start mb-4">
                  <div className="w-12 h-12 bg-purple-50 dark:bg-purple-900/30 rounded-2xl flex items-center justify-center text-purple-600"><Package size={24}/></div>
                </div>
                <p className="text-slate-400 text-[11px] font-bold uppercase tracking-widest">Total Produk</p>
                <h3 className="text-2xl font-black mt-1">{stats.totalProducts} <span className="text-slate-300 text-sm">SKU</span></h3>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-8">
                <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                  <div className="flex justify-between items-end mb-8">
                    <div>
                      <h4 className="text-lg font-bold">Ikhtisar Penjualan</h4>
                      <p className="text-sm text-slate-400">Ringkasan transaksi bulan ini</p>
                    </div>
                    <div className="flex gap-2">
                      <div className="flex items-center gap-1.5"><div className="w-2.5 h-2.5 bg-blue-600 rounded-full"></div><span className="text-[10px] font-bold text-slate-500 uppercase">Selesai</span></div>
                      <div className="flex items-center gap-1.5"><div className="w-2.5 h-2.5 bg-amber-400 rounded-full"></div><span className="text-[10px] font-bold text-slate-500 uppercase">Progress</span></div>
                    </div>
                  </div>
                  <div className="h-48 flex items-end gap-3 px-2">
                    {[40, 70, 45, 90, 65, 80, 55, 30, 85, 60, 95, 50].map((val, i) => (
                      <div key={i} className="flex-1 flex flex-col items-center gap-2 group">
                        <div className="w-full bg-slate-100 dark:bg-slate-700/50 rounded-t-lg relative flex items-end overflow-hidden h-full">
                          <div style={{height: `${val}%`}} className="w-full bg-blue-600 group-hover:bg-blue-500 transition-all duration-500"></div>
                        </div>
                        <span className="text-[9px] font-bold text-slate-400 uppercase">{['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'][i]}</span>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="bg-blue-600 p-8 rounded-[2.5rem] text-white shadow-xl shadow-blue-600/20 relative overflow-hidden">
                  <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-6 text-center md:text-left">
                    <div>
                      <h4 className="text-xl font-black">Siap untuk transaksi baru?</h4>
                      <p className="text-blue-100 text-sm mt-1 opacity-80">Input data penjualan dengan cepat & akurat hari ini.</p>
                    </div>
                    <button onClick={()=>{setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 }); setShowModal('trx');}} className="bg-white text-blue-600 px-8 py-3 rounded-2xl font-black text-sm hover:bg-blue-50 transition-all flex items-center gap-2 whitespace-nowrap">
                      <Plus size={20}/> Buat Invoice Baru
                    </button>
                  </div>
                  <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20 blur-3xl"></div>
                </div>
              </div>

              <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-700 shadow-sm flex flex-col">
                <div className="flex justify-between items-center mb-8">
                  <h4 className="text-lg font-bold">Aktivitas Terkini</h4>
                  <Activity size={20} className="text-slate-300"/>
                </div>
                <div className="space-y-6 flex-1">
                  {transactions.slice(0, 5).map(t => (
