// --- Interfaces ---
type Role = 'superadmin' | 'admin' | 'sales' | 'purchasing' | 'pajak' | 'finance' | 'stockist' | 'audit' | 'engineer';

interface User { username: string; role: Role; }

interface Supplier { id: string; nama: string; kode: string; npwp: string; }

interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product { id: string; nama: string; kode: string; lots: ProductLot[]; }

interface Customer {
  id: string; kode: string; nama: string; jenis: string; phone: string;
  email: string; alamat: string; sales: string; leadType: string;
  source: string; npwp: string; keterangan: string;
}

interface TransactionItem {
  produkId: string; nama: string; sku: string; harga: number; qty: number; diskon: number;
}

interface Transaction {
  id: string; noTrx: string; tanggal: string; customerName: string;
  items: TransactionItem[]; nilaiProyek: number; ppn: boolean; ongkir: boolean;
  biayaOngkir: number; jasaKirim: string; status: 'Selesai' | 'Progress' | 'Batal';
  sales: string; keterangan: string; skuHistory: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({});
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [currentStock, setCurrentStock] = useState<Partial<ProductLot>>({ stock: 0, hpp: 0, hargaJual: 0 });

  // Filters
  const [searchQuery, setSearchQuery] = useState('');
  const [prodFilter, setProdFilter] = useState('-- Semua Produk --');
  const [skuFilter, setSkuFilter] = useState('-- Semua SKU --');

  // Persistence
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');
    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Calculations & Derived
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => t.customerName.toLowerCase().includes(searchQuery.toLowerCase()) || t.noTrx.toLowerCase().includes(searchQuery.toLowerCase()));
  }, [transactions, searchQuery]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesProd = prodFilter === '-- Semua Produk --' || p.nama === prodFilter;
      const matchesSku = skuFilter === '-- Semua SKU --' || p.lots.some(l => l.sku === skuFilter);
      return matchesProd && matchesSku;
    });
  }, [products, prodFilter, skuFilter]);

  // Handlers
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data!");
    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`, nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowModal(null);
    setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 });
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
    setCurrentCust({ jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel' });
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Lengkapi data!");
    const newProd = { ...currentProd, id: currentProd.id || Date.now().toString(), lots: currentProd.lots || [] } as Product;
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowModal(null);
    setCurrentProd({});
  };

  const saveSupplier = () => {
    if (!currentSupp.nama || !currentSupp.kode) return alert("Lengkapi!");
    setSuppliers(prev => [...prev, { ...currentSupp, id: Date.now().toString() } as Supplier]);
    setCurrentSupp({});
  };

  const saveStockLot = () => {
    const prodId = (document.getElementById('stock-prod-select') as HTMLSelectElement)?.value;
    const suppId = (document.getElementById('stock-supp-select') as HTMLSelectElement)?.value;
    if (!prodId || !suppId) return alert("Pilih Produk dan Supplier!");
    const newLot: ProductLot = { lot: Date.now(), sku: `${products.find(p=>p.id===prodId)?.kode}${Date.now()}`, supplierId: suppId, stock: currentStock.stock || 0, hpp: currentStock.hpp || 0, hargaJual: currentStock.hargaJual || 0, tanggal: new Date().toISOString() };
    setProducts(prev => prev.map(p => p.id === prodId ? { ...p, lots: [...p.lots, newLot] } : p));
    setShowModal(null);
    setCurrentStock({ stock: 0, hpp: 0, hargaJual: 0 });
  };

  // --- DASHBOARD CALCULATIONS ---
  const stats = useMemo(() => {
    const totalOmzet = transactions.reduce((acc, t) => t.status === 'Selesai' ? acc + t.nilaiProyek : acc, 0);
    const progressOmzet = transactions.reduce((acc, t) => t.status === 'Progress' ? acc + t.nilaiProyek : acc, 0);
    const completedTrx = transactions.filter(t => t.status === 'Selesai').length;
    const pendingTrx = transactions.filter(t => t.status === 'Progress').length;

    return {
      totalOmzet,
      progressOmzet,
      completedTrx,
      pendingTrx,
      totalCustomers: customers.length,
      totalProducts: products.length
    };
  }, [transactions, customers, products]);

  const navItemClass = (panel: Panel) => `w-full flex items-center ${isSidebarCollapsed ? 'justify-center' : 'gap-3 px-4'} py-3 rounded-xl transition-all duration-200 ${activePanel===panel?'bg-blue-600 text-white shadow-lg shadow-blue-600/20':'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`;

  return (
    <div className={`min-h-screen flex transition-all duration-300 ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>

      {/* Mobile Sidebar Overlay */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black/50 z-[110] lg:hidden" onClick={() => setIsMobileMenuOpen(false)}></div>
      )}

      {/* --- SIDEBAR (RESPONSIVE) --- */}
      <aside className={`
        fixed inset-y-0 left-0 z-[120] bg-white dark:bg-[#1e293b] border-r border-slate-200 dark:border-slate-800 p-6 flex flex-col transition-all duration-300
        ${isMobileMenuOpen ? 'translate-x-0 w-72' : '-translate-x-full lg:translate-x-0'}
        ${isSidebarCollapsed ? 'lg:w-20' : 'lg:w-72'}
      `}>
        <div className={`flex items-center ${isSidebarCollapsed ? 'lg:justify-center' : 'gap-4'} mb-10`}>
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shrink-0 shadow-lg shadow-blue-600/20">
            <Package size={20}/>
          </div>
          {(!isSidebarCollapsed || isMobileMenuOpen) && <h1 className="font-black text-xl tracking-tight whitespace-nowrap">MyPanca</h1>}
          <button className="lg:hidden ml-auto p-2" onClick={() => setIsMobileMenuOpen(false)}><X size={20}/></button>
        </div>

        <nav className="flex-1 space-y-2">
          <button onClick={()=>{setActivePanel('dashboard'); setIsMobileMenuOpen(false)}} title="Dashboard" className={navItemClass('dashboard')}>
            <LayoutDashboard size={20}/>
            {(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Dashboard</span>}
          </button>
          <button onClick={()=>{setActivePanel('tracking'); setIsMobileMenuOpen(false)}} title="Transaksi" className={navItemClass('tracking')}>
            <LineChart size={20}/>
            {(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Transaksi</span>}
          </button>
          <button onClick={()=>{setActivePanel('customer'); setIsMobileMenuOpen(false)}} title="Customer" className={navItemClass('customer')}>
            <Users size={20}/>
            {(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Customer</span>}
          </button>
          <button onClick={()=>{setActivePanel('produk'); setIsMobileMenuOpen(false)}} title="Produk & Stock" className={navItemClass('produk')}>
            <Package size={20}/>
            {(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Produk & Stock</span>}
          </button>
        </nav>

        {/* Desktop Toggle Collapse Button */}
        <button 
          onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
          className="hidden lg:flex absolute -right-3 top-20 w-6 h-6 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full items-center justify-center text-slate-400 hover:text-blue-600 hover:border-blue-500 shadow-sm transition-all z-20"
        >
          {isSidebarCollapsed ? <ChevronRight size={14}/> : <ChevronLeft size={14}/>}
        </button>

        <div className="pt-6 border-t dark:border-slate-800 mt-auto">
          <button className={`w-full flex items-center ${isSidebarCollapsed ? 'lg:justify-center' : 'gap-3 px-4'} py-3 rounded-xl text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/10 transition-all font-bold text-sm`}>
            <LogOut size={20}/>
            {(!isSidebarCollapsed || isMobileMenuOpen) && <span>Logout</span>}
          </button>
        </div>
      </aside>

      {/* --- MAIN CONTENT --- */}
      <main className={`flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar transition-all duration-300 ${isSidebarCollapsed ? 'lg:ml-20' : 'lg:ml-72'}`}>
        <header className="flex justify-between items-center mb-6 md:mb-10">
          <div className="flex items-center gap-4">
            <button className="lg:hidden p-2 bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700" onClick={() => setIsMobileMenuOpen(true)}>
              <Menu size={20}/>
            </button>
            <div>
              <h2 className="text-xl md:text-3xl font-black tracking-tight">{activePanel.toUpperCase()}</h2>
              <p className="hidden md:block text-slate-400 text-sm font-medium">Selamat datang kembali, Superadmin</p>
            </div>
          </div>
          <button onClick={()=>setIsDarkMode(!isDarkMode)} className="w-10 h-10 md:w-12 md:h-12 flex items-center justify-center bg-white dark:bg-slate-800 rounded-xl md:rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 transition-all">
            {isDarkMode ? <Sun size={20} className="text-yellow-400"/> : <Moon size={20} className="text-blue-600"/>}
          </button>
        </header>

        {activePanel === 'dashboard' && (
          <div className="space-y-6 md:space-y-8 animate-in fade-in duration-500">
            {/* Stat Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
              {[
                { label: 'Omzet Selesai', value: `Rp${stats.totalOmzet.toLocaleString('id-ID')}`, icon: <TrendingUp size={24}/>, color: 'text-blue-600', bg: 'bg-blue-50', trend: '12.5%' },
                { label: 'Potential Revenue', value: `Rp${stats.progressOmzet.toLocaleString('id-ID')}`, icon: <Clock size={24}/>, color: 'text-amber-600', bg: 'bg-amber-50', trend: 'In Progress' },
                { label: 'Total Customer', value: stats.totalCustomers, icon: <Users size={24}/>, color: 'text-emerald-600', bg: 'bg-emerald-50', trend: 'Entitas' },
                { label: 'Total Produk', value: stats.totalProducts, icon: <Package size={24}/>, color: 'text-purple-600', bg: 'bg-purple-50', trend: 'SKU' }
              ].map((s, idx) => (
                <div key={idx} className="bg-white dark:bg-slate-800 p-5 md:p-6 rounded-[1.5rem] md:rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm transition-all hover:border-blue-500">
                  <div className="flex justify-between items-start mb-4">
                    <div className={`w-10 h-10 md:w-12 md:h-12 ${s.bg} dark:bg-opacity-10 rounded-xl md:rounded-2xl flex items-center justify-center ${s.color}`}>{s.icon}</div>
                    {s.label === 'Omzet Selesai' && <span className="flex items-center gap-1 text-emerald-500 text-[9px] font-black bg-emerald-50 dark:bg-emerald-900/30 px-2 py-1 rounded-full"><ArrowUpRight size={10}/> {s.trend}</span>}
                  </div>
                  <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">{s.label}</p>
                  <h3 className="text-lg md:text-2xl font-black mt-1 truncate">{s.value}</h3>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 md:gap-8">
              <div className="lg:col-span-2 space-y-6 md:space-y-8">
                <div className="bg-white dark:bg-slate-800 p-6 md:p-8 rounded-[1.5rem] md:rounded-[2.5rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                  <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-4 mb-8">
                    <div>
                      <h4 className="text-base md:text-lg font-bold">Ikhtisar Penjualan</h4>
                      <p className="text-xs md:text-sm text-slate-400">Ringkasan transaksi bulan ini</p>
                    </div>
                    <div className="flex gap-2">
                      <div className="flex items-center gap-1.5"><div className="w-2 h-2 bg-blue-600 rounded-full"></div><span className="text-[9px] font-bold text-slate-500 uppercase">Selesai</span></div>
                      <div className="flex items-center gap-1.5"><div className="w-2 h-2 bg-amber-400 rounded-full"></div><span className="text-[9px] font-bold text-slate-500 uppercase">Progress</span></div>
                    </div>
                  </div>
                  <div className="h-40 md:h-48 flex items-end gap-1.5 md:gap-3 px-1 md:px-2 overflow-x-auto scrollbar-hide">
                    {[40, 70, 45, 90, 65, 80, 55, 30, 85, 60, 95, 50].map((val, i) => (
                      <div key={i} className="min-w-[12px] flex-1 flex flex-col items-center gap-2 group">
                        <div className="w-full bg-slate-100 dark:bg-slate-700/50 rounded-t-lg relative flex items-end overflow-hidden h-full">
                          <div style={{height: `${val}%`}} className="w-full bg-blue-600 group-hover:bg-blue-500 transition-all duration-500"></div>
                        </div>
                        <span className="text-[8px] font-bold text-slate-400 uppercase">{['J','F','M','A','M','J','J','A','S','O','N','D'][i]}</span>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="bg-blue-600 p-6 md:p-8 rounded-[1.5rem] md:rounded-[2.5rem] text-white shadow-xl shadow-blue-600/20 relative overflow-hidden">
                  <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-4 text-center md:text-left">
                    <div>
                      <h4 className="text-lg md:text-xl font-black">Siap untuk transaksi baru?</h4>
                      <p className="text-blue-100 text-xs md:text-sm mt-1 opacity-80">Input data penjualan dengan cepat & akurat hari ini.</p>
                    </div>
                    <button onClick={()=>{setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 }); setShowModal('trx');}} className="w-full md:w-auto bg-white text-blue-600 px-6 py-2.5 rounded-xl md:rounded-2xl font-black text-xs md:text-sm hover:bg-blue-50 transition-all flex items-center justify-center gap-2 whitespace-nowrap">
                      <Plus size={18}/> Buat Invoice Baru
                    </button>
                  </div>
                  <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20 blur-3xl"></div>
                </div>
              </div>

              <div className="bg-white dark:bg-slate-800 p-6 md:p-8 rounded-[1.5rem] md:rounded-[2.5rem] border border-slate-100 dark:border-slate-700 shadow-sm flex flex-col">
                <div className="flex justify-between items-center mb-6 md:mb-8">
                  <h4 className="text-base md:text-lg font-bold">Aktivitas Terkini</h4>
                  <Activity size={18} className="text-slate-300"/>
                </div>
                <div className="space-y-4 md:space-y-6 flex-1">
                  {transactions.slice(0, 5).map(t => (
                    <div key={t.id} className="flex items-center gap-3 md:gap-4 group cursor-pointer" onClick={()=>{setCurrentTrx(t); setShowModal('trx');}}>
                      <div className={`w-10 h-10 md:w-12 md:h-12 rounded-xl md:rounded-2xl flex items-center justify-center shrink-0 ${t.status==='Selesai'?'bg-emerald-50 text-emerald-600':'bg-amber-50 text-amber-600'}`}>
                        {t.status === 'Selesai' ? <Check size={18}/> : <Clock size={18}/>}
                      </div>
                      <div className="min-w-0 flex-1">
                        <h5 className="font-bold text-xs md:text-sm truncate">{t.customerName}</h5>
                        <p className="text-[9px] md:text-[10px] text-slate-400 font-bold uppercase truncate">{t.noTrx} • {new Date(t.tanggal).toLocaleDateString('id-ID', {day:'numeric', month:'short'})}</p>
                      </div>
                      <div className="text-right shrink-0">
                        <p className="font-black text-[10px] md:text-xs text-blue-600">Rp{(t.nilaiProyek/1000000).toFixed(1)}M</p>
                        <p className={`text-[8px] md:text-[9px] font-black uppercase ${t.status==='Selesai'?'text-emerald-500':'text-amber-500'}`}>{t.status}</p>
                      </div>
                    </div>
                  ))}
                  {transactions.length === 0 && <div className="text-center py-10 md:py-20 text-slate-300"><History size={40} className="mx-auto mb-2 opacity-20"/><p className="text-[10px] font-bold">Belum ada aktivitas</p></div>}
                </div>
                <button onClick={()=>setActivePanel('tracking')} className="w-full mt-6 md:mt-8 py-3 bg-slate-50 dark:bg-slate-700/50 rounded-xl text-[9px] md:text-[11px] font-black uppercase tracking-widest text-slate-400 hover:text-blue-600 transition-all border border-dashed border-slate-200 dark:border-slate-600">
                  Lihat Semua
                </button>
              </div>
            </div>
          </div>
        )}

        {activePanel === 'tracking' && (
          <div className="bg-white dark:bg-slate-800 rounded-[1.5rem] md:rounded-[2.5rem] p-4 md:p-8 border border-slate-100 dark:border-slate-700 shadow-sm animate-in fade-in duration-500 overflow-hidden">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6 md:mb-8">
              <div>
                <h3 className="text-lg md:text-xl font-bold">Daftar Transaksi</h3>
                <p className="text-xs md:text-sm text-slate-400">Manajemen invoice & pembayaran</p>
              </div>
              <button onClick={()=>{setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 }); setShowModal('trx');}} className="w-full sm:w-auto bg-blue-600 text-white px-6 py-2.5 rounded-xl md:rounded-2xl font-bold text-xs md:text-sm flex items-center justify-center gap-2 hover:bg-blue-700 shadow-lg shadow-blue-600/20 transition-all"><Plus size={18}/> Buat Invoice</button>
            </div>
            <div className="overflow-x-auto -mx-4 px-4 scrollbar-hide">
              <table className="w-full text-xs md:text-sm min-w-[600px]">
                <thead className="text-slate-400 font-bold border-b dark:border-slate-700"><tr className="text-left"><th className="pb-4 px-2 font-black uppercase text-[9px] md:text-[10px] tracking-widest">No Invoice</th><th className="pb-4 px-2 font-black uppercase text-[9px] md:text-[10px] tracking-widest">Customer</th><th className="pb-4 px-2 font-black uppercase text-[9px] md:text-[10px] tracking-widest text-right">Nilai Proyek</th><th className="pb-4 px-2 font-black uppercase text-[9px] md:text-[10px] tracking-widest text-center">Status</th><th className="pb-4 px-2"></th></tr></thead>
                <tbody className="divide-y dark:divide-slate-700">
                  {filteredTransactions.map(t => (
                    <tr key={t.id} className="group hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-all cursor-pointer" onClick={()=>{setCurrentTrx(t); setShowModal('trx');}}>
                      <td className="py-4 px-2"><span className="font-black text-slate-900 dark:text-white group-hover:text-blue-600">{t.noTrx}</span><p className="text-[9px] md:text-[10px] text-slate-400 font-bold">{t.tanggal}</p></td>
                      <td className="py-4 px-2 font-bold truncate max-w-[150px]">{t.customerName}</td>
                      <td className="py-4 px-2 font-black text-blue-600 text-right">Rp{t.nilaiProyek.toLocaleString('id-ID')}</td>
                      <td className="py-4 px-2 text-center"><span className={`px-3 py-1 rounded-lg text-[8px] md:text-[10px] font-black uppercase tracking-wider ${t.status==='Selesai'?'bg-emerald-50 text-emerald-600':'bg-amber-50 text-amber-600'}`}>{t.status}</span></td>
                      <td className="py-4 px-2 text-right"><button className="p-1.5 md:p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-600 hover:text-white transition-all"><ArrowUpRight size={14}/></button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* ... Panel Customer & Produk dengan Responsivitas serupa ... */}
        {activePanel === 'customer' && (
