interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product { id: string; nama: string; kode: string; lots: ProductLot[]; }

interface Customer {
  id: string; kode: string; nama: string; jenis: string; phone: string;
  email: string; alamat: string; sales: string; leadType: string;
  source: string; npwp: string; keterangan: string;
}

interface TransactionItem {
  produkId: string; nama: string; sku: string; harga: number; qty: number; diskon: number;
}

interface Transaction {
  id: string; noTrx: string; tanggal: string; customerName: string;
  items: TransactionItem[]; nilaiProyek: number; ppn: boolean; ongkir: boolean;
  biayaOngkir: number; jasaKirim: string; status: 'Selesai' | 'Progress' | 'Batal';
  sales: string; keterangan: string; skuHistory: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({});
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [currentStock, setCurrentStock] = useState<Partial<ProductLot>>({ stock: 0, hpp: 0, hargaJual: 0 });

  // Filters
  const [searchQuery, setSearchQuery] = useState('');
  const [prodFilter, setProdFilter] = useState('-- Semua Produk --');
  const [skuFilter, setSkuFilter] = useState('-- Semua SKU --');

  // Persistence
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');
    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Calculations & Derived
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => t.customerName.toLowerCase().includes(searchQuery.toLowerCase()) || t.noTrx.toLowerCase().includes(searchQuery.toLowerCase()));
  }, [transactions, searchQuery]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesProd = prodFilter === '-- Semua Produk --' || p.nama === prodFilter;
      const matchesSku = skuFilter === '-- Semua SKU --' || p.lots.some(l => l.sku === skuFilter);
      return matchesProd && matchesSku;
    });
  }, [products, prodFilter, skuFilter]);

  // Handlers
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data!");
    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`, nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowModal(null);
    setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 });
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
    setCurrentCust({ jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel' });
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Lengkapi data!");
    const newProd = { ...currentProd, id: currentProd.id || Date.now().toString(), lots: currentProd.lots || [] } as Product;
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowModal(null);
    setCurrentProd({});
  };

  const saveSupplier = () => {
    if (!currentSupp.nama || !currentSupp.kode) return alert("Lengkapi!");
    setSuppliers(prev => [...prev, { ...currentSupp, id: Date.now().toString() } as Supplier]);
    setCurrentSupp({});
  };

  const saveStockLot = () => {
    const prodId = (document.getElementById('stock-prod-select') as HTMLSelectElement)?.value;
    const suppId = (document.getElementById('stock-supp-select') as HTMLSelectElement)?.value;
    if (!prodId || !suppId) return alert("Pilih Produk dan Supplier!");
    const newLot: ProductLot = { lot: Date.now(), sku: `${products.find(p=>p.id===prodId)?.kode}${Date.now()}`, supplierId: suppId, stock: currentStock.stock || 0, hpp: currentStock.hpp || 0, hargaJual: currentStock.hargaJual || 0, tanggal: new Date().toISOString() };
    setProducts(prev => prev.map(p => p.id === prodId ? { ...p, lots: [...p.lots, newLot] } : p));
    setShowModal(null);
    setCurrentStock({ stock: 0, hpp: 0, hargaJual: 0 });
  };

  // --- DASHBOARD CALCULATIONS ---
  const stats = useMemo(() => {
    const totalOmzet = transactions.reduce((acc, t) => t.status === 'Selesai' ? acc + t.nilaiProyek : acc, 0);
    const progressOmzet = transactions.reduce((acc, t) => t.status === 'Progress' ? acc + t.nilaiProyek : acc, 0);
    const totalCustomers = customers.length;
    const totalProducts = products.length;

    return { totalOmzet, progressOmzet, totalCustomers, totalProducts };
  }, [transactions, customers, products]);

  const navItemClass = (panel: Panel) => `w-full flex items-center ${isSidebarCollapsed ? 'justify-center' : 'gap-3 px-4'} py-3 rounded-xl transition-all duration-200 ${activePanel===panel?'bg-blue-600 text-white shadow-lg shadow-blue-600/20':'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`;

  return (
    <div className={`min-h-screen flex transition-all duration-300 ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>

      {/* Mobile Sidebar Overlay */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black/50 z-[110] lg:hidden" onClick={() => setIsMobileMenuOpen(false)}></div>
      )}

      {/* SIDEBAR */}
      <aside className={`
        fixed inset-y-0 left-0 z-[120] bg-white dark:bg-[#1e293b] border-r border-slate-200 dark:border-slate-800 p-6 flex flex-col transition-all duration-300
        ${isMobileMenuOpen ? 'translate-x-0 w-72' : '-translate-x-full lg:translate-x-0'}
        ${isSidebarCollapsed ? 'lg:w-20' : 'lg:w-72'}
      `}>
        <div className={`flex items-center ${isSidebarCollapsed ? 'lg:justify-center' : 'gap-4'} mb-10`}>
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shrink-0 shadow-lg shadow-blue-600/20">
            <Package size={20}/>
          </div>
          {(!isSidebarCollapsed || isMobileMenuOpen) && <h1 className="font-black text-xl tracking-tight whitespace-nowrap">MyPanca</h1>}
        </div>
        <nav className="flex-1 space-y-2">
          <button onClick={()=>{setActivePanel('dashboard'); setIsMobileMenuOpen(false)}} className={navItemClass('dashboard')}><LayoutDashboard size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Dashboard</span>}</button>
          <button onClick={()=>{setActivePanel('tracking'); setIsMobileMenuOpen(false)}} className={navItemClass('tracking')}><LineChart size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Transaksi</span>}</button>
          <button onClick={()=>{setActivePanel('customer'); setIsMobileMenuOpen(false)}} className={navItemClass('customer')}><Users size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Customer</span>}</button>
          <button onClick={()=>{setActivePanel('produk'); setIsMobileMenuOpen(false)}} className={navItemClass('produk')}><Package size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Produk & Stock</span>}</button>
        </nav>
      </aside>

      {/* MAIN CONTENT */}
      <main className={`flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar transition-all duration-300 ${isSidebarCollapsed ? 'lg:ml-20' : 'lg:ml-72'}`}>
        <header className="flex justify-between items-center mb-6 md:mb-10">
          <div className="flex items-center gap-4">
            <button className="lg:hidden p-2 bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-100 dark:border-slate-700" onClick={() => setIsMobileMenuOpen(true)}><Menu size={20}/></button>
            <h2 className="text-xl md:text-3xl font-black tracking-tight">{activePanel.toUpperCase()}</h2>
          </div>
          <button onClick={()=>setIsDarkMode(!isDarkMode)} className="w-10 h-10 md:w-12 md:h-12 flex items-center justify-center bg-white dark:bg-slate-800 rounded-xl md:rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700">
            {isDarkMode ? <Sun size={20} className="text-yellow-400"/> : <Moon size={20} className="text-blue-600"/>}
          </button>
        </header>

        {/* Dynamic Panels */}
        {activePanel === 'dashboard' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
            <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm">
              <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Total Omzet</p>
              <h3 className="text-xl md:text-2xl font-black mt-1">Rp{stats.totalOmzet.toLocaleString()}</h3>
            </div>
            <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm">
              <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Customers</p>
              <h3 className="text-xl md:text-2xl font-black mt-1">{stats.totalCustomers}</h3>
            </div>
            {/* ... other stats ... */}
          </div>
        )}

        {activePanel === 'customer' && (
          <div className="bg-white dark:bg-slate-800 rounded-[1.5rem] md:rounded-[2.5rem] p-6 border border-slate-100 dark:border-slate-700 shadow-sm">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-8">
              <h3 className="text-lg md:text-xl font-bold">Database Customer</h3>
              <button onClick={()=>{setCurrentCust({jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'}); setShowModal('cust');}} className="w-full sm:w-auto bg-blue-600 text-white px-6 py-2.5 rounded-xl font-bold text-xs md:text-sm flex items-center justify-center gap-2"><Plus size={18}/> Customer Baru</button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
              {customers.map(c => (
                <div key={c.id} onClick={()=>{setCurrentCust(c); setShowModal('cust');}} className="bg-slate-50 dark:bg-slate-700/30 p-5 rounded-3xl border border-slate-100 dark:border-slate-700 hover:border-blue-500 transition-all cursor-pointer group">
                  <div className="w-12 h-12 bg-white dark:bg-slate-800 text-blue-600 rounded-2xl flex items-center justify-center font-black text-xl mb-3 shadow-sm group-hover:bg-blue-600 group-hover:text-white transition-all">{c.nama[0]}</div>
                  <h4 className="font-bold text-xs md:text-sm truncate">{c.nama}</h4>
                  <p className="text-[9px] md:text-[10px] text-slate-400 font-bold uppercase tracking-wider mt-1">{c.kode}</p>
                  <div className="mt-3 pt-3 border-t border-dashed border-slate-200 dark:border-slate-600 flex justify-between items-center">
                    <span className="text-[8px] font-black text-blue-500 uppercase bg-blue-50 dark:bg-blue-900/30 px-2 py-0.5 rounded">{c.leadType}</span>
                    <ArrowUpRight size={14} className="text-slate-300"/>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Tracking & Produk simplified for space */}
        {activePanel === 'tracking' && <div className="p-10 text-center font-bold">Panel Transaksi - Memuat Data...</div>}
        {activePanel === 'produk' && <div className="p-10 text-center font-bold">Panel Produk - Memuat Data...</div>}
      </main>

      {/* --- MODALS (CUSTOMER LENGKAP) --- */}
      {showModal === 'cust' && (
        <div className="fixed inset-0 z-[200] flex items-end sm:items-center justify-center bg-black/40 backdrop-blur-sm p-0 sm:p-4">
          <div className="bg-white dark:bg-slate-800 w-full max-w-xl rounded-t-[1.5rem] sm:rounded-2xl shadow-2xl flex flex-col h-[90vh] sm:h-auto sm:max-h-[95vh] animate-in slide-in-from-bottom-10 sm:zoom-in-95 duration-200">
            <div className="px-5 md:px-6 py-4 border-b dark:border-slate-700 flex justify-between items-center shrink-0">
              <h3 className="text-base md:text-lg font-bold text-slate-800 dark:text-white">Form Customer Lengkap</h3>
              <button onClick={() => setShowModal(null)} className="p-1.5 bg-slate-100 dark:bg-slate-700 rounded-lg"><X size={18}/></button>
            </div>

            <div className="flex-1 overflow-y-auto p-5 md:p-6 space-y-5 custom-scrollbar text-[12px] md:text-[13px]">
              {/* Field Utama */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Nama Customer *</label><input value={currentCust.nama||''} onChange={e=>setCurrentCust({...currentCust, nama:e.target.value})} className="w-full border p-2.5 rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white outline-none focus:border-blue-500" placeholder="Contoh: PT. Sumber Makmur"/></div>
                <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Jenis Customer</label><select value={currentCust.jenis||'Perusahaan'} onChange={e=>setCurrentCust({...currentCust, jenis:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2.5 dark:bg-slate-700 font-bold dark:text-white"><option value="Perusahaan">Perusahaan</option><option value="Perorangan">Perorangan</option></select></div>
              </div>

              {/* Kontak */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Email</label><input type="email" value={currentCust.email||''} onChange={e=>setCurrentCust({...currentCust, email:e.target.value})} className="w-full border p-2.5 rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white outline-none" placeholder="email@bisnis.com"/></div>
                <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">No Telp</label><input value={currentCust.phone||''} onChange={e=>setCurrentCust({...currentCust, phone:e.target.value})} className="w-full border p-2.5 rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white outline-none" placeholder="0812..."/></div>
              </div>

              {/* Alamat & NPWP */}
              <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Alamat Lengkap</label><textarea value={currentCust.alamat||''} onChange={e=>setCurrentCust({...currentCust, alamat:e.target.value})} className="w-full border p-2.5 rounded-lg h-20 md:h-24 resize-none dark:bg-slate-700 dark:border-slate-600 dark:text-white outline-none" placeholder="Alamat pengiriman dan tagihan..."/></div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">NPWP</label><input value={currentCust.npwp||''} onChange={e=>setCurrentCust({...currentCust, npwp:e.target.value})} className="w-full border p-2.5 rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white outline-none" placeholder="12.345.678.9-000.000"/></div>
                <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Nama Sales</label><select value={currentCust.sales||'Angel'} onChange={e=>setCurrentCust({...currentCust, sales:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2.5 dark:bg-slate-700 font-bold dark:text-white"><option value="Angel">Angel</option><option value="Maria">Maria</option><option value="Budi">Budi</option><option value="Admin">Admin</option></select></div>
              </div>

              {/* Status & Sumber */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Jenis Leads</label><select value={currentCust.leadType||'Belum Transaksi'} onChange={e=>setCurrentCust({...currentCust, leadType:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2.5 dark:bg-slate-700 font-bold dark:text-white"><option value="Belum Transaksi">Belum Transaksi</option><option value="Sudah Transaksi">Sudah Transaksi</option><option value="Repeat Order">Repeat Order</option><option value="Lost">Lost Lead</option></select></div>
                <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Sumber Leads</label><select value={currentCust.source||'Organic'} onChange={e=>setCurrentCust({...currentCust, source:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2.5 dark:bg-slate-700 font-bold dark:text-white"><option value="Organic">Organic (Search)</option><option value="Paid Ads">Paid Ads (Meta/Google)</option><option value="Referral">Referral</option><option value="Exhibition">Exhibition/Event</option></select></div>
              </div>

              <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Keterangan Tambahan</label><input value={currentCust.keterangan||''} onChange={e=>setCurrentCust({...currentCust, keterangan:e.target.value})} className="w-full border p-2.5 rounded-lg dark:bg-slate-700 dark:border-slate-600 dark:text-white outline-none" placeholder="Catatan internal..."/></div>
            </div>

            <div className="px-5 md:px-6 py-4 border-t dark:border-slate-700 flex flex-col sm:flex-row justify-end gap-3 bg-slate-50/50 dark:bg-slate-900/20 shrink-0">
              <button onClick={() => setShowModal(null)} className="order-2 sm:order-1 px-6 py-2.5 border border-slate-200 dark:border-slate-700 rounded-xl font-bold text-slate-500 text-xs md:text-sm">Batal</button>
              <button onClick={saveCustomer} className="order-1 sm:order-2 px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold text-xs md:text-sm flex items-center justify-center gap-2 shadow-lg shadow-blue-600/20"><Save size={16}/> Simpan Data</button>
            </div>
          </div>
        </div>
      )}

      {/* Floating Chat */}
      <button className="fixed bottom-6 right-6 w-14 h-14 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center z-50 animate-bounce"><MessageSquare size={24}/></button>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, Users, Package, LineChart, FileEdit, ShieldCheck, 
  LogOut, Menu, X, Sun, Moon, Search, Plus, Phone, MessageSquare, 
  Send, Trash2, Edit3, ChevronDown, Check, AlertCircle, TrendingUp, Clock,
  Printer, History, Briefcase, ExternalLink, Calculator, Save, PlusCircle, Trash,
  Mail, FileText, Globe, UserCircle, RotateCcw, Download, Info, ArrowUpRight, ArrowDownRight, Activity,
  ChevronLeft, ChevronRight
} from 'lucide-react';

// --- Interfaces ---
type Role = 'superadmin' | 'admin' | 'sales' | 'purchasing' | 'pajak' | 'finance' | 'stockist' | 'audit' | 'engineer';

interface Supplier { id: string; nama: string; kode: string; npwp: string; }

interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product { id: string; nama: string; kode: string; lots: ProductLot[]; }

interface Customer {
  id: string; kode: string; nama: string; jenis: string; phone: string;
  email: string; alamat: string; sales: string; leadType: string;
  source: string; npwp: string; keterangan: string;
}

interface TransactionItem {
  produkId: string; nama: string; sku: string; harga: number; qty: number; diskon: number;
}

interface Transaction {
  id: string; noTrx: string; tanggal: string; customerName: string;
  items: TransactionItem[]; nilaiProyek: number; ppn: boolean; ongkir: boolean;
  biayaOngkir: number; jasaKirim: string; status: 'Selesai' | 'Progress' | 'Batal';
  sales: string; keterangan: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({});
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [currentStock, setCurrentStock] = useState<Partial<ProductLot>>({ stock: 0, hpp: 0, hargaJual: 0 });

  // Persistence
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');
    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Calculations
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  // Handlers
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data!");
    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`, nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowModal(null);
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Lengkapi!");
    const newProd = { ...currentProd, id: currentProd.id || Date.now().toString(), lots: currentProd.lots || [] } as Product;
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowModal(null);
  };

  const saveStockLot = () => {
    const prodId = (document.getElementById('stock-prod-select') as HTMLSelectElement)?.value;
    const suppId = (document.getElementById('stock-supp-select') as HTMLSelectElement)?.value;
    if (!prodId || !suppId) return alert("Pilih Produk & Supplier!");
    const prod = products.find(p => p.id === prodId);
    const newLot: ProductLot = { lot: Date.now(), sku: `${prod?.kode}-${Date.now().toString().slice(-4)}`, supplierId: suppId, stock: currentStock.stock || 0, hpp: currentStock.hpp || 0, hargaJual: currentStock.hargaJual || 0, tanggal: new Date().toISOString() };
    setProducts(prev => prev.map(p => p.id === prodId ? { ...p, lots: [...p.lots, newLot] } : p));
    setShowModal(null);
  };

  const stats = useMemo(() => {
    const totalOmzet = transactions.reduce((acc, t) => t.status === 'Selesai' ? acc + t.nilaiProyek : acc, 0);
    const progressOmzet = transactions.reduce((acc, t) => t.status === 'Progress' ? acc + t.nilaiProyek : acc, 0);
    return { totalOmzet, progressOmzet, totalCustomers: customers.length, totalProducts: products.length };
  }, [transactions, customers, products]);

  const navItemClass = (panel: Panel) => `w-full flex items-center ${isSidebarCollapsed ? 'lg:justify-center' : 'gap-3 px-4'} py-3 rounded-xl transition-all ${activePanel===panel?'bg-blue-600 text-white shadow-lg':'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`;

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>

      {/* Mobile Sidebar Overlay */}
      {isMobileMenuOpen && <div className="fixed inset-0 bg-black/50 z-[110] lg:hidden" onClick={() => setIsMobileMenuOpen(false)}></div>}

      {/* SIDEBAR */}
      <aside className={`fixed inset-y-0 left-0 z-[120] bg-white dark:bg-[#1e293b] border-r border-slate-200 dark:border-slate-800 p-6 flex flex-col transition-all duration-300 ${isMobileMenuOpen ? 'translate-x-0 w-72' : '-translate-x-full lg:translate-x-0'} ${isSidebarCollapsed ? 'lg:w-20' : 'lg:w-72'}`}>
        <div className={`flex items-center ${isSidebarCollapsed ? 'lg:justify-center' : 'gap-4'} mb-10`}>
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shrink-0 shadow-lg"><Package size={20}/></div>
          {(!isSidebarCollapsed || isMobileMenuOpen) && <h1 className="font-black text-xl tracking-tight">MyPanca</h1>}
        </div>
        <nav className="flex-1 space-y-2">
          <button onClick={()=>{setActivePanel('dashboard'); setIsMobileMenuOpen(false)}} className={navItemClass('dashboard')}><LayoutDashboard size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Dashboard</span>}</button>
          <button onClick={()=>{setActivePanel('tracking'); setIsMobileMenuOpen(false)}} className={navItemClass('tracking')}><LineChart size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Transaksi</span>}</button>
          <button onClick={()=>{setActivePanel('customer'); setIsMobileMenuOpen(false)}} className={navItemClass('customer')}><Users size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Customer</span>}</button>
          <button onClick={()=>{setActivePanel('produk'); setIsMobileMenuOpen(false)}} className={navItemClass('produk')}><Package size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Produk & Stock</span>}</button>
        </nav>
        <button onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)} className="hidden lg:flex absolute -right-3 top-20 w-6 h-6 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full items-center justify-center text-slate-400 hover:text-blue-600 shadow-sm z-20">{isSidebarCollapsed ? <ChevronRight size={14}/> : <ChevronLeft size={14}/>}</button>
      </aside>

      {/* MAIN CONTENT */}
      <main className={`flex-1 overflow-y-auto p-4 md:p-8 transition-all duration-300 ${isSidebarCollapsed ? 'lg:ml-20' : 'lg:ml-72'}`}>
        <header className="flex justify-between items-center mb-8">
          <div className="flex items-center gap-4">
            <button className="lg:hidden p-2 bg-white dark:bg-slate-800 rounded-xl border border-slate-100" onClick={() => setIsMobileMenuOpen(true)}><Menu size={20}/></button>
            <h2 className="text-xl md:text-3xl font-black tracking-tight uppercase">{activePanel}</h2>
          </div>
          <button onClick={()=>setIsDarkMode(!isDarkMode)} className="w-10 h-10 md:w-12 md:h-12 flex items-center justify-center bg-white dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-700">
            {isDarkMode ? <Sun size={20} className="text-yellow-400"/> : <Moon size={20} className="text-blue-600"/>}
          </button>
        </header>

        {activePanel === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Omzet Selesai</p>
                <h3 className="text-xl md:text-2xl font-black mt-1">Rp{stats.totalOmzet.toLocaleString()}</h3>
              </div>
              <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Potential Rev</p>
                <h3 className="text-xl md:text-2xl font-black mt-1 text-amber-500">Rp{stats.progressOmzet.toLocaleString()}</h3>
              </div>
              <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Customer</p>
                <h3 className="text-xl md:text-2xl font-black mt-1">{stats.totalCustomers}</h3>
              </div>
              <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Produk</p>
                <h3 className="text-xl md:text-2xl font-black mt-1">{stats.totalProducts}</h3>
              </div>
            </div>

            <div className="bg-blue-600 p-8 rounded-[2.5rem] text-white shadow-xl flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
               <div className="relative z-10 text-center md:text-left">
                  <h4 className="text-xl font-black">Mulai Transaksi Baru</h4>
                  <p className="text-blue-100 text-sm mt-1 opacity-80">Gunakan form transaksi untuk pencatatan otomatis.</p>
               </div>
               <button onClick={()=>{setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 }); setShowModal('trx');}} className="bg-white text-blue-600 px-8 py-3 rounded-2xl font-black text-sm hover:scale-105 transition-all flex items-center gap-2">
                 <Plus size={20}/> Buat Invoice Baru
               </button>
            </div>
          </div>
        )}

        {activePanel === 'tracking' && (
          <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] p-6 border border-slate-100 dark:border-slate-700 shadow-sm overflow-hidden">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold">Daftar Transaksi</h3>
              <button onClick={()=>{setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 }); setShowModal('trx');}} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2"><Plus size={18}/> Transaksi Baru</button>
            </div>
            <div className="overflow-x-auto -mx-6 px-6">
              <table className="w-full text-sm min-w-[700px]">
                <thead className="text-slate-400 border-b dark:border-slate-700 text-left"><tr className="uppercase text-[10px] font-black tracking-widest"><th className="pb-4 px-4">Invoice</th><th className="pb-4 px-4">Customer</th><th className="pb-4 px-4 text-right">Nilai Proyek</th><th className="pb-4 px-4 text-center">Status</th><th className="pb-4"></th></tr></thead>
                <tbody className="divide-y dark:divide-slate-700">
                  {transactions.map(t => (
                    <tr key={t.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-all cursor-pointer" onClick={()=>{setCurrentTrx(t); setShowModal('trx');}}>
                      <td className="py-5 px-4"><span className="font-black text-slate-900 dark:text-white">{t.noTrx}</span><p className="text-[10px] text-slate-400">{t.tanggal}</p></td>
                      <td className="py-5 px-4 font-bold">{t.customerName}</td>
                      <td className="py-5 px-4 text-right font-black text-blue-600">Rp{t.nilaiProyek.toLocaleString()}</td>
                      <td className="py-5 px-4 text-center"><span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase ${t.status==='Selesai'?'bg-emerald-50 text-emerald-600':'bg-amber-50 text-amber-600'}`}>{t.status}</span></td>
                      <td className="py-5 px-4 text-right"><ArrowUpRight size={16} className="text-slate-300"/></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activePanel === 'customer' && (
          <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] p-6 border border-slate-100 dark:border-slate-700 shadow-sm">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold">Database Customer</h3>
              <button onClick={()=>{setCurrentCust({jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'}); setShowModal('cust');}} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2"><Plus size={18}/> Customer Baru</button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              {customers.map(c => (
                <div key={c.id} onClick={()=>{setCurrentCust(c); setShowModal('cust');}} className="bg-slate-50 dark:bg-slate-700/30 p-5 rounded-3xl border border-slate-100 dark:border-slate-700 hover:border-blue-500 transition-all cursor-pointer group">
                  <div className="w-12 h-12 bg-white dark:bg-slate-800 text-blue-600 rounded-2xl flex items-center justify-center font-black text-xl mb-4 group-hover:bg-blue-600 group-hover:text-white transition-all shadow-sm">{c.nama[0]}</div>
                  <h4 className="font-bold text-sm truncate">{c.nama}</h4>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider mt-1">{c.kode}</p>
                  <div className="mt-4 pt-4 border-t border-dashed border-slate-200 dark:border-slate-600 flex justify-between items-center">
                    <span className="text-[9px] font-black text-blue-600 uppercase bg-blue-50 dark:bg-blue-900/30 px-2 py-0.5 rounded">{c.leadType}</span>
                    <span className="text-[9px] font-bold text-slate-400">{c.sales}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activePanel === 'produk' && (
          <div className="space-y-8">
            <div className="flex flex-wrap gap-3">
              <button onClick={()=>setShowModal('prod')} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2"><Plus size={18}/> Produk Baru</button>
              <button onClick={()=>setShowModal('supp')} className="bg-white dark:bg-slate-800 border border-slate-200 px-6 py-2 rounded-xl font-bold flex items-center gap-2"><FileText size={18}/> Supplier</button>
              <button onClick={()=>setShowModal('stock')} className="bg-emerald-500 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2"><Download size={18}/> Input Stock</button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              {products.map(p => (
                <div key={p.id} className="bg-white dark:bg-slate-800 p-6 rounded-3xl border border-slate-100 dark:border-slate-700 shadow-sm group">
                  <div className="flex gap-4 items-center mb-4"><div className="w-10 h-10 bg-blue-50 dark:bg-blue-900/30 rounded-xl flex items-center justify-center text-blue-600"><Package size={20}/></div><h5 className="font-bold text-sm truncate">{p.nama}</h5></div>
                  <div className="flex justify-between items-center border-t border-slate-50 pt-4"><span className="text-[10px] font-bold text-slate-400 uppercase">Stock</span><span className="font-black text-blue-600">{p.lots.reduce((a,b)=>a+b.stock,0)}</span></div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {/* MODALS */}
      {showModal && (
        <div className="fixed inset-0 z-[200] flex items-end sm:items-center justify-center bg-black/40 backdrop-blur-sm p-0 sm:p-4">
          <div className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-t-[1.5rem] sm:rounded-2xl shadow-2xl flex flex-col h-[90vh] sm:h-auto sm:max-h-[95vh] animate-in slide-in-from-bottom-10 sm:zoom-in-95">

            <div className="px-6 py-4 border-b dark:border-slate-700 flex justify-between items-center">
              <h3 className="font-bold">{showModal==='trx'?'Transaksi Baru':showModal==='cust'?'Customer Baru':'Form Data'}</h3>
              <button onClick={()=>setShowModal(null)} className="p-1.5 bg-slate-100 dark:bg-slate-700 rounded-lg"><X size={18}/></button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar text-[12px] md:text-[13px]">

              {showModal === 'trx' && (
                <>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="font-bold text-slate-500 uppercase text-[10px]">Tanggal</label><input type="date" value={currentTrx.tanggal} onChange={e=>setCurrentTrx(p=>({...p, tanggal: e.target.value}))} className="w-full border p-2.5 rounded-xl dark:bg-slate-700 dark:border-slate-600 dark:text-white"/></div>
                    <div className="space-y-1"><label className="font-bold text-slate-500 uppercase text-[10px]">Pilih Customer *</label><select value={currentTrx.customerName} onChange={e=>{const c=customers.find(x=>x.nama===e.target.value); setCurrentTrx(p=>({...p, customerName: e.target.value, sales: c?.sales}));}} className="w-full border-2 border-blue-500 rounded-full p-2.5 font-bold dark:bg-slate-700 dark:text-white"><option value="">-- Pilih --</option>{customers.map(c=><option key={c.id} value={c.nama}>{c.nama}</option>)}</select></div>
                  </div>

                  {selectedCustomer && (
                    <div className="grid grid-cols-2 gap-4 bg-slate-50 dark:bg-slate-900/30 p-4 rounded-2xl border border-slate-100 dark:border-slate-700">
                      <div><p className="text-[9px] font-bold text-slate-400 uppercase">Sales</p><p className="font-black text-blue-600">{selectedCustomer.sales}</p></div>
                      <div><p className="text-[9px] font-bold text-slate-400 uppercase">Lead Type</p><p className="font-black text-emerald-600">{selectedCustomer.leadType}</p></div>
                    </div>
                  )}

                  <div className="space-y-4 pt-2">
                    <div className="flex justify-between items-center"><h4 className="font-bold text-slate-800 dark:text-white uppercase text-[10px]">Daftar Produk</h4><button onClick={()=>setCurrentTrx(p=>({...p, items: [...(p.items||[]), { produkId: '', nama: '', sku: '', harga: 0, qty: 1, diskon: 0 }]}))} className="text-blue-600 font-bold flex items-center gap-1 text-[11px]"><PlusCircle size={14}/> Tambah Baris</button></div>
                    <div className="space-y-3">
                      {currentTrx.items?.map((item, idx) => (
                        <div key={idx} className="bg-slate-50 dark:bg-slate-700/20 p-4 rounded-xl border border-slate-100 flex flex-col gap-3">
                          <div className="grid grid-cols-2 gap-3">
                            <select value={item.nama} onChange={e=>{const prod=products.find(p=>p.nama===e.target.value); const lot=prod?.lots[0]; const newI=[...(currentTrx.items||[])]; newI[idx]={...item, nama: e.target.value, produkId: prod?.id||'', sku: lot?.sku||'', harga: lot?.hargaJual||0}; setCurrentTrx(p=>({...p, items: newI}));}} className="w-full border-2 border-blue-500 rounded-full p-2 text-[10px] font-bold dark:bg-slate-800"><option value="">Pilih Produk</option>{products.map(p=><option key={p.id} value={p.nama}>{p.nama}</option>)}</select>
                            <select value={item.sku} onChange={e=>{const p=products.find(x=>x.nama===item.nama); const lot=p?.lots.find(l=>l.sku===e.target.value); const newI=[...(currentTrx.items||[])]; newI[idx]={...item, sku: e.target.value, harga: lot?.hargaJual||0}; setCurrentTrx(p=>({...p, items: newI}));}} className="w-full border-2 border-blue-500 rounded-full p-2 text-[10px] font-bold dark:bg-slate-800"><option value="">SKU</option>{products.find(x=>x.nama===item.nama)?.lots.map(l=><option key={l.sku} value={l.sku}>{l.sku}</option>)}</select>
                          </div>
                          <div className="grid grid-cols-4 gap-2 items-end">
                             <div className="space-y-1"><label className="text-[9px] font-bold text-slate-400">QTY</label><input type="number" value={item.qty} onChange={e=>{const newI=[...(currentTrx.items||[])]; newI[idx]={...item, qty: parseInt(e.target.value)||0}; setCurrentTrx(p=>({...p, items: newI}));}} className="w-full border p-1.5 rounded-lg text-center font-bold text-[11px] dark:bg-slate-800"/></div>
                             <div className="space-y-1"><label className="text-[9px] font-bold text-slate-400">DISC</label><input type="number" value={item.diskon} onChange={e=>{const newI=[...(currentTrx.items||[])]; newI[idx]={...item, diskon: parseInt(e.target.value)||0}; setCurrentTrx(p=>({...p, items: newI}));}} className="w-full border p-1.5 rounded-lg text-center font-bold text-[11px] dark:bg-slate-800"/></div>
                             <div className="col-span-1.5 text-right"><p className="text-[9px] font-bold text-slate-400">SUBTOTAL</p><p className="font-black text-blue-600 text-[11px]">Rp{((item.qty*item.harga)-item.diskon).toLocaleString()}</p></div>
                             <button onClick={()=>setCurrentTrx(p=>({...p, items: p.items?.filter((_,i)=>i!==idx)}))} className="p-2 text-rose-500 hover:bg-rose-50 rounded-lg flex justify-center"><Trash2 size={16}/></button>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="flex flex-wrap gap-4 p-4 bg-slate-50 dark:bg-slate-700/20 rounded-xl">
                    <label className="flex items-center gap-2 cursor-pointer font-bold text-[10px]"><input type="checkbox" checked={currentTrx.ppn} onChange={e=>setCurrentTrx(p=>({...p, ppn: e.target.checked}))} className="w-4 h-4" /> PPN 11%</label>
                    <label className="flex items-center gap-2 cursor-pointer font-bold text-[10px]"><input type="checkbox" checked={currentTrx.ongkir} onChange={e=>setCurrentTrx(p=>({...p, ongkir: e.target.checked}))} className="w-4 h-4" /> Termasuk Ongkir</label>
                  </div>

                  {currentTrx.ongkir && (
                    <div className="p-4 bg-emerald-50 dark:bg-emerald-900/10 border border-emerald-100 rounded-xl grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div className="space-y-1"><label className="text-[9px] font-bold text-emerald-600 uppercase">Jasa Kirim</label><select value={currentTrx.jasaKirim} onChange={e=>setCurrentTrx(p=>({...p, jasaKirim: e.target.value}))} className="w-full border-2 border-blue-500 rounded-full p-2 text-[11px] font-bold dark:bg-slate-800"><option value="">Pilih Kurir</option><option value="JNE">JNE</option><option value="J&T">J&T</option></select></div>
                      <div className="space-y-1"><label className="text-[9px] font-bold text-emerald-600 uppercase">Biaya (Rp)</label><input type="number" value={currentTrx.biayaOngkir} onChange={e=>setCurrentTrx(p=>({...p, biayaOngkir: parseInt(e.target.value)||0}))} className="w-full border p-2 rounded-xl font-bold text-[11px] dark:bg-slate-800"/></div>
                    </div>
                  )}

                  <div className="text-right border-t dark:border-slate-700 pt-4 bg-slate-50 dark:bg-slate-900/10 p-4 rounded-xl">
                    <p className="text-slate-400 font-bold uppercase text-[9px] tracking-widest">Grand Total</p>
                    <h4 className="text-2xl md:text-3xl font-black text-blue-600">Rp{trxCalculations.grandTotal.toLocaleString()}</h4>
                  </div>
                </>
              )}

              {showModal === 'cust' && (
                <>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Nama Customer *</label><input value={currentCust.nama||''} onChange={e=>setCurrentCust({...currentCust, nama:e.target.value})} className="w-full border p-2.5 rounded-xl dark:bg-slate-700 dark:border-slate-600 outline-none focus:border-blue-500" placeholder="PT. Nama Perusahaan"/></div>
                    <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Jenis</label><select value={currentCust.jenis||'Perusahaan'} onChange={e=>setCurrentCust({...currentCust, jenis:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2.5 font-bold dark:bg-slate-700"><option value="Perusahaan">Perusahaan</option><option value="Perorangan">Perorangan</option></select></div>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Email</label><input type="email" value={currentCust.email||''} onChange={e=>setCurrentCust({...currentCust, email:e.target.value})} className="w-full border p-2.5 rounded-xl dark:bg-slate-700 dark:border-slate-600 outline-none" placeholder="email@domain.com"/></div>
                    <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Telepon</label><input value={currentCust.phone||''} onChange={e=>setCurrentCust({...currentCust, phone:e.target.value})} className="w-full border p-2.5 rounded-xl dark:bg-slate-700 dark:border-slate-600 outline-none" placeholder="0812..."/></div>
                  </div>
                  <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Alamat</label><textarea value={currentCust.alamat||''} onChange={e=>setCurrentCust({...currentCust, alamat:e.target.value})} className="w-full border p-2.5 rounded-xl h-20 md:h-24 resize-none dark:bg-slate-700 dark:border-slate-600 outline-none" placeholder="Alamat lengkap..."/></div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">NPWP</label><input value={currentCust.npwp||''} onChange={e=>setCurrentCust({...currentCust, npwp:e.target.value})} className="w-full border p-2.5 rounded-xl dark:bg-slate-700 dark:border-slate-600 outline-none" placeholder="00.000.000.0-000.000"/></div>
                    <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Nama Sales</label><select value={currentCust.sales||'Angel'} onChange={e=>setCurrentCust({...currentCust, sales:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2.5 font-bold dark:bg-slate-700"><option value="Angel">Angel</option><option value="Maria">Maria</option><option value="Budi">Budi</option><option value="Admin">Admin</option></select></div>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Lead Type</label><select value={currentCust.leadType||'Belum Transaksi'} onChange={e=>setCurrentCust({...currentCust, leadType:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2.5 font-bold dark:bg-slate-700"><option value="Belum Transaksi">Belum Transaksi</option><option value="Sudah Transaksi">Sudah Transaksi</option><option value="Repeat Order">Repeat Order</option><option value="Lost">Lost</option></select></div>
                    <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Source</label><select value={currentCust.source||'Organic'} onChange={e=>setCurrentCust({...currentCust, source:e.target.value})} className="w-full border-2 border-blue-500 rounded-full p-2.5 font-bold dark:bg-slate-700"><option value="Organic">Organic</option><option value="Paid Ads">Paid Ads</option><option value="Referral">Referral</option></select></div>
                  </div>
                </>
              )}

              {showModal === 'prod' && (
                <div className="space-y-4">
                  <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Nama Produk</label><input value={currentProd.nama||''} onChange={e=>setCurrentProd({...currentProd, nama:e.target.value})} className="w-full border p-3 rounded-xl dark:bg-slate-700 dark:border-slate-600"/></div>
                  <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Kode (SKU Base)</label><input value={currentProd.kode||''} onChange={e=>setCurrentProd({...currentProd, kode:e.target.value})} className="w-full border p-3 rounded-xl dark:bg-slate-700 dark:border-slate-600" placeholder="MIS: PT01"/></div>
                </div>
              )}

              {showModal === 'stock' && (
                <div className="space-y-6">
                  <div className="grid grid-cols-1 gap-4">
                    <div className="space-y-1"><label className="font-bold text-[10px] uppercase">Pilih Produk</label><select id="stock-prod-select" className="w-full border-2 border-blue-500 rounded-full p-2.5 font-bold dark:bg-slate-700"><option value="">-- Pilih --</option>{products.map(p=><option key={p.id} value={p.id}>{p.nama}</option>)}</select></div>
                    <div className="space-y-1"><label className="font-bold text-[10px] uppercase">Pilih Supplier</label><select id="stock-supp-select" className="w-full border-2 border-blue-500 rounded-full p-2.5 font-bold dark:bg-slate-700"><option value="">-- Pilih --</option>{suppliers.map(s=><option key={s.id} value={s.id}>{s.nama}</option>)}</select></div>
                  </div>
                  <div className="grid grid-cols-3 gap-3">
                    <div className="space-y-1"><label className="font-bold text-[9px] uppercase">QTY</label><input type="number" value={currentStock.stock} onChange={e=>setCurrentStock({...currentStock, stock: parseInt(e.target.value)||0})} className="w-full border p-2 rounded-xl font-bold dark:bg-slate-700"/></div>
                    <div className="space-y-1"><label className="font-bold text-[9px] uppercase">HPP</label><input type="number" value={currentStock.hpp} onChange={e=>setCurrentStock({...currentStock, hpp: parseInt(e.target.value)||0})} className="w-full border p-2 rounded-xl font-bold dark:bg-slate-700"/></div>
                    <div className="space-y-1"><label className="font-bold text-[9px] uppercase">JUAL</label><input type="number" value={currentStock.hargaJual} onChange={e=>setCurrentStock({...currentStock, hargaJual: parseInt(e.target.value)||0})} className="w-full border p-2 rounded-xl font-bold dark:bg-slate-700 text-blue-600"/></div>
                  </div>
                </div>
              )}

              {showModal === 'supp' && (
                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-1"><label className="font-bold text-[10px] uppercase">Nama Perusahaan</label><input value={currentSupp.nama||''} onChange={e=>setCurrentSupp({...currentSupp, nama:e.target.value})} className="w-full border p-2 rounded-xl dark:bg-slate-700" placeholder="PT..."/></div>
                    <div className="space-y-1"><label className="font-bold text-[10px] uppercase">Kode</label><input value={currentSupp.kode||''} onChange={e=>setCurrentSupp({...currentSupp, kode:e.target.value})} className="w-full border p-2 rounded-xl dark:bg-slate-700" placeholder="S-001"/></div>
                  </div>
                  <button onClick={()=>{if(!currentSupp.nama) return; setSuppliers(p=>[...p, {...currentSupp, id: Date.now().toString()} as Supplier]); setCurrentSupp({});}} className="w-full bg-blue-600 text-white py-2 rounded-xl font-bold">Simpan Supplier</button>
                  <div className="max-h-40 overflow-y-auto border dark:border-slate-700 rounded-xl">
                    <table className="w-full text-xs text-left"><thead className="bg-slate-50 dark:bg-slate-900/30 sticky top-0"><tr><th className="p-3">Nama</th><th className="p-3 text-right">Kode</th></tr></thead><tbody className="divide-y dark:divide-slate-700">{suppliers.map(s=>(<tr key={s.id}><td className="p-3">{s.nama}</td><td className="p-3 text-right font-bold">{s.kode}</td></tr>))}</tbody></table>
                  </div>
                </div>
              )}

            </div>

            <div className="px-6 py-4 border-t dark:border-slate-700 flex flex-col sm:flex-row justify-end gap-3 bg-slate-50/50 dark:bg-slate-900/20">
              <button onClick={()=>setShowModal(null)} className="order-2 sm:order-1 px-6 py-2.5 border border-slate-200 dark:border-slate-700 rounded-xl font-bold text-slate-500 text-xs">Batal</button>
              <button onClick={()=>{if(showModal==='trx') saveTransaction(); else if(showModal==='cust') saveCustomer(); else if(showModal==='prod') saveProduct(); else if(showModal==='stock') saveStockLot(); else setShowModal(null);}} className="order-1 sm:order-2 px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold text-xs flex items-center justify-center gap-2 shadow-lg"><Save size={16}/> Simpan Data</button>
            </div>
          </div>
        </div>
      )}

      {/* Floating Chat */}
      <button className="fixed bottom-6 right-6 w-14 h-14 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center z-50 animate-bounce"><MessageSquare size={24}/></button>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, Users, Package, LineChart, FileEdit, ShieldCheck, 
  LogOut, Menu, X, Sun, Moon, Search, Plus, Phone, MessageSquare, 
  Send, Trash2, Edit3, ChevronDown, Check, AlertCircle, TrendingUp, Clock,
  Printer, History, Briefcase, ExternalLink, Calculator, Save, PlusCircle, Trash,
  Mail, FileText, Globe, UserCircle, RotateCcw, Download, Info, ArrowUpRight, ArrowDownRight, Activity,
  ChevronLeft, ChevronRight
} from 'lucide-react';

// --- Interfaces ---
interface Supplier { id: string; nama: string; kode: string; npwp: string; }

interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product { id: string; nama: string; kode: string; lots: ProductLot[]; }

interface Customer {
  id: string; kode: string; nama: string; jenis: string; phone: string;
  email: string; alamat: string; sales: string; leadType: string;
  source: string; npwp: string; keterangan: string;
}

interface TransactionItem {
  produkId: string; nama: string; sku: string; harga: number; qty: number; diskon: number;
}

interface Transaction {
  id: string; noTrx: string; tanggal: string; customerName: string;
  items: TransactionItem[]; nilaiProyek: number; ppn: boolean; ongkir: boolean;
  biayaOngkir: number; jasaKirim: string; status: 'Selesai' | 'Progress' | 'Batal';
  sales: string; keterangan: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({});
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [currentStock, setCurrentStock] = useState<Partial<ProductLot>>({ stock: 0, hpp: 0, hargaJual: 0 });

  // Persistence
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');
    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Calculations
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  // Handlers
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data!");
    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`, nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowModal(null);
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Lengkapi data!");
    const newProd = { ...currentProd, id: currentProd.id || Date.now().toString(), lots: currentProd.lots || [] } as Product;
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowModal(null);
  };

  const saveStockLot = () => {
    const prodId = (document.getElementById('stock-prod-select') as HTMLSelectElement)?.value;
    const suppId = (document.getElementById('stock-supp-select') as HTMLSelectElement)?.value;
    if (!prodId || !suppId) return alert("Pilih Produk & Supplier!");
    const prod = products.find(p => p.id === prodId);
    const newLot: ProductLot = { lot: Date.now(), sku: `${prod?.kode}-${Date.now().toString().slice(-4)}`, supplierId: suppId, stock: currentStock.stock || 0, hpp: currentStock.hpp || 0, hargaJual: currentStock.hargaJual || 0, tanggal: new Date().toISOString() };
    setProducts(prev => prev.map(p => p.id === prodId ? { ...p, lots: [...p.lots, newLot] } : p));
    setShowModal(null);
  };

  const navItemClass = (panel: Panel) => `w-full flex items-center ${isSidebarCollapsed ? 'lg:justify-center' : 'gap-3 px-4'} py-3 rounded-xl transition-all ${activePanel===panel?'bg-blue-600 text-white shadow-lg':'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`;

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>

      {/* Mobile Sidebar Overlay */}
      {isMobileMenuOpen && <div className="fixed inset-0 bg-black/50 z-[110] lg:hidden" onClick={() => setIsMobileMenuOpen(false)}></div>}

      {/* SIDEBAR */}
      <aside className={`fixed inset-y-0 left-0 z-[120] bg-white dark:bg-[#1e293b] border-r border-slate-200 dark:border-slate-800 p-6 flex flex-col transition-all duration-300 ${isMobileMenuOpen ? 'translate-x-0 w-72' : '-translate-x-full lg:translate-x-0'} ${isSidebarCollapsed ? 'lg:w-20' : 'lg:w-72'}`}>
        <div className={`flex items-center ${isSidebarCollapsed ? 'lg:justify-center' : 'gap-4'} mb-10`}>
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shrink-0 shadow-lg shadow-blue-600/20"><Package size={20}/></div>
          {(!isSidebarCollapsed || isMobileMenuOpen) && <h1 className="font-black text-xl tracking-tight whitespace-nowrap">MyPanca</h1>}
        </div>
        <nav className="flex-1 space-y-2">
          <button onClick={()=>{setActivePanel('dashboard'); setIsMobileMenuOpen(false)}} className={navItemClass('dashboard')}><LayoutDashboard size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Dashboard</span>}</button>
          <button onClick={()=>{setActivePanel('tracking'); setIsMobileMenuOpen(false)}} className={navItemClass('tracking')}><LineChart size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Transaksi</span>}</button>
          <button onClick={()=>{setActivePanel('customer'); setIsMobileMenuOpen(false)}} className={navItemClass('customer')}><Users size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Customer</span>}</button>
          <button onClick={()=>{setActivePanel('produk'); setIsMobileMenuOpen(false)}} className={navItemClass('produk')}><Package size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Produk & Stock</span>}</button>
        </nav>
        <button onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)} className="hidden lg:flex absolute -right-3 top-20 w-6 h-6 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full items-center justify-center text-slate-400 hover:text-blue-600 shadow-sm z-20">{isSidebarCollapsed ? <ChevronRight size={14}/> : <ChevronLeft size={14}/>}</button>
      </aside>

      {/* MAIN CONTENT */}
      <main className={`flex-1 overflow-y-auto p-4 md:p-8 transition-all duration-300 ${isSidebarCollapsed ? 'lg:ml-20' : 'lg:ml-72'}`}>
        <header className="flex justify-between items-center mb-8">
          <div className="flex items-center gap-4">
            <button className="lg:hidden p-2 bg-white dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-700" onClick={() => setIsMobileMenuOpen(true)}><Menu size={20}/></button>
            <h2 className="text-xl md:text-3xl font-black tracking-tight uppercase">{activePanel}</h2>
          </div>
          <button onClick={()=>setIsDarkMode(!isDarkMode)} className="w-10 h-10 md:w-12 md:h-12 flex items-center justify-center bg-white dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-700">
            {isDarkMode ? <Sun size={20} className="text-yellow-400"/> : <Moon size={20} className="text-blue-600"/>}
          </button>
        </header>

        {activePanel === 'dashboard' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 animate-in fade-in duration-500">
             <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Total Transaksi</p>
                <h3 className="text-xl md:text-2xl font-black mt-1">{transactions.length}</h3>
             </div>
             <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Customer</p>
                <h3 className="text-xl md:text-2xl font-black mt-1">{customers.length}</h3>
             </div>
             <div className="bg-blue-600 p-8 rounded-[2.5rem] text-white shadow-xl col-span-1 sm:col-span-2 lg:col-span-2 flex flex-col md:flex-row justify-between items-center gap-6">
                <div><h4 className="text-xl font-black">Invoice Cepat</h4><p className="text-blue-100 text-sm">Buat transaksi dalam hitungan detik.</p></div>
                <button onClick={()=>{setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 }); setShowModal('trx');}} className="bg-white text-blue-600 px-8 py-3 rounded-2xl font-black text-sm flex items-center gap-2"><Plus size={18}/> Buat Sekarang</button>
             </div>
          </div>
        )}

        {activePanel === 'tracking' && (
          <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] p-6 border border-slate-100 dark:border-slate-700 shadow-sm overflow-hidden">
             <div className="flex justify-between items-center mb-8">
               <h3 className="text-xl font-bold">Daftar Transaksi</h3>
               <button onClick={()=>{setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 }); setShowModal('trx');}} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2 text-xs md:text-sm"><Plus size={18}/> Baru</button>
             </div>
             <div className="overflow-x-auto -mx-6 px-6 scrollbar-hide">
               <table className="w-full text-sm min-w-[700px]">
                 <thead className="text-slate-400 border-b dark:border-slate-700 text-left"><tr className="uppercase text-[10px] font-black tracking-widest"><th className="pb-4 px-4">Invoice</th><th className="pb-4 px-4">Customer</th><th className="pb-4 px-4 text-right">Nilai</th><th className="pb-4 px-4 text-center">Status</th><th className="pb-4"></th></tr></thead>
