                  </div>
                  <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Alamat Lengkap</label><textarea value={currentCust.alamat||''} onChange={e=>setCurrentCust({...currentCust, alamat:e.target.value})} className="w-full border p-2.5 rounded-xl h-20 md:h-24 resize-none dark:bg-slate-700 dark:border-slate-600 outline-none" placeholder="Alamat pengiriman dan tagihan..."/></div>
