                  <div className="space-y-1"><label className="font-bold text-slate-500 text-[10px] uppercase">Kode Dasar (MIS: PT01)</label><input value={currentProd.kode||''} onChange={e=>setCurrentProd({...currentProd, kode:e.target.value})} className="w-full border p-3 rounded-xl dark:bg-slate-700 dark:border-slate-600 outline-none" placeholder="MIS: PT01"/></div>
                </div>
              )}

              {showModal === 'stock' && (
                <div className="space-y-6">
                  <div className="grid grid-cols-1 gap-4">
                    <div className="space-y-1"><label className="font-bold text-[10px] uppercase">Produk Target</label><select id="stock-prod-select" className="w-full border-2 border-blue-500 rounded-full p-2.5 font-bold dark:bg-slate-700 outline-none"><option value="">-- Pilih --</option>{products.map(p=><option key={p.id} value={p.id}>{p.nama}</option>)}</select></div>
                    <div className="space-y-1"><label className="font-bold text-[10px] uppercase">Supplier Pengirim</label><select id="stock-supp-select" className="w-full border-2 border-blue-500 rounded-full p-2.5 font-bold dark:bg-slate-700 outline-none"><option value="">-- Pilih --</option>{suppliers.map(s=><option key={s.id} value={s.id}>{s.nama}</option>)}</select></div>
                  </div>
                  <div className="grid grid-cols-3 gap-3">
                    <div className="space-y-1"><label className="font-bold text-[9px] uppercase">QTY</label><input type="number" value={currentStock.stock} onChange={e=>setCurrentStock({...currentStock, stock: parseInt(e.target.value)||0})} className="w-full border p-2 rounded-xl font-bold dark:bg-slate-700 outline-none"/></div>
                    <div className="space-y-1"><label className="font-bold text-[9px] uppercase">HPP</label><input type="number" value={currentStock.hpp} onChange={e=>setCurrentStock({...currentStock, hpp: parseInt(e.target.value)||0})} className="w-full border p-2 rounded-xl font-bold dark:bg-slate-700 outline-none"/></div>
                    <div className="space-y-1"><label className="font-bold text-[9px] uppercase">JUAL</label><input type="number" value={currentStock.hargaJual} onChange={e=>setCurrentStock({...currentStock, hargaJual: parseInt(e.target.value)||0})} className="w-full border p-2 rounded-xl font-bold dark:bg-slate-700 text-blue-600 outline-none"/></div>
                  </div>
                </div>
              )}

              {showModal === 'supp' && (
                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-1"><label className="font-bold text-[10px] uppercase">Nama Supplier</label><input value={currentSupp.nama||''} onChange={e=>setCurrentSupp({...currentSupp, nama:e.target.value})} className="w-full border p-2 rounded-xl dark:bg-slate-700 outline-none" placeholder="PT..."/></div>
                    <div className="space-y-1"><label className="font-bold text-[10px] uppercase">Kode</label><input value={currentSupp.kode||''} onChange={e=>setCurrentSupp({...currentSupp, kode:e.target.value})} className="w-full border p-2 rounded-xl dark:bg-slate-700 outline-none" placeholder="S-001"/></div>
                  </div>
                  <button onClick={()=>{if(!currentSupp.nama) return; setSuppliers(p=>[...p, {...currentSupp, id: Date.now().toString()} as Supplier]); setCurrentSupp({});}} className="w-full bg-blue-600 text-white py-2.5 rounded-xl font-bold hover:bg-blue-700 transition-colors shadow-lg">Simpan Supplier</button>
                  <div className="max-h-40 overflow-y-auto border dark:border-slate-700 rounded-xl scrollbar-hide">
                    <table className="w-full text-xs text-left"><thead className="bg-slate-50 dark:bg-slate-900/30 sticky top-0"><tr><th className="p-3">Nama</th><th className="p-3 text-right">Kode</th></tr></thead><tbody className="divide-y dark:divide-slate-700">{suppliers.map(s=>(<tr key={s.id}><td className="p-3">{s.nama}</td><td className="p-3 text-right font-bold">{s.kode}</td></tr>))}</tbody></table>
                  </div>
                </div>
              )}

            </div>

            <div className="px-6 py-4 border-t dark:border-slate-700 flex flex-col sm:flex-row justify-end gap-3 bg-slate-50/50 dark:bg-slate-900/20 shrink-0">
              <button onClick={()=>setShowModal(null)} className="order-2 sm:order-1 px-6 py-2.5 border border-slate-200 dark:border-slate-700 rounded-xl font-bold text-slate-500 text-xs">Batal</button>
              <button onClick={()=>{if(showModal==='trx') saveTransaction(); else if(showModal==='cust') saveCustomer(); else if(showModal==='prod') saveProduct(); else if(showModal==='stock') saveStockLot(); else setShowModal(null);}} className="order-1 sm:order-2 px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold text-xs flex items-center justify-center gap-2 shadow-lg shadow-blue-600/20"><Save size={16}/> Simpan Data</button>
            </div>
          </div>
        </div>
      )}

      {/* Floating Chat Button */}
      <button className="fixed bottom-6 right-6 w-14 h-14 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center z-50 animate-bounce"><MessageSquare size={24}/></button>
    </div>
  );
};

export default App;

