} from 'lucide-react';

// --- Interfaces ---
interface Supplier { id: string; nama: string; kode: string; npwp: string; }

interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product { id: string; nama: string; kode: string; lots: ProductLot[]; }

interface Customer {
  id: string; kode: string; nama: string; jenis: string; phone: string;
  email: string; alamat: string; sales: string; leadType: string;
  source: string; npwp: string; keterangan: string;
}

interface TransactionItem {
  produkId: string; nama: string; sku: string; harga: number; qty: number; diskon: number;
}

interface Transaction {
  id: string; noTrx: string; tanggal: string; customerName: string;
  items: TransactionItem[]; nilaiProyek: number; ppn: boolean; ongkir: boolean;
  biayaOngkir: number; jasaKirim: string; status: 'Selesai' | 'Progress' | 'Batal';
  sales: string; keterangan: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

const App: React.FC = () => {
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({});
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [currentStock, setCurrentStock] = useState<Partial<ProductLot>>({ stock: 0, hpp: 0, hargaJual: 0 });

  // Persistence
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');
    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Utility: Format Rupiah
  const formatRupiah = (value: number) => {
    return new Intl.NumberFormat('id-ID', {
      style: 'currency',
      currency: 'IDR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(value);
  };

  // Calculations
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  // Handlers
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data!");
    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`, nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowModal(null);
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
  };

  const saveProduct = () => {
    if (!currentProd.nama || !currentProd.kode) return alert("Lengkapi data!");
    const newProd = { ...currentProd, id: currentProd.id || Date.now().toString(), lots: currentProd.lots || [] } as Product;
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowModal(null);
  };

  const saveStockLot = () => {
    const prodId = (document.getElementById('stock-prod-select') as HTMLSelectElement)?.value;
    const suppId = (document.getElementById('stock-supp-select') as HTMLSelectElement)?.value;
    if (!prodId || !suppId) return alert("Pilih Produk & Supplier!");
    const prod = products.find(p => p.id === prodId);
    const newLot: ProductLot = { lot: Date.now(), sku: `${prod?.kode}-${Date.now().toString().slice(-4)}`, supplierId: suppId, stock: currentStock.stock || 0, hpp: currentStock.hpp || 0, hargaJual: currentStock.hargaJual || 0, tanggal: new Date().toISOString() };
    setProducts(prev => prev.map(p => p.id === prodId ? { ...p, lots: [...p.lots, newLot] } : p));
    setShowModal(null);
  };

  const navItemClass = (panel: Panel) => `w-full flex items-center ${isSidebarCollapsed ? 'lg:justify-center' : 'gap-3 px-4'} py-3 rounded-xl transition-all ${activePanel===panel?'bg-blue-600 text-white shadow-lg':'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`;

  return (
    <div className={`min-h-screen flex ${isDarkMode ? 'dark bg-[#0f172a] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>

      {/* Mobile Sidebar Overlay */}
      {isMobileMenuOpen && <div className="fixed inset-0 bg-black/50 z-[110] lg:hidden" onClick={() => setIsMobileMenuOpen(false)}></div>}

      {/* SIDEBAR */}
      <aside className={`fixed inset-y-0 left-0 z-[120] bg-white dark:bg-[#1e293b] border-r border-slate-200 dark:border-slate-800 p-6 flex flex-col transition-all duration-300 ${isMobileMenuOpen ? 'translate-x-0 w-72' : '-translate-x-full lg:translate-x-0'} ${isSidebarCollapsed ? 'lg:w-20' : 'lg:w-72'}`}>
        <div className={`flex items-center ${isSidebarCollapsed ? 'lg:justify-center' : 'gap-4'} mb-10`}>
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shrink-0 shadow-lg shadow-blue-600/20"><Package size={20}/></div>
          {(!isSidebarCollapsed || isMobileMenuOpen) && <h1 className="font-black text-xl tracking-tight whitespace-nowrap">MyPanca</h1>}
        </div>
        <nav className="flex-1 space-y-2">
          <button onClick={()=>{setActivePanel('dashboard'); setIsMobileMenuOpen(false)}} className={navItemClass('dashboard')}><LayoutDashboard size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Dashboard</span>}</button>
          <button onClick={()=>{setActivePanel('tracking'); setIsMobileMenuOpen(false)}} className={navItemClass('tracking')}><LineChart size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Transaksi</span>}</button>
          <button onClick={()=>{setActivePanel('customer'); setIsMobileMenuOpen(false)}} className={navItemClass('customer')}><Users size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Customer</span>}</button>
          <button onClick={()=>{setActivePanel('produk'); setIsMobileMenuOpen(false)}} className={navItemClass('produk')}><Package size={20}/>{(!isSidebarCollapsed || isMobileMenuOpen) && <span className="font-bold text-sm">Produk & Stock</span>}</button>
        </nav>
        <button onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)} className="hidden lg:flex absolute -right-3 top-20 w-6 h-6 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full items-center justify-center text-slate-400 hover:text-blue-600 shadow-sm z-20">{isSidebarCollapsed ? <ChevronRight size={14}/> : <ChevronLeft size={14}/>}</button>
      </aside>

      {/* MAIN CONTENT */}
      <main className={`flex-1 overflow-y-auto p-4 md:p-8 transition-all duration-300 ${isSidebarCollapsed ? 'lg:ml-20' : 'lg:ml-72'}`}>
        <header className="flex justify-between items-center mb-8">
          <div className="flex items-center gap-4">
            <button className="lg:hidden p-2 bg-white dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-700" onClick={() => setIsMobileMenuOpen(true)}><Menu size={20}/></button>
            <h2 className="text-xl md:text-3xl font-black tracking-tight uppercase">{activePanel}</h2>
          </div>
          <button onClick={()=>setIsDarkMode(!isDarkMode)} className="w-10 h-10 md:w-12 md:h-12 flex items-center justify-center bg-white dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-700">
            {isDarkMode ? <Sun size={20} className="text-yellow-400"/> : <Moon size={20} className="text-blue-600"/>}
          </button>
        </header>

        {activePanel === 'dashboard' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 animate-in fade-in duration-500">
             <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Total Transaksi</p>
                <h3 className="text-xl md:text-2xl font-black mt-1">{transactions.length}</h3>
             </div>
             <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 shadow-sm">
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Customer</p>
                <h3 className="text-xl md:text-2xl font-black mt-1">{customers.length}</h3>
             </div>
             <div className="bg-blue-600 p-8 rounded-[2.5rem] text-white shadow-xl col-span-1 sm:col-span-2 lg:col-span-2 flex flex-col md:flex-row justify-between items-center gap-6">
                <div><h4 className="text-xl font-black">Invoice Cepat</h4><p className="text-blue-100 text-sm">Buat transaksi dalam hitungan detik.</p></div>
                <button onClick={()=>{setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 }); setShowModal('trx');}} className="bg-white text-blue-600 px-8 py-3 rounded-2xl font-black text-sm flex items-center gap-2"><Plus size={18}/> Buat Sekarang</button>
             </div>
          </div>
        )}

        {activePanel === 'tracking' && (
          <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] p-6 border border-slate-100 dark:border-slate-700 shadow-sm overflow-hidden">
             <div className="flex justify-between items-center mb-8">
               <h3 className="text-xl font-bold">Daftar Transaksi</h3>
               <button onClick={()=>{setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 }); setShowModal('trx');}} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2 text-xs md:text-sm"><Plus size={18}/> Baru</button>
             </div>
             <div className="overflow-x-auto -mx-6 px-6 scrollbar-hide">
               <table className="w-full text-sm min-w-[700px]">
                 <thead className="text-slate-400 border-b dark:border-slate-700 text-left"><tr className="uppercase text-[10px] font-black tracking-widest"><th className="pb-4 px-4">Invoice</th><th className="pb-4 px-4">Customer</th><th className="pb-4 px-4 text-right">Nilai</th><th className="pb-4 px-4 text-center">Status</th><th className="pb-4"></th></tr></thead>
                 <tbody className="divide-y dark:divide-slate-700">
                   {transactions.map(t => (
                     <tr key={t.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-all cursor-pointer" onClick={()=>{setCurrentTrx(t); setShowModal('trx');}}>
                       <td className="py-5 px-4"><span className="font-black">{t.noTrx}</span><p className="text-[10px] text-slate-400">{t.tanggal}</p></td>
                       <td className="py-5 px-4 font-bold">{t.customerName}</td>
                       <td className="py-5 px-4 text-right font-black text-blue-600">{formatRupiah(t.nilaiProyek)}</td>
                       <td className="py-5 px-4 text-center"><span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase ${t.status==='Selesai'?'bg-emerald-50 text-emerald-600':'bg-amber-50 text-amber-600'}`}>{t.status}</span></td>
                       <td className="py-5 px-4 text-right text-slate-300"><ArrowUpRight size={16}/></td>
                     </tr>
                   ))}
                 </tbody>
               </table>
             </div>
          </div>
        )}

        {activePanel === 'customer' && (
          <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] p-6 border border-slate-100 dark:border-slate-700 shadow-sm animate-in fade-in duration-500">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold">Database Customer</h3>
              <button onClick={()=>{setCurrentCust({jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel'}); setShowModal('cust');}} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2 text-xs md:text-sm"><Plus size={18}/> Customer Baru</button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              {customers.map(c => (
                <div key={c.id} onClick={()=>{setCurrentCust(c); setShowModal('cust');}} className="bg-slate-50 dark:bg-slate-700/30 p-5 rounded-3xl border border-slate-100 dark:border-slate-700 hover:border-blue-500 transition-all cursor-pointer group">
                  <div className="w-12 h-12 bg-white dark:bg-slate-800 text-blue-600 rounded-2xl flex items-center justify-center font-black text-xl mb-4 group-hover:bg-blue-600 group-hover:text-white transition-all shadow-sm">{c.nama[0]}</div>
                  <h4 className="font-bold text-sm truncate">{c.nama}</h4>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider mt-1">{c.kode}</p>
                  <div className="mt-4 pt-4 border-t border-dashed border-slate-200 dark:border-slate-600 flex justify-between items-center">
                    <span className="text-[9px] font-black text-blue-600 uppercase bg-blue-50 dark:bg-blue-900/30 px-2 py-0.5 rounded">{c.leadType}</span>
                    <span className="text-[9px] font-bold text-slate-400">{c.sales}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activePanel === 'produk' && (
          <div className="space-y-8">
            <div className="flex flex-wrap gap-3">
              <button onClick={()=>setShowModal('prod')} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2 text-xs md:text-sm"><Plus size={18}/> Produk Baru</button>
              <button onClick={()=>setShowModal('supp')} className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 px-6 py-2 rounded-xl font-bold flex items-center gap-2 text-xs md:text-sm"><FileText size={18}/> Supplier</button>
              <button onClick={()=>setShowModal('stock')} className="bg-emerald-500 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2 text-xs md:text-sm"><Download size={18}/> Input Stock</button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              {products.map(p => (
                <div key={p.id} className="bg-white dark:bg-slate-800 p-6 rounded-3xl border border-slate-100 dark:border-slate-700 shadow-sm">
                  <div className="flex gap-4 items-center mb-4"><div className="w-10 h-10 bg-blue-50 dark:bg-blue-900/30 rounded-xl flex items-center justify-center text-blue-600"><Package size={20}/></div><h5 className="font-bold text-sm truncate">{p.nama}</h5></div>
                  <div className="flex justify-between items-center border-t border-slate-50 dark:border-slate-700 pt-4"><span className="text-[10px] font-bold text-slate-400 uppercase">Stock</span><span className="font-black text-blue-600">{p.lots.reduce((a,b)=>a+b.stock,0)}</span></div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {/* MODALS */}
      {showModal && (
        <div className="fixed inset-0 z-[200] flex items-end sm:items-center justify-center bg-black/40 backdrop-blur-sm p-0 sm:p-4 overflow-y-auto">
          <div className="bg-white dark:bg-slate-800 w-full max-w-2xl rounded-t-[1.5rem] sm:rounded-2xl shadow-2xl flex flex-col h-[90vh] sm:h-auto sm:max-h-[95vh] animate-in slide-in-from-bottom-10 sm:zoom-in-95 duration-200">

            <div className="px-6 py-4 border-b dark:border-slate-700 flex justify-between items-center shrink-0">
              <h3 className="font-bold text-slate-800 dark:text-white">{showModal==='trx'?'Transaksi Baru':showModal==='cust'?'Customer Lengkap':'Form Data'}</h3>
              <button onClick={()=>setShowModal(null)} className="p-1.5 bg-slate-100 dark:bg-slate-700 rounded-lg"><X size={18}/></button>
            </div>

            <div className="flex-1 overflow-y-auto p-5 md:p-6 space-y-6 custom-scrollbar text-[12px] md:text-[13px]">

              {showModal === 'trx' && (
                <>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="space-y-1"><label className="font-bold text-slate-500 uppercase text-[10px]">Tanggal</label><input type="date" value={currentTrx.tanggal} onChange={e=>setCurrentTrx(p=>({...p, tanggal: e.target.value}))} className="w-full border p-2.5 rounded-xl dark:bg-slate-700 dark:border-slate-600 dark:text-white"/></div>
                    <div className="space-y-1"><label className="font-bold text-slate-500 uppercase text-[10px]">Pilih Customer *</label><select value={currentTrx.customerName || ''} onChange={e=>{const c=customers.find(x=>x.nama===e.target.value); setCurrentTrx(p=>({...p, customerName: e.target.value, sales: c?.sales || 'Angel'}));}} className="w-full border-2 border-blue-500 rounded-full p-2.5 font-bold dark:bg-slate-700 dark:text-white outline-none"><option value="">-- Pilih --</option>{customers.map(c=><option key={c.id} value={c.nama}>{c.nama}</option>)}</select></div>
                  </div>

                  {selectedCustomer && (
                    <div className="grid grid-cols-2 gap-4 bg-slate-50 dark:bg-slate-900/30 p-4 rounded-2xl border border-slate-100 dark:border-slate-700">
                      <div><p className="text-[9px] font-bold text-slate-400 uppercase">Sales Bertugas</p><p className="font-black text-blue-600">{selectedCustomer.sales}</p></div>
                      <div><p className="text-[9px] font-bold text-slate-400 uppercase">Status Lead</p><p className="font-black text-emerald-600">{selectedCustomer.leadType}</p></div>
                    </div>
                  )}

                  <div className="space-y-4 pt-2 border-t dark:border-slate-700">
                    <div className="flex justify-between items-center"><h4 className="font-bold text-slate-800 dark:text-white uppercase text-[10px]">Daftar Produk</h4><button onClick={()=>setCurrentTrx(p=>({...p, items: [...(p.items||[]), { produkId: '', nama: '', sku: '', harga: 0, qty: 1, diskon: 0 }]}))} className="text-blue-600 font-bold flex items-center gap-1 text-[11px] hover:underline"><PlusCircle size={14}/> Tambah Baris</button></div>
                    <div className="space-y-3">
                      {currentTrx.items?.map((item, idx) => (
                        <div key={idx} className="bg-slate-50 dark:bg-slate-700/20 p-4 rounded-xl border border-slate-100 dark:border-slate-700 flex flex-col gap-3 relative">
                          <div className="grid grid-cols-2 gap-3">
                            <select value={item.nama} onChange={e=>{const prod=products.find(p=>p.nama===e.target.value); const lot=prod?.lots[0]; const newI=[...(currentTrx.items||[])]; newI[idx]={...item, nama: e.target.value, produkId: prod?.id||'', sku: lot?.sku||'', harga: lot?.hargaJual||0}; setCurrentTrx(p=>({...p, items: newI}));}} className="w-full border-2 border-blue-500 rounded-full p-2 text-[10px] font-bold dark:bg-slate-800 outline-none"><option value="">Pilih Produk</option>{products.map(p=><option key={p.id} value={p.nama}>{p.nama}</option>)}</select>
                            <select value={item.sku} onChange={e=>{const p=products.find(x=>x.nama===item.nama); const lot=p?.lots.find(l=>l.sku===e.target.value); const newI=[...(currentTrx.items||[])]; newI[idx]={...item, sku: e.target.value, harga: lot?.hargaJual||0}; setCurrentTrx(p=>({...p, items: newI}));}} className="w-full border-2 border-blue-500 rounded-full p-2 text-[10px] font-bold dark:bg-slate-800 outline-none"><option value="">SKU</option>{products.find(x=>x.nama===item.nama)?.lots.map(l=><option key={l.sku} value={l.sku}>{l.sku}</option>)}</select>
                          </div>
                          <div className="grid grid-cols-4 gap-2 items-end">
                             <div className="space-y-1"><label className="text-[9px] font-bold text-slate-400">QTY</label><input type="number" value={item.qty} onChange={e=>{const newI=[...(currentTrx.items||[])]; newI[idx]={...item, qty: parseInt(e.target.value)||0}; setCurrentTrx(p=>({...p, items: newI}));}} className="w-full border p-1.5 rounded-lg text-center font-bold text-[11px] dark:bg-slate-800"/></div>
                             <div className="space-y-1"><label className="text-[9px] font-bold text-slate-400">DISC</label><input type="number" value={item.diskon} onChange={e=>{const newI=[...(currentTrx.items||[])]; newI[idx]={...item, diskon: parseInt(e.target.value)||0}; setCurrentTrx(p=>({...p, items: newI}));}} className="w-full border p-1.5 rounded-lg text-center font-bold text-[11px] dark:bg-slate-800"/></div>
                             <div className="col-span-1.5 text-right"><p className="text-[9px] font-bold text-slate-400 uppercase">Subtotal</p><p className="font-black text-blue-600 text-[11px]">{formatRupiah((item.qty*item.harga)-item.diskon)}</p></div>
                             <button onClick={()=>setCurrentTrx(p=>({...p, items: p.items?.filter((_,i)=>i!==idx)}))} className="p-2 text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg flex justify-center transition-colors"><Trash2 size={16}/></button>
                          </div>
                        </div>
                      ))}
                    </div>
