} from 'lucide-react';

// --- Interfaces ---
interface Supplier { id: string; nama: string; kode: string; npwp: string; }

interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product { id: string; nama: string; kode: string; lots: ProductLot[]; }

interface Customer {
  id: string; kode: string; nama: string; jenis: string; phone: string;
  email: string; alamat: string; sales: string; leadType: string;
  source: string; npwp: string; keterangan: string; negara: string;
}

interface TransactionItem {
  produkId: string; nama: string; sku: string; harga: number; qty: number; diskon: number;
}

interface Transaction {
  id: string; noTrx: string; tanggal: string; customerName: string;
  items: TransactionItem[]; nilaiProyek: number; ppn: boolean; ongkir: boolean;
  biayaOngkir: number; jasaKirim: string; status: 'Selesai' | 'Progress' | 'Batal';
  sales: string; keterangan: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

// --- Constants ---
const COUNTRY_LIST = [
  { name: 'Indonesia', code: '62' },
  { name: 'Malaysia', code: '60' },
  { name: 'Singapore', code: '65' },
  { name: 'Thailand', code: '66' },
  { name: 'Vietnam', code: '84' },
  { name: 'Philippines', code: '63' },
  { name: 'United States', code: '1' },
  { name: 'Australia', code: '61' },
  { name: 'Japan', code: '81' },
  { name: 'China', code: '86' },
];

// --- Helpers & Custom Components ---

// Format angka ke string dengan titik (misal: 1000 -> "1.000")
const formatInputNumber = (val: number | string | undefined) => {
  if (val === undefined || val === null || val === '') return '';
  const num = typeof val === 'string' ? parseInt(val.replace(/\./g, '')) : val;
  if (isNaN(num)) return '';
  return new Intl.NumberFormat('id-ID').format(num);
};

// Parse string ber-titik kembali ke number (misal: "1.000" -> 1000)
const parseInputNumber = (val: string) => {
  return parseInt(val.replace(/\./g, '')) || 0;
};

// Component: Searchable Select (Dropdown dengan pencarian)
const SearchableSelect = ({ 
  options, 
  value, 
  onChange, 
  placeholder, 
  className 
}: { 
  options: { value: string; label: string }[], 
  value: string, 
  onChange: (val: string) => void, 
  placeholder: string,
  className?: string
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Reset search saat menu ditutup
  useEffect(() => {
    if (!isOpen) {
        setSearch(''); 
    }
  }, [isOpen]);

  const selectedLabel = options.find(o => o.value === value)?.label || '';
  const filteredOptions = options.filter(o => o.label.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="relative" ref={wrapperRef}>
      <div 
        onClick={() => setIsOpen(!isOpen)} 
        className={`relative cursor-pointer flex items-center justify-between ${className} ${!value ? 'text-slate-400' : 'text-slate-900 dark:text-white'}`}
      >
        <span className="truncate block w-[90%]">
           {selectedLabel || placeholder}
        </span>
        <ChevronDown size={16} className="text-slate-400 shrink-0"/>
      </div>

      {isOpen && (
        <div className="absolute z-50 w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 rounded-xl mt-1 shadow-2xl max-h-60 overflow-y-auto custom-scrollbar animate-in fade-in zoom-in-95 duration-100">
          <div className="p-2 sticky top-0 bg-white dark:bg-slate-800 border-b dark:border-slate-700">
            <div className="relative">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/>
                <input 
                    autoFocus
                    type="text" 
                    className="w-full bg-slate-50 dark:bg-slate-700 rounded-lg py-2 pl-9 pr-3 text-xs outline-none border focus:border-blue-500 transition-colors"
                    placeholder="Cari..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />
            </div>
          </div>
          <div className="p-1">
            {filteredOptions.length > 0 ? filteredOptions.map(opt => (
                <div 
                    key={opt.value} 
                    onClick={() => { onChange(opt.value); setIsOpen(false); }}
                    className={`p-2.5 text-xs rounded-lg cursor-pointer hover:bg-blue-50 dark:hover:bg-blue-900/30 hover:text-blue-600 flex justify-between items-center ${value === opt.value ? 'bg-blue-50 text-blue-600 dark:bg-blue-900/20' : ''}`}
                >
                    <span className="font-bold">{opt.label}</span>
                    {value === opt.value && <Check size={14}/>}
                </div>
            )) : (
                <div className="p-4 text-center text-xs text-slate-400">Tidak ditemukan</div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

