                  <div className="max-h-40 overflow-y-auto border dark:border-slate-700 rounded-xl scrollbar-hide">
                    <table className="w-full text-xs text-left"><thead className="bg-slate-50 dark:bg-slate-900/30 sticky top-0"><tr><th className="p-3">Nama</th><th className="p-3 text-right">Kode</th></tr></thead><tbody className="divide-y dark:divide-slate-700">{suppliers.map(s=>(<tr key={s.id}><td className="p-3">{s.nama}</td><td className="p-3 text-right font-bold">{s.kode}</td></tr>))}</tbody></table>
                  </div>
                </div>
              )}

            </div>

            <div className="px-6 py-4 border-t dark:border-slate-700 flex flex-col sm:flex-row justify-end gap-3 bg-slate-50/50 dark:bg-slate-900/20 shrink-0">
              <button onClick={()=>setShowModal(null)} className="order-2 sm:order-1 px-6 py-2.5 border border-slate-200 dark:border-slate-700 rounded-xl font-bold text-slate-500 text-xs">Batal</button>
              <button onClick={()=>{if(showModal==='trx') saveTransaction(); else if(showModal==='cust') saveCustomer(); else if(showModal==='prod') saveProduct(); else if(showModal==='stock') saveStockLot(); else setShowModal(null);}} className="order-1 sm:order-2 px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold text-xs flex items-center justify-center gap-2 shadow-lg shadow-blue-600/20"><Save size={16}/> Simpan Data</button>
            </div>
          </div>
        </div>
      )}

      {/* Floating Chat Button */}
      <button className="fixed bottom-6 right-6 w-14 h-14 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center z-50 animate-bounce"><MessageSquare size={24}/></button>
    </div>
  );
};

