// Generator Kode
const generateProductCode = () => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  let result = '';
  for (let i = 0; i < 3; i++) result += chars.charAt(Math.floor(Math.random() * chars.length));
  return result;
};

const generateSupplierCode = () => {
  return Math.floor(10000 + Math.random() * 90000).toString();
};

// Format angka ke string dengan titik (misal: 1000 -> "1.000")
const formatInputNumber = (val: number | string | undefined) => {
  if (val === undefined || val === null || val === '') return '';
  const num = typeof val === 'string' ? parseInt(val.replace(/\./g, '')) : val;
  if (isNaN(num)) return '';
  return new Intl.NumberFormat('id-ID').format(num);
};

// Parse string ber-titik kembali ke number (misal: "1.000" -> 1000)
const parseInputNumber = (val: string) => {
  return parseInt(val.replace(/\./g, '')) || 0;
};

// Component: Searchable Select (Dropdown dengan pencarian modern)
const SearchableSelect = ({ 
  options, 
  value, 
  onChange, 
  placeholder, 
  className 
}: { 
  options: { value: string; label: string }[], 
  value: string, 
  onChange: (val: string) => void, 
  placeholder: string,
  className?: string
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    if (!isOpen) {
        setSearch(''); 
    }
  }, [isOpen]);

  const selectedLabel = options.find(o => o.value === value)?.label || '';
  const filteredOptions = options.filter(o => o.label.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="relative group" ref={wrapperRef}>
      <div 
        onClick={() => setIsOpen(!isOpen)} 
        className={`relative cursor-pointer flex items-center justify-between transition-all duration-200 ease-in-out hover:border-blue-400 ${className} ${!value ? 'text-slate-400' : 'text-slate-900 dark:text-white'} ${isOpen ? 'border-blue-600 ring-4 ring-blue-100 dark:ring-blue-900/30' : ''}`}
      >
        <span className="truncate block w-[90%] select-none">
           {selectedLabel || placeholder}
        </span>
        <ChevronDown size={16} className={`text-slate-400 shrink-0 transition-transform duration-300 ${isOpen ? 'rotate-180 text-blue-600' : ''}`}/>
      </div>

      {isOpen && (
        <div className="absolute z-50 w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl mt-2 shadow-xl shadow-slate-200/50 dark:shadow-black/50 max-h-60 overflow-y-auto custom-scrollbar animate-in fade-in zoom-in-95 duration-200">
          <div className="p-2 sticky top-0 bg-white dark:bg-slate-800 border-b dark:border-slate-700 z-10">
            <div className="relative">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/>
                <input 
                    autoFocus
                    type="text" 
                    className="w-full bg-slate-50 dark:bg-slate-700/50 rounded-lg py-2 pl-9 pr-3 text-xs outline-none border border-slate-200 dark:border-slate-600 focus:border-blue-500 transition-colors placeholder:text-slate-400"
                    placeholder="Cari data..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />
            </div>
          </div>
          <div className="p-1.5 space-y-0.5">
            {filteredOptions.length > 0 ? filteredOptions.map(opt => (
                <div 
                    key={opt.value} 
                    onClick={() => { onChange(opt.value); setIsOpen(false); }}
                    className={`p-2.5 text-xs rounded-lg cursor-pointer transition-colors flex justify-between items-center ${value === opt.value ? 'bg-blue-50 text-blue-700 font-bold dark:bg-blue-900/40 dark:text-blue-400' : 'hover:bg-slate-50 dark:hover:bg-slate-700/50 text-slate-600 dark:text-slate-300'}`}
                >
                    <span>{opt.label}</span>
                    {value === opt.value && <Check size={14} className="text-blue-600 dark:text-blue-400"/>}
                </div>
            )) : (
                <div className="p-8 text-center flex flex-col items-center justify-center text-slate-400 gap-2">
                    <Search size={24} className="opacity-20"/>
                    <span className="text-xs">Data tidak ditemukan</span>
                </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => {
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showModal, setShowModal] = useState<string | null>(null);

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel', negara: 'Indonesia', phone: '62'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({ satuan: 'Pcs' });
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [currentStock, setCurrentStock] = useState<Partial<ProductLot>>({ stock: 0, hpp: 0, hargaJual: 0 });

  // Persistence
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');
    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Utility: Format Rupiah Display (untuk label non-input)
  const formatRupiah = (value: number) => {
    return new Intl.NumberFormat('id-ID', {
      style: 'currency',
      currency: 'IDR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(value);
  };

  // Calculations
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  // Handlers
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data!");
    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`, nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowModal(null);
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowModal(null);
  };

  const saveProduct = () => {
    if (!currentProd.nama) return alert("Nama produk wajib diisi!");

    // Otomatis generate kode jika baru (3 huruf acak)
    const kodeOtomatis = currentProd.kode || generateProductCode();

    const newProd = { 
        ...currentProd, 
        kode: kodeOtomatis,
        id: currentProd.id || Date.now().toString(), 
        lots: currentProd.lots || [] 
    } as Product;

    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowModal(null);
  };

  const saveSupplier = () => {
      if(!currentSupp.nama) return alert("Nama supplier wajib diisi!");

      // Otomatis generate kode (5 angka acak)
      const kodeOtomatis = currentSupp.kode || generateSupplierCode();

      const newSupp = {
          ...currentSupp,
          kode: kodeOtomatis,
          id: currentSupp.id || Date.now().toString()
      } as Supplier;

      setSuppliers(p => currentSupp.id ? p.map(s => s.id === newSupp.id ? newSupp : s) : [...p, newSupp]);
      setCurrentSupp({});
  };

  const saveStockLot = () => {
    if (!currentStock.sku || !currentStock.supplierId) return alert("Pilih Produk & Supplier!");

    const prod = products.find(p => p.id === currentStock.sku);
    const supp = suppliers.find(s => s.id === currentStock.supplierId);

    if (!prod || !supp) return alert("Data produk atau supplier tidak valid");

    // SKU = KODE PRODUK - KODE SUPPLIER
    const newSku = `${prod.kode}-${supp.kode}`;

    const newLot: ProductLot = { 
        lot: Date.now(), 
        sku: newSku, 
        supplierId: currentStock.supplierId, 
        stock: currentStock.stock || 0, 
        hpp: currentStock.hpp || 0, 
        hargaJual: currentStock.hargaJual || 0, 
        tanggal: new Date().toISOString() 
    };
    setProducts(prev => prev.map(p => p.id === currentStock.sku ? { ...p, lots: [...p.lots, newLot] } : p));
    setShowModal(null);
  };

