const generateProductCode = () => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  let result = '';
  for (let i = 0; i < 3; i++) result += chars.charAt(Math.floor(Math.random() * chars.length));
  return result;
};

const generateSupplierCode = () => {
  return Math.floor(10000 + Math.random() * 90000).toString();
};

const formatInputNumber = (val: number | string | undefined) => {
  if (val === undefined || val === null || val === '') return '';
  const num = typeof val === 'string' ? parseInt(val.replace(/\./g, '')) : val;
  if (isNaN(num)) return '';
  return new Intl.NumberFormat('id-ID').format(num);
};

const parseInputNumber = (val: string) => {
  return parseInt(val.replace(/\./g, '')) || 0;
};

// Component: Modern Soft Searchable Select
const SearchableSelect = ({ 
  options, 
  value, 
  onChange, 
  placeholder, 
  className 
}: { 
  options: { value: string; label: string }[], 
  value: string, 
  onChange: (val: string) => void, 
  placeholder: string,
  className?: string
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => { if (!isOpen) setSearch(''); }, [isOpen]);

  const selectedLabel = options.find(o => o.value === value)?.label || '';
  const filteredOptions = options.filter(o => o.label.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="relative group" ref={wrapperRef}>
      <div 
        onClick={() => setIsOpen(!isOpen)} 
        className={`relative cursor-pointer flex items-center justify-between transition-all duration-200 ease-in-out ${className} ${!value ? 'text-slate-400' : 'text-slate-800 dark:text-white'} ${isOpen ? 'ring-2 ring-indigo-500/20 bg-white' : ''}`}
      >
        <span className="truncate block w-[90%] select-none">
           {selectedLabel || placeholder}
        </span>
        <ChevronDown size={16} className={`text-slate-400 shrink-0 transition-transform duration-300 ${isOpen ? 'rotate-180 text-indigo-500' : ''}`}/>
      </div>

      {isOpen && (
        <div className="absolute z-50 w-full bg-white dark:bg-slate-800 rounded-2xl mt-2 shadow-2xl shadow-slate-200/50 dark:shadow-black/50 max-h-60 overflow-y-auto custom-scrollbar animate-in fade-in zoom-in-95 duration-200 border border-slate-100 dark:border-slate-700">
          <div className="p-2 sticky top-0 bg-white/95 backdrop-blur dark:bg-slate-800/95 z-10 border-b border-slate-50 dark:border-slate-700">
            <div className="relative">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/>
                <input 
                    autoFocus
                    type="text" 
                    className="w-full bg-slate-100 dark:bg-slate-700/50 rounded-xl py-2 pl-9 pr-3 text-xs outline-none focus:ring-2 focus:ring-indigo-500/20 transition-all placeholder:text-slate-400"
                    placeholder="Cari..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />
            </div>
          </div>
          <div className="p-1.5 space-y-0.5">
            {filteredOptions.length > 0 ? filteredOptions.map(opt => (
                <div 
                    key={opt.value} 
                    onClick={() => { onChange(opt.value); setIsOpen(false); }}
                    className={`p-2.5 text-xs rounded-xl cursor-pointer transition-all flex justify-between items-center ${value === opt.value ? 'bg-indigo-50 text-indigo-700 font-bold dark:bg-indigo-900/40 dark:text-indigo-400' : 'hover:bg-slate-50 dark:hover:bg-slate-700/50 text-slate-600 dark:text-slate-300'}`}
                >
                    <span>{opt.label}</span>
                    {value === opt.value && <Check size={14} className="text-indigo-600 dark:text-indigo-400"/>}
                </div>
            )) : (
                <div className="p-8 text-center flex flex-col items-center justify-center text-slate-400 gap-2">
                    <Search size={24} className="opacity-20"/>
                    <span className="text-xs">Kosong</span>
                </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

