                           <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
                               <button onClick={()=>setProductViewMode('grid')} className={`p-1.5 rounded-md transition-all ${productViewMode==='grid' ? 'bg-white dark:bg-slate-600 shadow text-violet-600' : 'text-slate-400'}`}><LayoutGrid size={18}/></button>
                               <button onClick={()=>setProductViewMode('list')} className={`p-1.5 rounded-md transition-all ${productViewMode==='list' ? 'bg-white dark:bg-slate-600 shadow text-violet-600' : 'text-slate-400'}`}><List size={18}/></button>
                           </div>
                        </div>
                        <button onClick={()=>setShowDrawer('stock')} className="w-full sm:w-auto px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-lg text-sm flex items-center justify-center gap-2 transition-colors shadow-lg shadow-emerald-600/20">
                           <Download size={16}/> Stock In
                        </button>
                    </div>

                    {productViewMode === 'grid' ? (
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
