                                                <span className="bg-emerald-100 text-emerald-700 text-[10px] font-bold px-2 py-1 rounded-full border border-emerald-200">In Stock</span>
                                            ) : (
                                                <span className="bg-rose-100 text-rose-700 text-[10px] font-bold px-2 py-1 rounded-full border border-rose-200">Out of Stock</span>
