                                            <h4 className="font-bold text-slate-900 dark:text-white text-base mb-1 truncate" title={p.nama}>{p.nama}</h4>
                                            <p className="text-xs font-mono text-slate-400 bg-slate-100 dark:bg-slate-800 inline-block px-1.5 py-0.5 rounded">{p.kode}</p>
                                        </div>

                                        <div className="grid grid-cols-3 gap-2 mb-6">
                                            <div className="text-center p-2 rounded-lg bg-slate-50 dark:bg-slate-800/50">
                                                <span className="block text-[10px] text-slate-400 uppercase font-bold">Dim</span>
                                                <span className="text-xs font-semibold text-slate-700 dark:text-slate-300">{p.panjang}x{p.lebar}x{p.tinggi}</span>
                                            </div>
                                            <div className="text-center p-2 rounded-lg bg-slate-50 dark:bg-slate-800/50">
                                                <span className="block text-[10px] text-slate-400 uppercase font-bold">Wgt</span>
                                                <span className="text-xs font-semibold text-slate-700 dark:text-slate-300">{p.berat}kg</span>
                                            </div>
                                            <div className="text-center p-2 rounded-lg bg-slate-50 dark:bg-slate-800/50">
                                                <span className="block text-[10px] text-slate-400 uppercase font-bold">Unit</span>
                                                <span className="text-xs font-semibold text-slate-700 dark:text-slate-300">{p.satuan}</span>
                                            </div>
                                        </div>

                                        <div className="mt-auto pt-4 border-t border-slate-100 dark:border-slate-800 flex items-end justify-between">
