                                            </div>
                                            <div className="text-right">
                                                <p className="text-[10px] font-bold text-slate-400 uppercase mb-0.5">Stock</p>
                                                <p className="text-lg font-black text-slate-800 dark:text-white">{totalStock}</p>
                                            </div>
                                        </div>
                                     </div>
                                  </div>
