                                    <thead className="text-xs text-slate-500 uppercase bg-slate-50 dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700">
                                        <tr>
                                            <th className="px-6 py-4 font-semibold">Product Info</th>
                                            <th className="px-6 py-4 font-semibold">Dimensions</th>
                                            <th className="px-6 py-4 font-semibold">Unit</th>
                                            <th className="px-6 py-4 font-semibold text-right">Latest Price</th>
                                            <th className="px-6 py-4 font-semibold text-right">Total Stock</th>
                                            <th className="px-6 py-4 font-semibold text-center">Action</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                        {products.map(p => {
                                            const totalStock = p.lots.reduce((a,b)=>a+b.stock,0);
