                                                <tr key={p.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                                    <td className="px-6 py-4">
                                                        <div className="font-bold text-slate-900 dark:text-white">{p.nama}</div>
                                                        <div className="text-xs font-mono text-slate-400">{p.kode}</div>
                                                    </td>
                                                    <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{p.panjang}x{p.lebar}x{p.tinggi} <span className="text-slate-400">({p.berat}kg)</span></td>
                                                    <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{p.satuan}</td>
                                                    <td className="px-6 py-4 text-right font-bold text-violet-600">{price > 0 ? formatRupiah(price) : '-'}</td>
                                                    <td className="px-6 py-4 text-right">
                                                        <span className={`font-bold ${totalStock > 0 ? 'text-slate-800 dark:text-white' : 'text-rose-500'}`}>{totalStock}</span>
