                                                    <td className="px-6 py-4 text-center">
                                                        <button className="text-slate-400 hover:text-violet-600"><Edit3 size={16}/></button>
                                                    </td>
                                                </tr>
                                            )
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    )}
                 </div>
              )}

           </div>
        </div>
      </main>

