import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  LayoutDashboard, Users, Package, LineChart, FileEdit, ShieldCheck, 
  LogOut, Menu, X, Sun, Moon, Search, Plus, Phone, MessageSquare, 
  Send, Trash2, Edit3, ChevronDown, Check, AlertCircle, TrendingUp, Clock,
  Printer, History, Briefcase, ExternalLink, Calculator, Save, PlusCircle, Trash,
  Mail, FileText, Globe, UserCircle, RotateCcw, Download, Info, ArrowUpRight, ArrowDownRight, Activity,
  ChevronLeft, ChevronRight, Filter, MoreHorizontal, Wallet, ShoppingBag, Truck, LayoutGrid, List, Calendar as CalendarIcon
} from 'lucide-react';

// --- Interfaces ---
interface Supplier { id: string; nama: string; kode: string; npwp: string; }

interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product { 
  id: string; 
  nama: string; 
  kode: string; 
  lots: ProductLot[]; 
  panjang?: number; 
  lebar?: number;   
  tinggi?: number;  
  berat?: number;    
  satuan?: string;   
}

interface Customer {
  id: string; kode: string; nama: string; jenis: string; phone: string;
  email: string; alamat: string; sales: string; leadType: string;
  source: string; npwp: string; keterangan: string; negara: string;
}

interface TransactionItem {
  produkId: string; nama: string; sku: string; harga: number; qty: number; diskon: number;
}

interface Transaction {
  id: string; noTrx: string; tanggal: string; customerName: string;
  items: TransactionItem[]; nilaiProyek: number; ppn: boolean; ongkir: boolean;
  biayaOngkir: number; jasaKirim: string; status: 'Selesai' | 'Progress' | 'Batal';
  sales: string; keterangan: string;
}

type Panel = 'dashboard' | 'tracking' | 'customer' | 'produk';

// --- Constants ---
const COUNTRY_LIST = [
  { name: 'Indonesia', code: '62', flag: '🇮🇩' },
  { name: 'Malaysia', code: '60', flag: '🇲🇾' },
  { name: 'Singapore', code: '65', flag: '🇸🇬' },
  { name: 'Philippines', code: '63', flag: '🇵🇭' },
  { name: 'Thailand', code: '66', flag: '🇹🇭' },
  { name: 'Vietnam', code: '84', flag: '🇻🇳' },
  { name: 'Australia', code: '61', flag: '🇦🇺' },
  { name: 'United States', code: '1', flag: '🇺🇸' },
  { name: 'United Kingdom', code: '44', flag: '🇬🇧' },
  { name: 'Japan', code: '81', flag: '🇯🇵' },
  { name: 'China', code: '86', flag: '🇨🇳' },
];

const UNIT_LIST = ['Pcs', 'Unit', 'Set', 'Box', 'Kg', 'Mtr', 'Roll', 'Lembar', 'Pack', 'Kaleng'];

// --- Helpers & Custom Components ---

const generateProductCode = () => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  let result = '';
  for (let i = 0; i < 3; i++) result += chars.charAt(Math.floor(Math.random() * chars.length));
  return result;
};

const generateSupplierCode = () => {
  return Math.floor(10000 + Math.random() * 90000).toString();
};

const formatInputNumber = (val: number | string | undefined) => {
  if (val === undefined || val === null || val === '') return '';
  const num = typeof val === 'string' ? parseInt(val.replace(/\./g, '')) : val;
  if (isNaN(num)) return '';
  return new Intl.NumberFormat('id-ID').format(num);
};

const parseInputNumber = (val: string) => {
  return parseInt(val.replace(/\./g, '')) || 0;
};

// Component: Modern Clean Searchable Select
const SearchableSelect = ({ 
  options, 
  value, 
  onChange, 
  placeholder, 
  className 
}: { 
  options: { value: string; label: string }[], 
  value: string, 
  onChange: (val: string) => void, 
  placeholder: string,
  className?: string
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => { if (!isOpen) setSearch(''); }, [isOpen]);

  const selectedLabel = options.find(o => o.value === value)?.label || '';
  const filteredOptions = options.filter(o => o.label.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="relative group w-full" ref={wrapperRef}>
      <div 
        onClick={() => setIsOpen(!isOpen)} 
        className={`relative cursor-pointer flex items-center justify-between ${className} ${!value ? 'text-slate-400' : 'text-slate-900 dark:text-white'} ${isOpen ? 'border-violet-600 ring-1 ring-violet-600' : ''}`}
      >
        <span className="truncate block w-[90%] select-none text-sm">
           {selectedLabel || placeholder}
        </span>
        <ChevronDown size={14} className={`text-slate-400 shrink-0 transition-transform duration-200 ${isOpen ? 'rotate-180 text-violet-600' : ''}`}/>
      </div>

      {isOpen && (
        <div className="absolute z-50 w-full bg-white dark:bg-slate-800 rounded-lg mt-1 shadow-xl border border-slate-200 dark:border-slate-700 max-h-60 overflow-y-auto custom-scrollbar animate-in fade-in zoom-in-95 duration-150">
          <div className="p-2 sticky top-0 bg-white/95 backdrop-blur dark:bg-slate-800/95 z-10 border-b border-slate-100 dark:border-slate-700">
            <input 
                autoFocus
                type="text" 
                className="w-full bg-slate-50 dark:bg-slate-900 rounded-md py-1.5 px-3 text-xs outline-none border border-transparent focus:border-violet-500 transition-all placeholder:text-slate-400"
                placeholder="Type to search..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <div className="p-1">
            {filteredOptions.length > 0 ? filteredOptions.map(opt => (
                <div 
                    key={opt.value} 
                    onClick={() => { onChange(opt.value); setIsOpen(false); }}
                    className={`px-3 py-2 text-xs rounded-md cursor-pointer transition-all flex justify-between items-center ${value === opt.value ? 'bg-violet-50 text-violet-700 font-medium dark:bg-violet-900/30 dark:text-violet-300' : 'hover:bg-slate-50 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300'}`}
                >
                    <span>{opt.label}</span>
                    {value === opt.value && <Check size={12} className="text-violet-600"/>}
                </div>
            )) : (
                <div className="p-4 text-center text-slate-400 text-xs">No options found</div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

const StatCard = ({ title, value, icon, trend, color }: { title: string; value: string; icon: React.ReactNode; trend: string; color: string }) => {
  const colorClasses: Record<string, string> = {
    violet: "bg-violet-100 text-violet-600",
    blue: "bg-blue-100 text-blue-600",
    emerald: "bg-emerald-100 text-emerald-700",
    orange: "bg-orange-100 text-orange-600",
  };

  return (
    <div className="bg-white dark:bg-[#111827] rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm flex items-start justify-between">
      <div>
        <p className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-1">{title}</p>
        <h3 className="text-2xl font-black text-slate-800 dark:text-white">{value}</h3>
        <span className="text-xs font-medium text-emerald-600 flex items-center gap-1 mt-1">
          <TrendingUp size={12} /> {trend}
        </span>
      </div>
      <div className={`p-3 rounded-lg ${colorClasses[color] || 'bg-slate-100 text-slate-600'}`}>
        {icon}
      </div>
    </div>
  );
};

const StatusBadge = ({ status }: { status: string }) => {
  const styles: Record<string, string> = {
    'Selesai': 'bg-emerald-100 text-emerald-700 border-emerald-200',
    'Progress': 'bg-blue-100 text-blue-700 border-blue-200',
    'Batal': 'bg-rose-100 text-rose-700 border-rose-200',
  };
  return (
    <span className={`px-2.5 py-1 rounded-full text-xs font-bold border ${styles[status] || 'bg-slate-100 text-slate-600 border-slate-200'}`}>
      {status}
    </span>
  );
};

const App: React.FC = () => {
  const [activePanel, setActivePanel] = useState<Panel>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true); // Default open for desktop
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showDrawer, setShowDrawer] = useState<string | null>(null);
  const [productViewMode, setProductViewMode] = useState<'grid' | 'list'>('grid');

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel', negara: 'Indonesia', phone: '62'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({ satuan: 'Pcs' });
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [currentStock, setCurrentStock] = useState<Partial<ProductLot>>({ stock: 0, hpp: 0, hargaJual: 0 });

  // Persistence
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');
    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  const formatRupiah = (value: number) => {
    return new Intl.NumberFormat('id-ID', {
      style: 'currency',
      currency: 'IDR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(value);
  };

  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  // Logic Handlers
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data!");
    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`, nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowDrawer(null);
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowDrawer(null);
  };

  const saveProduct = () => {
    if (!currentProd.nama) return alert("Nama produk wajib diisi!");
    const kodeOtomatis = currentProd.kode || generateProductCode();
    const newProd = { 
        ...currentProd, 
        kode: kodeOtomatis,
        id: currentProd.id || Date.now().toString(), 
        lots: currentProd.lots || [] 
    } as Product;
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowDrawer(null);
  };

  const saveSupplier = () => {
      if(!currentSupp.nama) return alert("Nama supplier wajib diisi!");
      const kodeOtomatis = currentSupp.kode || generateSupplierCode();
      const newSupp = { ...currentSupp, kode: kodeOtomatis, id: currentSupp.id || Date.now().toString() } as Supplier;
      setSuppliers(p => currentSupp.id ? p.map(s => s.id === newSupp.id ? newSupp : s) : [...p, newSupp]);
      setCurrentSupp({});
  };

  const saveStockLot = () => {
