      setSuppliers(p => currentSupp.id ? p.map(s => s.id === newSupp.id ? newSupp : s) : [...p, newSupp]);
      setCurrentSupp({});
  };

  const getProductPrice = (p: Product) => {
    if (p.lots.length === 0) return 0;
    return p.lots[p.lots.length - 1].hargaJual;
  };

