    if (savedTrx) setTransactions(JSON.parse(savedTrx));
    if (savedCust) setCustomers(JSON.parse(savedCust));
    if (savedProd) setProducts(JSON.parse(savedProd));
    if (savedSupp) setSuppliers(JSON.parse(savedSupp));
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Derived Values
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const selectedCustomer = useMemo(() => customers.find(c => c.nama === currentTrx.customerName), [currentTrx.customerName, customers]);

  // Actions
  const handleNavClick = (module: string, view: string) => {
      setActiveModule(module);
      setActiveView(view);
      const newTabLabel = `#${view}`;
      if (!tabs.includes(newTabLabel)) setTabs([...tabs, newTabLabel]);
      setActiveTab(newTabLabel);
  };

  const handleSelectRow = (id: string) => {
      if (selectedIds.includes(id)) setSelectedIds(selectedIds.filter(i => i !== id));
      else setSelectedIds([...selectedIds, id]);
  };

  const handleSelectAll = (ids: string[]) => {
      if (selectedIds.length === ids.length) setSelectedIds([]);
      else setSelectedIds(ids);
  };

  const handleDeleteSelected = () => {
      if(activeView === 'Accounts') {
          setCustomers(prev => prev.filter(c => !selectedIds.includes(c.id)));
      } else if (activeView === 'Inventory') {
          setProducts(prev => prev.filter(p => !selectedIds.includes(p.id)));
      } else if (activeView === 'Orders') {
          setTransactions(prev => prev.filter(t => !selectedIds.includes(t.id)));
      }
      setSelectedIds([]);
  };

  // CRUD Save Functions
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data!");
    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || `TRX-${transactions.length + 1}`, nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowDrawer(null);
  };

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowDrawer(null);
  };

  const saveProduct = () => {
    if (!currentProd.nama) return alert("Nama produk wajib diisi!");
    const kodeOtomatis = currentProd.kode || generateProductCode();
    let newProd = { ...currentProd, kode: kodeOtomatis, id: currentProd.id || Date.now().toString(), lots: currentProd.lots || [] } as Product;

    if (tempStock.stock > 0 || (tempStock.hargaJual > 0 && newProd.lots.length === 0)) {
        if (!tempStock.supplierId && suppliers.length > 0) tempStock.supplierId = suppliers[0].id; 
        const supp = suppliers.find(s => s.id === tempStock.supplierId);
        const newSku = `${newProd.kode}-${supp?.kode || '000'}`;
        const newLot: ProductLot = { 
            lot: Date.now(), sku: newSku, supplierId: tempStock.supplierId || '', 
            stock: tempStock.stock || 0, hpp: tempStock.hpp || 0, hargaJual: tempStock.hargaJual || 0, 
            tanggal: new Date().toISOString() 
        };
        newProd.lots.push(newLot);
    }
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowDrawer(null);
    setTempStock({stock: 0, hpp: 0, hargaJual: 0, supplierId: ''});
  };

  const saveSupplier = () => {
      if(!currentSupp.nama) return alert("Nama supplier wajib diisi!");
      const kodeOtomatis = currentSupp.kode || generateSupplierCode();
      const newSupp = { ...currentSupp, kode: kodeOtomatis, id: currentSupp.id || Date.now().toString() } as Supplier;
      setSuppliers(p => currentSupp.id ? p.map(s => s.id === newSupp.id ? newSupp : s) : [...p, newSupp]);
      setCurrentSupp({});
      setShowDrawer(null); // Close drawer after saving supplier
  };

  const getProductPrice = (p: Product) => p.lots.length > 0 ? p.lots[p.lots.length - 1].hargaJual : 0;
  const getSupplierName = (p: Product) => {
      if (p.lots.length === 0) return 'No Supplier';
      const s = suppliers.find(sup => sup.id === p.lots[p.lots.length - 1].supplierId);
      return s ? s.nama : 'Unknown';
  }

  // Styles
  const inputClass = "w-full bg-white border border-slate-300 rounded-lg px-3 py-2 text-sm text-slate-900 outline-none focus:border-violet-600 focus:ring-1 focus:ring-violet-600 transition-all placeholder:text-slate-400";
  const labelClass = "block text-xs font-semibold text-slate-500 mb-1.5 uppercase tracking-wide";
  const thClass = "px-4 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200 bg-slate-50 select-none";
  const tdClass = "px-4 py-2.5 text-sm text-slate-700 border-b border-slate-100 whitespace-nowrap";

  return (
    <div className="h-screen w-screen flex flex-col bg-[#F5F5F5] overflow-hidden font-sans">

      {/* 1. Header Utama (Black) */}
      <header className="h-12 bg-[#333333] flex items-center justify-between px-4 shrink-0 shadow-md z-20">
         <div className="flex items-center gap-3">
             <div className="w-8 h-8 border-2 border-white flex items-center justify-center">
                 <span className="text-white font-bold text-xl leading-none font-serif">F</span>
             </div>
             <span className="text-white font-semibold text-lg tracking-tight">Factumsoft</span>
         </div>
         <div className="flex items-center gap-4 text-slate-300">
             <Bell size={18} className="hover:text-white cursor-pointer"/>
             <div className="flex items-center gap-2 hover:text-white cursor-pointer">
                 <div className="w-6 h-6 bg-slate-500 rounded-full flex items-center justify-center text-xs text-white">AH</div>
                 <span className="text-sm font-medium">armine.hayrapetyan</span>
                 <Settings size={16} />
             </div>
         </div>
      </header>

      {/* 2. Tab Navigation (White Bar) */}
      <div className="h-9 bg-white border-b border-slate-300 flex items-end px-2 gap-1 overflow-x-auto shrink-0 z-10">
          {tabs.map(tab => (
              <TopTab 
                key={tab} 
                label={tab} 
                active={activeTab === tab} 
                onClick={() => setActiveTab(tab)}
                onClose={tabs.length > 1 ? () => setTabs(tabs.filter(t => t !== tab)) : undefined}
              />
          ))}
          <button className="px-2 py-2 text-slate-400 hover:text-slate-600"><Plus size={16}/></button>
      </div>

      {/* 3. Main Body (Sidebar + Content) */}
      <div className="flex-1 flex overflow-hidden">

          {/* Sidebar */}
          <aside className="w-[220px] bg-[#F5F7F9] border-r border-slate-300 flex flex-col overflow-y-auto shrink-0 pb-10">

              <SidebarItem title="CRM" isHeader />
              <SidebarItem title="Accounts" active={activeView === 'Accounts'} onClick={() => handleNavClick('CRM', 'Accounts')} />
              <SidebarItem title="Contacts" />
              <SidebarItem title="Leads" />
              <SidebarItem title="Opportunities" />
              <SidebarItem title="Activities" />

              <SidebarItem title="Procurement" isHeader />
              <SidebarItem title="Inventory" active={activeView === 'Inventory'} onClick={() => handleNavClick('Procurement', 'Inventory')} />
              <SidebarItem title="Suppliers" active={activeView === 'Suppliers'} onClick={() => {setShowDrawer('supp');}}/>
              <SidebarItem title="Purchase Orders" />

              <SidebarItem title="Sales" isHeader />
              <SidebarItem title="Orders" active={activeView === 'Orders'} onClick={() => handleNavClick('Sales', 'Orders')} />
              <SidebarItem title="Invoices" />
              <SidebarItem title="Shipments" />

              <SidebarItem title="HR" isHeader />
              <SidebarItem title="Employees" />
              <SidebarItem title="Skills" />

              <SidebarItem title="Admin" isHeader />
              <SidebarItem title="Users" />
              <SidebarItem title="Settings" />
          </aside>

          {/* Content Area */}
          <main className="flex-1 flex flex-col bg-white min-w-0">

              {/* Context Header */}
              <div className="h-10 border-b border-slate-200 flex items-center px-4 bg-white shrink-0">
                  <span className="text-sm font-bold text-slate-700">{activeModule}:</span>
                  <span className="text-sm text-slate-500 ml-1">{activeView}</span>
              </div>

              {/* Filter Bar */}
              <div className="p-3 border-b border-slate-200 bg-[#FAFAFA] flex flex-wrap gap-3 items-center shrink-0">
                  <div className="relative">
                      <button className="absolute left-0 top-0 h-full px-2 bg-[#2C3E50] text-white rounded-l-sm"><ChevronDown size={14}/></button>
                      <input type="text" placeholder="Search..." className="pl-10 pr-3 py-1.5 text-sm border border-slate-300 rounded-sm w-64 outline-none focus:border-blue-500"/>
                      <Search size={14} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400"/>
                  </div>

                  <div className="flex items-center gap-2">
                      <span className="text-xs text-slate-500">Status</span>
                      <select className="text-sm border border-slate-300 rounded-sm py-1 px-2 outline-none bg-white">
                          <option>Select</option>
                          <option>Active</option>
                          <option>Inactive</option>
                      </select>
                  </div>

                  <div className="flex items-center gap-1 border border-slate-300 rounded-full px-2 py-0.5 bg-white">
                        <span className="text-xs text-slate-500">Department</span>
                        <div className="flex gap-1">
                            <span className="px-1.5 py-0.5 bg-slate-200 rounded-full text-[10px] flex items-center gap-1">HR <X size={10}/></span>
                            <span className="px-1.5 py-0.5 bg-slate-200 rounded-full text-[10px] flex items-center gap-1">Sales <X size={10}/></span>
                        </div>
                        <MoreVertical size={12} className="text-slate-400"/>
                  </div>

                  <div className="ml-auto flex items-center gap-2">
                      <div className="relative inline-block w-8 h-4 align-middle select-none transition duration-200 ease-in">
                        <input type="checkbox" name="toggle" id="toggle" className="toggle-checkbox absolute block w-4 h-4 rounded-full bg-white border-4 appearance-none cursor-pointer border-[#A91D3A]"/>
                        <label htmlFor="toggle" className="toggle-label block overflow-hidden h-4 rounded-full bg-slate-300 cursor-pointer"></label>
                      </div>
                      <span className="text-xs text-slate-600">My Accounts</span>
                  </div>
              </div>

              {/* Action Toolbar */}
              <div className="px-3 py-1.5 border-b border-slate-200 flex items-center gap-1 bg-white shrink-0">
                  <IconButton icon={Plus} tooltip="Add New" onClick={() => {
                      if(activeView === 'Accounts') { setCurrentCust({jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel', negara: 'Indonesia', phone: '62'}); setShowDrawer('cust'); }
                      else if(activeView === 'Inventory') { setCurrentProd({satuan:'Pcs'}); setTempStock({stock:0, hpp:0, hargaJual:0, supplierId:''}); setShowDrawer('prod'); }
                      else if(activeView === 'Orders') { setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: true, biayaOngkir: 0 }); setShowDrawer('trx'); }
                  }}/>
                  <IconButton icon={Edit3} tooltip="Edit Selected" onClick={() => {
                      if(selectedIds.length !== 1) return alert("Select exactly one item to edit");
                      const id = selectedIds[0];
                      if(activeView === 'Accounts') { const c = customers.find(x => x.id === id); if(c) { setCurrentCust(c); setShowDrawer('cust'); }}
                      else if(activeView === 'Inventory') { const p = products.find(x => x.id === id); if(p) { setCurrentProd(p); setShowDrawer('prod'); }} // Go to Edit Form
                      else if(activeView === 'Orders') { const t = transactions.find(x => x.id === id); if(t) { setCurrentTrx(t); setShowDrawer('trx'); }}
                  }}/>
                  <IconButton icon={Trash2} tooltip="Delete Selected" onClick={handleDeleteSelected} />
                  <IconButton icon={Eye} tooltip="View Details" onClick={() => {
                      if(selectedIds.length !== 1) return alert("Select exactly one item to view");
                      const id = selectedIds[0];
                      if(activeView === 'Inventory') { const p = products.find(x => x.id === id); if(p) { setCurrentProd(p); setShowDrawer('prodDetail'); }} // Go to Detail View
                  }}/>
                  <div className="w-px h-5 bg-slate-300 mx-1"></div>
                  <IconButton icon={RefreshCw} tooltip="Refresh" />
                  <IconButton icon={Download} tooltip="Export" />
                  <IconButton icon={Printer} tooltip="Print" />
              </div>

              {/* Data Table Area */}
              <div className="flex-1 overflow-auto bg-[#FAFAFA] p-4">
                  <div className="bg-white border border-slate-200 shadow-sm min-w-full inline-block align-middle">
                      <table className="min-w-full divide-y divide-slate-200">
                          <thead>
                              <tr>
                                  <th className={`${thClass} w-10 text-center`}>
                                      <input type="checkbox" className="rounded border-slate-300 text-[#A91D3A] focus:ring-[#A91D3A]" 
                                        onChange={(e) => {
                                            if(e.target.checked) {
                                                if(activeView==='Accounts') handleSelectAll(customers.map(c=>c.id));
                                                if(activeView==='Inventory') handleSelectAll(products.map(p=>p.id));
                                                if(activeView==='Orders') handleSelectAll(transactions.map(t=>t.id));
                                            } else {
                                                setSelectedIds([]);
                                            }
                                        }}
                                      />
                                  </th>
                                  {/* Dynamic Headers */}
                                  {activeView === 'Accounts' && (
                                      <>
                                          <th className={thClass}>Name</th>
                                          <th className={thClass}>Type</th>
                                          <th className={thClass}>Contact</th>
                                          <th className={thClass}>Sales Rep</th>
                                          <th className={thClass}>Status</th>
                                      </>
                                  )}
                                  {activeView === 'Inventory' && (
                                      <>
                                          <th className={thClass}>Product Name</th>
                                          <th className={thClass}>Code</th>
                                          <th className={thClass}>Stock</th>
                                          <th className={thClass}>Price</th>
                                          <th className={thClass}>Supplier</th>
                                      </>
                                  )}
                                  {activeView === 'Orders' && (
                                      <>
                                          <th className={thClass}>Invoice #</th>
                                          <th className={thClass}>Date</th>
                                          <th className={thClass}>Customer</th>
                                          <th className={thClass} align="right">Amount</th>
                                          <th className={thClass} align="center">Status</th>
                                      </>
                                  )}
                                  {/* Placeholder for empty views */}
                                  {!['Accounts','Inventory','Orders'].includes(activeView) && <th className={thClass}>Description</th>}
                              </tr>
                          </thead>
                          <tbody className="divide-y divide-slate-100">
                              {/* ACCOUNTS DATA */}
                              {activeView === 'Accounts' && customers.map((c, i) => (
                                  <tr key={c.id} className={`${i % 2 === 0 ? 'bg-white' : 'bg-[#F9FAFB]'} hover:bg-slate-50`}>
                                      <td className="px-4 py-2.5 text-center">
                                          <input type="checkbox" checked={selectedIds.includes(c.id)} onChange={()=>handleSelectRow(c.id)} className="rounded border-slate-300 text-[#A91D3A] focus:ring-[#A91D3A]"/>
                                      </td>
                                      <td className={tdClass}><span className="font-medium text-[#A91D3A] hover:underline cursor-pointer">{c.nama}</span></td>
                                      <td className={tdClass}>{c.jenis}</td>
                                      <td className={tdClass}>{c.phone}</td>
                                      <td className={tdClass}>{c.sales}</td>
                                      <td className={tdClass}><span className="px-2 py-0.5 rounded text-[10px] font-bold bg-green-100 text-green-700 uppercase">{c.leadType}</span></td>
                                  </tr>
                              ))}

                              {/* INVENTORY DATA */}
                              {activeView === 'Inventory' && products.map((p, i) => (
                                  <tr key={p.id} className={`${i % 2 === 0 ? 'bg-white' : 'bg-[#F9FAFB]'} hover:bg-slate-50`}>
                                      <td className="px-4 py-2.5 text-center">
                                          <input type="checkbox" checked={selectedIds.includes(p.id)} onChange={()=>handleSelectRow(p.id)} className="rounded border-slate-300 text-[#A91D3A] focus:ring-[#A91D3A]"/>
                                      </td>
                                      <td className={tdClass}>
                                          <div className="flex items-center gap-2">
                                              <div className="w-6 h-6 bg-slate-100 rounded flex items-center justify-center text-slate-500"><Box size={14}/></div>
                                              <span className="font-medium text-slate-700">{p.nama}</span>
                                          </div>
                                      </td>
                                      <td className={tdClass}><span className="font-mono text-xs">{p.kode}</span></td>
                                      <td className={tdClass}>{p.lots.reduce((a,b)=>a+b.stock,0)} {p.satuan}</td>
                                      <td className={tdClass}>{formatRupiah(getProductPrice(p))}</td>
                                      <td className={tdClass}>{getSupplierName(p)}</td>
                                  </tr>
                              ))}

                              {/* ORDERS DATA */}
                              {activeView === 'Orders' && transactions.map((t, i) => (
                                  <tr key={t.id} className={`${i % 2 === 0 ? 'bg-white' : 'bg-[#F9FAFB]'} hover:bg-slate-50`}>
                                      <td className="px-4 py-2.5 text-center">
                                          <input type="checkbox" checked={selectedIds.includes(t.id)} onChange={()=>handleSelectRow(t.id)} className="rounded border-slate-300 text-[#A91D3A] focus:ring-[#A91D3A]"/>
                                      </td>
                                      <td className={tdClass}><span className="font-medium text-[#A91D3A]">{t.noTrx}</span></td>
                                      <td className={tdClass}>{t.tanggal}</td>
                                      <td className={tdClass}>{t.customerName}</td>
                                      <td className={tdClass} align="right">{formatRupiah(t.nilaiProyek)}</td>
                                      <td className={tdClass} align="center">
                                          <span className={`px-2 py-0.5 rounded text-[10px] font-bold border 
                                            ${t.status==='Selesai' ? 'bg-green-50 text-green-700 border-green-200' : 
                                              t.status==='Progress' ? 'bg-blue-50 text-blue-700 border-blue-200' : 'bg-red-50 text-red-700 border-red-200'}`}>
                                              {t.status}
                                          </span>
                                      </td>
                                  </tr>
                              ))}

                              {/* EMPTY STATE */}
                              {((activeView === 'Accounts' && customers.length === 0) || 
                                (activeView === 'Inventory' && products.length === 0) ||
                                (activeView === 'Orders' && transactions.length === 0)) && (
                                  <tr>
                                      <td colSpan={10} className="px-4 py-10 text-center text-slate-400 text-sm">
                                          No records found in {activeView}.
                                      </td>
                                  </tr>
                              )}
                          </tbody>
                      </table>
                  </div>

                  {/* Pagination Footer */}
                  <div className="flex items-center justify-between mt-4 text-xs text-slate-500">
                        <span>1-{activeView === 'Accounts' ? customers.length : activeView === 'Inventory' ? products.length : transactions.length} of {activeView === 'Accounts' ? customers.length : activeView === 'Inventory' ? products.length : transactions.length} items</span>
                        <div className="flex items-center gap-2">
                            <button className="p-1 border border-slate-200 bg-white rounded hover:bg-slate-50"><ChevronLeft size={14}/></button>
                            <span className="px-2">10/page</span>
                            <button className="p-1 border border-slate-200 bg-white rounded hover:bg-slate-50"><ChevronRight size={14}/></button>
                        </div>
                  </div>
              </div>
          </main>
      </div>

      {/* --- DRAWERS (Retained from previous logic but styled to fit) --- */}
      {showDrawer && (
        <div className="fixed inset-0 z-[60] flex justify-end">
          <div className="absolute inset-0 bg-black/30 backdrop-blur-sm" onClick={() => setShowDrawer(null)} />
          <div className="relative w-full max-w-md bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">
            <div className="flex justify-between items-center p-4 border-b border-slate-200 bg-[#FAFAFA]">
              <h3 className="text-lg font-bold text-slate-800">
                {showDrawer === 'trx' ? 'Transaction' : 
                  showDrawer === 'cust' ? 'Customer' :
                  showDrawer === 'prod' ? 'Product & Stock' :
                  showDrawer === 'prodDetail' ? 'Product Detail' : 'Supplier'}
              </h3>
              <button onClick={() => setShowDrawer(null)} className="p-1 hover:bg-slate-200 rounded text-slate-500"><X size={20}/></button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-6">

              {/* --- PRODUCT DETAIL READ-ONLY --- */}
              {showDrawer === 'prodDetail' && (
                <div className="space-y-6">
                     <div className="bg-slate-50 rounded-lg p-5 border border-slate-200">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <h4 className="text-xl font-bold text-slate-900">{currentProd.nama}</h4>
                                <span className="font-mono text-xs text-slate-500">{currentProd.kode}</span>
                            </div>
                            <span className="px-2.5 py-1 rounded text-xs font-bold bg-[#A91D3A]/10 text-[#A91D3A]">{currentProd.satuan}</span>
                        </div>
                        <div className="grid grid-cols-3 gap-2 pt-2 border-t border-slate-200">
                            <div className="text-center p-2">
                                <div className="text-[10px] uppercase text-slate-400 font-bold mb-0.5">Dimensi</div>
                                <div className="text-sm font-semibold">{currentProd.panjang}x{currentProd.lebar}x{currentProd.tinggi}</div>
                            </div>
                            <div className="text-center p-2 border-l border-slate-200">
                                <div className="text-[10px] uppercase text-slate-400 font-bold mb-0.5">Berat</div>
                                <div className="text-sm font-semibold">{currentProd.berat} Kg</div>
                            </div>
                             <div className="text-center p-2 border-l border-slate-200">
                                <div className="text-[10px] uppercase text-slate-400 font-bold mb-0.5">Total Stok</div>
                                <div className="text-sm font-bold text-slate-900">{currentProd.lots?.reduce((a,b)=>a+b.stock,0) || 0}</div>
                            </div>
                        </div>
                     </div>
                     <div>
                        <h5 className="font-bold text-sm text-slate-800 mb-3 flex items-center gap-2"><Store size={16} className="text-slate-400"/> Stock Sources</h5>
                        <div className="space-y-3">
                            {currentProd.lots && currentProd.lots.length > 0 ? (
                                currentProd.lots.map((lot, idx) => (
                                    <div key={idx} className="p-4 border border-slate-100 rounded-lg flex justify-between items-center bg-white shadow-sm">
                                        <div>
                                            <div className="text-xs text-slate-500 mb-1">{formatDateShort(lot.tanggal)}</div>
                                            <div className="font-bold text-slate-800">{suppliers.find(s=>s.id===lot.supplierId)?.nama || 'Unknown'}</div>
                                            <div className="text-xs font-mono text-slate-400">{lot.sku}</div>
                                        </div>
                                        <div className="text-right">
                                            <div className="text-lg font-bold text-slate-900">{lot.stock}</div>
                                            <div className="text-xs text-[#A91D3A] font-semibold">{formatRupiah(lot.hargaJual)}</div>
                                        </div>
                                    </div>
                                ))
                            ) : <div className="text-slate-400 text-sm text-center py-4">No stock history</div>}
                        </div>
                     </div>
                </div>
              )}

              {/* --- PRODUCT EDIT FORM --- */}
