                      <div className="grid grid-cols-3 gap-3">
                         <div><label className={labelClass}>Qty</label><input className={`${inputClass} bg-white`} value={formatInputNumber(tempStock.stock)} onChange={e => setTempStock({...tempStock, stock: parseInputNumber(e.target.value)})} placeholder="0"/></div>
                         <div><label className={labelClass}>HPP</label><input className={`${inputClass} bg-white`} value={formatInputNumber(tempStock.hpp)} onChange={e => setTempStock({...tempStock, hpp: parseInputNumber(e.target.value)})} placeholder="0"/></div>
                         <div><label className={labelClass}>Price</label><input className={`${inputClass} bg-white font-bold text-[#A91D3A]`} value={formatInputNumber(tempStock.hargaJual)} onChange={e => setTempStock({...tempStock, hargaJual: parseInputNumber(e.target.value)})} placeholder="0"/></div>
                      </div>
                  </div>
                </>
              )}

              {/* --- CUSTOMER FORM --- */}
              {showDrawer === 'cust' && (
                <div className="space-y-4">
                    <div><label className={labelClass}>Name</label><input className={inputClass} value={currentCust.nama || ''} onChange={e => setCurrentCust({...currentCust, nama: e.target.value})} /></div>
                    <div className="grid grid-cols-2 gap-4">
                        <div><label className={labelClass}>Phone</label><input className={inputClass} value={currentCust.phone || ''} onChange={e => setCurrentCust({...currentCust, phone: e.target.value})} /></div>
                        <div><label className={labelClass}>Type</label><SearchableSelect options={['Perusahaan', 'Perorangan'].map(k => ({ value: k, label: k }))} value={currentCust.jenis || 'Perusahaan'} onChange={val => setCurrentCust({...currentCust, jenis: val})} placeholder="Type" /></div>
                    </div>
                </div>
              )}

               {/* --- SUPPLIER FORM --- */}
               {showDrawer === 'supp' && (
                <div className="space-y-4">
                    <div><label className={labelClass}>Supplier Name</label><input className={inputClass} value={currentSupp.nama || ''} onChange={e => setCurrentSupp({...currentSupp, nama: e.target.value})} /></div>
                    <div><label className={labelClass}>NPWP</label><input className={inputClass} value={currentSupp.npwp || ''} onChange={e => setCurrentSupp({...currentSupp, npwp: e.target.value})} /></div>
                </div>
              )}

              {/* --- TRANSACTION FORM --- */}
              {showDrawer === 'trx' && (
                <div className="space-y-4">
                    <div><label className={labelClass}>Customer</label><SearchableSelect options={customers.map(c => ({ value: c.nama, label: c.nama }))} value={currentTrx.customerName || ''} onChange={v => setCurrentTrx({...currentTrx, customerName: v})} placeholder="Select Customer" /></div>
                    <div className="border-t border-slate-200 pt-4">
                        <div className="flex justify-between mb-2"><label className={labelClass}>Items</label><button onClick={()=>setCurrentTrx(p=>({...p, items: [...(p.items||[]), { produkId: '', nama: '', sku: '', harga: 0, qty: 1, diskon: 0 }]}))} className="text-xs font-bold text-[#A91D3A]">+ Add Item</button></div>
                        {currentTrx.items?.map((item, idx) => (
                             <div key={idx} className="p-3 bg-slate-50 mb-2 rounded border border-slate-200 relative group">
                                <button onClick={()=>setCurrentTrx(p=>({...p, items: p.items?.filter((_,i)=>i!==idx)}))} className="absolute top-1 right-1 text-slate-400 hover:text-red-500"><X size={14}/></button>
                                <SearchableSelect options={products.map(p => ({ value: p.nama, label: p.nama }))} value={item.nama} onChange={(val) => { const prod = products.find(p => p.nama === val); const lot = prod?.lots[0]; const newI = [...(currentTrx.items||[])]; newI[idx] = { ...item, nama: val, produkId: prod?.id||'', sku: lot?.sku||'', harga: lot?.hargaJual||0 }; setCurrentTrx(p => ({...p, items: newI})); }} placeholder="Product" className="bg-white mb-2" />
                                <div className="grid grid-cols-3 gap-2">
                                    <input type="text" placeholder="Qty" value={item.qty} onChange={e => { const newI = [...(currentTrx.items||[])]; newI[idx] = { ...item, qty: parseInputNumber(e.target.value) }; setCurrentTrx(p => ({...p, items: newI})); }} className="w-full text-xs p-1.5 rounded border border-slate-200"/>
                                    <div className="text-xs font-bold pt-1.5 text-right col-span-2">{formatRupiah((item.qty*item.harga)-item.diskon)}</div>
                                </div>
                             </div>
                        ))}
                    </div>
                </div>
              )}

            </div>

            {showDrawer !== 'prodDetail' && (
                <div className="p-4 border-t border-slate-200 bg-[#FAFAFA]">
                    <button 
                        onClick={() => {
                            if(showDrawer==='prod') saveProduct();
                            else if(showDrawer==='trx') saveTransaction();
                            else if(showDrawer==='cust') saveCustomer();
                            else if(showDrawer==='supp') saveSupplier();
                        }} 
                        className="w-full bg-[#2C3E50] hover:bg-[#1a252f] text-white font-bold py-3 rounded-lg shadow-sm"
                    >
                        Save Record
                    </button>
                </div>
            )}
            {showDrawer === 'prodDetail' && (
                 <div className="p-4 border-t border-slate-200 bg-[#FAFAFA]">
                    <button onClick={() => setShowDrawer('prod')} className="w-full border border-slate-300 bg-white text-slate-700 font-bold py-3 rounded-lg hover:bg-slate-50">Edit Product</button>
                 </div>
            )}
          </div>
        </div>
      )}

    </div>
  );
};

