const SearchableSelect = ({ 
  options, 
  value, 
  onChange, 
  placeholder, 
  className 
}: { 
  options: { value: string; label: string }[], 
  value: string, 
  onChange: (val: string) => void, 
  placeholder: string,
  className?: string
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => { if (!isOpen) setSearch(''); }, [isOpen]);

  const selectedLabel = options.find(o => o.value === value)?.label || '';
  const filteredOptions = options.filter(o => o.label.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="relative group w-full" ref={wrapperRef}>
      <div 
        onClick={() => setIsOpen(!isOpen)} 
        className={`relative cursor-pointer flex items-center justify-between ${className} ${!value ? 'text-slate-400' : 'text-slate-900'} ${isOpen ? 'border-violet-600 ring-1 ring-violet-600' : ''}`}
      >
        <span className="truncate block w-[90%] select-none text-sm">
           {selectedLabel || placeholder}
        </span>
        <ChevronDown size={14} className={`text-slate-400 shrink-0 transition-transform duration-200 ${isOpen ? 'rotate-180 text-violet-600' : ''}`}/>
      </div>

      {isOpen && (
        <div className="absolute z-50 w-full bg-white rounded-lg mt-1 shadow-xl border border-slate-200 max-h-60 overflow-y-auto custom-scrollbar animate-in fade-in zoom-in-95 duration-150">
          <div className="p-2 sticky top-0 bg-white/95 backdrop-blur z-10 border-b border-slate-100">
            <input 
                autoFocus
                type="text" 
                className="w-full bg-slate-50 rounded-md py-1.5 px-3 text-xs outline-none border border-transparent focus:border-violet-500 transition-all placeholder:text-slate-400"
                placeholder="Type to search..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <div className="p-1">
            {filteredOptions.length > 0 ? filteredOptions.map(opt => (
                <div 
                    key={opt.value} 
                    onClick={() => { onChange(opt.value); setIsOpen(false); }}
                    className={`px-3 py-2 text-xs rounded-md cursor-pointer transition-all flex justify-between items-center ${value === opt.value ? 'bg-violet-50 text-violet-700 font-medium' : 'hover:bg-slate-50 text-slate-600'}`}
                >
                    <span>{opt.label}</span>
                    {value === opt.value && <Check size={12} className="text-violet-600"/>}
                </div>
            )) : (
                <div className="p-4 text-center text-slate-400 text-xs">No options found</div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

const TopTab = ({ label, active, onClick, onClose }: { label: string, active: boolean, onClick: () => void, onClose?: () => void }) => (
    <div 
        onClick={onClick}
        className={`
            relative px-4 py-2 min-w-[120px] text-xs font-semibold cursor-pointer border-r border-slate-200 flex items-center justify-between group
            ${active ? 'bg-white text-[#A91D3A] border-t-2 border-t-[#A91D3A]' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}
        `}
    >
        <span>{label}</span>
        {onClose && <X size={12} className="opacity-0 group-hover:opacity-100 hover:text-red-500 transition-opacity" onClick={(e) => { e.stopPropagation(); onClose(); }} />}
    </div>
);

const IconButton = ({ icon: Icon, onClick, tooltip, active }: { icon: any, onClick?: () => void, tooltip?: string, active?: boolean }) => (
    <button 
        onClick={onClick}
        title={tooltip}
        className={`p-1.5 rounded-md transition-all ${active ? 'bg-slate-200 text-[#A91D3A]' : 'text-slate-500 hover:bg-slate-100 hover:text-slate-800'}`}
    >
        <Icon size={16} strokeWidth={2} />
    </button>
);

const App: React.FC = () => {
  // Navigation State
  const [activeModule, setActiveModule] = useState('CRM');
  const [activeView, setActiveView] = useState('Dashboard'); 
  const [activeTab, setActiveTab] = useState('#Dashboard');
  const [tabs, setTabs] = useState(['#Dashboard']);
  const [openCategory, setOpenCategory] = useState<string>('CRM'); // For Accordion sidebar
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false); // Mobile toggle

  // App Logic State
  const [showDrawer, setShowDrawer] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: false, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel', negara: 'Indonesia', phone: '62'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({ satuan: 'Pcs' });
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [tempStock, setTempStock] = useState<{stock: number, hpp: number, hargaJual: number, supplierId: string}>({stock: 0, hpp: 0, hargaJual: 0, supplierId: ''});

  // Persistence & Dummy Data Injection
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');

    // Load data or inject dummy if empty
    if (savedTrx) setTransactions(JSON.parse(savedTrx)); else setTransactions(DUMMY_TRANSACTIONS);
    if (savedCust) setCustomers(JSON.parse(savedCust)); else setCustomers(DUMMY_CUSTOMERS);
    if (savedProd) setProducts(JSON.parse(savedProd)); else setProducts(DUMMY_PRODUCTS);
    if (savedSupp) setSuppliers(JSON.parse(savedSupp)); else setSuppliers(DUMMY_SUPPLIERS);
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Derived Values
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const stats = useMemo(() => {
      const totalOmzet = transactions.filter(t => t.status === 'Selesai').reduce((acc, t) => acc + t.nilaiProyek, 0);
      const activeTrx = transactions.filter(t => t.status === 'Progress' || t.status === 'Pengiriman').length;
      const totalCust = customers.length;
      const totalProd = products.length;
      return { totalOmzet, activeTrx, totalCust, totalProd };
  }, [transactions, customers, products]);

  // View Data
  const viewData = useMemo(() => {
      if (activeView === 'Contacts') return customers;
      if (activeView === 'Produk') return products;
      if (activeView === 'Pesanan Selesai') return transactions.filter(t => t.status === 'Selesai');
      if (activeView === 'Pengiriman') return transactions.filter(t => t.status === 'Pengiriman');
      if (['Transaksi', 'Invoice'].includes(activeView)) return transactions.filter(t => t.status !== 'Selesai' && t.status !== 'Pengiriman'); // Basic CRM flow: Transaksi -> Pengiriman -> Selesai
      if (activeView === 'Orders') return transactions;
      return [];
  }, [activeView, customers, products, transactions]);

  // Actions
  const handleNavClick = (module: string, view: string) => {
      setActiveModule(module);
      setActiveView(view);
      const newTabLabel = `#${view}`;
      if (!tabs.includes(newTabLabel)) setTabs([...tabs, newTabLabel]);
      setActiveTab(newTabLabel);
      setSelectedIds([]);
      setIsMobileMenuOpen(false); // Close sidebar on mobile
  };

  const handleDelete = (id: string) => {
      if(!confirm("Apakah anda yakin ingin menghapus data ini?")) return;

      if(activeView === 'Contacts') {
          setCustomers(prev => prev.filter(c => c.id !== id));
      } else if (activeView === 'Produk') {
          setProducts(prev => prev.filter(p => p.id !== id));
      } else if (['Transaksi', 'Invoice', 'Pesanan Selesai', 'Orders', 'Pengiriman'].includes(activeView)) {
          setTransactions(prev => prev.filter(t => t.id !== id));
      }
  };

  // Status Change Helpers
  const updateTransactionStatus = (id: string, newStatus: Transaction['status'], extraUpdates = {}) => {
      setTransactions(prev => prev.map(t => t.id === id ? { ...t, status: newStatus, ...extraUpdates } : t));
  };

  // CRUD Save Functions
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data transaksi!");
    if (!currentTrx.sales) return alert("Pilih Sales Rep!");

    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || generateInvoiceNumber(), nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowDrawer(null);
  };

  const saveResi = () => {
     if(!currentTrx.noResi) return alert("Masukkan Nomor Resi!");
     updateTransactionStatus(currentTrx.id!, 'Pengiriman', { noResi: currentTrx.noResi });
     setShowDrawer(null);
  }

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowDrawer(null);
  };

  const saveProduct = () => {
    if (!currentProd.nama) return alert("Nama produk wajib diisi!");
    const kodeOtomatis = currentProd.kode || generateProductCode();
    let newProd = { ...currentProd, kode: kodeOtomatis, id: currentProd.id || Date.now().toString(), lots: currentProd.lots || [] } as Product;

    if (tempStock.stock > 0 || (tempStock.hargaJual > 0 && newProd.lots.length === 0)) {
        if (!tempStock.supplierId && suppliers.length > 0) tempStock.supplierId = suppliers[0].id; 
        const supp = suppliers.find(s => s.id === tempStock.supplierId);
        const newSku = `${newProd.kode}-${supp?.kode || '000'}`;
        const newLot: ProductLot = { 
            lot: Date.now(), sku: newSku, supplierId: tempStock.supplierId || '', 
            stock: tempStock.stock || 0, hpp: tempStock.hpp || 0, hargaJual: tempStock.hargaJual || 0, 
            tanggal: new Date().toISOString() 
        };
        newProd.lots.push(newLot);
    }
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowDrawer(null);
    setTempStock({stock: 0, hpp: 0, hargaJual: 0, supplierId: ''});
  };

  const saveSupplier = () => {
      if(!currentSupp.nama) return alert("Nama supplier wajib diisi!");
      const newSupp = { ...currentSupp, kode: currentSupp.kode || generateSupplierCode(), id: currentSupp.id || Date.now().toString() } as Supplier;
      setSuppliers(p => currentSupp.id ? p.map(s => s.id === newSupp.id ? newSupp : s) : [...p, newSupp]);
      setCurrentSupp({});
      setShowDrawer(null); 
  };

  const getProductPrice = (p: Product) => p.lots.length > 0 ? p.lots[p.lots.length - 1].hargaJual : 0;
  const getSupplierName = (p: Product) => {
      if (p.lots.length === 0) return 'No Supplier';
      const s = suppliers.find(sup => sup.id === p.lots[p.lots.length - 1].supplierId);
      return s ? s.nama : 'Unknown';
  }

  // Styles
  const inputClass = "w-full bg-white border border-slate-300 rounded-lg px-3 py-2 text-sm text-slate-900 outline-none focus:border-violet-600 focus:ring-1 focus:ring-violet-600 transition-all placeholder:text-slate-400";
  const labelClass = "block text-xs font-semibold text-slate-500 mb-1.5 uppercase tracking-wide";
  const thClass = "px-4 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200 bg-slate-50 select-none";
  const tdClass = "px-4 py-2.5 text-sm text-slate-700 border-b border-slate-100 whitespace-nowrap";

  return (
    <div className="h-screen w-screen flex flex-col bg-[#F5F5F5] overflow-hidden font-sans">

      {/* 1. Header Utama (Black) */}
      <header className="h-12 bg-[#333333] flex items-center justify-between px-4 shrink-0 shadow-md z-20">
         <div className="flex items-center gap-3">
             <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden text-white"><Menu size={20}/></button>
             <div className="w-8 h-8 border-2 border-white flex items-center justify-center">
                 <span className="text-white font-bold text-xl leading-none font-serif">F</span>
             </div>
             <span className="text-white font-semibold text-lg tracking-tight">Factumsoft</span>
         </div>
         <div className="flex items-center gap-4 text-slate-300">
             <Bell size={18} className="hover:text-white cursor-pointer"/>
             <div className="flex items-center gap-2 hover:text-white cursor-pointer hidden md:flex">
                 <div className="w-6 h-6 bg-slate-500 rounded-full flex items-center justify-center text-xs text-white">AH</div>
                 <span className="text-sm font-medium">armine.hayrapetyan</span>
                 <Settings size={16} />
             </div>
         </div>
      </header>

      {/* 2. Tab Navigation (White Bar) */}
      <div className="h-9 bg-white border-b border-slate-300 flex items-end px-2 gap-1 overflow-x-auto shrink-0 z-10 scrollbar-hide">
          {tabs.map(tab => (
              <TopTab 
                key={tab} 
                label={tab} 
                active={activeTab === tab} 
                onClick={() => setActiveTab(tab)}
                onClose={tabs.length > 1 ? () => setTabs(tabs.filter(t => t !== tab)) : undefined}
              />
          ))}
          <button className="px-2 py-2 text-slate-400 hover:text-slate-600"><Plus size={16}/></button>
      </div>

      {/* 3. Main Body (Sidebar + Content) */}
      <div className="flex-1 flex overflow-hidden relative">

          {/* Mobile Overlay */}
          {isMobileMenuOpen && (
              <div 
                  className="absolute inset-0 bg-black/50 z-30 lg:hidden"
                  onClick={() => setIsMobileMenuOpen(false)}
              ></div>
          )}

          {/* Sidebar */}
          <aside className={`
            absolute top-0 left-0 bottom-0 w-[240px] bg-[#F5F7F9] border-r border-slate-300 flex flex-col overflow-y-auto z-40
            transform transition-transform duration-300 ease-in-out
            ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
            lg:translate-x-0 lg:static lg:shrink-0
          `}>
             <div className="flex justify-between items-center p-4 lg:hidden">
                 <span className="font-bold text-slate-700">Menu</span>
                 <button onClick={() => setIsMobileMenuOpen(false)}><X size={20}/></button>
             </div>

             {/* Accordion Menu */}
             {MENU_STRUCTURE.map((menu) => (
