               {showDrawer === 'supp' && (
                <div className="space-y-4">
                    <div><label className={labelClass}>Nama Supplier</label><input className={inputClass} value={currentSupp.nama || ''} onChange={e => setCurrentSupp({...currentSupp, nama: e.target.value})} /></div>
                    <div><label className={labelClass}>NPWP / ID Pajak</label><input className={inputClass} value={currentSupp.npwp || ''} onChange={e => setCurrentSupp({...currentSupp, npwp: e.target.value})} /></div>
                </div>
              )}

              {showDrawer === 'prodDetail' && (
                 /* Detail View Read Only */
                 <div className="space-y-6">
                     <div className="bg-slate-50 rounded-lg p-5 border border-slate-200">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <h4 className="text-xl font-bold text-slate-900">{currentProd.nama}</h4>
                                <span className="font-mono text-xs text-slate-500">{currentProd.kode}</span>
                            </div>
                            <span className="px-2.5 py-1 rounded text-xs font-bold bg-[#A91D3A]/10 text-[#A91D3A]">{currentProd.satuan}</span>
                        </div>
                        <div className="grid grid-cols-3 gap-2 pt-2 border-t border-slate-200">
                             <div className="text-center p-2"><div className="text-[10px] uppercase text-slate-400 font-bold mb-0.5">Total Stok</div><div className="text-sm font-bold text-slate-900">{currentProd.lots?.reduce((a,b)=>a+b.stock,0) || 0}</div></div>
                             <div className="text-center p-2 border-l"><div className="text-[10px] uppercase text-slate-400 font-bold mb-0.5">Berat</div><div className="text-sm font-semibold">{currentProd.berat} Kg</div></div>
                             <div className="text-center p-2 border-l"><div className="text-[10px] uppercase text-slate-400 font-bold mb-0.5">Harga Jual</div><div className="text-sm font-semibold">{formatRupiah(getProductPrice(currentProd as Product))}</div></div>
                        </div>
                     </div>
                     <div>
                        <h5 className="font-bold text-sm text-slate-800 mb-3 flex items-center gap-2"><Store size={16} className="text-slate-400"/> Riwayat Stok</h5>
                        <div className="space-y-3">
                            {currentProd.lots && currentProd.lots.length > 0 ? (
                                currentProd.lots.map((lot, idx) => (
                                    <div key={idx} className="p-4 border border-slate-100 rounded-lg flex justify-between items-center bg-white shadow-sm">
                                        <div>
                                            <div className="text-xs text-slate-500 mb-1">{formatDateShort(lot.tanggal)}</div>
                                            <div className="font-bold text-slate-800">{suppliers.find(s=>s.id===lot.supplierId)?.nama || 'Unknown'}</div>
                                        </div>
                                        <div className="text-right">
                                            <div className="text-lg font-bold text-slate-900">{lot.stock}</div>
                                            <div className="text-xs text-[#A91D3A] font-semibold">{formatRupiah(lot.hargaJual)}</div>
                                        </div>
                                    </div>
                                ))
                            ) : <div className="text-slate-400 text-sm text-center py-4">Belum ada riwayat stok</div>}
                        </div>
                     </div>
                </div>
              )}

            </div>

            {showDrawer !== 'prodDetail' && showDrawer !== 'custDetail' && (
                <div className="p-4 border-t border-slate-200 bg-[#FAFAFA]">
                    <button 
                        onClick={() => {
                            if(showDrawer==='prod') saveProduct();
                            else if(showDrawer==='trx') saveTransaction();
                            else if(showDrawer==='cust') saveCustomer();
                            else if(showDrawer==='supp') saveSupplier();
                            else if(showDrawer==='inputResi') saveResi();
                        }} 
                        className="w-full bg-[#2C3E50] hover:bg-[#1a252f] text-white font-bold py-3 rounded-lg shadow-sm"
                    >
                        Simpan Data
                    </button>
                </div>
            )}

            {(showDrawer === 'prodDetail' || showDrawer === 'custDetail') && (
                 <div className="p-4 border-t border-slate-200 bg-[#FAFAFA]">
                    <button onClick={() => setShowDrawer(showDrawer === 'prodDetail' ? 'prod' : 'cust')} className="w-full border border-slate-300 bg-white text-slate-700 font-bold py-3 rounded-lg hover:bg-slate-50">
                        {showDrawer === 'prodDetail' ? 'Edit Produk' : 'Edit Kontak'}
                    </button>
                 </div>
            )}
          </div>
        </div>
      )}

    </div>
  );
};

export default App;
// Helper for Date display in detail view
const formatDateShort = (dateStr: string) => {
    try { return new Date(dateStr).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: '2-digit' }); } 
    catch { return '-'; }
};
const handleSelectAll = (ids: string[]) => {}; // Helper dummy for TS safety in loop if needed, but inlined logic preferred

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Menu, X, Sun, Moon, Search, Plus, Trash2, Edit3, ChevronDown, Check, 
  TrendingUp, Calendar as CalendarIcon, Store, Tag, Box,
  Settings, User, Bell, ChevronLeft, ChevronRight, Filter, 
  Eye, RefreshCw, Download, Printer, MoreVertical, LayoutGrid, List,
  Wallet, Activity, Users, Package, FileText, CheckCircle, ChevronRight as ChevronRightIcon,
  Truck, Mail, MapPin, AlignLeft, Send
} from 'lucide-react';

// --- Interfaces ---
interface Supplier { id: string; nama: string; kode: string; npwp: string; }

interface ProductLot {
  lot: number;
  sku: string;
  supplierId: string;
  stock: number;
  hpp: number;
  hargaJual: number;
  tanggal: string;
}

interface Product { 
  id: string; 
  nama: string; 
  kode: string; 
  lots: ProductLot[]; 
  panjang?: number; 
  lebar?: number;   
  tinggi?: number;  
  berat?: number;    
  satuan?: string;   
}

interface Customer {
  id: string; kode: string; nama: string; jenis: string; phone: string;
  email: string; alamat: string; sales: string; leadType: string;
  source: string; npwp: string; keterangan: string; negara: string;
}

interface TransactionItem {
  produkId: string; nama: string; sku: string; harga: number; qty: number; diskon: number;
}

interface Transaction {
  id: string; noTrx: string; tanggal: string; customerName: string;
  items: TransactionItem[]; nilaiProyek: number; ppn: boolean; ongkir: boolean;
  biayaOngkir: number; jasaKirim: string; noResi?: string; 
  status: 'Selesai' | 'Progress' | 'Batal' | 'Pengiriman';
  sales: string; keterangan: string;
}

// --- Constants & Dummy Data ---
const UNIT_LIST = ['Pcs', 'Unit', 'Set', 'Box', 'Kg', 'Mtr', 'Roll', 'Lembar', 'Pack', 'Kaleng', 'Liter', 'Galon'];
const SHIPPING_SERVICES = ['JNE Regular', 'J&T Express', 'SiCepat Halu', 'SiCepat Gokil', 'AnterAja', 'GoSend Instant', 'GrabExpress', 'Kurir Internal', 'Ambil Sendiri'];
const SALES_TEAM = ['Angel', 'Budi', 'Chandra', 'Dewi', 'Eko'];

