const SearchableSelect = ({ 
  options, 
  value, 
  onChange, 
  placeholder, 
  className 
}: { 
  options: { value: string; label: string }[], 
  value: string, 
  onChange: (val: string) => void, 
  placeholder: string,
  className?: string
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => { if (!isOpen) setSearch(''); }, [isOpen]);

  const selectedLabel = options.find(o => o.value === value)?.label || '';
  const filteredOptions = options.filter(o => o.label.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="relative group w-full" ref={wrapperRef}>
      <div 
        onClick={() => setIsOpen(!isOpen)} 
        className={`relative cursor-pointer flex items-center justify-between ${className} ${!value ? 'text-slate-400' : 'text-slate-900'} ${isOpen ? 'border-violet-600 ring-1 ring-violet-600' : ''}`}
      >
        <span className="truncate block w-[90%] select-none text-sm">
           {selectedLabel || placeholder}
        </span>
        <ChevronDown size={14} className={`text-slate-400 shrink-0 transition-transform duration-200 ${isOpen ? 'rotate-180 text-violet-600' : ''}`}/>
      </div>

      {isOpen && (
        <div className="absolute z-50 w-full bg-white rounded-lg mt-1 shadow-xl border border-slate-200 max-h-60 overflow-y-auto custom-scrollbar animate-in fade-in zoom-in-95 duration-150">
          <div className="p-2 sticky top-0 bg-white/95 backdrop-blur z-10 border-b border-slate-100">
            <input 
                autoFocus
                type="text" 
                className="w-full bg-slate-50 rounded-md py-1.5 px-3 text-xs outline-none border border-transparent focus:border-violet-500 transition-all placeholder:text-slate-400"
                placeholder="Type to search..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <div className="p-1">
            {filteredOptions.length > 0 ? filteredOptions.map(opt => (
                <div 
                    key={opt.value} 
                    onClick={() => { onChange(opt.value); setIsOpen(false); }}
                    className={`px-3 py-2 text-xs rounded-md cursor-pointer transition-all flex justify-between items-center ${value === opt.value ? 'bg-violet-50 text-violet-700 font-medium' : 'hover:bg-slate-50 text-slate-600'}`}
                >
                    <span>{opt.label}</span>
                    {value === opt.value && <Check size={12} className="text-violet-600"/>}
                </div>
            )) : (
                <div className="p-4 text-center text-slate-400 text-xs">No options found</div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

const TopTab = ({ label, active, onClick, onClose }: { label: string, active: boolean, onClick: () => void, onClose?: () => void }) => (
    <div 
        onClick={onClick}
        className={`
            relative px-4 py-2 min-w-[120px] text-xs font-semibold cursor-pointer border-r border-slate-200 flex items-center justify-between group
            ${active ? 'bg-white text-[#A91D3A] border-t-2 border-t-[#A91D3A]' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}
        `}
    >
        <span>{label}</span>
        {onClose && <X size={12} className="opacity-0 group-hover:opacity-100 hover:text-red-500 transition-opacity" onClick={(e) => { e.stopPropagation(); onClose(); }} />}
    </div>
);

