                            onClick={() => setIsCardView(!isCardView)} 
                            className={`p-2 rounded md:hidden ${isCardView ? 'bg-slate-200 text-slate-800' : 'text-slate-400'}`}
                            title="Toggle View"
                         >
                            {isCardView ? <List size={18}/> : <LayoutGrid size={18}/>}
                         </button>

                         <button 
                            onClick={() => {
                                if(activeView === 'Contacts') { setCurrentCust({jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel', negara: 'Indonesia', phone: '62'}); setShowDrawer('cust'); }
                                else if(activeView === 'Produk') { setCurrentProd({satuan:'Pcs'}); setTempStock({stock:0, hpp:0, hargaJual:0, supplierId:''}); setShowDrawer('prod'); }
                                else if(['Transaksi', 'Invoice', 'Pesanan Selesai'].includes(activeView)) { setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: false, biayaOngkir: 0, sales: 'Angel', jasaKirim: 'JNE Regular' }); setShowDrawer('trx'); }
                            }}
                            className="bg-[#2C3E50] hover:bg-[#1a252f] text-white text-xs font-bold px-4 py-2 rounded-lg flex items-center gap-2 transition-colors shadow-sm"
                        >
                            <Plus size={14} />
                            <span className="hidden md:inline">Tambah {activeView === 'Contacts' ? 'Kontak' : activeView === 'Produk' ? 'Produk' : 'Data'}</span>
                            <span className="md:hidden">Add</span>
                        </button>
                    </div>
                </div>
              )}

              {/* Main Content Area: Dashboard or Table */}
              <div className="flex-1 overflow-auto bg-[#FAFAFA] p-4">
