  // Navigation State
  const [activeModule, setActiveModule] = useState('CRM');
  const [activeView, setActiveView] = useState('Dashboard'); 
  const [activeTab, setActiveTab] = useState('#Dashboard');
  const [tabs, setTabs] = useState(['#Dashboard']);
  const [openCategory, setOpenCategory] = useState<string>('CRM'); 
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isCardView, setIsCardView] = useState(false); // Toggle for mobile card view

  // App Logic State
  const [showDrawer, setShowDrawer] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  // Data States
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Form States
  const [currentTrx, setCurrentTrx] = useState<Partial<Transaction>>({ 
    items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: false, biayaOngkir: 0 
  });
  const [currentCust, setCurrentCust] = useState<Partial<Customer>>({
    jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel', negara: 'Indonesia', phone: '62'
  });
  const [currentProd, setCurrentProd] = useState<Partial<Product>>({ satuan: 'Pcs' });
  const [currentSupp, setCurrentSupp] = useState<Partial<Supplier>>({});
  const [tempStock, setTempStock] = useState<{stock: number, hpp: number, hargaJual: number, supplierId: string}>({stock: 0, hpp: 0, hargaJual: 0, supplierId: ''});

  // Persistence & Dummy Data Injection
  useEffect(() => {
    const savedTrx = localStorage.getItem('mypanca_db_trx');
    const savedCust = localStorage.getItem('mypanca_db_cust');
    const savedProd = localStorage.getItem('mypanca_db_prod');
    const savedSupp = localStorage.getItem('mypanca_db_supp');

    // Load data or inject dummy if empty
    if (savedTrx) setTransactions(JSON.parse(savedTrx)); else setTransactions(DUMMY_TRANSACTIONS);
    if (savedCust) setCustomers(JSON.parse(savedCust)); else setCustomers(DUMMY_CUSTOMERS);
    if (savedProd) setProducts(JSON.parse(savedProd)); else setProducts(DUMMY_PRODUCTS);
    if (savedSupp) setSuppliers(JSON.parse(savedSupp)); else setSuppliers(DUMMY_SUPPLIERS);

    // Auto detect mobile to switch to card view initially
    if (window.innerWidth < 768) setIsCardView(true);
  }, []);

  useEffect(() => {
    localStorage.setItem('mypanca_db_trx', JSON.stringify(transactions));
    localStorage.setItem('mypanca_db_cust', JSON.stringify(customers));
    localStorage.setItem('mypanca_db_prod', JSON.stringify(products));
    localStorage.setItem('mypanca_db_supp', JSON.stringify(suppliers));
  }, [transactions, customers, products, suppliers]);

  // Derived Values
  const trxCalculations = useMemo(() => {
    const itemsSubtotal = currentTrx.items?.reduce((acc, i) => acc + ((i.harga || 0) * (i.qty || 0) - (i.diskon || 0)), 0) || 0;
    const ppnAmount = currentTrx.ppn ? itemsSubtotal * 0.11 : 0;
    const shippingAmount = currentTrx.ongkir ? (Number(currentTrx.biayaOngkir) || 0) : 0;
    return { itemsSubtotal, ppnAmount, shippingAmount, grandTotal: itemsSubtotal + ppnAmount + shippingAmount };
  }, [currentTrx.items, currentTrx.ppn, currentTrx.ongkir, currentTrx.biayaOngkir]);

  const stats = useMemo(() => {
      const totalOmzet = transactions.filter(t => t.status === 'Selesai').reduce((acc, t) => acc + t.nilaiProyek, 0);
      const activeTrx = transactions.filter(t => t.status === 'Progress' || t.status === 'Pengiriman' || t.status === 'Payment').length;
      const totalCust = customers.length;
      const totalProd = products.length;
      return { totalOmzet, activeTrx, totalCust, totalProd };
  }, [transactions, customers, products]);

  // View Data
  const viewData = useMemo(() => {
      if (activeView === 'Contacts') return customers;
      if (activeView === 'Produk') return products;
      if (activeView === 'Pesanan Selesai') return transactions.filter(t => t.status === 'Selesai');
      if (activeView === 'Pesanan Batal') return transactions.filter(t => t.status === 'Batal');
      if (activeView === 'Pengiriman') return transactions.filter(t => t.status === 'Pengiriman');
      if (activeView === 'Invoice') return transactions.filter(t => t.status === 'Payment');
      if (activeView === 'Transaksi') return transactions.filter(t => t.status === 'Progress');
      if (activeView === 'Orders') return transactions;
      return [];
  }, [activeView, customers, products, transactions]);

  // Actions
  const handleNavClick = (module: string, view: string) => {
      setActiveModule(module);
      setActiveView(view);
      const newTabLabel = `#${view}`;
      if (!tabs.includes(newTabLabel)) setTabs([...tabs, newTabLabel]);
      setActiveTab(newTabLabel);
      setSelectedIds([]);
      setIsMobileMenuOpen(false); // Close sidebar on mobile
  };

  const handleDelete = (id: string) => {
      if(!confirm("Apakah anda yakin ingin menghapus data ini?")) return;

      if(activeView === 'Contacts') {
          setCustomers(prev => prev.filter(c => c.id !== id));
      } else if (activeView === 'Produk') {
          setProducts(prev => prev.filter(p => p.id !== id));
      } else if (['Transaksi', 'Invoice', 'Pesanan Selesai', 'Orders', 'Pengiriman', 'Pesanan Batal'].includes(activeView)) {
          setTransactions(prev => prev.filter(t => t.id !== id));
      }
  };

  // Status Change Helpers
  const updateTransactionStatus = (id: string, newStatus: Transaction['status'], extraUpdates = {}) => {
      setTransactions(prev => prev.map(t => t.id === id ? { ...t, status: newStatus, ...extraUpdates } : t));
  };

  const handlePrintInvoice = (t: Transaction) => {
      // 1. Change Status to Payment
      const updatedStatus = t.status === 'Progress' ? 'Payment' : t.status;
      updateTransactionStatus(t.id, updatedStatus);

      // 2. Set Active View to Invoice (user asked to move transaction to invoice menu)
      if (t.status === 'Progress') setActiveView('Invoice');

      // 3. Open Print Drawer
      setCurrentTrx(t);
      setShowDrawer('printInvoice');
  };

  const handlePaymentComplete = (t: Transaction) => {
      updateTransactionStatus(t.id, 'Pengiriman');
      setActiveView('Pengiriman');
  };

  // CRUD Save Functions
  const saveTransaction = () => {
    if (!currentTrx.customerName || !currentTrx.items?.length) return alert("Lengkapi data transaksi!");
    if (!currentTrx.sales) return alert("Pilih Sales Rep!");

    const newTrx = { ...currentTrx, id: currentTrx.id || Date.now().toString(), noTrx: currentTrx.noTrx || generateInvoiceNumber(), nilaiProyek: trxCalculations.grandTotal } as Transaction;
    setTransactions(prev => currentTrx.id ? prev.map(t => t.id === newTrx.id ? newTrx : t) : [newTrx, ...prev]);
    setShowDrawer(null);
  };

  const saveResi = () => {
     if(!currentTrx.noResi) return alert("Masukkan Nomor Resi!");
     updateTransactionStatus(currentTrx.id!, 'Pengiriman', { noResi: currentTrx.noResi });
     setShowDrawer(null);
  }

  const saveCustomer = () => {
    if (!currentCust.nama) return alert("Nama wajib diisi!");
    const newCust = { ...currentCust, id: currentCust.id || Date.now().toString(), kode: currentCust.kode || `CUST-${customers.length + 1}` } as Customer;
    setCustomers(prev => currentCust.id ? prev.map(c => c.id === newCust.id ? newCust : c) : [...prev, newCust]);
    setShowDrawer(null);
  };

  const saveProduct = () => {
    if (!currentProd.nama) return alert("Nama produk wajib diisi!");
    const kodeOtomatis = currentProd.kode || generateProductCode();
    let newProd = { ...currentProd, kode: kodeOtomatis, id: currentProd.id || Date.now().toString(), lots: currentProd.lots || [] } as Product;

    if (tempStock.stock > 0 || (tempStock.hargaJual > 0 && newProd.lots.length === 0)) {
        if (!tempStock.supplierId && suppliers.length > 0) tempStock.supplierId = suppliers[0].id; 
        const supp = suppliers.find(s => s.id === tempStock.supplierId);
        const newSku = `${newProd.kode}-${supp?.kode || '000'}`;
        const newLot: ProductLot = { 
            lot: Date.now(), sku: newSku, supplierId: tempStock.supplierId || '', 
            stock: tempStock.stock || 0, hpp: tempStock.hpp || 0, hargaJual: tempStock.hargaJual || 0, 
            tanggal: new Date().toISOString() 
        };
        newProd.lots.push(newLot);
    }
    setProducts(prev => currentProd.id ? prev.map(p => p.id === newProd.id ? newProd : p) : [...prev, newProd]);
    setShowDrawer(null);
    setTempStock({stock: 0, hpp: 0, hargaJual: 0, supplierId: ''});
  };

  const saveSupplier = () => {
      if(!currentSupp.nama) return alert("Nama supplier wajib diisi!");
      const newSupp = { ...currentSupp, kode: currentSupp.kode || generateSupplierCode(), id: currentSupp.id || Date.now().toString() } as Supplier;
      setSuppliers(p => currentSupp.id ? p.map(s => s.id === newSupp.id ? newSupp : s) : [...p, newSupp]);
      setCurrentSupp({});
      setShowDrawer(null); 
  };

  const getProductPrice = (p: Product) => p.lots.length > 0 ? p.lots[p.lots.length - 1].hargaJual : 0;
  const getSupplierName = (p: Product) => {
      if (p.lots.length === 0) return 'No Supplier';
      const s = suppliers.find(sup => sup.id === p.lots[p.lots.length - 1].supplierId);
      return s ? s.nama : 'Unknown';
  }

  // Styles
  const inputClass = "w-full bg-white border border-slate-300 rounded-lg px-3 py-2 text-sm text-slate-900 outline-none focus:border-violet-600 focus:ring-1 focus:ring-violet-600 transition-all placeholder:text-slate-400";
  const labelClass = "block text-xs font-semibold text-slate-500 mb-1.5 uppercase tracking-wide";
  const thClass = "px-4 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200 bg-slate-50 select-none whitespace-nowrap";
  const tdClass = "px-4 py-2.5 text-sm text-slate-700 border-b border-slate-100 whitespace-nowrap";

  return (
    <div className="h-screen w-screen flex flex-col bg-[#F5F5F5] overflow-hidden font-sans">

      {/* 1. Header Utama (Black) */}
      <header className="h-12 bg-[#333333] flex items-center justify-between px-4 shrink-0 shadow-md z-20">
         <div className="flex items-center gap-3">
             <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden text-white"><Menu size={20}/></button>
             <div className="w-8 h-8 border-2 border-white flex items-center justify-center">
                 <span className="text-white font-bold text-xl leading-none font-serif">F</span>
             </div>
             <span className="text-white font-semibold text-lg tracking-tight">Factumsoft</span>
         </div>
         <div className="flex items-center gap-4 text-slate-300">
             <Bell size={18} className="hover:text-white cursor-pointer"/>
             <div className="flex items-center gap-2 hover:text-white cursor-pointer hidden md:flex">
                 <div className="w-6 h-6 bg-slate-500 rounded-full flex items-center justify-center text-xs text-white">AH</div>
                 <span className="text-sm font-medium">armine.hayrapetyan</span>
                 <Settings size={16} />
             </div>
         </div>
      </header>

      {/* 2. Tab Navigation (White Bar) */}
      <div className="h-9 bg-white border-b border-slate-300 flex items-end px-2 gap-1 overflow-x-auto shrink-0 z-10 scrollbar-hide">
          {tabs.map(tab => (
              <TopTab 
                key={tab} 
                label={tab} 
                active={activeTab === tab} 
                onClick={() => setActiveTab(tab)}
                onClose={tabs.length > 1 ? () => setTabs(tabs.filter(t => t !== tab)) : undefined}
              />
          ))}
          <button className="px-2 py-2 text-slate-400 hover:text-slate-600"><Plus size={16}/></button>
      </div>

      {/* 3. Main Body (Sidebar + Content) */}
      <div className="flex-1 flex overflow-hidden relative">

          {/* Mobile Overlay */}
          {isMobileMenuOpen && (
              <div 
                  className="absolute inset-0 bg-black/50 z-30 lg:hidden"
                  onClick={() => setIsMobileMenuOpen(false)}
              ></div>
          )}

          {/* Sidebar */}
          <aside className={`
            absolute top-0 left-0 bottom-0 w-[240px] bg-[#F5F7F9] border-r border-slate-300 flex flex-col overflow-y-auto z-40
            transform transition-transform duration-300 ease-in-out
            ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
            lg:translate-x-0 lg:static lg:shrink-0
          `}>
             <div className="flex justify-between items-center p-4 lg:hidden">
                 <span className="font-bold text-slate-700">Menu</span>
                 <button onClick={() => setIsMobileMenuOpen(false)}><X size={20}/></button>
             </div>

             {/* Accordion Menu */}
             {MENU_STRUCTURE.map((menu) => (
                 <div key={menu.category} className="border-b border-slate-200 lg:border-none">
                     <div 
                        onClick={() => setOpenCategory(openCategory === menu.category ? '' : menu.category)}
                        className="px-4 py-3 flex items-center justify-between cursor-pointer hover:bg-slate-100 group"
                     >
                         <span className="text-xs font-bold text-slate-800 uppercase tracking-wide">{menu.category}</span>
                         <ChevronRightIcon 
                            size={14} 
                            className={`text-slate-400 transition-transform duration-200 ${openCategory === menu.category ? 'rotate-90' : ''}`}
                        />
                     </div>
                     {/* Sub Menu Items */}
                     <div className={`overflow-hidden transition-all duration-200 ${openCategory === menu.category ? 'max-h-96' : 'max-h-0'}`}>
                         {menu.items.map((item) => (
                             <div 
                                key={item.id}
                                onClick={() => {
                                    if(item.isDrawer) setShowDrawer('supp');
                                    else handleNavClick(menu.category, item.id);
                                }}
                                className={`
                                    pl-8 pr-4 py-2 text-[13px] cursor-pointer border-l-4 border-transparent flex items-center justify-between
                                    ${activeView === item.id 
                                        ? 'bg-white text-slate-900 font-medium border-l-[#A91D3A]' 
                                        : 'text-slate-600 hover:bg-slate-100 hover:text-slate-900'}
                                `}
                             >
                                 {item.label}
                             </div>
                         ))}
                     </div>
                 </div>
             ))}
          </aside>

          {/* Content Area */}
          <main className="flex-1 flex flex-col bg-white min-w-0">

              {/* Context Header */}
              <div className="h-10 border-b border-slate-200 flex items-center px-4 bg-white shrink-0">
                  <span className="text-sm font-bold text-slate-700">{activeModule}:</span>
                  <span className="text-sm text-slate-500 ml-1">{activeView}</span>
              </div>

              {/* Filter Bar (Hidden for Dashboard) */}
              {activeView !== 'Dashboard' && (
                <div className="p-3 border-b border-slate-200 bg-[#FAFAFA] flex flex-wrap gap-3 items-center shrink-0">
                    <div className="relative w-full md:w-auto">
                        <button className="absolute left-0 top-0 h-full px-2 bg-[#2C3E50] text-white rounded-l-sm"><ChevronDown size={14}/></button>
                        <input type="text" placeholder="Search..." className="pl-10 pr-3 py-1.5 text-sm border border-slate-300 rounded-sm w-full md:w-64 outline-none focus:border-blue-500"/>
                        <Search size={14} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400"/>
                    </div>

                    <div className="flex items-center gap-2 hidden md:flex">
                        <span className="text-xs text-slate-500">Status</span>
                        <select className="text-sm border border-slate-300 rounded-sm py-1 px-2 outline-none bg-white">
                            <option>Select</option>
                            <option>Active</option>
                            <option>Inactive</option>
                        </select>
                    </div>

                    <div className="ml-auto flex items-center gap-2">
                        {/* Mobile Toggle Grid/List */}
                         <button 
                            onClick={() => setIsCardView(!isCardView)} 
                            className={`p-2 rounded md:hidden ${isCardView ? 'bg-slate-200 text-slate-800' : 'text-slate-400'}`}
                            title="Toggle View"
                         >
                            {isCardView ? <List size={18}/> : <LayoutGrid size={18}/>}
                         </button>

                         <button 
                            onClick={() => {
                                if(activeView === 'Contacts') { setCurrentCust({jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel', negara: 'Indonesia', phone: '62'}); setShowDrawer('cust'); }
                                else if(activeView === 'Produk') { setCurrentProd({satuan:'Pcs'}); setTempStock({stock:0, hpp:0, hargaJual:0, supplierId:''}); setShowDrawer('prod'); }
                                else if(['Transaksi', 'Invoice', 'Pesanan Selesai'].includes(activeView)) { setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: false, biayaOngkir: 0, sales: 'Angel', jasaKirim: 'JNE Regular' }); setShowDrawer('trx'); }
                            }}
                            className="bg-[#2C3E50] hover:bg-[#1a252f] text-white text-xs font-bold px-4 py-2 rounded-lg flex items-center gap-2 transition-colors shadow-sm"
                        >
                            <Plus size={14} />
                            <span className="hidden md:inline">Tambah {activeView === 'Contacts' ? 'Kontak' : activeView === 'Produk' ? 'Produk' : 'Data'}</span>
                            <span className="md:hidden">Add</span>
                        </button>
                    </div>
                </div>
              )}

              {/* Main Content Area: Dashboard or Table */}
              <div className="flex-1 overflow-auto bg-[#FAFAFA] p-4">
                  {/* DASHBOARD VIEW */}
                  {activeView === 'Dashboard' ? (
                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                        <StatCard 
                            title="Total Omzet (Selesai)" 
                            value={formatRupiah(stats.totalOmzet)} 
                            icon={<Wallet className="text-white" size={24} />} 
                            trend="+12% from last month"
                            colorClass="bg-violet-600 shadow-violet-200"
                        />
                         <StatCard 
                            title="Transaksi Aktif" 
                            value={stats.activeTrx.toString()} 
                            icon={<Activity className="text-white" size={24} />} 
                            trend="+5% new orders"
                            colorClass="bg-blue-500 shadow-blue-200"
                        />
                         <StatCard 
                            title="Total Customer" 
                            value={stats.totalCust.toString()} 
                            icon={<Users className="text-white" size={24} />} 
                            trend="+2 new today"
                            colorClass="bg-emerald-500 shadow-emerald-200"
                        />
                        <StatCard 
                            title="Total Produk" 
                            value={stats.totalProd.toString()} 
                            icon={<Package className="text-white" size={24} />} 
                            trend="Inventory healthy"
                            colorClass="bg-orange-500 shadow-orange-200"
                        />
                      </div>
                  ) : (
                  /* LIST / TABLE VIEW */
                  <div className={`${isCardView ? 'grid grid-cols-1 gap-4' : 'bg-white border border-slate-200 shadow-sm rounded-lg overflow-hidden min-w-full inline-block align-middle'}`}>

                      {/* CARD VIEW FOR MOBILE (Simplified) */}
                      {isCardView ? (
                          viewData.map((item: any) => (
                             <div 
                                key={item.id} 
                                className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 cursor-pointer"
                                onClick={() => {
                                    if(activeView === 'Contacts') { setCurrentCust(item); setShowDrawer('custDetail'); }
                                    else if(activeView === 'Produk') { setCurrentProd(item); setShowDrawer('prodDetail'); }
                                    else { setCurrentTrx(item); setShowDrawer('trxDetail'); }
                                }}
                             >
                                 <div className="flex justify-between items-start mb-2">
                                     <div>
                                         <h4 className="font-bold text-slate-800">{item.nama || item.noTrx}</h4>
                                         <div className="text-xs text-slate-500">{item.kode || item.customerName}</div>
                                     </div>
                                     {item.status && (
                                         <span className={`px-2 py-0.5 rounded text-[10px] font-bold border ${
                                            item.status === 'Selesai' ? 'bg-green-50 text-green-700 border-green-200' :
                                            item.status === 'Progress' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                            item.status === 'Payment' ? 'bg-indigo-50 text-indigo-700 border-indigo-200' :
                                            item.status === 'Pengiriman' ? 'bg-orange-50 text-orange-700 border-orange-200' :
                                            'bg-red-50 text-red-700 border-red-200'
                                         }`}>
                                             {item.status}
                                         </span>
                                     )}
                                 </div>
                                 <div className="flex justify-between items-center text-sm">
                                    {item.nilaiProyek !== undefined && <span className="font-bold text-[#A91D3A]">{formatRupiah(item.nilaiProyek)}</span>}
                                    {item.lots && <span>Stock: {item.lots.reduce((a:any,b:any)=>a+b.stock,0)}</span>}
                                    {item.phone && <span>{item.phone}</span>}
                                 </div>
                             </div>
                          ))
                      ) : (
                      /* DESKTOP TABLE VIEW */
                      <div className="overflow-x-auto">
                        <table className="min-w-full divide-y divide-slate-200">
                            <thead>
                                <tr>
                                    {activeView === 'Contacts' && (
                                        <>
                                            <th className={thClass}>Name</th>
                                            <th className={thClass}>Type</th>
                                            <th className={thClass}>Phone</th>
                                            <th className={thClass}>Sales Rep</th>
                                            <th className={thClass}>Status</th>
                                        </>
                                    )}
                                    {activeView === 'Produk' && (
                                        <>
                                            <th className={thClass}>Product Name</th>
                                            <th className={thClass}>Code</th>
                                            <th className={thClass}>Stock</th>
                                            <th className={thClass}>Price</th>
                                            <th className={thClass}>Supplier</th>
                                        </>
                                    )}
                                    {['Transaksi', 'Invoice', 'Pesanan Selesai', 'Pesanan Batal'].includes(activeView) && (
                                        <>
                                            <th className={thClass}>Invoice #</th>
                                            <th className={thClass}>Date</th>
                                            <th className={thClass}>Customer</th>
                                            <th className={thClass} align="right">Amount</th>
                                            <th className={thClass}>Sales Rep</th>
                                            <th className={thClass} align="center">Status</th>
                                        </>
                                    )}
                                    {activeView === 'Pengiriman' && (
                                        <>
                                            <th className={thClass}>Invoice #</th>
                                            <th className={thClass}>Customer</th>
                                            <th className={thClass}>Jasa Kirim</th>
                                            <th className={thClass}>No. Resi</th>
                                            <th className={thClass} align="center">Action</th>
                                        </>
                                    )}
                                    {/* ACTION COLUMN HEADER */}
                                    {(activeView === 'Contacts' || activeView === 'Produk' || ['Transaksi', 'Invoice', 'Pesanan Selesai', 'Orders', 'Pesanan Batal'].includes(activeView)) && (
                                        <th className={thClass} align="center">Action</th>
                                    )}
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {/* CUSTOMERS DATA */}
                                {activeView === 'Contacts' && customers.map((c, i) => (
                                    <tr 
                                        key={c.id} 
                                        className={`${i % 2 === 0 ? 'bg-white' : 'bg-[#F9FAFB]'} hover:bg-slate-50 cursor-pointer transition-colors`}
                                        onClick={() => { setCurrentCust(c); setShowDrawer('custDetail'); }}
                                    >
                                        <td className={tdClass}><span className="font-medium text-[#A91D3A] hover:underline cursor-pointer">{c.nama}</span></td>
                                        <td className={tdClass}>{c.jenis}</td>
                                        <td className={tdClass}>{c.phone}</td>
                                        <td className={tdClass}>{c.sales}</td>
                                        <td className={tdClass}><span className="px-2 py-0.5 rounded text-[10px] font-bold bg-green-100 text-green-700 uppercase">{c.leadType}</span></td>
                                        <td className={tdClass} align="center">
                                            <div className="flex items-center justify-center gap-1">
