                                            <div className="text-xs text-[#A91D3A] font-semibold">{formatRupiah(lot.hargaJual)}</div>
                                        </div>
                                    </div>
                                ))
                            ) : <div className="text-slate-400 text-sm text-center py-4">Belum ada riwayat stok</div>}
                        </div>
                     </div>
                </div>
              )}

            </div>

            {showDrawer !== 'prodDetail' && showDrawer !== 'custDetail' && showDrawer !== 'trxDetail' && showDrawer !== 'printInvoice' && (
                <div className="p-4 border-t border-slate-200 bg-[#FAFAFA]">
                    <button 
                        onClick={() => {
                            if(showDrawer==='prod') saveProduct();
                            else if(showDrawer==='trx') saveTransaction();
                            else if(showDrawer==='cust') saveCustomer();
                            else if(showDrawer==='supp') saveSupplier();
                            else if(showDrawer==='inputResi') saveResi();
                        }} 
                        className="w-full bg-[#2C3E50] hover:bg-[#1a252f] text-white font-bold py-3 rounded-lg shadow-sm"
                    >
                        Simpan Data
                    </button>
                </div>
            )}

            {(showDrawer === 'prodDetail' || showDrawer === 'custDetail' || showDrawer === 'trxDetail') && (
                 <div className="p-4 border-t border-slate-200 bg-[#FAFAFA]">
                    <button onClick={() => setShowDrawer(showDrawer === 'prodDetail' ? 'prod' : showDrawer === 'custDetail' ? 'cust' : 'trx')} className="w-full border border-slate-300 bg-white text-slate-700 font-bold py-3 rounded-lg hover:bg-slate-50">
                        {showDrawer === 'prodDetail' ? 'Edit Produk' : showDrawer === 'custDetail' ? 'Edit Kontak' : 'Edit Transaksi'}
                    </button>
                 </div>
            )}
          </div>
        </div>
      )}

    </div>
  );
};

