                        <select className="text-sm border border-slate-300 rounded-sm py-1 px-2 outline-none bg-white">
                            <option>Select</option>
                            <option>Active</option>
                            <option>Inactive</option>
                        </select>
                    </div>

                    <div className="ml-auto flex items-center gap-2">
                        {/* Mobile Toggle Grid/List */}
                         <button 
                            onClick={() => setIsCardView(!isCardView)} 
                            className={`p-2 rounded md:hidden ${isCardView ? 'bg-slate-200 text-slate-800' : 'text-slate-400'}`}
                            title="Toggle View"
                         >
                            {isCardView ? <List size={18}/> : <LayoutGrid size={18}/>}
                         </button>

                         <button 
                            onClick={() => {
                                if(activeView === 'Contacts') { setCurrentCust({jenis: 'Perusahaan', leadType: 'Belum Transaksi', source: 'Organic', sales: 'Angel', negara: 'Indonesia', phone: '62'}); setShowDrawer('cust'); }
                                else if(activeView === 'Produk') { setCurrentProd({satuan:'Pcs'}); setTempStock({stock:0, hpp:0, hargaJual:0, supplierId:''}); setShowDrawer('prod'); }
                                else if(['Transaksi', 'Invoice', 'Pesanan Selesai'].includes(activeView)) { setCurrentTrx({ items: [], status: 'Progress', tanggal: new Date().toISOString().split('T')[0], ppn: true, ongkir: false, biayaOngkir: 0, sales: 'Angel', jasaKirim: 'JNE Regular' }); setShowDrawer('trx'); }
                            }}
                            className="bg-[#2C3E50] hover:bg-[#1a252f] text-white text-xs font-bold px-4 py-2 rounded-lg flex items-center gap-2 transition-colors shadow-sm"
                        >
                            <Plus size={14} />
                            <span className="hidden md:inline">Tambah {activeView === 'Contacts' ? 'Kontak' : activeView === 'Produk' ? 'Produk' : 'Data'}</span>
                            <span className="md:hidden">Add</span>
                        </button>
                    </div>
                </div>
              )}

              {/* Main Content Area: Dashboard or Table */}
              <div className="flex-1 overflow-auto bg-[#FAFAFA] p-4">
                  {/* DASHBOARD VIEW */}
                  {activeView === 'Dashboard' ? (
                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                        <StatCard 
                            title="Total Omzet (Selesai)" 
                            value={formatRupiah(stats.totalOmzet)} 
                            icon={<Wallet className="text-white" size={24} />} 
                            trend="+12% from last month"
                            colorClass="bg-violet-600 shadow-violet-200"
                        />
                         <StatCard 
                            title="Transaksi Aktif" 
                            value={stats.activeTrx.toString()} 
                            icon={<Activity className="text-white" size={24} />} 
                            trend="+5% new orders"
                            colorClass="bg-blue-500 shadow-blue-200"
                        />
                         <StatCard 
                            title="Total Customer" 
                            value={stats.totalCust.toString()} 
                            icon={<Users className="text-white" size={24} />} 
                            trend="+2 new today"
                            colorClass="bg-emerald-500 shadow-emerald-200"
                        />
                        <StatCard 
                            title="Total Produk" 
                            value={stats.totalProd.toString()} 
                            icon={<Package className="text-white" size={24} />} 
                            trend="Inventory healthy"
                            colorClass="bg-orange-500 shadow-orange-200"
                        />
                      </div>
                  ) : (
                  /* LIST / TABLE VIEW */
                  <div className={`${isCardView ? 'grid grid-cols-1 gap-4' : 'bg-white border border-slate-200 shadow-sm rounded-lg overflow-hidden'}`}>

                      {/* CARD VIEW FOR MOBILE (Simplified) */}
                      {isCardView ? (
                          viewData.map((item: any) => (
                             <div 
                                key={item.id} 
                                className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 cursor-pointer"
                                onClick={() => {
                                    if(activeView === 'Contacts') { setCurrentCust(item); setShowDrawer('custDetail'); }
                                    else if(activeView === 'Produk') { setCurrentProd(item); setShowDrawer('prodDetail'); }
                                    else { setCurrentTrx(item); setShowDrawer('trxDetail'); }
                                }}
                             >
                                 <div className="flex justify-between items-start mb-2">
                                     <div>
                                         <h4 className="font-bold text-slate-800">{item.nama || item.noTrx}</h4>
                                         <div className="text-xs text-slate-500">{item.kode || item.customerName}</div>
                                     </div>
                                     {item.status && (
                                         <span className={`px-2 py-0.5 rounded text-[10px] font-bold border ${
                                            item.status === 'Selesai' ? 'bg-green-50 text-green-700 border-green-200' :
                                            item.status === 'Progress' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                            item.status === 'Payment' ? 'bg-indigo-50 text-indigo-700 border-indigo-200' :
                                            item.status === 'Pengiriman' ? 'bg-orange-50 text-orange-700 border-orange-200' :
                                            'bg-red-50 text-red-700 border-red-200'
                                         }`}>
                                             {item.status}
                                         </span>
                                     )}
                                 </div>
                                 <div className="flex justify-between items-center text-sm">
                                    {item.nilaiProyek !== undefined && <span className="font-bold text-[#A91D3A]">{formatRupiah(item.nilaiProyek)}</span>}
                                    {item.lots && <span>Stock: {item.lots.reduce((a:any,b:any)=>a+b.stock,0)}</span>}
                                    {item.phone && <span>{item.phone}</span>}
                                 </div>
                             </div>
                          ))
                      ) : (
                      /* DESKTOP TABLE VIEW */
                      <div className="overflow-x-auto w-full">
                        <table className="min-w-full divide-y divide-slate-200">
                            <thead>
                                <tr>
                                    {activeView === 'Contacts' && (
                                        <>
                                            <th className={thClass}>Name</th>
                                            <th className={thClass}>Type</th>
                                            <th className={thClass}>Phone</th>
                                            <th className={thClass}>Sales Rep</th>
                                            <th className={thClass}>Status</th>
                                        </>
                                    )}
                                    {activeView === 'Produk' && (
                                        <>
                                            <th className={thClass}>Product Name</th>
                                            <th className={thClass}>Code</th>
                                            <th className={thClass}>Stock</th>
                                            <th className={thClass}>Price</th>
                                            <th className={thClass}>Supplier</th>
                                        </>
                                    )}
                                    {['Transaksi', 'Invoice', 'Pesanan Selesai', 'Pesanan Batal'].includes(activeView) && (
                                        <>
                                            <th className={thClass}>Invoice #</th>
                                            <th className={thClass}>Date</th>
                                            <th className={thClass}>Customer</th>
                                            <th className={thClass} align="right">Amount</th>
                                            <th className={thClass}>Sales Rep</th>
                                            <th className={thClass} align="center">Status</th>
                                        </>
                                    )}
                                    {activeView === 'Pengiriman' && (
                                        <>
                                            <th className={thClass}>Invoice #</th>
                                            <th className={thClass}>Customer</th>
                                            <th className={thClass}>Jasa Kirim</th>
                                            <th className={thClass}>No. Resi</th>
                                            <th className={thClass} align="center">Action</th>
                                        </>
                                    )}
                                    {/* ACTION COLUMN HEADER */}
                                    {(activeView === 'Contacts' || activeView === 'Produk' || ['Transaksi', 'Invoice', 'Pesanan Selesai', 'Orders', 'Pesanan Batal'].includes(activeView)) && (
                                        <th className={thClass} align="center">Action</th>
                                    )}
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {/* CUSTOMERS DATA */}
                                {activeView === 'Contacts' && customers.map((c, i) => (
                                    <tr 
                                        key={c.id} 
                                        className={`${i % 2 === 0 ? 'bg-white' : 'bg-[#F9FAFB]'} hover:bg-slate-50 cursor-pointer transition-colors`}
                                        onClick={() => { setCurrentCust(c); setShowDrawer('custDetail'); }}
                                    >
                                        <td className={tdClass}><span className="font-medium text-[#A91D3A] hover:underline cursor-pointer">{c.nama}</span></td>
                                        <td className={tdClass}>{c.jenis}</td>
                                        <td className={tdClass}>{c.phone}</td>
                                        <td className={tdClass}>{c.sales}</td>
                                        <td className={tdClass}><span className="px-2 py-0.5 rounded text-[10px] font-bold bg-green-100 text-green-700 uppercase">{c.leadType}</span></td>
                                        <td className={tdClass} align="center">
                                            <div className="flex items-center justify-center gap-1">
                                                <button onClick={(e) => { e.stopPropagation(); setCurrentCust(c); setShowDrawer('custDetail'); }} className="text-slate-400 hover:text-blue-600 transition-colors p-1 rounded-full hover:bg-slate-100"><Eye size={18}/></button>
                                                <button onClick={(e) => { e.stopPropagation(); setCurrentCust(c); setShowDrawer('cust'); }} className="text-slate-400 hover:text-orange-600 transition-colors p-1 rounded-full hover:bg-slate-100"><Edit3 size={18}/></button>
                                                <button onClick={(e) => { e.stopPropagation(); handleDelete(c.id); }} className="text-slate-400 hover:text-red-600 transition-colors p-1 rounded-full hover:bg-slate-100"><Trash2 size={18}/></button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}

                                {/* PRODUK DATA */}
                                {activeView === 'Produk' && products.map((p, i) => (
                                    <tr 
                                        key={p.id} 
                                        className={`${i % 2 === 0 ? 'bg-white' : 'bg-[#F9FAFB]'} hover:bg-slate-50 cursor-pointer transition-colors`}
                                        onClick={() => { setCurrentProd(p); setShowDrawer('prodDetail'); }}
                                    >
                                        <td className={tdClass}>
                                            <div className="flex items-center gap-2">
                                                <div className="w-6 h-6 bg-slate-100 rounded flex items-center justify-center text-slate-500"><Box size={14}/></div>
                                                <span className="font-medium text-slate-700">{p.nama}</span>
                                            </div>
                                        </td>
                                        <td className={tdClass}><span className="font-mono text-xs">{p.kode}</span></td>
                                        <td className={tdClass}>{p.lots.reduce((a,b)=>a+b.stock,0)} {p.satuan}</td>
                                        <td className={tdClass}>{formatRupiah(getProductPrice(p))}</td>
                                        <td className={tdClass}>{getSupplierName(p)}</td>
                                         <td className={tdClass} align="center">
                                            <div className="flex items-center justify-center gap-1">
                                                <button onClick={(e) => { e.stopPropagation(); setCurrentProd(p); setShowDrawer('prodDetail'); }} className="text-slate-400 hover:text-blue-600 transition-colors p-1 rounded-full hover:bg-slate-100"><Eye size={18}/></button>
                                                <button onClick={(e) => { e.stopPropagation(); setCurrentProd(p); setShowDrawer('prod'); }} className="text-slate-400 hover:text-orange-600 transition-colors p-1 rounded-full hover:bg-slate-100"><Edit3 size={18}/></button>
                                                <button onClick={(e) => { e.stopPropagation(); handleDelete(p.id); }} className="text-slate-400 hover:text-red-600 transition-colors p-1 rounded-full hover:bg-slate-100"><Trash2 size={18}/></button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}

                                {/* TRANSAKSI DATA (Include Invoice, Selesai, Batal) */}
                                {['Transaksi', 'Invoice', 'Pesanan Selesai', 'Pesanan Batal'].includes(activeView) && (viewData as Transaction[]).map((t, i) => (
                                    <tr 
                                        key={t.id} 
                                        className={`${i % 2 === 0 ? 'bg-white' : 'bg-[#F9FAFB]'} hover:bg-slate-50 cursor-pointer transition-colors`}
                                        onClick={() => { setCurrentTrx(t); setShowDrawer('trxDetail'); }}
                                    >
                                        <td className={tdClass}><span className="font-medium text-[#A91D3A]">{t.noTrx}</span></td>
                                        <td className={tdClass}>{t.tanggal}</td>
                                        <td className={tdClass}>{t.customerName}</td>
                                        <td className={tdClass} align="right">{formatRupiah(t.nilaiProyek)}</td>
                                        <td className={tdClass}>{t.sales}</td>
                                        <td className={tdClass} align="center">
                                            <span className={`px-2 py-0.5 rounded text-[10px] font-bold border 
                                                ${t.status==='Selesai' ? 'bg-green-50 text-green-700 border-green-200' : 
                                                t.status==='Progress' ? 'bg-blue-50 text-blue-700 border-blue-200' : 
                                                t.status==='Payment' ? 'bg-indigo-50 text-indigo-700 border-indigo-200' :
                                                t.status==='Pengiriman' ? 'bg-orange-50 text-orange-700 border-orange-200' :
                                                'bg-red-50 text-red-700 border-red-200'}`}>
                                                {t.status}
                                            </span>
                                        </td>
                                        <td className={tdClass} align="center">
                                            <div className="flex items-center justify-center gap-2">
                                                {/* Transaksi View Actions */}
                                                {activeView === 'Transaksi' && (
                                                    <>
                                                        <button title="Print & Create Invoice" onClick={(e) => { e.stopPropagation(); handlePrintInvoice(t); }} className="text-slate-400 hover:text-violet-600 p-1"><Printer size={16}/></button>
                                                        <button title="Batal Transaksi" onClick={(e) => { e.stopPropagation(); updateTransactionStatus(t.id, 'Batal'); }} className="text-slate-400 hover:text-red-600 p-1"><X size={16}/></button>
                                                    </>
                                                )}
                                                {/* Invoice View Actions */}
                                                {activeView === 'Invoice' && (
                                                    <>
                                                        <button title="Print Invoice" onClick={(e) => { e.stopPropagation(); handlePrintInvoice(t); }} className="text-slate-400 hover:text-violet-600 p-1"><Printer size={16}/></button>
                                                        <button title="Payment Complete" onClick={(e) => { e.stopPropagation(); handlePaymentComplete(t); }} className="text-slate-400 hover:text-green-600 p-1"><CheckCircle size={16}/></button>
                                                        <button title="Batal Transaksi" onClick={(e) => { e.stopPropagation(); updateTransactionStatus(t.id, 'Batal'); }} className="text-slate-400 hover:text-red-600 p-1"><X size={16}/></button>
                                                    </>
                                                )}
                                                 {/* Pesanan Batal Actions */}
                                                 {activeView === 'Pesanan Batal' && (
                                                    <button title="Hapus Permanen" onClick={(e) => { e.stopPropagation(); handleDelete(t.id); }} className="text-slate-400 hover:text-red-600 p-1"><Trash2 size={16}/></button>
                                                )}
                                                {/* Common Actions for Active/Finished */}
                                                {['Transaksi', 'Invoice', 'Pesanan Selesai'].includes(activeView) && (
                                                    <>
                                                        <button title="Edit Transaksi" onClick={(e) => { e.stopPropagation(); setCurrentTrx(t); setShowDrawer('trx'); }} className="text-slate-400 hover:text-blue-600 p-1"><Edit3 size={16}/></button>
                                                        <button title="Hapus Data" onClick={(e) => { e.stopPropagation(); handleDelete(t.id); }} className="text-slate-400 hover:text-red-600 p-1"><Trash2 size={16}/></button>
                                                    </>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}

                                {/* PENGIRIMAN DATA */}
                                {activeView === 'Pengiriman' && (viewData as Transaction[]).map((t, i) => (
                                     <tr 
                                        key={t.id} 
                                        className={`${i % 2 === 0 ? 'bg-white' : 'bg-[#F9FAFB]'} hover:bg-slate-50 cursor-pointer transition-colors`}
                                        onClick={() => { setCurrentTrx(t); setShowDrawer('trxDetail'); }}
                                    >
                                        <td className={tdClass}><span className="font-medium text-[#A91D3A]">{t.noTrx}</span></td>
                                        <td className={tdClass}>{t.customerName}</td>
                                        <td className={tdClass}>{t.jasaKirim}</td>
                                        <td className={tdClass}>
                                            {t.noResi ? <span className="font-mono text-slate-600 bg-slate-100 px-2 py-0.5 rounded">{t.noResi}</span> : <span className="text-xs text-red-400 italic">Belum ada resi</span>}
                                        </td>
                                        <td className={tdClass} align="center">
                                            <div className="flex items-center justify-center gap-2">
                                                <button onClick={(e) => { e.stopPropagation(); setCurrentTrx(t); setShowDrawer('inputResi'); }} className="px-2 py-1 text-xs font-bold text-white bg-blue-500 rounded hover:bg-blue-600 flex items-center gap-1">
                                                    {t.noResi ? <Edit3 size={12}/> : <Plus size={12}/>} Resi
                                                </button>
                                                <button onClick={(e) => { e.stopPropagation(); updateTransactionStatus(t.id, 'Selesai'); }} className="px-2 py-1 text-xs font-bold text-white bg-green-500 rounded hover:bg-green-600 flex items-center gap-1">
                                                    <CheckCircle size={12}/> Selesai
                                                </button>
                                            </div>
                                        </td>
                                     </tr>
                                ))}

                                {/* EMPTY STATE */}
                                {viewData.length === 0 && (
                                    <tr>
                                        <td colSpan={10} className="px-4 py-10 text-center text-slate-400 text-sm">
                                            No records found in {activeView}.
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                      </div>
                      )}
                  </div>
                  )}
              </div>
          </main>
      </div>

      {/* --- DRAWERS --- */}
      {showDrawer && (
        <div className="fixed inset-0 z-[60] flex justify-end">
          <div className="absolute inset-0 bg-black/30 backdrop-blur-sm" onClick={() => setShowDrawer(null)} />
          <div className={`relative w-full ${['inputResi', 'printInvoice'].includes(showDrawer) ? 'max-w-xl' : 'lg:max-w-xl'} bg-white h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300`}>
            <div className="flex justify-between items-center p-4 border-b border-slate-200 bg-[#FAFAFA]">
              <h3 className="text-lg font-bold text-slate-800">
                {showDrawer === 'trx' ? 'Transaksi Baru' : 
                  showDrawer === 'trxDetail' ? 'Detail Transaksi' :
                  showDrawer === 'cust' ? 'Data Kontak' :
                  showDrawer === 'custDetail' ? 'Detail Kontak' :
                  showDrawer === 'prod' ? 'Produk & Stok' :
                  showDrawer === 'prodDetail' ? 'Detail Produk' : 
                  showDrawer === 'inputResi' ? 'Input Resi Pengiriman' : 
                  showDrawer === 'printInvoice' ? 'Cetak Invoice' : 'Supplier Baru'}
              </h3>
              <button onClick={() => setShowDrawer(null)} className="p-1 hover:bg-slate-200 rounded text-slate-500"><X size={20}/></button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-6">

              {/* --- PRINT INVOICE PREVIEW --- */}
              {showDrawer === 'printInvoice' && (
                  <div className="flex flex-col h-full">
                      <div className="bg-white border border-slate-200 p-8 shadow-sm mb-4" id="invoice-area">
                          <div className="flex justify-between items-start mb-8">
                              <div>
                                  <h1 className="text-2xl font-bold text-slate-800">INVOICE</h1>
                                  <p className="text-sm text-slate-500">#{currentTrx.noTrx}</p>
                              </div>
                              <div className="text-right">
                                  <h2 className="font-bold text-slate-800 text-lg">MyPanca CRM</h2>
                                  <p className="text-xs text-slate-500">Jakarta, Indonesia</p>
                              </div>
                          </div>

                          <div className="grid grid-cols-2 gap-8 mb-8">
                              <div>
                                  <h3 className="text-xs font-bold text-slate-400 uppercase mb-1">Bill To</h3>
                                  <p className="font-bold text-slate-800">{currentTrx.customerName}</p>
                                  {(() => {
                                      const c = customers.find(x => x.nama === currentTrx.customerName);
                                      return c ? (
                                          <div className="text-sm text-slate-600 mt-1">
                                              <p>{c.alamat}</p>
                                              <p>{c.phone}</p>
                                              <p>{c.email}</p>
                                          </div>
                                      ) : null;
                                  })()}
                              </div>
                              <div className="text-right">
                                  <div className="mb-2">
                                    <h3 className="text-xs font-bold text-slate-400 uppercase">Date</h3>
                                    <p className="text-sm font-medium">{formatDateShort(currentTrx.tanggal || '')}</p>
                                  </div>
                                  <div>
                                    <h3 className="text-xs font-bold text-slate-400 uppercase">Sales Rep</h3>
                                    <p className="text-sm font-medium">{currentTrx.sales}</p>
                                  </div>
                              </div>
                          </div>

                          <table className="w-full mb-8">
                              <thead>
                                  <tr className="border-b-2 border-slate-800">
                                      <th className="text-left py-2 text-sm font-bold">Description</th>
                                      <th className="text-center py-2 text-sm font-bold">Qty</th>
                                      <th className="text-right py-2 text-sm font-bold">Price</th>
                                      <th className="text-right py-2 text-sm font-bold">Total</th>
                                  </tr>
                              </thead>
                              <tbody>
                                  {currentTrx.items?.map((item, i) => (
                                      <tr key={i} className="border-b border-slate-100">
                                          <td className="py-2 text-sm">{item.nama}</td>
                                          <td className="py-2 text-sm text-center">{item.qty}</td>
                                          <td className="py-2 text-sm text-right">{formatRupiah(item.harga)}</td>
                                          <td className="py-2 text-sm text-right">{formatRupiah((item.harga * item.qty) - (item.diskon || 0))}</td>
                                      </tr>
                                  ))}
                              </tbody>
                          </table>

                          <div className="flex justify-end">
                              <div className="w-1/2 space-y-2">
                                  {currentTrx.ppn && (
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-500">PPN 11%</span>
                                        <span className="font-medium">{formatRupiah((currentTrx.nilaiProyek || 0) * 0.11)}</span>
                                    </div>
                                  )}
                                  {currentTrx.ongkir && (
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-500">Shipping</span>
                                        <span className="font-medium">{formatRupiah(currentTrx.biayaOngkir || 0)}</span>
                                    </div>
                                  )}
                                  <div className="flex justify-between text-lg font-bold border-t border-slate-800 pt-2">
                                      <span>Total</span>
                                      <span>{formatRupiah(currentTrx.nilaiProyek || 0)}</span>
                                  </div>
                              </div>
                          </div>
                      </div>

                      <button 
                        onClick={() => window.print()} 
                        className="w-full bg-slate-800 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 hover:bg-slate-900"
                      >
                          <Printer size={18}/> Print Invoice
                      </button>
                  </div>
              )}

              {/* --- INPUT RESI FORM --- */}
              {showDrawer === 'inputResi' && (
                  <div className="space-y-4">
                      <div className="bg-blue-50 p-4 rounded border border-blue-100 text-sm text-blue-800 mb-2">
                          Masukkan nomor resi untuk transaksi <b>{currentTrx.noTrx}</b> menggunakan <b>{currentTrx.jasaKirim}</b>.
                      </div>
                      <div>
                          <label className={labelClass}>Nomor Resi</label>
                          <input autoFocus className={inputClass} value={currentTrx.noResi || ''} onChange={e => setCurrentTrx({...currentTrx, noResi: e.target.value})} placeholder="Contoh: JP123456789" />
                      </div>
                  </div>
              )}

              {/* --- CUSTOMER DETAIL (READ ONLY + HISTORY) --- */}
              {showDrawer === 'custDetail' && (
                  <div className="space-y-6">
                      {/* Profile Header */}
                      <div className="bg-slate-50 p-5 rounded-lg border border-slate-200">
                          <div className="flex justify-between items-start mb-4">
                                <div className="flex items-center gap-3">
                                    <div className="w-12 h-12 bg-violet-100 text-violet-600 rounded-full flex items-center justify-center font-bold text-lg">
                                        {currentCust.nama?.substring(0,2).toUpperCase()}
                                    </div>
                                    <div>
                                        <h4 className="text-lg font-bold text-slate-900">{currentCust.nama}</h4>
                                        <span className="text-xs text-slate-500 flex items-center gap-1"><MapPin size={10}/> {currentCust.alamat || 'Alamat tidak tersedia'}</span>
                                    </div>
                                </div>
                                <span className={`px-2.5 py-1 rounded text-xs font-bold border ${currentCust.jenis === 'Perusahaan' ? 'bg-blue-50 text-blue-600 border-blue-200' : 'bg-orange-50 text-orange-600 border-orange-200'}`}>
                                    {currentCust.jenis}
                                </span>
                          </div>
                          <div className="grid grid-cols-2 gap-4 mt-4 text-sm">
                              <div>
                                  <label className="text-[10px] uppercase font-bold text-slate-400">Phone</label>
                                  <div className="font-medium text-slate-700">{currentCust.phone}</div>
                              </div>
                              <div>
                                  <label className="text-[10px] uppercase font-bold text-slate-400">Email</label>
                                  <div className="font-medium text-slate-700">{currentCust.email || '-'}</div>
                              </div>
                              <div>
                                  <label className="text-[10px] uppercase font-bold text-slate-400">Sales Rep</label>
                                  <div className="font-medium text-slate-700">{currentCust.sales}</div>
                              </div>
                          </div>
                      </div>

                      {/* Transaction History */}
                      <div>
                          <h5 className="font-bold text-sm text-slate-800 mb-3 flex items-center gap-2"><Activity size={16} className="text-slate-400"/> Riwayat Transaksi</h5>

                          {/* Summary Stats for Customer */}
                          <div className="grid grid-cols-3 gap-2 mb-4">
                              <div className="p-2 bg-green-50 rounded border border-green-100 text-center">
                                  <div className="text-xs text-green-600 font-bold">Selesai</div>
                                  <div className="text-sm font-bold">{transactions.filter(t => t.customerName === currentCust.nama && t.status === 'Selesai').length}</div>
                              </div>
                              <div className="p-2 bg-blue-50 rounded border border-blue-100 text-center">
                                  <div className="text-xs text-blue-600 font-bold">Progress</div>
                                  <div className="text-sm font-bold">{transactions.filter(t => t.customerName === currentCust.nama && (t.status === 'Progress' || t.status === 'Pengiriman')).length}</div>
                              </div>
                              <div className="p-2 bg-red-50 rounded border border-red-100 text-center">
                                  <div className="text-xs text-red-600 font-bold">Batal</div>
                                  <div className="text-sm font-bold">{transactions.filter(t => t.customerName === currentCust.nama && t.status === 'Batal').length}</div>
                              </div>
                          </div>

                          <div className="space-y-2 max-h-64 overflow-y-auto pr-1">
                              {transactions.filter(t => t.customerName === currentCust.nama).length > 0 ? (
                                  transactions.filter(t => t.customerName === currentCust.nama).map(t => (
                                      <div key={t.id} className="p-3 bg-white border border-slate-100 rounded-lg shadow-sm flex justify-between items-center hover:bg-slate-50 transition-colors">
                                          <div>
                                              <div className="text-xs font-bold text-slate-800">{t.noTrx}</div>
                                              <div className="text-[10px] text-slate-500">{formatDateShort(t.tanggal)}</div>
                                          </div>
                                          <div className="text-right">
                                              <div className="text-xs font-bold text-slate-700">{formatRupiah(t.nilaiProyek)}</div>
                                              <span className={`text-[10px] font-bold ${
                                                  t.status === 'Selesai' ? 'text-green-600' :
                                                  t.status === 'Progress' ? 'text-blue-600' : 
                                                  t.status === 'Pengiriman' ? 'text-orange-600' : 'text-red-600'
                                              }`}>
                                                  {t.status}
                                              </span>
                                          </div>
                                      </div>
                                  ))
                              ) : (
                                  <div className="text-center py-6 border-2 border-dashed border-slate-200 rounded-lg text-slate-400 text-xs">
                                      Belum ada riwayat transaksi
                                  </div>
                              )}
                          </div>
                      </div>
                  </div>
              )}

              {/* --- TRANSACTION FORM (Updated) --- */}
              {showDrawer === 'trx' && (
                <div className="space-y-6">
                    {/* Header Info */}
                    <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="col-span-1 md:col-span-2">
                            <label className={labelClass}>Customer</label>
                            <SearchableSelect options={customers.map(c => ({ value: c.nama, label: c.nama }))} value={currentTrx.customerName || ''} onChange={v => setCurrentTrx({...currentTrx, customerName: v})} placeholder="Cari Customer..." className="bg-white" />
                        </div>
                        <div>
                             <label className={labelClass}>Tanggal</label>
                             <input type="date" className={inputClass} value={currentTrx.tanggal} onChange={e => setCurrentTrx({...currentTrx, tanggal: e.target.value})} />
                        </div>
                        <div>
                             <label className={labelClass}>Status Transaksi</label>
                             <select className={inputClass} value={currentTrx.status} onChange={e => setCurrentTrx({...currentTrx, status: e.target.value as any})}>
                                 <option value="Progress">On Progress</option>
                                 <option value="Payment">Payment (Invoice)</option>
                                 <option value="Pengiriman">Pengiriman</option>
                                 <option value="Selesai">Selesai</option>
                                 <option value="Batal">Batal</option>
                             </select>
                        </div>
                        <div>
                             <label className={labelClass}>Sales Responsible</label>
                             <SearchableSelect options={SALES_TEAM.map(s => ({ value: s, label: s }))} value={currentTrx.sales || 'Angel'} onChange={v => setCurrentTrx({...currentTrx, sales: v})} placeholder="Pilih Sales" className="bg-white" />
                        </div>
                        <div>
                             <label className={labelClass}>Jasa Kirim</label>
                             <SearchableSelect options={SHIPPING_SERVICES.map(s => ({ value: s, label: s }))} value={currentTrx.jasaKirim || 'JNE Regular'} onChange={v => setCurrentTrx({...currentTrx, jasaKirim: v})} placeholder="Pilih Ekspedisi" className="bg-white" />
                        </div>
                    </div>

                    {/* Items Section */}
                    <div>
                        <div className="flex justify-between items-center mb-2">
                            <label className={labelClass}>Item Transaksi</label>
                            <button onClick={()=>setCurrentTrx(p=>({...p, items: [...(p.items||[]), { produkId: '', nama: '', sku: '', harga: 0, qty: 1, diskon: 0 }]}))} className="flex items-center gap-1 text-xs font-bold text-[#A91D3A] bg-red-50 px-2 py-1 rounded hover:bg-red-100"><Plus size={12}/> Tambah Produk</button>
                        </div>
                        <div className="space-y-3">
                            {currentTrx.items?.map((item, idx) => (
                                <div key={idx} className="p-3 bg-white border border-slate-200 rounded-lg shadow-sm relative group">
                                    <button onClick={()=>setCurrentTrx(p=>({...p, items: p.items?.filter((_,i)=>i!==idx)}))} className="absolute -top-2 -right-2 bg-white text-red-500 border border-slate-200 rounded-full p-1 shadow-sm hover:bg-red-50"><X size={12}/></button>

                                    <div className="mb-2">
                                        <SearchableSelect options={products.map(p => ({ value: p.nama, label: `${p.nama} (Stok: ${p.lots.reduce((a,b)=>a+b.stock,0)})` }))} value={item.nama} onChange={(val) => { const prod = products.find(p => p.nama === val); const lot = prod?.lots[0]; const newI = [...(currentTrx.items||[])]; newI[idx] = { ...item, nama: val, produkId: prod?.id||'', sku: lot?.sku||'', harga: lot?.hargaJual||0 }; setCurrentTrx(p => ({...p, items: newI})); }} placeholder="Pilih Produk" className="bg-slate-50" />
                                    </div>

                                    <div className="grid grid-cols-3 gap-3">
                                        <div>
                                            <span className="text-[10px] text-slate-400 block mb-1">Harga Satuan</span>
                                            <input type="text" className={`${inputClass} text-right`} value={formatInputNumber(item.harga)} onChange={e => { const newI = [...(currentTrx.items||[])]; newI[idx] = { ...item, harga: parseInputNumber(e.target.value) }; setCurrentTrx(p => ({...p, items: newI})); }} />
                                        </div>
                                        <div>
                                            <span className="text-[10px] text-slate-400 block mb-1">Qty</span>
                                            <input type="number" className={`${inputClass} text-center`} value={item.qty} onChange={e => { const newI = [...(currentTrx.items||[])]; newI[idx] = { ...item, qty: parseInt(e.target.value)||0 }; setCurrentTrx(p => ({...p, items: newI})); }} />
                                        </div>
                                        <div>
                                            <span className="text-[10px] text-slate-400 block mb-1">Diskon Item</span>
                                            <input type="text" className={`${inputClass} text-right text-red-500`} value={formatInputNumber(item.diskon)} onChange={e => { const newI = [...(currentTrx.items||[])]; newI[idx] = { ...item, diskon: parseInputNumber(e.target.value) }; setCurrentTrx(p => ({...p, items: newI})); }} placeholder="0" />
                                        </div>
                                    </div>
                                    <div className="mt-2 text-right text-sm font-bold text-slate-700 bg-slate-50 px-2 py-1 rounded">
                                        Subtotal: {formatRupiah((item.qty * item.harga) - item.diskon)}
                                    </div>
                                </div>
                            ))}
                            {(!currentTrx.items || currentTrx.items.length === 0) && (
                                <div className="text-center py-6 border-2 border-dashed border-slate-200 rounded-lg text-slate-400 text-sm">Belum ada produk dipilih</div>
                            )}
                        </div>
                    </div>

                    {/* Summary & Ongkir */}
                    <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 space-y-3">
                         <div className="flex items-center justify-between">
                             <div className="flex items-center gap-2">
                                 <input type="checkbox" checked={currentTrx.ppn} onChange={e => setCurrentTrx({...currentTrx, ppn: e.target.checked})} className="rounded text-violet-600"/>
                                 <span className="text-sm font-medium">PPN 11%</span>
                             </div>
                             <div className="font-mono text-sm">{formatRupiah(trxCalculations.ppnAmount)}</div>
                         </div>
                         <div className="flex items-center justify-between">
                             <div className="flex items-center gap-2">
                                 <input type="checkbox" checked={currentTrx.ongkir} onChange={e => setCurrentTrx({...currentTrx, ongkir: e.target.checked})} className="rounded text-violet-600"/>
                                 <span className="text-sm font-medium">Biaya Kirim</span>
                             </div>
                             {currentTrx.ongkir ? (
                                 <input type="text" className="w-32 text-right text-sm border rounded p-1" value={formatInputNumber(currentTrx.biayaOngkir)} onChange={e => setCurrentTrx({...currentTrx, biayaOngkir: parseInputNumber(e.target.value)})} autoFocus />
                             ) : <span className="text-sm text-slate-400">-</span>}
                         </div>
                         <div className="border-t border-slate-300 pt-3 flex justify-between items-center">
                             <span className="font-bold text-lg">Total</span>
                             <span className="font-bold text-xl text-[#A91D3A]">{formatRupiah(trxCalculations.grandTotal)}</span>
                         </div>
                    </div>
                </div>
              )}

              {/* --- PRODUCT FORM --- */}
              {showDrawer === 'prod' && (
                <>
                  <div className="space-y-4">
                      <div><label className={labelClass}>Nama Produk</label><input className={inputClass} value={currentProd.nama || ''} onChange={e => setCurrentProd({...currentProd, nama: e.target.value})} /></div>
                      <div className="grid grid-cols-2 gap-4">
                         <div><label className={labelClass}>Satuan</label><SearchableSelect options={UNIT_LIST.map(u => ({ value: u, label: u }))} value={currentProd.satuan || 'Pcs'} onChange={val => setCurrentProd({...currentProd, satuan: val})} placeholder="Pilih Satuan" /></div>
                         <div><label className={labelClass}>Berat (Kg)</label><input className={inputClass} value={currentProd.berat || ''} onChange={e => setCurrentProd({...currentProd, berat: parseInputNumber(e.target.value)})} placeholder="0" /></div>
                      </div>
                  </div>
                  <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 space-y-4">
                      <div className="font-bold text-sm text-slate-800 border-b pb-2">Stok Awal (Opsional)</div>
                      <div><label className={labelClass}>Supplier</label><SearchableSelect options={suppliers.map(s => ({ value: s.id, label: s.nama }))} value={tempStock.supplierId || ''} onChange={v => setTempStock({...tempStock, supplierId: v})} placeholder="Pilih Supplier" className="bg-white" /></div>
                      <div className="grid grid-cols-3 gap-3">
                         <div><label className={labelClass}>Stok Masuk</label><input className={`${inputClass} bg-white`} value={formatInputNumber(tempStock.stock)} onChange={e => setTempStock({...tempStock, stock: parseInputNumber(e.target.value)})} placeholder="0"/></div>
                         <div><label className={labelClass}>Harga Beli (HPP)</label><input className={`${inputClass} bg-white`} value={formatInputNumber(tempStock.hpp)} onChange={e => setTempStock({...tempStock, hpp: parseInputNumber(e.target.value)})} placeholder="0"/></div>
                         <div><label className={labelClass}>Harga Jual</label><input className={`${inputClass} bg-white font-bold text-[#A91D3A]`} value={formatInputNumber(tempStock.hargaJual)} onChange={e => setTempStock({...tempStock, hargaJual: parseInputNumber(e.target.value)})} placeholder="0"/></div>
                      </div>
                  </div>
                </>
              )}

               {showDrawer === 'supp' && (
                <div className="space-y-4">
                    <div><label className={labelClass}>Nama Supplier</label><input className={inputClass} value={currentSupp.nama || ''} onChange={e => setCurrentSupp({...currentSupp, nama: e.target.value})} /></div>
                    <div><label className={labelClass}>NPWP / ID Pajak</label><input className={inputClass} value={currentSupp.npwp || ''} onChange={e => setCurrentSupp({...currentSupp, npwp: e.target.value})} /></div>
                </div>
              )}

              {showDrawer === 'prodDetail' && (
                 /* Detail View Read Only */
                 <div className="space-y-6">
                     <div className="bg-slate-50 rounded-lg p-5 border border-slate-200">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <h4 className="text-xl font-bold text-slate-900">{currentProd.nama}</h4>
                                <span className="font-mono text-xs text-slate-500">{currentProd.kode}</span>
                            </div>
                            <span className="px-2.5 py-1 rounded text-xs font-bold bg-[#A91D3A]/10 text-[#A91D3A]">{currentProd.satuan}</span>
                        </div>
                        <div className="grid grid-cols-3 gap-2 pt-2 border-t border-slate-200">
                             <div className="text-center p-2"><div className="text-[10px] uppercase text-slate-400 font-bold mb-0.5">Total Stok</div><div className="text-sm font-bold text-slate-900">{currentProd.lots?.reduce((a,b)=>a+b.stock,0) || 0}</div></div>
                             <div className="text-center p-2 border-l"><div className="text-[10px] uppercase text-slate-400 font-bold mb-0.5">Berat</div><div className="text-sm font-semibold">{currentProd.berat} Kg</div></div>
                             <div className="text-center p-2 border-l"><div className="text-[10px] uppercase text-slate-400 font-bold mb-0.5">Harga Jual</div><div className="text-sm font-semibold">{formatRupiah(getProductPrice(currentProd as Product))}</div></div>
                        </div>
                     </div>
                     <div>
                        <h5 className="font-bold text-sm text-slate-800 mb-3 flex items-center gap-2"><Store size={16} className="text-slate-400"/> Riwayat Stok</h5>
                        <div className="space-y-3">
                            {currentProd.lots && currentProd.lots.length > 0 ? (
                                currentProd.lots.map((lot, idx) => (
                                    <div key={idx} className="p-4 border border-slate-100 rounded-lg flex justify-between items-center bg-white shadow-sm">
                                        <div>
                                            <div className="text-xs text-slate-500 mb-1">{formatDateShort(lot.tanggal)}</div>
                                            <div className="font-bold text-slate-800">{suppliers.find(s=>s.id===lot.supplierId)?.nama || 'Unknown'}</div>
                                        </div>
                                        <div className="text-right">
                                            <div className="text-lg font-bold text-slate-900">{lot.stock}</div>
                                            <div className="text-xs text-[#A91D3A] font-semibold">{formatRupiah(lot.hargaJual)}</div>
                                        </div>
                                    </div>
                                ))
                            ) : <div className="text-slate-400 text-sm text-center py-4">Belum ada riwayat stok</div>}
                        </div>
                     </div>
                </div>
              )}

            </div>

            {showDrawer !== 'prodDetail' && showDrawer !== 'custDetail' && showDrawer !== 'trxDetail' && showDrawer !== 'printInvoice' && (
                <div className="p-4 border-t border-slate-200 bg-[#FAFAFA]">
                    <button 
                        onClick={() => {
                            if(showDrawer==='prod') saveProduct();
                            else if(showDrawer==='trx') saveTransaction();
                            else if(showDrawer==='cust') saveCustomer();
                            else if(showDrawer==='supp') saveSupplier();
                            else if(showDrawer==='inputResi') saveResi();
                        }} 
                        className="w-full bg-[#2C3E50] hover:bg-[#1a252f] text-white font-bold py-3 rounded-lg shadow-sm"
                    >
                        Simpan Data
                    </button>
                </div>
            )}

            {(showDrawer === 'prodDetail' || showDrawer === 'custDetail' || showDrawer === 'trxDetail') && (
                 <div className="p-4 border-t border-slate-200 bg-[#FAFAFA]">
                    <button onClick={() => setShowDrawer(showDrawer === 'prodDetail' ? 'prod' : showDrawer === 'custDetail' ? 'cust' : 'trx')} className="w-full border border-slate-300 bg-white text-slate-700 font-bold py-3 rounded-lg hover:bg-slate-50">
                        {showDrawer === 'prodDetail' ? 'Edit Produk' : showDrawer === 'custDetail' ? 'Edit Kontak' : 'Edit Transaksi'}
                    </button>
                 </div>
            )}
          </div>
        </div>
      )}

    </div>
  );
};

export default App;
// Helper for Date display in detail view
const formatDateShort = (dateStr: string) => {
    try { return new Date(dateStr).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: '2-digit' }); } 
    catch { return '-'; }
};
const handleSelectAll = (ids: string[]) => {}; // Helper dummy for TS safety in loop if needed, but inlined logic preferred
